  quests = {
    [2] = {ot = "Apporter la griffe de Serres-tranchantes à Senani Thunderheart, au poste de Bois-brisé, en Ashenvale.", st = "Le grand hippogryphe Serres-tranchantes a été tué, et la griffe arrachée à son cadavre témoigne de votre victoire. Senani Thunderheart, au poste de Bois-brisé, sera sans doute intéressée de voir ce trophée qui est la preuve de votre exploit.", t = "La griffe de Serres-tranchantes"},
    [5] = {ot = "Parler au chef Grual.", st = "Je suis resté caché dans cette ville fantôme depuis des semaines.$B$BApportez-moi de quoi festoyer et je vous payerai généreusement.$B$BJ'ai entendu parler d'un certain chef Grual qui fait de succulents gâteaux au crabe brun, à la taverne du Corbeau écarlate à Darkshire...", t = "L'estomac qui gargouille"},
    [6] = {ot = "Tuer Garrick Padfoot et rapporter sa tête à l'Adjoint Willem de l’abbaye de Comté-du-Nord.", st = "Garrick Padfoot – un brigand qui harcèle les fermiers et les marchands de la région depuis des semaines – a été vu dans une cabane près des vignes qui se trouvent à l'est de l'abbaye, juste après le pont. Rapportez-moi la tête de ce mécréant, et vous empocherez la récompense !$B$BMais soyez $gprudent:prudente; $n. Garrick a rassemblé une bande de voyous autour de lui. Il ne sera pas aisé de l'approcher.", t = "La prime pour Garrick Padfoot"},
    [7] = {ot = "Tuer 10 Vermines kobold, puis revenir voir le maréchal McBride.", st = "Votre première tâche est un nettoyage, $n. Un clan de kobolds a envahi les bois se trouvant au nord. Allez là-bas et combattez cette vermine. Affaiblissez-la assez, pour qu'un jour nous puissions la repousser hors de Comté-du-Nord.", t = "Nettoyer le camp des kobolds"},
    [8] = {ot = "Livrer une Lettre à Renée dans les Clairières de Tirisfal.", st = "Hé ! Voudriez-vous faire une faveur à un homme qui a eu plus que sa part de combats contre des zombies et des araignées ?$B$BJ'ai ici une lettre qui doit être livrée à Brill... à une aubergiste du nom de Renée quelque chose. Enfin c'est pas important son nom de famille.$B$BBref, c'est un joli petit coin, plein de personnes victimes de la peste qui essayent de trouver leur voie en ce bas monde. De plus, c’est un bon endroit pour se reposer. Vous devriez aller voir... D'autant que je vous payerai bien.", t = "Un marché de voleur"},
    [9] = {ot = "Le Fermier Saldean veut que vous tuiez 20 Gardiens des moissons.", st = "Regardez ce qu'il s'est passé ici ! Ces terres étaient autrefois habitées par de braves fermiers. Mais ces maudits voleurs les ont tous chassés. Pas moi, pour sûr ! Mais il semble que quelques Gardiens des moissons ont pris possession des champs.$b$bSi vous êtes d'accord, j'aimerais que vous y alliez et que vous en détruisiez une vingtaine. Revenez quand vous aurez fini pour recevoir votre dû. Une fois que vous aurez débarrassé ceux de mon champ, occupez-vous des champs alentours.", t = "Les champs de mort"},
    [11] = {ot = "Apporter 8 Brassards peints de gnolls à l'Adjoint Rainer à la Caserne.", st = "Des gnolls, des animaux brutaux qui n'ont rien à faire ici, ont été aperçus à la lisière de la forêt d'Elwynn. C'est un très grand groupe, bien trop nombreux pour que nous nous en occupions seuls. Ils ont envahi les bois au sud de la tour de garde. Un autre groupe à envahi les zones autour du lac du Cairn à l'est.$B$BL'armée de Stormwind engage quiconque pourrait en tuer. Apportez-moi des Brassards peints de gnolls pour me prouver vos actions.", t = "Prime pour les gnolls Rivepatte"},
    [12] = {ot = "Tuer 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", st = "La Milice du peuple n'a qu'un seul objectif : défendre la marche de l'Ouest et ramener le calme dans les environs. Malheureusement, le prix de la paix est souvent le sang.$b$bUn de mes éclaireurs rapporte qu'une bande de Trappeurs défias sème le trouble dans le coin. Ils auraient été aperçus près de la mine Veine-de-Jango, au nord-ouest, ainsi que dans la Ferme des Molsen et la Ferme de potirons des Froncebouille. Si vous voulez rejoindre nos rangs, tuez 15 Trappeurs défias et 15 Contrebandiers défias, puis revenez me voir.", t = "La milice du peuple"},
    [13] = {ot = "Tuer 15 Pilleurs défias et 15 Pillards défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", st = "Une bande de pilleurs défias a été vue en train de saccager la carrière de la Côte de l'or ainsi que Ruisselune et la ferme des Alexston. La Milice du peuple n'acceptera pas ce genre de comportement. Déployez-vous immédiatement, $n, et faites en sorte que l'on sache que la Lumière est présente dans la marche de l'Ouest.$b$bLa carrière est près de la côte, à l'ouest de la tour. Comme étape de votre instruction, je veux que vous tuiez 15 Pilleurs défias et 15 Pillards défias.", t = "La milice du peuple"},
    [14] = {ot = "Tuer 15 Malandrins défias, 5 Eclaireurs défias et 5 Truands défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.", st = "Quelques Défias nous ont échappé. Mon éclaireur le plus fiable fait état de pillages défias dans les campagnes, au sud de la marche de l'Ouest. Nous pensons qu'ils se cachent dans les collines de la Dague, fomentant leur prochain coup. Détruisez ces misérables au nom de la Milice du peuple.", t = "La milice du peuple"},
    [15] = {ot = "Tuer 10 Ouvriers kobolds, puis revenir faire son rapport au maréchal McBride.", st = "$n, mes éclaireurs me rapportent que l'infestation kobold est d'une plus grande envergure que nous le pensions. Un groupe d'ouvriers kobolds a établi son campement près de la mine de la Crête aux échos au nord.$B$BAllez à la mine et faites en sorte qu'il n'y en ait plus. Nous savons qu'il y en a au moins 10. Tuez-les, voyez s'il y en a davantage, et revenez me présenter votre rapport.", t = "Enquête sur la crête aux échos"},
    [18] = {ot = "Apporter 12 Masques rouges à l’Adjoint Willem à l’extérieur de l’abbaye de Comté-du-Nord.", st = "Un groupe de voleurs traîne depuis peu autour de Comté-du-Nord. Ils se nomment eux-mêmes la Confrérie défias, et ont été aperçus de l'autre côté de la rivière à l'est.$B$BJe ne sais pas ce qu'ils préparent, mais il est certain que ce n'est rien de bon ! Apportez-moi les Masques qu'ils portent, et je vous récompenserai d'une arme.", t = "La confrérie des voleurs"},
    [19] = {ot = "Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines.", st = "Les renégats et les estafettes rochenoires tendent des embuscades entre ici et le donjon de Guet-de-pierre. Le chef des estafettes est un orc du nom de Tharil'zun – nous voulons qu'il meure. Rapportez-moi la tête de Tharil'zun !", t = "Tharil'zun"},
    [20] = {ot = "Rapporter 10 Haches détériorées au maréchal Marris de Comté-du-Lac.", st = "Les orcs rochenoires ont voyagé depuis les Steppes ardentes et ont pris possession du donjon de Guet-de-pierre, depuis le nord. De cette base, ils patrouillent dans toutes les zones au nord de Comté-du-Lac et forcent les citoyens à rester en ville, parqués comme du bétail.$B$BAidez à libérer Comté-du-Lac de cette oppression. Tuez ces orcs rochenoires et rapportez-moi 10 haches détériorées comme preuve de votre réussite.$B$BBien que les orcs rochenoires nous menacent au nord, nous avons des informations disant qu’il y aurait aussi des orcs au sud-est des Carmines. Si vous en trouvez là-bas, tuez-les.", t = "La menace des Rochenoires"},
    [21] = {ot = "Tuer 12 Travailleurs kobold, puis revenir voir le maréchal McBride, à l’abbaye de Comté-du-Nord.", st = "Vos dernières investigations ont prouvé que la mine de la Crête aux échos devait être nettoyée. Retournez-y et chassez les kobolds.$B$BNe perdez pas de temps, $n. Plus les kobolds seront tranquilles dans la mine, plus ils renforceront leurs positions dans Comté-du-Nord.", t = "La bataille de la Crête aux échos"},
    [22] = {ot = "Salma Saldean a besoin de 8 Foies de Broche-tripes pour faire une Tourte au foie de Broche-tripes.", st = "Les oignons sont pelés et l'ail émincé. Le romarin est pilé. La pâte est cuite et le fenouil haché. La sauce finit de mijoter. Il ne me manque que 8 foies de Broche-tripes pour réussir ma fameuse tourte à la viande !", t = "La tourte au foie de Broche-tripes"},
    [23] = {ot = "Apporter la Patte d'Ursangous à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", st = "<La patte du puissant ours Ursangous représente votre trophée pour cette partie de la chasse d’Orneval. Sur la patte figure un petit emblème en forme de croissant de lune, dont la signification reste mystérieuse.$B$BLa patte doit être apportée à Senani Cœur-de-Tonnerre, au poste de Bois-brisé, comme preuve que vous avez abattu la puissante créature et terminé cette partie de la chasse.>", t = "La patte d'Ursangous"},
    [24] = {ot = "Apporter la Tête de Shadumbra à Senani Thunderheart, au Poste de Bois-brisé, dans Ashenvale.", st = "Le rapide et redoutable Shadumbra gît, immobile et silencieux, maintenant que vous l'avez vaincu. La tête du sabre-de-nuit est un trophée de première classe, parfaitement à même de satisfaire les conditions de la Chasse d'Ashenvale. Senani Thunderheart, au Poste de Bois-brisé, aimerait voir un tel trophée pour pouvoir valider cette partie de la Chasse d'Ashenvale.", t = "La tête de Shadumbra"},
    [25] = {ot = "Tuer 12 Elémentaires d’eau corrompus au lac Mystral, à l’est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.$B$BFaire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l’avant-poste de l’Alliance.$B$BRetourner voir Mastok Wrilehiss, au poste de Bois-brisé, dans Ashenvale.", st = "Si vous voulez vous rendre utile, pourquoi n'iriez-vous pas essayer de régler le problème près de la Perce des Serres ?$B$BLes convois entre Ashenvale et les Serres-Rocheuses sont au point mort. En effet, c'est comme si le lac avait pris vie et attaquait tout ce qui s'approche à proximité... c'est à dire quiconque s'aventure sur la Perce. Au lieu de simplement massacrer ces élémentaires d'eau, il serait vraiment utile que quelqu'un aille reconnaître le kiosque du lac Mystral ; celui qui offre une si belle vue sur l'avant-poste de l'Alliance à cet endroit.$B$BAlors, voulez-vous vous rendre utile ?", t = "Impasse aux Serres-Rocheuses"},
    [26] = {ot = "Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", st = "$n, j'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir $gun véritable gardien et protecteur:une véritable gardienne et protectrice; de la nature.$B$BLe temps est venu pour vous d'en apprendre plus à propos de l'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l'eau. Pour cela, vous devez voyager jusqu'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Starblaze, du Cercle cénarien. Il vous guidera plus avant.", t = "Une leçon à apprendre"},
    [27] = {ot = "Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", st = "$n, j'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir $gun véritable gardien et protecteur:une véritable gardienne et protectrice; de la nature.$B$BLe temps est venu pour vous d'en apprendre plus à propos de l'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l'eau. Pour cela, vous devez voyager jusqu'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Starblaze, du Cercle cénarien. Il vous guidera plus avant.", t = "Une leçon à apprendre"},
    [28] = {ot = "Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.$B$BVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.", st = "Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Elune'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l'un des gardiens les plus fiables de Reflet-de-Lune.$B$BVous devez réussir cette quête avant l'expiration du temps imparti, et vous serez peut-être en concurrence avec d'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.$B$BBonne chance, $n.", t = "L'épreuve du lac"},
    [29] = {ot = "Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.$B$BVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.", st = "Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Elune'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l'un des gardiens les plus fiables de Reflet-de-Lune.$B$BVous devez réussir cette quête avant l'expiration du temps imparti, et vous serez peut-être en concurrence avec d'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.$B$BBonne chance, $n.", t = "L'épreuve du lac"},
    [30] = {ot = "Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.$B$BReformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.$B$BApporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", st = "Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L'autre moitié emprunte à l'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.$B$BAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Starblaze.", t = "L'épreuve du lion de mer"},
    [31] = {ot = "Retourner à Thunder Bluff et montrer le Pendentif du lion de mer à Turak Runetotem.", st = "Vous avez terminé les leçons nécessaires, enseignées à tous les jeunes druides avant qu'ils ne puissent adopter un aspect aquatique. Retournez voir votre Maître, Turak Runetotem, à Thunder Bluff. Présentez-lui votre pendentif et montrez-lui que vous êtes en mesure d'apprendre ce qu'il est prêt à vous enseigner. Il veillera à parachever votre entraînement, vous permettant de revêtir une forme aquatique.$B$BAu revoir, jeune druide. Nous nous reparlerons plus tard.", t = "Forme aquatique"},
    [33] = {ot = "Apporter 8 pièces de Viande de loup coriace à Eagan Peltskinner, à l’extérieur de l’abbaye de Comté-du-Nord.", st = "J'ai horreur de ces maudits loups des bois ! Mais j'aime beaucoup en déguster des steaks… Apportez-moi de la viande de loup coriace et je vous donnerai en contrepartie quelque chose que vous devriez trouver utile.$B$BOn peut trouver de la viande de loup coriace en chassant les loups des bois et les jeunes loups qui parcourent la campagne de Comté-du-Nord.", t = "Les loups derrière la frontière"},
    [34] = {t = "Un indésirable"},
    [35] = {ot = "Le maréchal Dughan veut que vous parliez au garde Thomas.", st = "Si vous voulez savoir si les rumeurs concernant les murlocs sont vraies, allez donc au pont, à l'est d’Elwynn et parlez au garde Thomas. Il y est en poste depuis une semaine, il saura de quoi il retourne.$B$BRamenez-moi son compte rendu.", t = "Inquiétudes supplémentaires"},
    [36] = {ot = "Verna Froncebouille veut que vous apportiez la Recette du ragoût de la marche de l'Ouest à Salma Saldean.", st = "Je n'avais jamais pensé un jour quitter ma ferme. Mais les champs grouillent de voleurs, et cela devient vraiment trop dangereux pour nous. Dès que la charrette du Fermier Froncebouille sera réparée, nous partirons. $b $bVous pourriez peut-être me faire une faveur? Laissez-moi écrire la recette du ragoût de la marche de l'Ouest. S'il vous plaît, apportez-la à Salma Saldean à la ferme de l'autre côté, là-bas. La ferme des Saldean est un peu plus loin sur la route, juste après l'embranchement.", t = "Le ragoût de la marche de l'Ouest"},
    [37] = {ot = "Le garde Thomas veut que vous alliez vers le nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai.", st = "Il y a quelques jours, j'ai envoyé deux gardes, Rolf et Malakai, patrouiller le long de la rivière, et ils ne sont toujours pas revenus. Afin de finaliser mon rapport, je dois absolument savoir ce qu'il est advenu de ces hommes.$B$BAllez vers le nord, le long de la rivière, et trouvez les gardes... ou ce qu'il en reste.", t = "Trouver les gardes disparus"},
    [38] = {t = "Le ragoût de la marche de l'Ouest"},
    [39] = {ot = "Avertir le maréchal Dughan de Comté-de-l’Or.", st = "Allez annoncer au maréchal Dughan la mort de Malakai et de Rolf, et prévenez-le que les murlocs à l'est d'Elwynn ne pourront pas être contenus par les troupes présentes actuellement.$B$BJe sais que nous n’avons pas beaucoup de troupes disponibles, mais Dughan trouvera une solution.", t = "Remettre le rapport de Thomas"},
    [40] = {t = "Péril en la rivière"},
    [45] = {ot = "Fouiller le village des murlocs pour trouver Rolf ou des traces de sa mort.", st = "En fouillant un peu plus dans la zone, vous tombez sur des traces de pas palmés qui mènent vers l'est, le long de la rive du lac du Cairn. Légèrement plus loin, vous apercevez un village murloc.$B$BPeut-être que le destin de Rolf s'est arrêté ici...", t = "La destinée de Rolf"},
    [46] = {ot = "Ramener 8 Ailerons de murloc au garde Thomas au Pont est d'Elwynn.", st = "L'armée de Stormwind a mis à prix la tête des rôdeurs et des fourrageurs murlocs qui se trouvent à Elwynn. Tuez-les, découpez leurs ailerons et ramenez-les-moi, l'armée de Stormwind vous récompensera.$B$BLes murlocs ont construit un village au lac du Cairn au nord d'ici, et un autre au sud, là où la rivière se sépare.", t = "Des primes pour les murlocs"},
    [47] = {ot = "Rapporter 10 Poussières d'or à Remy \"Deux fois\" à Comté-de-l’Or. La Poussière d'or se récupère sur les kobolds dans la forêt d'Elwynn.", st = "Par ici les kobolds transportent quelquefois de la poussière d'or sur eux. Cela peut m'être très utile : rapportez-m'en et je vous en donnerai le meilleur prix de la ville ! Le meilleur prix de la ville !$B$BVous trouverez des kobolds dans la mine de Fargodeep, au sud, et autour de la mine Veine-de-jaspe au nord-est.", t = "L'échange de poussière d'or"},
    [52] = {t = "Protéger la frontière"},
    [54] = {ot = "Apporter les documents du maréchal McBride au maréchal Dughan de Comté-de-l’Or.", st = "$n, vous êtes $gun:une:c; $c indubitablement $gimpliqué:impliquée:c; dans la sûreté de Comté-du-Nord. Vous avez maintenant en charge la protection de la zone entourant la forêt d'Elwynn.$B$BSi vous acceptez cette responsabilité, j'ai préparé tous les documents qui doivent être apportés au maréchal Dughan à Comté-de-l’Or. Comté-de-l’Or se situe le long de la route sud, au-delà de la frontière.", t = "Rapport pour Comté-de-l’Or"},
    [56] = {ot = "Le commandant Althea Ebonlocke de Darkshire veut que vous tuiez 8 Guerriers squelettes et 6 Mages squelettes.", st = "En tant que commandant des Veilleurs, et de par mon serment, il est de mon devoir de protéger les citoyens de Darkshire. Stormwind a rappelé les gardes qui étaient en faction ici, nous laissant nous débrouiller par nous-mêmes.$B$BCe serait un acte noble de votre part si vous nous aidiez, car nous en avons terriblement besoin ! Aidez les Veilleurs. Aventurez-vous dans les Jardins paisibles, juste au sud de Darkshire, et tuez 8 guerriers squelettes, ainsi que 6 mages squelettes. Les morts-vivants doivent être contrecarrés !", t = "Les Veilleurs"},
    [57] = {ot = "Le commandant de Darkshire, Althea Ebonlocke, veut que vous tuiez 15 Démons squelettes et 15 Squelettes infernaux.", st = "$n, on vient juste de me rapporter que la forêt était envahie de morts-vivants ! Si vous êtes d'accord pour le faire, voyagez jusqu'au cimetière de Colline-aux-Corbeaux et tuez 15 de ces infâmes démons squelettes et 15 squelettes infernaux. Mes informateurs me disent que des squelettes ont aussi été repérés au sud de Darkshire, autour et dans le cimetière des Jardins paisibles. Les morts-vivants doivent être repoussés hors du bois de la Pénombre !", t = "Les Veilleurs"},
    [59] = {ot = "Donner le Bon pour une pièce d'armure de Stormwind à Sara Timberlain.", st = "Pour récompenser votre perspicacité et votre bravoure, j'ai ici un Bon pour une pièce d'armure de Stormwind. Allez trouver Sara Timberlain, au Camp de bûcherons du Val d'est. Donnez-lui ce bon et elle vous fabriquera une armure. Une fois que vous l'aurez, $n, utilisez-la pour défendre Elwynn.$B$BLe Camp de bûcherons du Val d'est est au-delà du poste de garde de Thomas, vers l'est.", t = "Les armures de cuir et d'étoffe"},
    [60] = {ot = "Rapporter 8 Grandes bougies à William Pestle de Comté-de-l’Or.", st = "Bonjour, $gcher monsieur:ma dame; ! Auriez-vous une seconde ?$B$BMon frère et moi sommes apothicaires à Stormwind, et je suis ici pour acheter des grandes bougies, afin d'utiliser leur cire. Pourriez-vous m'aider ?$B$BLes kobolds produisent ces grandes bougies, et j'ai entendu dire qu’ils infesteraient les mines d'Elwynn... La mine de Fargodeep au sud et celle de Veine-de-jaspe à l'est. Je vous suggère d'aller me chercher ces bougies là où elles se trouvent.", t = "Les bougies de kobolds"},
    [61] = {ot = "Livrer la Cargaison de William à Morgan Pestle dans le Quartier commerçant de Stormwind.", st = "Mon frère Morgan attend ma cargaison de bougies à Stormwind. Je n'ai pas le temps de faire le voyage moi-même, mais si vous livrez la cargaison à ma place, il vous payera bien.$B$BJ'ai empaqueté les bougies, et vous pouvez trouver Morgan à notre magasin, les Apothicaires Pestle, dans le Quartier commerçant de Stormwind.", t = "Une cargaison pour Stormwind"},
    [62] = {ot = "Explorer la mine de Fargodeep, puis revenir voir le maréchal Dughan de Comté-de-l’Or.", st = "Comté-du-Nord n'est pas la seule région à avoir des problèmes avec ses mines ! J'ai des rapports disant que la mine de Fargodeep à Elwynn est aussi infestée de kobolds.$B$BAllez explorer la mine afin de confirmer ces rapports, puis revenez me voir. Elle se situe au sud de Comté-de-l’Or, entre les propriétés des Stonefield et des Maclure.", t = "La mine de Fargodeep"},
    [63] = {ot = "Vaincre la Manifestation d'eau corrompue et placer les Bracelets de manifestation corrompue avec le reste d'eau pure sur le brasero d'Everfount dans la forêt des Pins argentés.", st = "Le long de la côte de la forêt des Pins argentés, à l'ouest du Sépulcre, vous trouverez un autel qui a été corrompu. Les esprits n'y parlent plus aux gens. Vous devez résoudre le problème en purifiant l'autel.$B$BPrenez ces bracelets élémentaires et la potion de Brine, placez-les sur le brasero de l’autel. Ce rituel devrait suffire à invoquer un esprit pur à qui vous pourrez parler.$B$BRamenez-moi une preuve de votre réussite, et je vous récompenserai avec un totem.", t = "L'appel de l'eau"},
    [64] = {ot = "Le fermier Froncebouille désire que vous retrouviez sa Montre qui se trouve dans la penderie de sa ferme près du champ de citrouilles à l'ouest.", st = "C'était horrible ! Verna m'a réveillé quand elle a entendu du grabuge dans les champs. Ils étaient envahis par des vandales. Nous nous sommes enfuis à toutes jambes, du coup j'ai oublié ma montre sur place. Le père de Verna me l'avait offerte pour notre mariage et je suis malade de savoir qu'elle est entre les mains de ces voleurs. J'ai laissé ma montre dans la penderie à la ferme. Cherchez le champ de citrouilles à l'ouest – vous ne pouvez pas le manquer. Si vous me la ramenez, je saurais être reconnaissant !", t = "Le cadeau oublié"},
    [65] = {ot = "Gryan Stoutmantle veut que vous parliez à Wiley à Comté-du-Lac.", st = "La bande de misérables, responsable de la fuite des honnêtes gens de la marche de l'Ouest, se fait appeler la Confrérie défias. J'ai besoin de vous pour infiltrer ces voyous. Nous devons connaître l'identité de leur chef et où ils sont basés. À Comté-du-Lac, il y a un voleur nommé Wiley à l'auberge qui me doit une faveur.$b$bAllez jusqu'à Comté-du-Lac dans les Carmines, à l'est d'Elwynn, et trouvez ce que vous pouvez.", t = "La Confrérie défias"},
    [66] = {t = "La légende de Stalvan"},
    [67] = {t = "La légende de Stalvan"},
    [68] = {ot = "Rapporter la lettre poussiéreuse au greffier Daltry.", st = "Vous trouvez une lettre poussiéreuse dans la vieille caisse.", t = "La légende de Stalvan"},
    [69] = {t = "La légende de Stalvan"},
    [70] = {t = "La légende de Stalvan"},
    [71] = {ot = "Rapporter les Médaillons de Rolf et Malakai au garde Thomas au pont est d’Elwynn.", st = "Maintenant que vous avez les deux médaillons, apportez-les au Garde Thomas au Pont est, il saura peut-être comment ces hommes ont été assassinés.", t = "Faire son rapport au garde Thomas"},
    [72] = {ot = "Rechercher un indice dans le tas d'affaires.", st = "Mon père fut le gardien de cette propriété bien avant que je ne le sois. Il a dû tout nettoyer après le massacre.$b$bLes derniers fonds des Flintridge ont fondu comme neige au soleil. Le reste des affaires de la famille va partir aux enchères. La faute à ces vautours des impôts. J'imagine que vous êtes $gimpatient:impatiente; de voir ce qu'il y a, vous pouvez regarder dans le tas de vieilleries. Si ça se trouve, quelque chose vous intéressera.", t = "La légende de Stalvan"},
    [76] = {ot = "Explorer la mine Veine-de-jaspe, puis faites votre rapport au maréchal Dughan de Comté-de-l’Or.", st = "Merci, nous savons désormais que la mine de Fargodeep est infestée de kobolds. Nous avons besoin maintenant d'un éclaireur pour explorer la mine la plus éloignée, celle de Veine-de-jaspe.$B$BExplorez-la et confirmez la présence de kobolds. Pour parvenir à la mine, allez vers l'est le long de la route, jusqu'à la tour d'Azora. De là prenez vers le nord et vous tomberez sur la mine dans les collines.", t = "La mine Veine-de-jaspe"},
    [83] = {ot = "Apporter 6 Masques rouge en lin à Sara Timberlain au Camp de bûcherons du Val d'est.", st = "Les Défias de Comté-du-Nord portent de simples masques, mais ceux d'Elwynn portent des masques en lin, une belle matière avec laquelle je pourrais faire de très beaux articles.$B$BRapportez-moi des masques rouges en lin et je les utiliserai pour vous confectionner quelque chose.$B$BLes membres de la Confrérie défias ont des campements disséminés à travers tout Elwynn.", t = "Articles rouges en lin"},
    [84] = {ot = "Porter la Tourte de panse de porc à Billy Maclure aux Vignes des Maclure.", st = "Voilà. Quand vous donnerez cette tourte à Billy, dites-lui de s’étouffer avec !", t = "Revenir voir Billy"},
    [85] = {ot = "Parler à Billy Maclure.", st = "J'ai perdu mon collier, et je pense que c'est ce garnement de Billy Maclure qui l'a pris ! Généralement il vagabonde dans les Vignes des Maclure, à l'est d'ici.$B$BRapportez-moi mon collier, et vous réchaufferez le cœur d'une pauvre veuve.", t = "Le collier perdu"},
    [86] = {ot = "Apporter 4 morceaux de Viande de sanglier à Tatie Bernice Stonefield à la ferme des Stonefield.", st = "Si je mangeais une tourte, je pourrais peut-être vous dire qui a ce collier. Vous savez, je pense que cette vieille dame du nom de Bernice, dans l'autre ferme, fait de formidables tourtes de panse de porc...$B$BSi vous lui apportiez quelques morceaux d’un des sangliers qui traînent autour de notre ferme, et si vous lui expliquiez toute l’histoire, alors elle vous préparerait une tourte.", t = "Une tourte pour Billy"},
    [87] = {ot = "Rapporter le Collier de Bernice à \"Tatie\" Bernice Stonefield à la ferme des Stonefield.", st = "Je jouais près de la mine de Fargodeep, et je pense que j'ai fait tomb... Euuuuh... Je veux dire que j'ai vu le collier de la vieille dame. Ne me demandez pas comment il est arrivé là... Ce n'est pas moi qui l'ai pris !$B$BQuoi qu'il en soit, j'ai vu cet énorme kobold avec une dent en or le prendre et s'enfuir vers la mine. Allez là-bas, trouvez le kobold et vous trouverez le collier, c'est juré !", t = "Dent-d'or"},
    [88] = {ot = "Tuer Princesse, prendre son collier, puis le porter à Maman Stonefield à la ferme des Stonefield.", st = "Les Brackwell ont un cochon qui a gagné des tas de prix, Princesse. C'est une ENORME truie, que je soupçonne de dévaster mon potager !$B$BAvant qu'elle ne s’intéresse à mes champs... La bête doit mourir ! Rapportez-moi son collier pour preuve de son exécution, et je vous récompenserai pour votre travail !$B$BPrincesse dîne généralement du côté du Champ de potirons des Brackwell, à l'est, après la ferme des Maclure. Chopez-la avant qu'elle commence à avoir faim, et ne revienne ici !", t = "Princesse doit mourir !"},
    [89] = {ot = "Apporter 5 Clous en fer et 5 Vis en fer au contremaître Oslow à Comté-du-Lac.", st = "Lors de la dernière invasion des orcs, nous avons été obligés de fondre tout notre fer pour fabriquer des balles, des armures et des épées. Nous avons envoyé une demande de ravitaillement à Stormwind, mais une bande de gnolls des Carmines a détourné la caravane puis s'est enfuie dans les collines au-delà de Comté-du-Lac.$B$BNous allons bientôt être à court de matériel pour reconstruire ce pont. Si vous pouviez me rapporter 5 clous en fer et 5 rivets en fer, $n, je ferais en sorte que l'on vous récompense.$B$BAllez, au travail !", t = "Le pont sur le lac"},
    [90] = {t = "Kébab de loup assaisonné"},
    [91] = {t = "La loi de Solomon"},
    [92] = {ot = "Le chef Breanna de Comté-du-Lac veut 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée.", st = "Rien ne me ferait plus plaisir que de vous faire du goulash des Carmines. Mais il y a un petit problème. Lors la dernière attaque des orcs, j'ai dû nourrir la totalité des troupes de Stormwind. Mon garde-manger est complètement vide. Mais si vous me ramenez les ingrédients, je me ferai un plaisir de vous en préparer.$b$bIl me faut seulement 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée.", t = "Goulash des Carmines"},
    [93] = {t = "Gâteaux au crabe brun"},
    [94] = {ot = "Placer le Glyphe d'Azora sur la Statue de lion près de la Tour d'Ilgalar dans les Carmines.", st = "Mon adversaire, Morganth, est un puissant mage vicieux qui vit dans la Tour d'Ilgalar dans les Carmines. J'ai élaboré un moyen pour l'espionner, l'Œil d'Azora, et je peux maintenant l'observer de loin.$B$BMais pour connaître ses pensées, j'ai besoin d'assistance.$B$BSi vous le voulez, portez mon Glyphe d'Azora à la Tour d'Ilgalar. Placez-le sur la Statue de lion près de la tour.$B$BLorsque cela sera fait, j'aurai une vision des plans futurs de Morganth.", t = "L'œil attentif"},
    [95] = {ot = "Aller à la ferme de Sven et trouver ce qui a été enterré derrière la vieille souche d'arbre.", st = "Je travaillais dans une ferme, au sud-est... Des cavaliers noirs du défilé de Deuillevent sont venus dans ma ferme et ont massacré toute ma famille alors que j'étais absent !$B$BQuand je suis rentré, j'ai vu une silhouette indistincte rôder près de ma grange, en train d'enterrer quelque chose. Il s'est enfui avant que j'aie pu l'attraper, et je n'ai pas pu m'attarder, car je suis parti aussitôt à sa poursuite. Du coup, je n'ai pas vu ce qu'il avait caché.$B$BSi vous pouviez découvrir ce qu'a enterré le cavalier noir, je vous en serai reconnaissant. L'endroit exact est derrière la vieille souche d'arbre près de la grange.", t = "La vengeance de Sven"},
    [99] = {ot = "Rapporter 6 Chaînes enchantées de Bois-du-Bûcher à Dalar Dawnweaver au Sépulcre.", st = "Mon mépris pour ce malheureux fou d'Arugal augmente à mesure que je déchiffre son enchantement. J'ai presque fini mes recherches pour y parvenir.$b$bMa compréhension sera totale quand j'aurai compris ce qui cause l'étrange comportement des habitants de Bois-du-Bûcher. Le jour, les paysans sont des gens normaux. Mais la nuit venue ils se transforment en worgens Ragelune.$b$bJe dois puiser l'énergie des chaînes qu'a enchantées Arugal. Rapportez-moi 6 Chaînes enchantées de Bois-du-Bûcher, $n.", t = "La folie d'Arugal"},
    [101] = {ot = "Apporter 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d'araignée à Madame Eva à Darkshire.", st = "À mesure que la corruption mystique rampe à travers la forêt, la nécessité d’une protection devient indispensable, $n. Les vents m'ont murmuré qu'un grand danger vous guette dans un avenir proche.$b$bSi vous voulez vous garder de ce danger, noble $c, apportez-moi 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d'araignée. J’enchanterai alors un Totem d'affliction qui blessera ceux qui tenteront de vous agresser.", t = "Le Totem d'affliction"},
    [102] = {ot = "Rapportez 8 Pattes de gnolls au capitaine Danuvin à la Colline des sentinelles.", st = "Stormwind nous a abandonnés. Un vent de corruption souffle sur la marche de l'Ouest. C'est ma terre natale et je n'abandonnerai pas les gens qui ont choisi de rester ici. Nous, les anciens fermiers, nous résisterons.$b$bVotre mission, si vous l'acceptez, sera de patrouiller dans les prairies de la marche. Débusquez et tuez les infâmes gnolls qui apparemment sont de connivence avec les voleurs des Mortemines. Apportez-moi 8 Pattes de gnolls et je vous récompenserai pour votre courage.", t = "Patrouilles dans la marche de l'Ouest"},
    [103] = {ot = "Apporter 5 Flasques d'huile au capitaine Grayson, au phare de l'Ouest", st = "Je me souviens de cette terrible nuit, au cours de laquelle la famille du gardien de phare a été tuée. J'ai contemplé, impuissant, l’attaque du Vieux Troubloeil. Mais bon, ce qui est fait est fait. Ma préoccupation maintenant est la sécurité des marins et des navires qui croisent sur la Grande mer, car la zone est très dangereuse près des récifs le long de la côte. Vu qu'il n'y a plus personne pour s'occuper du phare, la tâche m'incombe à présent de surveiller sa flamme.$b$bAidez-moi à garder la flamme allumée, apportez-moi 5 Flasques d'huile provenant des monstres des moissons.", t = "Le gardien de la flamme"},
    [104] = {ot = "Rapporter une Ecaille du Vieux Troubloeil au capitaine Grayson au phare de l'Ouest.", st = "Quand ma vie a pris fin sur ces rochers, je ne savais pas que je pouvais espérer quelque chose après la mort. Cette nuit-là, le phare était éteint parce que le Vieux Troubloeil avait fait fuir la famille qui s'en occupait. Mais les gens sont revenus et ont rallumé la flamme. Alors le Vieux Troubloeil a contraint ces faibles d'esprit de murlocs à attaquer le phare. Cette fois-ci, la famille n'a pas eu le temps de fuir, et elle a été massacrée par ces ignobles créatures, sans que personne ne puisse intervenir.$b$bTuez le Vieux Troubloeil si vous le rencontrez le long de la plage, et rapportez-moi une de ses écailles, je vous récompenserai.", t = "Menace sur la côte"},
    [106] = {ot = "Donner la Lettre d'amour de Maybell à Tommy Joe Stonefield.", st = "Je suis maudite ! Mon cœur appartient à Tommy Joe Stonefield, mais nos familles sont ennemies. Du coup, je ne peux pas le voir, et pourtant je languis d’admirer son magnifique visage !$B$BS'il vous plaît, portez-lui cette lettre de ma part. Généralement, il va à la rivière à l'ouest de la ferme des Stonefield, qui se trouve à l'ouest d'ici.", t = "Jeunes amoureux"},
    [107] = {ot = "Porter la Note de Mamie Stonefield à William Pestle.", st = "Je suis sûre que William Pestle a une potion qui permettrait de réunir ces deux amoureux !$B$BTenez, prenez cette note et portez-la à William. Il habite à l’auberge de la Fierté du lion à Comté-de-l’Or.", t = "Note pour William"},
    [109] = {ot = "Parler à Gryan Stoutmantle. Il se trouve à la Tour de pierre sur la Colline des sentinelles, près la route au centre de la marche de l'Ouest.", st = "J'ai l'impression que vous êtes rompu au combat, $c. Si vous ne l'avez pas déjà fait, vous devriez aller voir Gryan Stoutmantle. Il dirige la Milice du peuple, dont le but est de défendre les fermes de la marche de l'Ouest. Je suis sûr qu'il aurait besoin de vous. Il se trouve généralement à la Tour de pierre sur la Colline des sentinelles, près de la route au centre de la marche de l'Ouest.", t = "Aller voir Gryan Stoutmantle"},
    [111] = {ot = "Parler à Mamie Stonefield.", st = "S'il vous plaît, $n, allez parler à Mamie. Si quelqu’un peut trouver une solution à notre problème, c'est bien elle.$B$BElle habite dans notre ferme à l'est d'ici.", t = "Discuter avec Mamie"},
    [112] = {ot = "Apporter 4 Feuilles de Varech cristallin à William Pestle de Comté-de-l’Or.", st = "Je peux préparer une potion d'invisibilité pour Maybell, qui lui permettra de s'échapper du vignoble des Maclure et de rejoindre Tommy Joe. Mais pour préparer cette potion, j'ai besoin de varech cristallin.$B$BCette plante pousse habituellement dans l'océan, mais parfois les murlocs en récoltent. Il faut aller voir si les murlocs près du lac de Cristal n'en auraient pas en ce moment. Le lac de Cristal est à l'est de Comté-de-l’Or.", t = "À la recherche du varech"},
    [114] = {ot = "Porter la Potion d'invisibilité à Maybell Maclure.", st = "Prenez cette potion d'invisibilité pour la jeune Maybell. Les effets devraient être suffisamment longs pour qu'elle puisse rendre visite à Tommy Joe.", t = "La fuite"},
    [115] = {ot = "Apporter 3 Orbes de minuit au maréchal Marris à Comté-du-Lac.", st = "Les orcs rochenoires ont engagé des exhalombres pour les aider dans leurs attaques contre les Carmines ; ils ont emporté des orbes de minuit. Ces orbes ont infligé de graves dégâts aux défenses des Carmines et il est impératif que nous ne soyons plus confrontés à leur puissance.$B$BRetrouvez et rapportez-moi les orbes de minuit, après avoir tué les exhalombres rochenoires qui les possèdent. Je détruirai ces orbes ; le monde ne se portera que mieux sans eux !", t = "Magie des Ténèbres"},
    [118] = {ot = "Porter la Note de Verner à Argus le forgeron de Comté-de-l’Or.", st = "J'ai utilisé tellement de métal pour équiper les Gardes de Stormwind que je n'en ai même plus pour ferrer les chevaux !$B$BApportez cette note à Argus le forgeron de Comté-de-l’Or. Elle explique mon problème et lui demande une livraison de fers à cheval.", t = "Le prix des fers"},
    [119] = {ot = "Retourner chez Verner Osgood dans les Carmines et lui donner la caisse de Fers à cheval.", st = "D'accord, je lui envoie 50 fers à cheval… $B$BLes voilà, tout empaquetés et prêts à emporter ! Dites à Verner que c’est un plaisir de faire affaire, et faites en sorte qu'il trouve la facture accrochée à la caisse !", t = "Le retour chez Verner"},
    [120] = {ot = "Le magistrat Solomon vous a remis un rapport qui doit être transmis au général Marcus Jonathan de Stormwind. Il exige que vous reveniez vers lui aussitôt que vous aurez donné le message.", st = "Nous vivons un moment crucial, $c. Le bourg est assiégé. Sans renforts, nous allons succomber. Le rapport dont je vous charge est de la plus haute importance. Remettez-le au général Marcus Jonathan de Stormwind le plus rapidement possible. Dès que vous le lui aurez remis, revenez avec sa réponse, qu'elle soit bonne ou mauvaise. $b$bMaintenant hâtez-vous !", t = "Un message pour Stormwind"},
    [121] = {ot = "Porter la réponse du général Marcus Jonathan au magistrat Solomon, à Comté-du-Lac.", st = "Pendant que j'attends la réponse du roi, je veux que vous portiez cette lettre au Magistrat Solomon.$b$bRompez, $c !", t = "Un message pour Stormwind"},
    [122] = {ot = "Rassembler 6 Ecailles ventrales de dragonnet noir et les apporter à Verner Osgood dans les Carmines.", st = "J'ai besoin d'écailles ventrales de dragonnet noir pour payer les fers qu'Argus m'a envoyés de Comté-de-l’Or. Si vous pouviez m'en trouver six, je réglerais ma dette... et il m'en resterait suffisamment pour vous façonner quelque chose.$B$BLes dragonnets noirs errent souvent au sud de Comté-du-Lac, mais ils aiment aussi se balader. Vous devrez vous embusquer et les chasser quand vous les verrez.", t = "Les écailles de dragonnet"},
    [123] = {ot = "Aller voir le maréchal Dughan, à Comté-de-l’Or, et lui donner le Plan de route du Collecteur.", st = "Cette note est un tableau des heures et des jours auxquels une personne – décrite comme le \"Collecteur\" – doit recevoir une livraison d'or en provenance des mines de la forêt d'Elwynn. $B$BD'après le tableau, il semblerait que le Collecteur habite près du Champ de potirons des Brackwell, à l'est d'Elwynn. $B$BC'est une information importante. Vous devriez en faire part au maréchal Dughan de Comté-de-l’Or.", t = "Le collecteur"},
    [124] = {ot = "Tuer 10 Brutes des Carmines et 8 Mystiques des Carmines, puis retourner chez Verner Osgood.", st = "Comme si les attaques des orcs ne suffisaient pas ! Maintenant j'ai des brutes et des mystiques gnolls qui rôdent au nord de mon écurie et qui massacrent mes chevaux dès qu'ils s'éloignent...$B$BSi vous pouviez nous débarrasser de ces gnolls, mes chevaux et moi vous en serions très reconnaissants.", t = "Le hurlement des gnolls"},
    [125] = {ot = "Le contremaître Oslow de Comté-du-Lac veut que vous récupériez sa Boîte d'outils au fond du lac Placide.", st = "J'apprécierais vraiment votre aide, $n. La ville est assiégée, l'approvisionnement devient difficile. On devait me livrer des outils par chariot depuis Comté-de-l’Or, mais le pont a sauté. Nous avons alors mis les outils dans un bateau, mais les orcs l'ont touché avec une catapulte. Évidemment, ma boîte d'outils a coulé tout droit au fond du lac.$b$bRécupérez-la, $n, et je ferai en sorte que vous ne le regrettiez pas.", t = "Les outils perdus"},
    [126] = {ot = "Rapporter la patte de Couineur à Verner Osgood à Comté-du-Lac.", st = "$n, les gnolls sont toujours là. Je peux entendre leurs hurlements quand ils chassent dans les collines de Comté-du-Lac. Et l'un d'eux hurle plus fort que les autres : Couineur, leur chef.$B$BTuez Couineur et dispersez sa meute ! Rapportez-moi sa patte comme preuve.$B$BMais faites attention ! Ce gnoll n'est pas leur chef pour rien ! Ce n'est pas un bâtard !", t = "Les collines aux hurlements"},
    [127] = {ot = "Rapporter 10 Poissons-lunes au Chef des docks Baren à Comté-du-Lac.", st = "Le lac Placide est connu pour son poisson-lune. C'est un poisson qui se vend bien et j'ai justement besoin d'argent !$B$BRapportez-m'en 10 ; je paierai bien. Si vous ne savez pas pêcher, peut-être pourrez-vous en voler aux murlocs !", t = "Criée aux poissons"},
    [128] = {ot = "Tuez 15 Champions rochenoires et le garde Howe de Comté-du-Lac vous récompensera.", st = "Le clan Rochenoire doit être démantelé. L'Ennemi a envahi nos terres. Ces montagnes sont cependant sous le règne souverain du roi de Stormwind. Nos sources nous indiquent que les chefs de chaque unité du clan sont appelés des champions. Vous les trouverez dans leur campement au nord, juste à l'ouest de la route menant aux Steppes Ardentes.$B$BLe magistrat Solomon veut que ces brutes abjectes soient tuées. Tuez 15 Champions rochenoires et revenez me voir.", t = "La prime rochenoire"},
    [129] = {ot = "Apporter son déjeuner au Garde Parker. Il patrouille sur la route qui mène au Darkshire.", st = "Vous pouvez me faire une faveur ? J'ai préparé un déjeuner pour le Garde Parker, mais il est en patrouille... C'est un homme grand et fort, un Garde de Stormwind, qui peut se défendre, mais pour une citadine comme moi, c'est beaucoup trop dangereux dehors.$B$BSi vous lui apportez ce repas à ma place, revenez me voir, je vous offre un déjeuner gratuit ! Parker patrouille le long de la route qui mène au bois de la Pénombre.", t = "Un repas gratuit"},
    [130] = {ot = "Parler à Martie Jainrose, l'Herboriste des Carmines.", st = "Puisque vous retournez voir Darcy, pouvez-vous lui apporter des fleurs de ma part ? Vous en trouverez chez l'herboriste, quand vous serez de retour à Comté-du-Lac, à l'extrémité ouest de la ville.$B$BMais quand vous prendrez les fleurs, ne dites pas à l'herboriste, Martie, qui les achète, ni pour qui elles sont...", t = "Une visite chez l'herboriste"},
    [131] = {ot = "Donner à Darcy le bouquet de jonquilles.", st = "Voilà votre bouquet. J'ai choisi des jonquilles pour vous. Ce sont mes fleurs préférées !", t = "Bouquet de jonquilles"},
    [132] = {ot = "Apporter la Note de Wiley à Gryan Stoutmantle, dans la marche de l'Ouest", st = "Ce que je vais vous dire peut me coûter la vie. Le gang défias est en train de préparer un gros coup. Il paraît qu'ils se sont acoquinés avec des gnolls, des kobolds et même des gobelins.$b$bApportez ce message à Stoutmantle. Il donne tous les détails de ce que je sais à ce sujet.", t = "La Confrérie défias"},
    [135] = {ot = "Apporter la Note de Wiley à Mathias Shaw à Stormwind.", st = "Je me demande de quoi parlait Wiley quand il a mentionné les Maçons. C'était peut-être un lapsus ? Les Défias pourraient-ils être reliés aux Maçons ? Le seul qui pourrait le savoir à coup sûr, c'est Mathias Shaw, le chef du SI:7. Montrez-lui la note de Wiley et voyez s'il a quelque chose à tirer de ce mystère qui s'épaissit. Si vous avez du mal à trouver Shaw, cherchez du côté de la caserne de la vieille ville.", t = "La Confrérie défias"},
    [136] = {ot = "Trouver le Coffre du capitaine Sanders. Le fouiller pour trouver l'indice suivant.", st = "Si vous lisez ceci, c'est que le vieux capitaine Sanders repose sous six pieds de flotte. Mon trésor est à vous. Il vous suffit de suivre le jeu de piste.$b$bD'abord, trouvez mon coffre. Il doit être à moitié enterré dans le sable, depuis le temps, sur la côte de la marche de l'Ouest, à côté de l'épave. Il y a des tas d'épaves sur la côte, mais une seule ancre rouillée. Qui trouve cette ancre trouve mon coffre ! Et avec le coffre, l'indice suivant !", t = "Le trésor caché du capitaine Sanders"},
    [138] = {t = "Le trésor caché du capitaine Sanders"},
    [139] = {t = "Le trésor caché du capitaine Sanders"},
    [140] = {t = "Le trésor caché du capitaine Sanders"},
    [141] = {ot = "Apporter le Rapport de Shaw à Gryan Stoutmantle, dans la marche de l'Ouest.", st = "La Guilde des Maçons est dirigée par un homme du nom d'Edwin VanCleef. C'est lui qui a rebâti Stormwind après sa destruction par les orcs au cours de la Première Guerre. Apparemment, VanCleef et ses équipes n'ont pas apprécié la façon dont ils ont été traités par le roi à la fin de la reconstruction. Ça pourrait expliquer une ou deux petites choses.$b$bJ'ai rédigé un rapport détaillé pour ton maître, dans la marche de l'Ouest. Apporte-le-lui tout de suite !", t = "La Confrérie défias"},
    [142] = {ot = "Traquer le Messager défias dans la marche de l'Ouest et apporter les documents qu'il transporte à Stoutmantle.", st = "Nous devons débusquer les Défias de leur cache, $n. Mes éclaireurs ont rendu compte qu'un Messager Défias a été vu sur les routes entre Ruisselune, la carrière de la côte de l'Or et la mine Veine-de-Jango. Je veux que vous le capturiez. S'il résiste tuez-le et apportez-moi tout ce que vous trouverez sur lui.", t = "La Confrérie défias"},
    [143] = {ot = "Le Magistrat Solomon veut que vous portiez sa Demande d'aide à Gryan Stoutmantle dans la marche de l'Ouest.", st = "Il y a quelque chose d'étrange dans le comportement de l'armée de Stormwind. Elle devrait se trouver là en force à l'heure qu'il est. De toute façon, le temps est un luxe que nous ne pouvons pas nous offrir. Je ne resterai pas là à regarder couler le sang du peuple de Comté-du-Lac sans essayer de trouver de l'aide. J'ai entendu dire qu'une milice populaire s'était formée dans la marche de l'Ouest. $b$bApportez cette demande d'aide à leur chef, Gryan Stoutmantle. Ses hommes pourront peut-être nous apporter leur soutien en attendant que le roi envoie ses réserves.", t = "Un message pour la marche de l'Ouest"},
    [144] = {ot = "Retourner voir le Magistrat Solomon avec la Réponse de Stoutmantle.", st = "La demande du Magistrat Solomon me peine plus que je ne saurais le dire. Visiblement, il ignore que la guerre a éclaté dans la marche de l'Ouest, sinon il saurait qu'aucune aide n'est à attendre de la Milice. Si Stormwind ne nous avait pas abandonnés elle aussi, nous n'aurions pas eu besoin de la Milice.$B$BApportez cette réponse à votre maître dans les Carmines, $c. Et dites-lui que mon cœur est lourd à la pensée de la mort de tant de braves.", t = "Un message pour la marche de l'Ouest"},
    [145] = {ot = "Le magistrat Solomon veut que vous apportiez une lettre au seigneur Ebonlocke de Darkshire.", st = "Je sollicite votre aide une nouvelle fois. J'ai écrit au seigneur Ebonlocke pour lui demander de m'envoyer ses gardes les plus expérimentés, les Veilleurs, afin de renforcer les défenses de Comté-du-Lac. Il est primordial que ce message lui soit remis rapidement. Vous devez faire preuve de la plus grande vigilance. Ebonlocke est le maire de Darkshire, au cœur du bois de la Pénombre. Ne vous écartez pas des chemins.", t = "Un message pour Darkshire"},
    [146] = {ot = "Retourner voir le Magistrat Solomon avec la Lettre en réponse du Seigneur Ebonlocke.", st = "Si je ne connaissais pas personnellement le Magistrat Solomon, je penserais qu'il a perdu la tête ! Envoyer les Veilleurs à Comté-du-Lac simplement parce que Stormwind lui refuse son aide ? Nous avons dû créer le corps des Veilleurs justement parce que Stormwind nous avait abandonnés au moment où cette horrible magie a commencé à se répandre. Si j'envoie mes Veilleurs, notre région sera la proie du Mal avant même que les soldats n’aient atteint la lisière de la forêt.$B$BPortez cette lettre en réponse à votre maître à Comté-du-Lac.", t = "Un message pour Darkshire"},
    [147] = {ot = "Trouver et tuer le \"Collecteur\" puis rapporter son Anneau au maréchal Dughan.", st = "Si le \"Collecteur\" prend de l'or dans nos mines, il le vole au royaume ! Traînez-le devant la justice et apportez-moi l'anneau dont parlait le Plan de route que vous m'avez donné. Cela pourrait bien donner une indication sur l'employeur du Collecteur...$B$BCe plan de route indique que le Collecteur se cache près du Champ de potirons des Brackwell. Cherchez-le vers là-bas.", t = "Chasse à l'homme"},
    [148] = {t = "Fournitures en provenance de Darkshire"},
    [149] = {ot = "Apporter le Peigne spectral à Marie l'Aveugle.", st = "Il y a un pauvre fantôme triste, Marie l'Aveugle, qui hante une vieille ferme, dans les collines au sud de Darkshire.$B$BPrenez ce Peigne spectral et demandez-lui de peigner ses cheveux. Ensuite, rapportez-moi le peigne et j'en retirerai les cheveux nécessaires pour fabriquer la mèche.$B$BFaites attention, car des créatures des ténèbres sont terrées autour de la maison...", t = "Mèche de cheveux fantômes"},
    [150] = {ot = "Apporter 8 Ailerons de murloc au Chef des docks Baren à Comté-du-Lac", st = "Les murlocs sont en train de devenir gênants. De plus en plus de pêcheurs jettent l'ancre au large des rives du lac Placide et remontent un problème dans leurs filets ! Nous devons nous débarrasser d'eux avant qu'ils aient dévoré jusqu'au dernier poisson du lac !$B$BPartez à la chasse aux murlocs ! Rapportez-moi huit ailerons et je vous offrirai quelque chose...", t = "Les braconniers murlocs"},
    [151] = {ot = "Verna Froncebouille de la marche de l'Ouest veut que vous lui apportiez 8 Poignées d'avoine.", st = "Cette pauvre Blanchy ! Après tout ce que nous lui avons fait subir, elle est très fatiguée. Je l'ai nourrie avant que nous quittions la ferme, mais nous ne nous attendions pas à ce que le chariot nous trahisse. Si vous pouviez lui apporter quelques poignées d'avoine des champs, vous auriez ma reconnaissance.$B$BJe parie que vous pourriez en trouver un peu près des fermes de la marche de l'Ouest, si vous parvenez à éviter ces horribles machines qui ont pris possession des lieux. Vous verrez de nombreuses fermes, au sud-ouest.", t = "Pauvre Vieille Blanchy !"},
    [152] = {ot = "Tuer 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte, puis retourner voir le capitaine Grayson au Phare de l'Ouest.", st = "Vous avez probablement remarqué toutes les épaves le long de la côte. La Grande Mer est une maîtresse cruelle, en vérité. La côte de la marche de l'Ouest doit être nettoyée, afin de permettre aux marins de trouver leur chemin jusqu'à nos plages en toute sécurité. Les murlocs sont déjà assez dangereux !$b$bTuez 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte et vous recevrez une récompense.", t = "La côte n'est pas sûre"},
    [153] = {ot = "Apporter 15 Masques en cuir rouge à l'éclaireur Galiaan à la Colline des sentinelles.", st = "Les Défias bougent en permanence. Ça fait un moment que je suis leurs mouvements. J'ai remarqué que nombre des membres du gang portaient un masque en cuir rouge.$b$bApportez-moi 15 de ces masques et vous recevrez une récompense.", t = "Les masques en cuir rouge"},
    [154] = {ot = "Rapporter le Peigne spectral à Madame Eva à Darkshire.", st = "NON !$B$BPrenez-le, reprenez ce peigne, éloignez-le de moi !$B$BJe suis un monstre et personne ne peut me trouver le moindre charme !", t = "Rendre le peigne"},
    [155] = {ot = "Escortez le Traître défias jusqu'à la cache secrète de la Confrérie défias. Lorsque vous saurez où se cachent VanCleef et ses hommes, rapportez l'information à Gryan Stoutmantle.", st = "Ainsi Stoutmantle envoie quelqu'un d'aussi famélique pour me protéger ? Il faudra bien que ça aille. Tout de même, il vaudrait mieux s'entourer de quelques alliés...$B$BVous connaissez le plan, n'est-ce pas, $N ? Vous surveillez mes arrières et je vous mène à la cache des Défias. Vous feriez mieux de ne pas trop vous éloigner. Les Défias veulent ma tête à présent. S'ils me voient avec vous, ils essaieront de me tuer.$B$BPrévenez-moi quand vous aurez rassemblé quelques amis et que vous serez prêts à partir.", t = "La Confrérie défias"},
    [156] = {ot = "Rapporter 8 Racines pourries à Smitts l'aubergiste de Darkshire.", st = "Si vous m'apportez des racines pourries, je pourrai vous préparer une tournée de suc de zombie. $B$BLes racines pourries poussent dans des endroits étranges. J'ai entendu dire qu'on pouvait les trouver à l'intérieur des crânes des Démons squelettes et des Squelettes infernaux... Cela dit, je ne me suis jamais approché pour vérifier ! $B$BLe cimetière de Colline-aux-Corbeaux et celui des Jardins paisibles sont tous les deux pleins de ces squelettes. Vous pourriez nous en débarrasser tout en cherchant les racines pourries. Darkshire vous en serait infiniment reconnaissant.", t = "Cueillette de Racines pourries"},
    [157] = {ot = "Apporter la Mèche de cheveux fantômes à Abercrombie, dans sa cabane, au nord du cimetière de Colline-aux-Corbeaux.", st = "Voici votre mèche, $n. Elle a des milliers d'usages. Elle permet d'attacher les esprits maléfiques, de redonner la vie aux objets inanimés, que sais-je encore ?", t = "Apporter la mèche"},
    [158] = {ot = "S’adresser à Smitts l'aubergiste.", st = "J'ai besoin d'une bouteille d'une liqueur peu ordinaire : du Suc de zombie. Smitts, l'aubergiste de la taverne du Corbeau écarlate à Darkshire, doit pouvoir en fournir.$B$BEt dépêchez-vous, $n. Les nuits commencent à fraîchir et j'ai besoin de ce breuvage pour réchauffer le sang dans mes veines.", t = "Suc de zombie"},
    [159] = {ot = "Apporter le Suc de Zombie à Abercrombie, dans sa cabane.", st = "Voici votre Suc de zombie…$B$B… Et faites attention avec ce truc. Il est assez fort pour réveiller les morts !", t = "Livrer le Suc"},
    [161] = {ot = "L'Ingénieur en chef Hinderweir veut que vous apportiez cette étrange poudre à Stonesmirk l'Artificier à Dun Modr.", st = "Si mes soupçons sont justifiés, c'est une espèce de poudre explosive. Il faut la faire analyser par un artificier pour savoir à quoi nous avons à faire exactement. Ashlan Stonesmirk a été affecté au régiment qui garde Dun Modr et le viaduc de Thandol. Vous allez devoir faire un périlleux voyage, $n.$b$bTraversez la Porte d'Algaz, suivez la route jusqu'aux Paluns et trouvez Stonesmirk à Dun Modr. Et suivez mon conseil : ne vous éloignez pas de la route et ne vous arrêtez pour rien au monde !", t = "Une sombre menace se dessine"},
    [163] = {ot = "Découvrir ce qui hante Colline-aux-Corbeaux.", st = "Il y a quelque chose d'étrange à Colline-aux-Corbeaux, $n. Calor jure que quelqu'un (ou quelque chose) hante les bâtiments là-bas. Deux nuits de suite, il a remarqué que les ombres bougeaient et la nuit d'avant, il dit qu'il a vu de la lumière à l'une des fenêtres.$b$bSi, comme vous le prétendez, vous vous intéressez vraiment à la sécurité du bois de la Pénombre, trouvez le monstre qui hante Colline-aux-Corbeaux.", t = "Colline-aux-Corbeaux"},
    [164] = {ot = "Ravitailler Sven.", st = "Connaissez-vous Sven ? Voilà un homme fidèle à la Lumière ! Lui et ses fidèles vivent dans un camp à la lisière nord-ouest du bois de la Pénombre.$b$bMalheureusement, ils sont si peu nombreux qu'ils ne peuvent même pas dépêcher l'un des leurs pour aller en ville chercher du ravitaillement. Voudriez-vous lui apporter ceci ?", t = "Livraison à Sven"},
    [165] = {ot = "Aller voir le vieil homme dans sa cabane près du cimetière de Colline-aux-Corbeaux.", st = "Il y avait un vieil homme qui venait régulièrement en ville faire des courses, mais cela fait un moment que je ne l'ai pas vu. Il vit dans une cabane, au-dessus du cimetière de Colline-aux-Corbeaux, si je me souviens bien. Vous devriez aller voir ce qui ne va pas.", t = "L'ermite"},
    [166] = {ot = "Tuer Edwin VanCleef et apporter sa Tête à Gryan Stoutmantle.", st = "Il vous reste une dernière mission à accomplir. Il va falloir éliminer Edwin VanCleef. Bien que cela me chagrine de condamner un homme à mort, c'est pour le bien du peuple de la marche de l'Ouest que VanCleef doit mourir. Apportez-moi sa tête lorsque l'acte sera accompli.", t = "La Confrérie défias"},
    [167] = {ot = "Apporter l'Insigne de la Ligue des Explorateurs du contremaître Crispechardon à Wilder Crispechardon à Stormwind.", st = "Nous étions au plus profond d'une mine dans la marche de l'Ouest, cachés derrière un baraquement à Ruisselune. Impossible de savoir d'où viennent ces voleurs puants... Bref, la mine s'est effondrée sur nous. Je m'en suis sorti mais les autres... Enfin... On n'en a plus entendu parler. $b$bVous aurez peut-être plus de chance. Si vous arrivez à avoir des nouvelles de mon frère, je vous en serai reconnaissant. Il portait toujours son insigne de la Ligue des Explorateurs. Si vous ne le trouvez pas, mais que vous me rapportez cet insigne, cela me rendrait un peu de paix.", t = "Oh, mon frère…"},
    [168] = {ot = "Récupérer 4 Cartes du Syndicat des mineurs et les apporter à Wilder Crispechardon à Stormwind.", st = "Nombre de mes amis ont péri ce jour terrible de l'effondrement de la mine. Si vos pas vous conduisent dans cette partie de la mine de Ruisselune, voyez s’il existe des indices qui permettraient de les identifier. Si vous trouvez leurs Cartes du Syndicat des Mineurs, rapportez-les-moi et je préviendrai leurs familles.", t = "À la recherche de Cartes du Syndicat des Mineurs"},
    [169] = {t = "Avis de recherche : Gath’Ilzogg"},
    [170] = {ot = "Balir Frosthammer veut que vous tuiez 6 Troggs Mâcheroc et 6 Troggs Mâcheroc forcenés.", st = "J'espère que vous êtes là pour nous donner un coup de main, $c. Après la dernière attaque des troggs, nous avons besoin de toute l'aide possible !$b$bJe sais que ces canailles pullulent dans toutes les régions et on dirait que les Frigères ne font pas exception. On les a repérés au sud-est, partout dans les collines et à côté du lac Gelé.$b$bEt ce n'est pas tout ! Il y a à peine quelques nuits, ils ont attaqué et détruit notre camp, à l'ouest !$b$bNous sommes un peu à court de personnel, ici, $gmon gars:jeune fille;, et nous avons besoin de force et de bravoure pour renvoyer les troggs d'où ils viennent.", t = "Une nouvelle menace"},
    [174] = {ot = "Viktori Prism'Antras de Darkshire veut que vous lui apportiez un Tube en bronze.", st = "Mon ami Cog, un gnome, a promis de m'aider à construire un outil qui permet de voir les étoiles. Il semblerait qu'il existe une vérité, au-delà de la magie, qui explique les étranges changements survenus dans la forêt. $b$bApportez-moi un tube en bronze fabriqué par un ingénieur habile. C'est la première étape, si j'en crois le plan de Cog.", t = "Les yeux dans les étoiles"},
    [175] = {ot = "Trouver Marie et la persuader de prêter une surface réfléchissante pour le projet de Viktori.", st = "Selon le plan de Cog, il faut maintenant que je trouve un moyen de réfléchir la lumière. Je me souviens d'une femme du nom de Marie, bien connue par ici car elle avait l'habitude de transporter un miroir. Vous pourriez peut-être chercher Marie et voir si elle nous prêterait une surface réfléchissante pour notre entreprise ? Je crois qu'elle habitait au sud du bois de la Pénombre...", t = "Les yeux dans les étoiles"},
    [176] = {t = "On recherche : « Lardeur »"},
    [177] = {ot = "Prendre le miroir de Marie l'Aveugle à la Goule folle et l’apporter à Viktori de Darkshire.", st = "Le miroir était l'un de mes plus précieux trésors jusqu'à... l'accident. Après cela, je l'ai jeté derrière la grange. Il y avait une goule folle qui traînait souvent par là-bas. Elle l'a peut-être récupéré. La rumeur dit qu'elle vit dans le cimetière des Jardins paisibles.", t = "Les yeux dans les étoiles"},
    [179] = {ot = "Sten Stoutarm voudrait 8 Morceaux de Viande de loup coriace.", st = "Qu'est-ce que c'est ? On dirait que vous avez besoin de quelque chose pour tenir chaud aux mains, non ?$b$bJe vais vous dire ce qui vous serait utile : une paire de jolis gants bien chauds. Et comme je suis une âme charitable, je vous les fournirai. À une condition, cependant.$b$bJ'ai besoin de viande de loup. Arrangement équitable, n'est-ce pas ? Vous m'apportez de la viande et je m'assure qu'on ne sera pas obligé de vous amputer d’un ou deux doigts gelés. Qu'est-ce que vous en dites ?", t = "Tailleur chez les nains"},
    [180] = {t = "ON RECHERCHE : lieutenant Fangore"},
    [182] = {ot = "Grelin Whitebeard aimerait que vous tuiez 14 Jeunes trolls Frostmane.", st = "Mon frère Senir et moi avons voyagé dans tous les coins de Dun Morogh pour évaluer la menace posée par les trolls. Le Sénat est déjà débordé par les ennuis que causent les troggs, il n'a pas besoin de ce problème supplémentaire.$b$bDe ce que j'ai vu, les trolls sont bien installés dans la vallée des Frigères, principalement dans les grottes du sud. Je ne pense pas qu'il soit nécessaire de recourir à l'armée. Quelques hommes robustes devraient suffire.$b$bVous aimeriez peut-être vous joindre à cette campagne ? J'ai le pouvoir de vous dédommager pour votre aide.", t = "La caverne des trolls"},
    [183] = {ot = "Talin Keeneye aimerait que vous tuiez 12 Petits sangliers des rochers.", st = "Rien de tel qu'une journée de chasse au sanglier, pas vrai ?$b$bOui, eh bien ici, dans la vallée des Frigères, il y en a tellement que ça gâche tout plaisir. Pas besoin de les pousser à attaquer ! Ils sont furieux et prêts à charger sans qu'on les aide ! En fait, depuis quelque temps, il y a tellement de sangliers dans la vallée des Frigères que chasseur devient un métier à haut risque.$b$bPour faire court, si vous pouviez m'aider à tuer quelques bêtes, j'apprécierais le geste.", t = "Chasseur de sangliers"},
    [184] = {ot = "Rapporter son titre de propriété au Fermier Froncebouille.", st = "Voici un titre de propriété concernant une ferme de la marche de l'Ouest, signé par un certain Théodore Froncebouille et par sa femme, Verna. Au dos, il y a quelques mots hâtivement écrits : $B$B\"Nous avons fait pression sur Froncebouille et avons récupéré son titre pensant que ça pourrait nous être utile au cas où nous voudrions nous installer. $B$BIls ne nous embêteront pas. La dernière fois que je les ai vus, ils étaient sur la route de la marche, avec un chariot cassé.\"$B$BLes Froncebouille aimeraient sans doute récupérer leur titre...", t = "Titre de propriété de Froncebouille"},
    [199] = {ot = "Retourner voir l'ingénieur en chef Hinderweir et lui montrer l'indice que vous avez découvert.", st = "Vous devez prendre un échantillon de l'étrange poudre odorante.", t = "Une sombre menace se dessine"},
    [214] = {ot = "L'Eclaireur Riell de la tour de la Colline des sentinelles veut que vous lui rameniez 10 masques rouges en soie.", st = "Ce n'est un secret pour personne que le signe de reconnaissance du gang des Défias est un masque rouge. Mais nous avons appris que la qualité du tissu dont est fait le masque détermine le rang de celui qui le porte au sein du gang.$b$bCela étant dit, je veux que vous éliminiez autant de Défias haut placés que possible. Vous en trouverez à coup sûr dans la cachette de VanCleef. Lorsque vous en aurez terminé, ramenez-moi 10 masques rouges en soie pour me prouver leur mort, je vous remettrai alors une récompense. Bonne chance, $n.", t = "Les masques rouges en soie"},
    [216] = {ot = "Tuer 12 Vengeurs Crins-de-Chardon et 12 Chamans Crins-de-Chardon ; la plupart d’entre eux se trouvent à l’est de la grève de Zoram, dans le village des Crins-de-Chardon. Retourner voir Karang Amakkar, à l’avant-poste de Zoram'gar, à Ashenvale, une fois que vous aurez terminé.", st = "Les furbolgs Crins-de-Chardon sont devenus un danger qui menace notre expansion ! Le village des Crins-de-Chardon, à l'est, nous bloque la route menant au poste de Bois-brisé. Par ce chemin, nous pourrions contourner le village d'Astranaar. D'un autre côté, il offrirait à l'Alliance une voie d'accès supplémentaire par où poursuivre son expansion.$B$B$n, nous ne pouvons pas tolérer... que se forme ainsi un chemin facilitant leur campagne d'expansion !$B$BAllez au village des Crins-de-Chardon et réduisez le nombre des furbolgs. Vous recevrez une récompense en échange de ce travail ; mais surtout, vous ferez votre devoir au service de la Horde !", t = "Entre un roc et un Crin-de-Chardon"},
    [217] = {ot = "Tuer le chef des troggs, Grawmug, et ses deux gardes, Grinceur et Bagarreur, puis rendre compte de la situation au capitaine Rugelfuss à la Tour de garde méridionale.", st = "$n, nos éclaireurs ont identifié le chef des troggs qui a mené la récente incursion que nous avons subie. Il semble que ces bêtes du Loch Modan répondent aux ordres d'un certain Grawmug. Celui-ci est bien protégé. Deux de ses meilleurs gardes, Grinceur et Bagarreur, ne le quittent pas une seconde.$b$bSi vous vous en sentez capable, $n, j'aimerais que vous acceptiez la mission visant à assassiner Gramwug et ses deux acolytes. Une fois la direction des troggs décapitée, nous aurons peut-être une chance de renvoyer ces monstres sous terre.", t = "À la défense des terres du roi"},
    [218] = {t = "Le journal volé"},
    [219] = {ot = "Protéger le caporal Keeshan sur le chemin des Carmines.", st = "Enfin, des amis de l'Alliance !$B$BAu secours… Je vous en prie… $B$BLa dernière chose dont je me souviens est que les orcs ont submergé nos forces. La plupart des hommes ont été tués. J'ai reçu un coup terrible à la tête et tout s'est assombri. Je suis à présent prisonnier dans cette caverne. Au secours, je suis gravement blessé !$B$BJ'aurais besoin d'aide pour revenir jusqu'à la ville... par pitié... vous êtes mon seul espoir...", t = "Porté disparu"},
    [220] = {ot = "Apporter la Fiole d'eau la plus pure à Islen Waterseer dans les Tarides.", st = "Islen aura une nouvelle tâche à vous confier avant de vous récompenser d'un totem. La fiole d'eau que je vous ai donnée est nécessaire à l'accomplissement de cette tâche.$B$BPartez à présent et trouvez-la. Nous nous reverrons dans le futur.", t = "L'appel de l'eau"},
    [224] = {ot = "Le Montagnard Cobbleflint de la Tour de garde méridionale veut que vous tuiez 10 Troggs et 10 Eclaireurs Brisepierre.", st = "Nous devons protéger le Loch, $n ! Avec tant de soldats du roi combattant vaillamment sur des champs de bataille lointains, les forces nous manquent à l'intérieur. Les troggs nous envahissent depuis la plus petite brèche et constituent la menace principale qui pèse sur Forgefer. Ces répugnants mutants doivent être annihilés.$b$bNous avons besoin de vous, $gbrave aventurier:courageuse aventurière;, pour mener une expédition et amener le chaos dans leurs rangs. Tuez 10 Troggs et 10 Eclaireurs parmi les Brisepierre.", t = "À la défense des terres du roi"},
    [226] = {ot = "Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre.", st = "Sven et moi avons de difficiles journées qui nous attendent, avec ce Nécromancien à l'est et tout le reste. Et ici, isolés comme nous le sommes, nous devons chasser pour nous procurer de la nourriture. Il semble que chaque fois que je rentre au campement avec un peu de viande sur moi, des loups sauvages affamés ou enragés me poursuivent en quête d'un morceau. Cela va sans dire que vivre ici est une tâche ardue !$B$BMais si vous pouviez nous débarrasser de ces loups, vous nous rendriez les choses un peu plus simples. Ils rôdent pour la plupart au nord et à l'est d'ici, près de la rivière.", t = "Des loups aux trousses"},
    [230] = {ot = "Apporter à Sven le Livre de la ferme de Sven.", st = "En creusant, vous trouvez un petit livre, plein de terre.$B$BIl ne porte pas de titre, mais il contient des informations que Sven aimerait connaître.", t = "Le camp de Sven"},
    [233] = {ot = "Apporter la pile de lettres à Talin Keeneye.", st = "Hum, je ne pense pas que vous seriez $gprêt:prête; à me rendre un petit service, si ? Une pile de lettres est arrivée au tri aujourd'hui, mais je n'ai pas le temps de les distribuer.$b$bElles ont toutes pour destinataire un dénommé Talin Keeneye. Vous pouvez le trouver à l'ouest, sur la route. Il a établi son camp près du lac Gelé.$b$bQu'en dites-vous ?", t = "La distribution du courrier de la Vallée des Frigères"},
    [234] = {ot = "Remettre la lettre à Grelin Whitebeard.", st = "Si je me souviens bien, le camp de Grelin se trouve plus bas sur la route, vers le sud-est. Il ne fait aucun doute qu'il serait ravi de recevoir ce courrier.", t = "La distribution du courrier de la Vallée des Frigères"},
    [237] = {ot = "Le Montagnard Gravelgaw de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir.", st = "Le Montagnard Cobbleflint n'a pas tari d’éloges à votre égard, $n. Aussi, je vais vous confier une mission de la plus haute importance. Nous devons maintenir la pression sur les forces d'invasion des troggs jusqu'à ce que les nains, nos frères, reviennent du front de l'Alliance. $b$bMettez-vous en route pour les collines méridionales et tuez 10 Brise-crâne et 10 Prophètes Brisepierre. Vos attaques nous feront gagner un temps précieux. Revenez me voir une fois votre mission menée à bien.", t = "À la défense des terres du roi"},
    [239] = {ot = "Se rendre à la garnison du ruisseau de l'ouest et parler à l’Adjoint Rainer.", st = "La garnison basée sur notre frontière à l'ouest fait état d'une augmentation de l'activité des gnolls et des voleurs. Elle demande plus de soldats de Stormwind, mais nous ne pouvons nous passer d'aucun !$B$BSi vous le pouvez, votre aide sera la bienvenue. Allez voir l’Adjoint Rainer à la garnison du ruisseau de l'ouest. Il vous dira de quoi il s'agit.$B$BLa garnison se trouve le long de la route, à l'ouest. Après avoir traversé le pont au-dessus du ruisseau, ce sera sur la droite.", t = "Au secours de la garnison du ruisseau de l'ouest !"},
    [240] = {ot = "Retourner voir la Tremblotte avec des Gâteaux au crabe brun.", st = "Et nous y voilà. Des gâteaux au \"crabe\" façon Grual.", t = "Retour vers la Tremblotte"},
    [244] = {ot = "Informer l’Adjoint Feldon.", st = "Je vous salue, $c. On m'a chargé de patrouiller sur ce bout de route. Bien qu'elle soit sûre pour l'heure, j'ai vu des campements de gnolls au nord et à l'est d'ici.$B$BComté-du-Lac doit être mise au courant de ce rassemblement de forces ! Allez voir l’Adjoint Feldon et informez-le. Faites-le, et je suis sûr qu’il vous offrira la prime d'un éclaireur. $B$BD'ordinaire, Feldon inspecte les lieux au sud du pont menant à Comté-du-Lac.", t = "Des gnolls encombrants"},
    [245] = {t = "Les plaies à huit pattes"},
    [246] = {ot = "Tuer 10 Bâtards des Carmines et 6 Braconniers des Carmines, et aller faire un rapport à l’Adjoint Feldon à Comté-du-Lac.", st = "Nous ne pouvons nous passer de personne, la présence de chacun est vitale ici. Pourtant, quelque chose doit être fait à propos de ces gnolls dont vous m'avez parlé.$B$BPartez à leur recherche, au sud des Carmines. Harcelez-les, tuez tous ceux que vous pouvez et revenez m'informer de leur nombre et du danger potentiel qu'ils représentent. Vous trouverez le camp des gnolls le long de la route sud des Carmines.$B$BFaites-le pour l'armée de Stormwind, $n, et vous serez $grécompensé:récompensée;.", t = "L'appréciation du danger"},
    [247] = {t = "La chasse achevée"},
    [248] = {ot = "Monter au sommet de la Tour de garde intacte près du Donjon de Guet-de-pierre, puis trouver dans quoi placer le Glyphe d'Azora.", st = "J'ai observé la Tour d'Ilgalar, et ai découvert que Morganth est entré en conflit avec les orcs au donjon de Guet-de-pierre. Je n’en connais pas la raison, mais vous pourriez m'aider à lever le voile sur ce mystère.$B$BPrenez donc le Glyphe d'Azora, et rendez-vous au sommet de la Tour de garde restée intacte, près du donjon de Guet-de-Pierre.$B$BLà, trouvez un objet dans lequel placer le glyphe. Un coffre, une jarre, qu'importe, pourvu que le glyphe ne puisse pas être détecté.", t = "En regardant plus loin"},
    [250] = {t = "Une sombre menace se dessine"},
    [255] = {ot = "Le magistrat Bluntnose de Thelsamar vous a $gembauché:embauchée; pour tuer 4 Ogres, 4 Brutes et 4 Massacreurs Mo'grosh.", st = "Deux mois d'attente, et pour apprendre que seule une poignée d'hommes sera dépêchée ici, et qu'il lui faudra deux autres mois pour arriver ! Je comprends que notre ville risquerait d’être sans protection, mais le site de fouilles et le barrage – le barrage ! – sont également l’objet d’attaques.$b$bJe n'ai pas le choix, je vais devoir embaucher des mercenaires.$b$bQu'en pensez-vous ? Vous semblez faire l'affaire, $c. Un groupe d'ogres s'est établi au nord-est du lac. Vous pourriez peut-être recruter d'autres mercenaires et nous débarrasser de la menace qui pèse sur notre ville?", t = "Mercenaires"},
    [257] = {t = "La fanfaronnade d'un chasseur"},
    [258] = {ot = "Tuer 5 Anciens sangliers des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en 12 minutes.", st = "$naf, c'est ça ? Je vois que vous exultez pour avoir réussi le premier test, pas vrai ? Comme je vous l'ai dit, ce n'était pas grand-chose.$b$bVous devriez vous essayer à la chasse au sanglier. Croyez-moi, cela n'a rien à voir avec la chasse au sanglier de la Vallée des Frigères, alors prenez vos précautions. Vous n'aurez que douze minutes cette fois-ci.$b$bEt ne soyez pas $gdéçu:déçue; en cas d’échec. Je vous donnerai ma chemise si vous réussissez !$b$bÀ propos, je vous ai déjà raconté comment j'ai reçu ma célèbre cicatrice ? Non ? C'était il y a deux ans...", t = "Le défi d'un chasseur"},
    [262] = {ot = "Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Darkshire.", st = "Je dois savoir qui était ce rôdeur que j'ai vu dans les ombres, la nuit où ma famille a été tuée !$B$BJe vous en prie, $n, vous avez montré que vous êtes $gplein:pleine; de ressources, trouvez cet individu. Je dois apprendre les secrets qu'il détient !$B$BJe n'ai aucun autre indice que vous ne connaissiez déjà, mais tenez, prenez le livre que vous avez trouvé à la ferme. Peut-être quelqu'un pourra-t-il faire un lien entre ce livre et son propriétaire.", t = "L'obscure silhouette"},
    [263] = {ot = "Le Montagnard Wallbang de la Tour de garde méridionale veut que vous tuiez 10 Chamans et 10 Briseurs d'Os Brisepierre.", st = "Les Montagnards disent que vous êtes $gcourageux:courageuse; et $gcompétent:compétente;, $n. Nous avons besoin de gens tels que vous ici. Le problème avec les troggs ne s'arrange pas. Les réservistes ont été envoyés à la guerre et nous sommes seuls. Mais à présent que nous avons un $c expérimenté comme vous, $n, nous allons voir de quoi vous êtes capable.$b$bSortez et tuez 10 Chamans et 10 Briseurs d'Os Brisepierre. Nous allons voir si votre réputation est fondée, $gtueur de: tueuse de; troggs.", t = "À la défense des terres du roi"},
    [264] = {t = "Jusqu'à ce que la mort nous sépare"},
    [265] = {t = "L'obscure recherche se poursuit"},
    [266] = {ot = "Chercher à l'auberge des indices concernant l'obscure silhouette.", st = "Voici votre livre, et bonne chance dans votre quête.$B$BVous devriez aller jusqu'à l'auberge. Si celui que vous recherchez a passé quelque temps en ville, on l’a peut-être vu là-bas.", t = "Une enquête à l'auberge"},
    [267] = {ot = "Apporter 8 Dents de pierre de troggs au capitaine Rugelfuss à la Tour de garde méridionale.", st = "$C, il se peut que vous ayez entendu parler de la menace que les troggs font peser sur les nains. Les réservistes ayant été appelés pour servir sur le front de l'Alliance, nous nous retrouvons avec bien peu de forces pour assurer la sécurité de nos terres. Mon régiment a pour mission de garder la porte, ici, et nous ne pouvons quitter notre poste, nous craignons trop une invasion.$b$bMais nous devons attaquer ces maudits troggs, qui se terrent dans les collines. Si vous vous en sentez capable, lancez un assaut contre eux. Ramenez-moi 8 Dents de pierre de trogg comme preuve de votre réussite.", t = "La menace trogg"},
    [268] = {ot = "Retourner voir Sven avec le journal complété de la Tremblotte.", st = "Le livre que vous avez trouvé n'était écrit qu'à moitié. J'ai dû le laisser à l'exploitation de Sven lorsque je me suis enfui jusqu'ici…$B$BTenez, prenez la version complète de mon journal et donnez-la à Sven. Il décrit de manière plus exhaustive ce qu'il s'y est déroulé.$B$BCe journal a été ma seule compagnie durant ces dernières semaines, mais je vous le donne volontiers si cela m'épargne d’affronter Sven et sa colère.", t = "Retourner voir Sven"},
    [269] = {ot = "Donner le journal complété de la Tremblotte à l'évêque Farthing à Stormwind.", st = "Rendez-vous à la cité de Stormwind et parlez à l'évêque Farthing dans la cathédrale de la Lumière. Donnez-lui le journal de la Tremblotte et dites-lui que vous voulez combattre Morbent Fel.$B$BBien que Stormwind ait abandonné Darkshire, Farthing est un homme aimable et empli de sagesse. Il pourrait vous aider dans votre quête pour nous sauver.$B$BVotre mission est périlleuse, mais hâtez-vous, $n. À chaque heure qui s'écoule, le bois de la Pénombre s'assombrit encore...", t = "À la recherche de la sagesse"},
    [271] = {ot = "Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Blanc-bec au pavillon des pérégrins.", st = "Je suppose que vous ne seriez pas contre le fait de rabattre un peu le caquet de Monsieur le Brave ? Daryl a une certaine habileté, il nous le rabâche assez.$b$bIl y a un an, un grand ours était dans le collimateur du pavillon des pérégrins, mais pas un chasseur ne réussissait à le tuer. Alors Daryl s'est dit qu'il allait s'en occuper. La seule chose qu'il y a gagnée, c'est cette vilaine cicatrice à l’œil.$b$bTuez cet ours, ça clouera le bec de Daryl, pour une fois.$b$bVous trouverez cet ours, le vieux Noiraud, près de sa tanière dans les collines, au-delà de Thelsamar.", t = "La vengeance de Vyrin"},
    [272] = {ot = "Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.$B$BReformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire ceci.$B$BApporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.", st = "Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L'autre moitié emprunte à l'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.$B$BAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Starblaze.", t = "L'épreuve du lion de mer"},
    [273] = {ot = "Aller voir Huldar.", st = "Cependant, il n'est pas trop tard, votre aide est la bienvenue pour prêter main-forte à Huldar. Il ne peut pas être très loin : aussi forts qu'ils soient, Miran et Saean ne peuvent pas se déplacer très vite avec les barils dont ils sont chargés.$b$bIls ont pris la route habituelle pour aller au site, celle qui suit la courbe du lac au sud de la ville.$b$bÇa ne devrait pas poser de problème de les rattraper à moins qu'ils ne soient déjà arrivés.", t = "Approvisionnement du site de fouilles"},
    [275] = {ot = "Tuer 12 Rampants des tourbières, puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns.", st = "Je ne sais pas pourquoi, mais il y a une prolifération maligne dans les Paluns. Les rampants des tourbières se manifestent. Ils sont malades et répandent leur fièvre partout. Pour circonscrire l’épidémie, ils doivent être dispersés et renvoyés dans les marécages.$B$BLes rampants des tourbières divaguent dans les voies navigables des Paluns.", t = "Fièvre sur le pays"},
    [276] = {t = "Piétinements de pattes"},
    [277] = {t = "Feu interdit"},
    [279] = {ot = "Tuer 12 murlocs Branchies-bleues.$B$BTuer Enfourneur et prendre sa tête.$B$BL'apporter à Karl Boran au port de Menethil.", st = "Les murlocs sortent des eaux profondes et construisent leurs villages sur le littoral. Ils harcèlent nos pêcheurs et nos marchands, et il faut les arrêter.$B$BL'un de ces murlocs, Enfourneur, tend des embuscades aux marchands le long de la route, avec d'autres Branchies-bleues, et va ensuite se réfugier dans les taudis voisins. Nos marchands sont en danger et nous sommes prêts à payer pour les protéger.$B$BEnfourneur rôde le long du fleuve au nord d'ici. Trouvez-le, éliminez sa famille et apportez-moi sa tête.", t = "Griffes des profondeurs"},
    [281] = {ot = "Rechercher les caisses et les barils dans les camps murlocs le long de la côte.", st = "Il y a peu de temps, un navire marchand, le \"Princesse aveugle\" a été attaqué par les murlocs. Tout ce qui n’intéressait pas les créatures a été jeté par-dessus bord, à commencer par une statuette de très grande valeur de Terenas Menethil. Nous voulons retrouver cette statuette.$B$BRecherchez des caisses, des barils et autres éléments de la cargaison perdue le long de la côte ou dans les taudis des murlocs. Retrouvez la Statuette de Menethil et rendez-la-moi.", t = "Récupération de marchandises"},
    [282] = {t = "Les observations de Senir"},
    [284] = {ot = "Rechercher la Statuette de Menethil.", st = "Vous avez fouillé avec soin les taudis murlocs dans ce secteur et vous n'avez trouvé aucune trace de la Statuette de Menethil.$B$BIl y a peut-être davantage d'indices dans les deux taudis qui se trouvent tout près de vous au nord et au nord-est.", t = "La recherche continue"},
    [285] = {ot = "Continuer à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil.", st = "L'inspection minutieuse de ces quelques taudis murlocs n'a rien donné.$B$BMais le prochain indice sera le bon.$B$BL'un des taudis qui se situent au nord doit cacher la Statuette de Menethil !", t = "À la recherche d'autres taudis"},
    [286] = {ot = "Apporter la Statuette de Menethil à Karl Boran.", st = "Une fois le baril sorti de la boue et ouvert, on y trouve une figurine argentée empaquetée avec soin dans la paille. Elle représente un jeune paladin aux cheveux longs, qui brandit un marteau.$B$BCe doit être la Statuette de Menethil ! Vous devez maintenant l’apporter à Karl Boran au Port de Menethil.", t = "Rapporter la statuette"},
    [287] = {ot = "Explorer le repaire des Frostmane et tuer 5 Chasseurs de tête Frostmane pour Senir Whitebeard à Kharanos.", st = "Je suis sur mon rapport et j'ai besoin de votre aide, $n. Je viens juste de trouver où se cachent les trolls, mais ils sont si nombreux que j'ai peur d'y aller.$b$bVoici ce que j'attends de vous... Allez à la grotte, entrez, tuez quelques trolls et revenez ici.$b$bPrenez la route au nord de Kharanos, puis quand vous arriverez au pont, longez la rivière gelée par l'ouest jusqu'au Lac glacial. Vous trouverez le village de Brassetout sur la rive ouest. Leur repaire est au sud-ouest du village.", t = "Le repaire des Frostmane"},
    [288] = {t = "La IIIe flotte"},
    [291] = {ot = "Livrer le rapport de Senir au Sénateur Barin Redstone à Forgefer.", st = "Excellent ! Apportez mon rapport au Sénateur Barin Redstone. C'est un type plutôt aigri, alors ne vous laissez pas impressionner. Il est à Forgefer, dans la salle où se tient la cour du roi Magni.$b$bVous ne connaissez pas la route pour Forgefer ? Prenez la route au nord de Kharanos, traversez le pont, suivez ensuite la route de l'est – il y a de grandes bannières le long de la route – jusqu'en haut de la montagne.$b$bCela dit, si vous pouviez éviter de raconter que vous m'avez aidé... Je ne veux pas qu'ils pensent que je ne bosse pas assez dur ici, vous comprenez ?", t = "Les rapports"},
    [294] = {ot = "Sur ordre d'Ormer Ironbraid à l'Excavation de Whelgar, tuer 10 Hurleurs tachetés et 10 Raptors tachetés.", st = "La situation est grave, c’est certain. Les raptors ont été attirés par les ossements. Ces sales bêtes ont tué mes compagnons et nous ont coincés ici, Merrin, le pauvre prospecteur et moi.$b$bAidez-nous à nettoyer les Paluns de ces raptors, $n. Il y a des raptors tachetés et des hurleurs tachetés à l’ouest. Tuez-en 10 de chaque, si vous le pouvez.$b$bCe sera un bon début à la vengeance que je leur réserve.", t = "La vengeance d'Ormer"},
    [297] = {t = "Réunir les idoles"},
    [298] = {ot = "Apporter le Compte rendu d'avancement d'Ironband à Jern Hornhelm à Thelsamar.", st = "Je dois envoyer un compte rendu d'avancement à Thelsamar et une nouvelle demande pour avoir plus d'explosif ! Voici le rapport. Portez-le à Jern Hornhelm. C'est notre contact local à Thelsamar.$B$BCe n'est pas une tâche difficile, mais ça doit être fait.", t = "Compte rendu d'avancement des fouilles"},
    [301] = {ot = "Porter le Compte rendu d'avancement d'Ironband au Prospecteur Foudrepique.", st = "Nous aurons besoin d'une autorisation pour fournir à Ironband plus d'explosif. Vous devrez apporter son rapport au quartier général de la Ligue des Explorateurs à Forgefer.$B$BVoici ce rapport. Donnez-le au Prospecteur Foudrepique et mettez-vous à l'abri juste après ! Foudrepique est impétueux et il ne sera pas ravi d'apprendre qu'Ironband ne progresse que lentement sur le site.$B$BVous trouverez Foudrepique à l'Assemblée des Explorateurs.", t = "Rapport à Forgefer"},
    [302] = {ot = "Parler à Jern Hornhelm à Thelsamar.", st = "Si Ironband a encore besoin d'explosif, par Magni, alors il l'aura ! J'ai envoyé un messager à Thelsamar avec une autorisation pour Jern Hornhelm. Il préparera la poudre et du matériel à remettre à Ironband.$B$BEncore une chose : je veux que vous assuriez personnellement la livraison pour que l'explosif arrive à bon port. Le dernier chargement n'y est pas arrivé, alors gardez l'esprit vif et les yeux ouverts.", t = "De l'explosif pour Ironband"},
    [303] = {t = "La guerre contre les Sombrefer"},
    [305] = {t = "À la recherche de l’équipe de fouilles"},
    [306] = {t = "À la recherche de l’équipe de fouilles"},
    [307] = {t = "Bas les pattes !"},
    [308] = {t = "Distraire Jarven"},
    [309] = {ot = "S'assurer que Miran et la cargaison parviennent au Site de fouilles puis en informer le Prospecteur Ironband.", st = "Prêt à y aller, $n ?$b$bD'abord, nous devons trouver de l'explosif pour Ironband. Je ne pourrai pas le porter seul, d'autant que ça peut être dangereux – et qui sait ce que les Sombrefer me réservent ?$b$bJe me sentirais mieux si vous m'accompagniez.", t = "Protection de la cargaison"},
    [310] = {ot = "Aller au sous-sol de la distillerie Thunderbrew à Kharanos et remplacer un Tonneau de Thunder Ale par un Tonneau de Barleybrew Scalder.", st = "Je dois admettre que ces Thunderbrew font quelques bonnes boissons. Mais il faut qu’ils comprennent qu'ils ne sont pas les seuls brasseurs ! Vous pouvez peut-être m'aider à faire passer le message... $B$BTenez, prenez ce tonneau de Barleybrew Scalder. Glissez-vous dans le sous-sol de la distillerie Thunderbrew, à Kharanos, et échangez-le avec un de leurs tonneaux de Thunder Ale. Nous verrons bien si leurs clients préfèrent leur recette ou la mienne !$B$BBien sûr, si les tonneaux sont gardés, il faudra peut-être distraire le garde...", t = "Bières rivales"},
    [311] = {ot = "Apporter le Tonneau de Thunder Ale à Marleth Barleybrew au Village de Brassetout.", st = "Après avoir mis un tonneau de chez Marleth Scalder dans la cave de la Distillerie Thunderbrew, vous emportez un Tonneau de Thunder Ale pour prouver que vous l'avez vraiment fait...", t = "Retour chez Marleth"},
    [312] = {ot = "Récupérer la caisse de viande séchée de Tundra MacGrann dans la Caverne du Vieux Barbeglace.", st = "J'avais un mois de réserves de viande séchée et salée que j'avais stockées pour la saison froide. C'était hors d'atteinte des ours, dans une caisse fermée ! Mais pendant que j'étais à la chasse au daim, cette bête, le Vieux Barbeglace, est venue et repartie avec ma caisse de viande. Il ne sera pas capable de défoncer le thorium de la caisse. Mais je vais mourir de faim si je ne peux pas récupérer mes réserves de viande.$B$BVous semblez plus discret que moi. Peut-être parviendrez-vous à récupérer ma caisse ? Je n'arriverai jamais à entrer et sortir assez vite de cette caverne avec ma jambe qui se traîne.", t = "La réserve volée de Tundra MacGrann"},
    [313] = {ot = "Réunir 8 Peaux de Wendigo et les apporter au Pilote Stonegear.", st = "La conduite d'une machine de siège n'est pas à la portée de n'importe qui. Il faut une poigne de fer et des nerfs d'acier... Par chance, j'ai les deux ! Et vous ? De quel bois êtes-vous fait ? Vous voulez le prouver ?$B$BBon... Je cherche comment rendre mon engin, le \"Moissonne-trolls\", un peu plus confortable. Et si vous alliez me chercher quelques peaux de Wendigo dans l'Antre Gris, à l'ouest de Kharanos ? On pourrait en tapisser le pont intérieur de ma machine !", t = "L'antre Gris"},
    [314] = {ot = "Sur demande de Rudra Amberstill, tuer Vagash et rapporter un de ses crocs à la ferme des Amberstill.", st = "Nous avons entendu des cris au milieu de la nuit. Et ce matin, il manquait deux béliers dans le troupeau. C'est cette bête poltronne connue sous le nom de Vagash qui s'en est prise à notre gagne-pain. Vu que la grande partie de l'armée du roi Magni est loin d'ici, en train de se battre avec l'Alliance, il n'y a personne pour tenir Vagash à distance.$b$bVous avez peut-être assez de courage pour poursuivre la bête et la tuer. Apportez-moi un de ses crocs et je vous récompenserai. Vagash se cache juste au-dessus du ranch, mais soyez $gprudent:prudente;, il est très dangereux.", t = "Protection du troupeau"},
    [315] = {ot = "Apporter 6 Brins de chatoyante à Rejold Barleybrew au village de Brassetout.", st = "Je cherche à faire la bière parfaite. Je sais que je peux le faire : le brassage, j'ai ça dans le sang. Je dois juste trouver la bonne recette...$B$BLes trolls Frostmane cultivent une plante, la chatoyante, en haut des collines à l'est. Ils l'utilisent dans les rituels de leur tribu. Nous les nains, nous ne lui avons pas trouvé d'usages, mais elle a un goût unique... Et je veux essayer !$B$BApportez-moi de la chatoyante qu'utilisent les Prophètes Frostmane, ou piquez-en dans les paniers à chatoyante des trolls.", t = "La bière parfaite"},
    [317] = {ot = "Réunir 4 morceaux de Viande de sanglier et 2 Fourrures d'ours épaisses et les livrer au pilote Bellowfiz au dépôt de Steelgrill.", st = "Je me prépare à entamer une mission pour la brigade des Sapeurs. C'est une longue mission et j'ai besoin de ravitailler le Crache-vapeur avec l'équivalent d'un mois de provisions. Alors pendant que Steelgrill travaille sur mon réservoir, pouvez-vous aller chasser pour moi ?$B$BJ'ai besoin de fourrure pour nos lits et de viande pour nous nourrir. Vous pouvez rapporter de la viande de sanglier et de la fourrure d'ours... Vous trouverez l'un et l'autre dans les terrains enneigés au sud de l'Antre Gris.", t = "Ravitailler le Crache-vapeur"},
    [318] = {t = "L’Evershine"},
    [319] = {ot = "Tuer 6 Ours Griffeglace, 8 Anciens sangliers des rochers et 8 Léopards des neiges, puis retourner voir Rejold Barleybrew à Brassetout.", st = "J'ai un tonneau d'Evershine sous la main, mais... Pouvez-vous me faire une faveur ? Mon village aurait besoin d'un coup de main pour se débarrasser des animaux sauvages qui errent dans les neiges voisines. Parfois ils rôdent tout près.$B$BNous n'avons pas peur de ces oursons, de ces chats et de ces cochons – aucun nain digne de ce nom n'en aurait peur – mais si vous pouviez vous occuper de ces bestioles, nous aurions plus de temps pour travailler.", t = "Une faveur pour un tonneau d’Evershine"},
    [320] = {ot = "Donner le Tonneau d'Evershine au Pilote Bellowfiz au Dépôt de Steelgrill.", st = "Voici votre tonneau d'éternol, $n. Et merci encore pour la partie de chasse.", t = "Retour vers Bellowfiz"},
    [323] = {ot = "Tuer 15 Ecumeurs squelettes, 3 Soigneurs squelettes et 3 Gardiens squelettes puis retourner voir Sven.", st = "Morbent Fel est un nécromancien, allié des Cavaliers noirs. Je pourrais vous envoyer combattre Morbent Fel, mais je dois d’abord tester votre force avant que vous ne luttiez contre un tel adversaire.$B$BVous avez déjà prouvé votre bravoure, mais si vous voulez vraiment affronter le nécromancien, vous devez d’abord montrer votre valeur contre ses sbires.", t = "Prouver votre valeur"},
    [337] = {t = "Un vieux livre d'histoire"},
    [343] = {t = "En parlant de fermeté"},
    [344] = {t = "Frère Paxton"},
    [345] = {t = "Provisions d'encre"},
    [346] = {t = "Retourner voir Frère Kristoff"},
    [347] = {ot = "Réunir 5 charges de Minerai de rethban et les apporter à Frère Paxton à la bibliothèque de Comté-du-Nord.", st = "Le minerai de rethban a été découvert par Bart Rethban. Lorsqu’il est fondu, ce minerai est moins dur que le fer, mais il possède une essence que certains scribes utilisent comme encre. Il peut être trouvé dans les Cavernes de Rethban, plus au nord.$B$BNous en avons normalement en réserve, mais devant nous préparer aux attaques des orcs, nous n'avons pas eu le temps d'en collecter dernièrement. De plus, les gnolls des Carmines occupent maintenant les cavernes de Rethban et leurs manouvriers y exploitent le minerai eux-mêmes.$B$BSi vous voulez en collecter, vous devrez le faire par vos propres moyens.", t = "Minerai de rethban"},
    [350] = {ot = "Parler à Elling Trias à Stormwind.", st = "Ce Marzon va contacter un Défias et il est lié à Lescovar...$B$BEn ayant tué VanCleef et Thredd, il va être difficile de traîner en justice Lescovar, vu que vos preuves ne valent rien sans leurs témoignages. Sans compter que Lescovar est un noble et qu'il a de nombreux appuis. Il est ainsi au-dessus des lois.$B$BVous avez besoin d'une autre aide. Je répugne à le faire, mais voici quelqu'un que je connais et qui peut nous aider. Vous trouverez Trias dans le Quartier commerçant de la cité.", t = "Le point de vue d'un vieil ami"},
    [353] = {ot = "Livrer le Paquet au montagnard foudrepique au Loch Modan.", st = "Les Foudrepiques sont un clan nain respecté et connu pour ses goûts raffinés et subtils. Ce n'est donc pas surprenant que Gringer Foudrepique, un montagnard de Forgefer, m'ait demandé de lui fabriquer une arme.$B$BL'arme est terminée, mais Gringer vit loin d'ici, près du Loch Modan. Si vous projetez de voyager vers le nord, pouvez-vous lui livrer ce paquet ?$B$BSon dernier message disait qu'il se trouvait à la Tour de garde nord du Loch Modan.", t = "Livraison pour Foudrepique"},
    [354] = {ot = "Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill.", st = "Les Agamand étaient la famille la plus prospère des Clairières de Tirisfal. Je travaillais dans leurs moulins... avant la Peste.$B$BQuand le Fléau est apparu, les Agamand ont fortifié leur maison et convaincu leurs employés de rester et de les aider à se défendre. Nous étions des imbéciles, mais au moins nous étions des imbéciles loyaux.$B$BLes Agamand, à cause de leur orgueil, nous ont condamnés. Et maintenant le Fléau a fait d'eux ses favoris !$B$BServez ceux qui ont été abandonnés en vainquant les Agamand qui sont tombés du côté de la Peste. Servez-moi en m'apportant leurs restes.", t = "Morts dans la Famille"},
    [355] = {ot = "Parler au magistrat Sevren à Brill.", st = "Vous m'avez ramené les restes des Agamand et satisfait mon désir de vengeance. Mais les Moulins d'Agamand sont une menace pour tous les Réprouvés, pas seulement moi.$B$BJ'ai parlé au Magistrat Sevren de vos exploits contre les Agamand et il désire vous parler.", t = "Parler à Sevren"},
    [356] = {ot = "Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds, puis revenez voir Linnea, à son camp.", st = "Les défenseurs de la Barricade protègent Tirisfal des Maleterres et sont en alerte permanente. Mais parfois, le Fléau arrive à s’infiltrer.$B$BNotre succès à la Barricade dépend d’un front uni. Nous ne pouvons nous permettre d’être attaqués par l’arrière ou de voir les lignes d’approvisionnement des défenseurs coupées.$B$BRenforcez la Barricade. Patrouillez à l’est et détruisez toutes forces du Fléau que vous rencontrerez. Portez un effort particulier sur la ferme des Balnir. C’est devenu un havre pour les forces du Fléau qui maraudent dans le secteur.", t = "Patrouille d'arrière-garde"},
    [357] = {ot = "Rapporter le livre de sorts de la Liche et le donner à Bethor Iceshard à Fossoyeuse.", st = "Une liche réside dans l'île au nord du lac Etincelant. Bien qu'elle soit une Réprouvée sauvage, elle croit que tous les autres morts-vivants sont des esclaves du Fléau et envoie ses serviteurs attaquer quiconque s'approche d'elle.$B$BMais parce que c'est une Réprouvée, la Reine la veut. Et si elle est douée dans les arts de la nécromancie, son savoir serait réellement utile à notre cause.$B$BPour connaître son identité et ses capacités, j'ai besoin d'étudier son livre de sorts. Infiltrez-vous dans son camp, prenez-le livre et ramenez le moi.", t = "Le Nom de la Liche"},
    [358] = {ot = "Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides. $B$BRapporter les Ichors d'embaumement au magistrat Sevren à Brill.", st = "Dans le nord, les fosses communes, au sud-ouest de l'antre de Garren ont été construites pour accueillir les morts de Tirisfal lorsque la Peste frappa la première fois. $B$BLes corps qui s'y trouvent ont pu reposer en paix jusqu'ici mais le Fléau a envoyé des gnolls Poil-putride prendre les corps afin de les utiliser pour accroître leurs armées. Cela ne doit pas être !$B$BVotre mission comporte deux parties : tuer les Poils-putrides dans les fosses communes et dans l'Antre de Garren et récupérer sur eux l'ichor d'embaumement qui leur donne vie.", t = "Les Profanateurs"},
    [359] = {ot = "Parler à la Garde noire Linnea.", st = "J'ai besoin d'un rapport récent sur notre base de la Garde noire dans l'est.$B$BJe dois savoir s'il y a encore des incursions des forces du Fléau au-delà de la Barricade et dans Tirisfal. Notre vigilance à la frontière des Maleterres doit être maintenue. Nous ne pouvons pas nous permettre que les forces du Fléau s'établissent ici ! $B$BVoyagez vers le sud en suivant la route, puis vers l'est à l'embranchement jusqu'au poste. Demandez la Garde noire Linnea. Elle a les informations dont j'ai besoin.", t = "Mission des Réprouvés"},
    [360] = {ot = "Retourner voir le Magistrat Sevren à Brill.", st = "Maintenant, rapportez au Magistrat Sevren les informations que je vous ai données. Il en a besoin le plus vite possible, soyez rapide.$B$BEt si vous voyez des troupes du Fléau sur votre chemin, abattez-les. Nous ne pouvons leur permettre de parcourir nos contrées sans opposition.", t = "Retourner voir le Magistrat"},
    [361] = {ot = "Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand.", st = "Ceci est une lettre écrite par Thurman, l'aîné des fils de Gregor Agamand. Elle est adressée à Yvette Farthing, bien qu'il semble qu'elle n'ait pas atteint sa destinatrice…", t = "Une lettre perdue"},
    [362] = {ot = "Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill.", st = "Devlin Agamand était le plus jeune des deux fils de la famille Agamand. Jamais frères ne furent aussi différents. Thurman était grand et aimable tandis que son plus jeune frère était faible et acerbe.$B$BLorsque les Moulins d'Agamand sont tombés suite à la Peste, je n'ai pas été surpris d'apprendre que Devlin avait rapidement succombé. Son bavardage maladif peut toujours être entendu près de la route qui mène aux Moulins d'Agamand.$B$BJe collectionne les restes des Agamand. Je veux ce pauvre Devlin. Trouvez-le, détruisez-le et rapportez-moi ses os.", t = "Les Moulins Hantés"},
    [363] = {ot = "Parler au prêtre des ombres Sarvis.", st = "Il était temps de se réveiller. Nous nous apprêtions à vous jeter au feu avec les autres mais il semble que vous ayez réussi.$b$bJe suis Mordo, le fossoyeur de la crypte du Glas. Et vous n'êtes plus l'esclave du roi-liche.$b$bAllez parler au prêtre des ombres Sarvis dans la chapelle en bas de la colline, il vous en dira plus sur ce que vous devez savoir.", t = "Réveil brutal"},
    [364] = {ot = "Le prêtre des ombres Sarvis veut que vous tuiez 8 Zombies lunatiques et 8 Zombies décharnés.", st = "Nous, les Réprouvés, sommes en guerre contre le roi-liche et les troupes du Fléau : leurs armées de morts-vivants animés par la nécromancie, des bêtes immondes venues du nord et des spectres tourmentés.$b$bLa partie nord du village a été submergée par les Déchus et ils doivent être détruits. Anéantissez-les, n'ayez aucune pitié, même s'ils étaient nos frères et soeurs par le passé. Les Déchus ne sont rien d'autre que les esclaves du roi-liche.", t = "Les Déchus"},
    [365] = {ot = "Volez 10 Potirons dans la ferme à l'ouest, juste au nord du Glas, et apportez-les à l'Apothicaire Johaan à Brill.", st = "Ça par exemple ! Vous ressemblez à un épouvantail $c. Si vous espérez faire vos preuves au service de la Dame noire, il faudra apprendre les voies des Réprouvés.$b$bÀ l'ouest, vous trouverez une ferme. Les humains infestent cette terre comme la vermine un cadavre. Et pire, la Croisade écarlate patrouille près de leur tour. Donnez-leur une leçon et volez 10 de leurs précieux Potirons.$b$bUne fois que vous les avez, apportez-les à l'Apothicaire Johann à Brill.", t = "Les Champs du Chagrin"},
    [366] = {ot = "Ramener son livre de sorts à Gunther, dans sa retraite sur son île.", st = "Il y a longtemps, Gunther et moi, ainsi que Thule Ravenclaw qui est aujourd'hui Nécromancien du Fléau, étions amis et étudiants au Kirin Tor - une société de mages de Dalaran.$B$BGunther et moi sommes tombés, tués par la Peste, mais je pensais qu'il ne s'était pas relevé ou bien qu'il avait rejoint les rangs du roi-liche. Il est agréable de le savoir libre.$B$BIl doit être des nôtres. J'ai mis un sort dans son livre qui, une fois qu'il le verra, lui montrera que je ne suis pas non plus sous la domination du roi-liche. Une fois qu'il saura cela, j'espère qu'il nous rejoindra.", t = "Ramener le livre"},
    [367] = {t = "Une Peste nouvelle"},
    [368] = {ot = "L'Apothicaire Johaan de la ville de Brill a besoin de 5 Ecailles d'Aileron noir prises sur les murlocs des Clairières de Tirisfal.", st = "Pendant que vous collectiez mes échantillons, mes expériences m'ont permis de réaliser que des ingrédients supplémentaires seraient nécessaires pour que cette nouvelle maladie se répande proprement. Empoisonner une victime sans défense est un jeu d'enfant. Infecter un monde entier est un peu plus compliqué.$b$bJ'aurais besoin de 5 écailles prélevées sur les murlocs Ailerons noirs des environs. Vous trouverez ces créatures le long de la côte du nord ou de l'ouest.", t = "Une Peste nouvelle"},
    [369] = {ot = "L'Apothicaire Johaan de la ville de Brill désire que vous lui rameniez 4 échantillons de Venin de Tisse-nuit vicieuse.", st = "Tandis que votre quête vous occupait, j'ai découvert de vieux textes dans un de mes livres qui indique qu'une ancienne peste a balayé des milliers de victimes innocentes. Il a été compris plus tard que l'agent infectieux de l'épidémie avait été préservé grâce à du venin des araignées Tisse-nuit vicieuses.$b$bRapportez-moi un peu de ce venin pour compléter mes expériences. Je veux voir si le principe conservateur de ce venin agit aussi sur mes décoctions. Les rumeurs disent que les araignées peuvent être trouvées à l'est des clairières de Tirisfal.", t = "Une Peste nouvelle"},
    [370] = {ot = "Tuer le capitaine Perrine ainsi que 3 Zélotes écarlates et 3 Missionnaires écarlates.", st = "Les documents stratégiques de l'Exécuteur Arren contiennent tous les détails dont nous avons besoin pour balayer l'infection humaine de ces terres. Selon nos informations, la Croisade écarlate a assigné le capitaine Perrine et une brigade à la tour en ruine au sud-ouest de Brill.$b$bTuez Perrine ainsi que 3 Zélotes et 3 Missionnaires et revenez me rendre compte.", t = "En Guerre avec la Croisade écarlate"},
    [371] = {ot = "L'Exécuteur Zygand de Brill vous a chargé de liquider le capitaine Vachon et 5 Frères écarlates.", st = "Nous sommes toujours en guerre et la Croisade écarlate croît en puissance. Le rapport que l'Exécuteur Arren m'a envoyé indique que la Croisade lance ses raids depuis la tour en ruines au sud-est de Tirisfal, près de la ferme des Balnir. Elle est sous le commandement du capitaine Vachon.$b$bTuez Vachon et 5 Frères de la Croisade. Cela sera un coup dévastateur pour ces Croisés !", t = "En Guerre avec la Croisade écarlate"},
    [372] = {ot = "Assassiner le capitaine Melrach et ses deux gardes du corps pour l'Exécuteur Zygand de la ville de Brill.", st = "La Croisade écarlate lance des raids depuis la tour en ruine au nord-est de Tirisfal, au-delà du Repos de Faol. Selon nos informations, elle est menée par le capitaine Melrache qui a la réputation d'être un officier impitoyable.$b$bJe vous charge cette mission, dangereuse et spéciale. Abattez Melrache et ses deux gardes du corps au nom de la Dame noire.", t = "En Guerre avec la Croisade écarlate"},
    [373] = {ot = "Livrer la lettre pour l'Architecte de la Cité à Baros Alexston à Stormwind.", st = "En fouillant le corps d'Edwin VanCleef, vous trouvez parmi d'autres objets une lettre non envoyée. Elle est adressée à Baros Alexston, architecte de la cité de Stormwind, Hôtel de ville, place de la cathédrale.$B$BElle a l'air récemment écrite et scellée.", t = "La lettre non envoyée"},
    [374] = {ot = "Apporter 10 Anneaux de la Croisade écarlate au Garde noir Burgess à Brill.", st = "L'Exécuteur Zygand m'a dit que vous exterminiez des membres de la Croisade écarlate. Les Clairières de Tirisfal en sont remplies.$b$bVarimathras, lieutenant de la Dame noire, a pris personnellement en charge la mission d'exterminer toute la vermine humaine d'Azeroth. Ici, dans les Clairières de Tirisfal, nous faisons face à un genre particulièrement ennuyeux d'humains, la Croisade écarlate.$b$bAllez de l'avant et lancez une offensive sur la Croisade, $c. Ramenez moi 10 Anneaux de la Croisade écarlate comme preuve de votre loyauté à Varimathras et à la Dame noire.", t = "Preuves de la mort"},
    [375] = {ot = "Rapporter 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier à Gretchen Dedmar à Brill.", st = "Il fait si froid maintenant. Le Fléau mort-vivant brûle dans mes veines comme un serpent de glace. Mon âme sera bientôt perdue. Mais aucun destin, aussi irrévocable soit-il, ne m'empêchera de servir la Dame noire. Lorsque l'appel est arrivé, j'ai cousu des sacs pour les morts de la puissante armée de Sylvanas.$b$bMaintenant, mes mains tremblent à cause du froid. Si vous me ramenez 5 Peaux de chauve-souris du crépuscule et une Bobine de fil grossier, je pourrai me coudre une couverture. Aidez-moi, $n, que je puisse continuer à servir la cause.", t = "Le Frisson de la mort"},
    [376] = {ot = "La novice Elreth a besoin de 6 Pattes de charognard et de 6 Ailes de chauve-souris du crépuscule.", st = "Je soigne nos guerriers blessés, j'adapte leurs armures et vêtements, et j'assiste le prêtre des ombres Sarvis.$b$bApparemment, vous allez entrer à son service, vous aussi, pour chasser les Âmes Perdues. Si vous voulez rester en un morceau, ce dont je ne doute pas, je peux peut-être vous aider. Je manque de pattes et d’ailes ; si vous m’en apportez, je vous fournirai une armure. Vous trouverez de nombreux loups et chauves-souris au sud.", t = "Les Maudits"},
    [377] = {ot = "Le conseiller Millstipe de Darkshire désire que vous lui rameniez la main de Dextren Ward.", st = "Non contente de négliger les habitants du bois de la Pénombre, la Maison des Nobles a décidé d'humilier le Conseil de Darkshire en décidant d'emprisonner Dextren Ward à Stormwind plutôt que de le décapiter ainsi que le Seigneur Ebonlocke l'avait décidé.$b$bWard a été pris en train de vendre des corps du cimetière à Morbent Fel. Ce crime est passible de la peine capitale. Mais Stormwind exige que Ward soit leur prisonnier.$b$bAssassinez Ward dans la Prison de Stormwind et ramenez-moi sa main, je vous récompenserai pour cela.", t = "Crime et Châtiments"},
    [378] = {ot = "Rapportez la tête de Kam Deepfury à Motley Garmason à Dun Modr.", st = "Vous avez prouvé votre loyauté au roi Magni, $c. Et votre haine de la vermine Sombrefer est aussi forte que la mienne.$b$bVoici une tâche que je pourrais effectuer mais je suis obligé par une dette d'honneur de rester à Longbraid. Roggo a rassemblé un faisceau d'informations qui prouvent que Kam Deepfury était derrière l'attaque du viaduc de Thandol. Ce sont les plans de Deepfury qui ont amené la ruine de Longbraid.$b$bDeepfury est détenu pour des raisons politiques dans la Prison de Stormwind. Je veux qu'il meure, $n. Pour Longbraid ! Ramenez-moi sa tête !", t = "Fureur dans les Profondeurs"},
    [380] = {ot = "L’Exécuteur Arren veut que vous tuiez 10 Jeunes Tisse-nuit et 8 Araignées Tisse-nuit.", st = "Un de nos plus gros problèmes est d'obtenir les ressources nécessaires à notre survie. L'or était déjà rare lorsque l'Alliance était au sommet de sa puissance.$b$bIl y a une mine d'or au nord-ouest qui a été envahie par les araignées. Nous avons besoin de cet or, mais nous ne pouvons l'exploiter à cause de ces créatures. Je n'ai pas beaucoup de personnels à affecter à cette tâche, alors je vais devoir le faire par étapes.$B$BAllez-y et voyez ce que vous pouvez faire, $n.", t = "Les grottes des Tisse-nuit"},
    [381] = {ot = "Apporter à l’Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates.", st = "Il vous plaira d’entendre que nous progressons dans la mine, et cela grâce à vous. Nous pouvons maintenant nous atteler à d’autres tâches.$b$bMes éclaireurs m’ont dit qu’un détachement de la Croisade écarlate avait établi un campement au sud-est. Cette Croisade écarlate est une organisation abjecte qui nous chasse et n’aura de cesse d'exterminer jusqu'au dernier mort-vivant, qu'il soit du Fléau ou non. Nous devons frapper les premiers !$b$bAttention ce sont des adversaires zélés et dangereux.", t = "La Croisade écarlate"},
    [382] = {ot = "Tuer Meven Korgal, le messager, au camp de la Croisade, puis ramener toutes les informations trouvées à l'Exécuteur Arren.", st = "Les rapports de mes supérieurs à Brill indiquent qu'un agent de la Croisade a été détaché du Monastère écarlate et envoyé ici, au Glas. Toujours selon les rapports, ce messager possède d'importantes informations sur lui. Je n'ai pas plus de détails, mais qui que soit ce messager, nous devons l'avoir !$b$bVous êtes $gle meilleur:la meilleure; que je peux trouver, $n. Trouvez ce messager et ramenez-moi toutes les informations que vous trouverez sur lui.", t = "Le messager rouge"},
    [383] = {ot = "Livrer les documents de la Croisade écarlate à l'Exécuteur Zygand à Brill.", st = "Ceci doit être rapporté à mon supérieur, l'Exécuteur Zygand à Brill. Avec ces informations, nous serons à même de porter un coup décisif à la Croisade écarlate. Vos services ont été utiles ici au Glas, mais j'ai besoin de quelqu'un pour porter ceci à Zygand et je pense qu'il sera à même de vous trouver une mission plus en relation avec vos capacités.$b$bPrenez la route au nord du Glas. Une fois dans Tirisfal, vous arriverez à un croisement. Prenez la route vers l'est et continuez. Vous passerez devant le manoir du Foyer froid sur votre route.", t = "Informations décisives"},
    [384] = {ot = "Ragnar Thunderbrew à Kharanos veut 6 Côtes de sangliers des rochers et une Chope de bière au malt Rhapsody.", st = "Il n'y a rien que mes clients apprécient plus qu'une bonne côte de sanglier à la bière ! Le seul problème est que le trappeur qui nous ravitaille s'est engagé dans l'armée du roi pour aller à la guerre sur le front de l'Alliance.$b$bPeut-être pourriez-vous m'aider ? Si vous pouvez me procurer six côtes de sangliers des rochers et une bière au malt Rhapsody de la taverne, je vous donne ma recette familiale des côtes de sanglier à la bière accompagnée bien évidemment d'un échantillon gratuit ! Le secret est dans la bière, mais je ne vous en dis pas plus !", t = "Côtes de sanglier à la bière"},
    [385] = {ot = "Trouver 5 morceaux de Viande de cocilisque et 6 Peaux de crocilisque pour Marek Ironheart au pavillon des pérégrins.", st = "Beaucoup de chasseurs viennent au Loch Modan pour chasser nos fameux crocilisques. Il y a toujours des marchands qui payent pour avoir ces peaux servant à la confection de vêtements ou d’armures ; sans parler de ceux qui apprécient leur viande.$b$bLes crocilisques étant féroces et retranchés sur leur île, au milieu du Loch, nous manquons de peaux. Mais ne vous laissez pas effrayer : esquiver les mâchoires de ces bêtes est une expérience enrichissante.$b$bDu moins cette fois...", t = "Chasse aux crocilisques"},
    [386] = {ot = "Ramener la tête de Targorr le Terrifiant au Garde Berton à Comté-du-Lac.", st = "Targorr le Terrifiant a servi sous les ordres de Gath'llzogg en tant qu'Exécuteur suprême. Sa méthode était impitoyable, même selon les standards orcs. Les hommes qui combattaient vaillamment étaient torturés selon ses désirs. Maintenant il est enfermé dans la Prison de Stormwind, condamné à mort. Mais quelque chose ne va pas. Un de ces nobles passionnés de procédures bureaucratiques a suspendu l'exécution. Je suis sûr qu'il y a des magouilles là-dessous.$b$bMettez fin à la carrière de Targorr le Terrifiant, $n. Allez jusqu'à la Prison et décapitez-le avant que toutes ces arguties finissent par le libérer.", t = "Ce qui se passait ailleurs…"},
    [387] = {ot = "Tuer 10 Prisonniers défias, 8 Détenus défias et 8 Insurgés défias dans la Prison pour le Gardien Thelwater de Stormwind.", st = "La révolte doit être étouffée ! J'ai besoin de votre aide. Si l'on apprend dehors que cette prison est en rébellion, je perds mon poste ! Mais le plus important en ce moment est de forcer les prisonniers à se soumettre, pour la sécurité de Stormwind.$b$bLa punition en cas d'émeute est la mort. Tuez quelques-uns de ces déviants ! Cela devrait ramener les choses sous contrôle.", t = "Écraser la rébellion"},
    [388] = {ot = "Rapporter 10 foulards en laine rouge à Nikova Raskol de Stormwind.", st = "L'amertume coule dans mes veines comme un poison glacé. Mon petit-fils, Mac, était un si bon garçon. À peine 14 ans. Lorsque l'armée est partie en direction du front, Max a pris les armes pour défendre la ville. Il était garde à la Prison lorsque les Défias ont été emprisonnés. Mac a réprimandé certains prisonniers qui déchiraient leurs couvertures pour en faire des foulards, symbole de leur gang. Pour cela, ils l'ont poignardé dans le dos.$b$bJe veux qu'il soit vengé. Rapportez-moi 10 de leurs précieux foulards de laine. Ils sont de la couleur du sang.", t = "La couleur du Sang"},
    [389] = {ot = "Parler au gardien Thelwater à la prison.", st = "VanCleef et moi étions membres de la Guilde des Maçons. Notre grand projet était de reconstruire Stormwind après la guerre.$b$bUne fois notre tâche finie, nous avons été escroqués. Les nobles ont refusé de payer. Plusieurs Contremaîtres se virent proposer des emplois dans le gouvernement, mais VanCleef refusa par loyauté envers la guilde. Il mena une émeute et quitta la cité, jurant de se venger.$b$bSon lieutenant, Bazil Thredd, doit en savoir plus sur ses plans. Il est détenu dans la prison de Stormwind.", t = "Bazil Thredd"},
    [391] = {ot = "Tuer Bazil Thredd et ramener sa tête au Gardien Thelwater à la Prison.", st = "Qu'une chose soit bien claire, $n : je n'ai pas confiance en vous. Mais la situation étant ce qu'elle est, ça ne change pas grand-chose. $B$BAlors voilà comment on va faire : descendez là-bas et parlez à Thredd. Et si vous êtes vraiment de notre côté, tuez-le et ramenez-moi sa tête. Et s'il se trouve que vous êtes de son côté, et que vous ne revenez pas... Je vous retrouve et vous périrez comme un rat. Compris ?", t = "Les Emeutes de la Prison"},
    [392] = {ot = "Apporter la description du visiteur de Thredd à Baros Alexston à Stormwind.", st = "Pendant les premières années de son emprisonnement, Thredd n'a reçu aucun visiteur. Je pensais qu'il n'était plus utile à la Confrérie Défias, alors ils l'ont abandonné.$b$bQuoi qu'il en soit, il y a quelques mois, tout a changé ; il a commencé à recevoir des visites régulières... Une à deux fois par semaine. C'était un type étrange, calme. J'avais des soupçons, mais tous ses papiers étaient en règle.$b$bLe nom sur les papiers était Maelik, voici sa description. Je ne pense pas qu'il va revenir voir Thredd.", t = "Un curieux visiteur"},
    [393] = {ot = "Apporter la Description scellée du visiteur de Thredd au Maître Mathias Shaw à Stormwind.", st = "Je n'en ai aucune idée, $n. Il y a quelqu'un d'autre qui pourrait vous aider, et il se trouve qu'il me doit une faveur... bon, pas la peine de parler de ça. Vous trouverez maître Mathias Shaw, du SI:7, dans la caserne de la vieille ville. Shaw est impliqué dans la plupart des opérations louches de la cité.$B$BSi quelqu'un a des renseignements, ce sera lui.", t = "Les Ombres du Passé"},
    [394] = {ot = "Parler à Mathias Shaw, à Stormwind.", st = "Retrouvez Shaw dans la vieille ville. Faites-lui savoir que la menace Lescovar a été résolue grâce à vous. Je suis sûr qu'il sera fier d'avoir un nouveau héros parmi les citoyens de Stormwind.$B$BJe pense qu'il vous enverra rencontrer le Prince ou un autre noble. Ne vous laissez pas faire, $n. Les nobles peuvent penser qu'ils règnent sur la ville autant qu'ils le veulent, il n'en reste pas moins que certaines choses échappent à leur contrôle.", t = "La tête de la bête"},
    [395] = {ot = "Parler à Baros Alexston à Stormwind.", st = "Ah, j'avais presque oublié. Alexston est passé pendant que vous n'étiez pas là, il désirait vous parler. Il est clair qu'il désirait rendre compte de l'activité de la Confrérie défias au roi.$b$bUn petit conseil, $n. Si quelqu'un le demandait, je donnerais tous les détails, mais sans préciser que c'est votre main qui a tué Lescovar. Croyez-moi. Je suis... habitué... à ce genre de pratiques.$B$BEn ce qui concerne Trias, he bien, ne parlez de lui à personne... jamais... Si vous le pouvez.", t = "La fin de la Confrérie"},
    [396] = {ot = "Apporter le rapport de Baros Alexston sur la Confrérie Défias au Roi Varian Wrynn au Donjon de Stormwind.", st = "J'ai préparé un rapport pour le roi. Je crois que vous devriez le lui remettre, en même temps qu'une explication de vos découvertes. N'ayez crainte, il vous récompensera sûrement pour vos actions.$B$BVotre audience est prévue pour bientôt, vous devriez vous hâter, il y a du chemin jusqu'au donjon de Stormwind.", t = "Une audience avec le roi"},
    [398] = {t = "On recherche : Œil-de-ver"},
    [399] = {ot = "Aller à la maison de Baros Alexston dans la marche de l'Ouest pour chercher sa boussole et lui rapporter à la place de la Cathédrale de Stormwind.", st = "J'ai l'impression qu'une éternité s'est écoulée depuis que j'étais un jeune garçon travaillant à la ferme, dans la marche de l'Ouest. On dit que l'on ne peut jamais revenir en arrière et c'est vrai. C'est d'autant plus vrai dans mon cas que la maison de ma famille a été brûlée et détruite par des voleurs.$b$bJ'ai parlé avec mon père de ce qu'il était advenu de quelques-uns de mes biens, notamment de ma première boussole. Il n'a pas pu les sauver. Il m'a dit qu'ils devaient être cachés dans la ferme.$b$bLa ferme des Alexston se trouve à l'ouest de la Colline des sentinelles. Peut-être pourriez-vous y aller et rapporter mes biens ?", t = "Débuts modestes"},
    [400] = {ot = "Rapporter les outils de SteelGrill à Beldin Steelgrill.", st = "Beldin Steelgrill tient un magasin de mécanique. C’est notre meilleur technicien d'engins de siège ! Mais il n'est pas soigneux avec ses outils. Je vous jure qu'il casse ses clés plates aussi vite que nous les lui fournissons !$B$BNous venons juste de préparer sa dernière commande d'outils. Si vous la lui livrez, je suis sûr qu’il vous récompensera.$B$BSon magasin, le dépôt de Steelgrill, est juste au nord-est de Kharanos. Et c'est le repaire de nombreux pilotes d'engins de siège vétérans. Quand vous y serez, gardez les oreilles ouvertes, il y aura peut-être des occasions à saisir.", t = "Des outils pour Steelgrill"},
    [404] = {ot = "Rapporter 7 Griffes putrides au Garde noir Dillinger à Brill.", st = "Le Fléau s'est infiltré dans les clairières de Tirisfal et a infesté l'ouest de Brill, près du vieux pont.$B$BAllez là-bas et faites reculer les morts pourrissants et les cadavres décomposés que vous trouverez. Eparpillez leurs ossements et rapportez leurs griffes putrides et les gardes noirs vous récompenseront.", t = "Une tâche putride"},
    [405] = {ot = "Présenter les ordres de Sevren à Bethor Iceshard à Fossoyeuse.", st = "Bethor Iceshard, un puissant mage de Fossoyeuse, dans le sud, m'a demandé de lui envoyer un agent efficace contre le Fléau. Vous, $n, serez cet agent.$B$BPrésentez ces ordres à Bethor. Il vous instruira du détail de votre mission. Je ne connais pas les détails de celle-ci mais je crois qu'il s'agit de recruter une liche. Et cela sera dangereux.$B$BAlors soyez prêt, $c. Vous ne devez pas échouer.$B$BVous trouverez Bethor dans le quartier des mages de Fossoyeuse.", t = "La Liche prodigue"},
    [407] = {ot = "Donner la citrouille enchantée au Zélote écarlate capturé qui est gardé dans le cellier de la taverne des Pendus.", st = "D'inoffensives citrouilles, n'est-ce pas ? A ce qu'il semble. Si nous voulons stopper l'avance d'Arthas du nord et l'infestation humaine venant du sud, nous devons commencer à comprendre l'étendue de notre potentiel de morts-vivants.$b$bAvec un peu d'ingéniosité une simple citrouille va devenir un agent de la Dame noire. Cette citrouille, traitée avec ma dernière formule, sera une menace sérieuse.$b$bUn autre Zélote écarlate a été capturé et est gardé prisonnier dans le cellier de la Taverne des pendus. Prenez cette citrouille et donnez-la-lui.", t = "Les Champs du Chagrin"},
    [408] = {ot = "Tuer 8 Spectres ancestraux et 8 Ancêtres pourrissants.$B$BTuer le capitaine Dargol et ramener son crâne au magistrat Sevren à Brill.", st = "Les moulins d'Agamand sont devenus un avant-poste du Fléau. Leur point fort est la crypte de la famille Agamand où leur chef local, un squelette nommé le capitaine Dargol a son quartier général. A l'aide de la nécromancie, il a relevé les ancêtres des Agamand et veut les utiliser contre nous.$B$BCela ne doit pas être et c'est vous qui allez stopper ceci. Allez jusqu'à la crypte de la famille Agamand et battez les ancêtres Agamand.$B$BEt ramenez-moi le crâne du capitaine Dargol.", t = "La Crypte Familiale"},
    [409] = {ot = "Obtenir une Bougie de signal.$B$BInvoquer Lillith Nefara et la tuer.$B$BRetourner voir Gunther sur son île.", st = "Vous dites que vous n'êtes pas $glié:liée; à la volonté du roi-liche et l'enchantement que Bethor a mis dans mon livre corrobore ceci. Mais avant que je ne vous croie, je dois avoir des preuves que vous êtes $gun ennemi:une ennemie; du Fléau.$B$BIl y a un vieil et sanglant autel sur la côte sud de cette île. Il est utilisé par un puissant agent du Fléau, Lillith Nefara.$B$BPrenez une Bougie de signal dans cette boîte là-bas. Allumez-là sur l'autel et Lillith se réveillera. Détruisez-la et je saurai que vous êtes l'ennemi du Fléau.", t = "Prouver l'allégeance"},
    [411] = {ot = "Rapporter la Gemme du Néant à Bethor Iceshard à Fossoyeuse.", st = "Portez cette Gemme du néant à mon vieux compagnon Bethor. Cela nous permettra de communiquer… et j'ai tant de choses à lui dire.", t = "Le Retour de la Liche Prodigue"},
    [412] = {ot = "Porter 8 Rouages de Rééquilibrage et 8 Engrenages gyromécaniques à Razzle Sprysprocket à Kharanos.", st = "Après des analyses approfondies de la situation, il semble que non seulement nous avons échoué à éradiquer les troggs mais que nous avons changé la majorité de la race gnome en horribles gnomes lépreux.$b$bOzzie et moi voulons renverser l'effet de cette abominable lèpre grâce à notre dernière invention : le Recombobulateur. Cette machine est pratiquement complète mais nous avons un grand besoin de Rouages de Rééquilibrage et d'Engrenages gyromécaniques. Demandez-en pour nous aux gnomes lépreux devant Gnomeregan.", t = "Opération Recombobulation"},
    [413] = {ot = "Amener le Tonneau de Bière Shimmer au Montagnard Barleybrew.", st = "J'aimerais que mon frère Wellart essaye ma nouvelle bière Shimmer. C'est un montagnard dont la garnison est la tour de garde sud, une des deux tours au bord du Loch Modan.$B$BIl n'est peut être pas un brasseur comme le reste des Barleybrew mais il aime boire une bonne bière et je sais qu'il appréciera celle-ci.$b$BPouvez-vous lui porter ce Tonneau de Bière Shimmer pour moi ?", t = "La bière Shimmer"},
    [414] = {ot = "Portez le Tonneau de Bière Shimmer au montagnard Kadrell.", st = "J'ai encore bu un peu de cette bière Shimmer faite par mon frère, c'est vraiment une sacrée bière ! J'aimerais qu'un ami montagnard la goûte. Son nom est Kadrell et il patrouille en général sur la route qui passe par Thelsamar au Loch Modan.$B$BPour aller à Thelsamar, allez au sud-ouest à travers le tunnel puis allez au nord-est quand le chemin se sépare. Suivez cette route jusqu'à Thelsamar.$B$BDonnez au montagnard Kadrell ce Tonneau de Shimmer Stout et voyez ce qu'il en pense !", t = "Bière à Kadrell"},
    [416] = {ot = "Apporter 12 Oreilles de Rat des tunnels au Montagnard Kadrell à Thelsamar.", st = "Nous avons vraiment un problème de vermine à l'ouest. Les rats des tunnels kobolds sont venus dans les collines, ont creusé leurs terriers et contaminé notre terre avec leur pestilence !$B$BNous voulons les éliminer. Chassez-les et ramenez-moi leurs oreilles pour la récompense.$B$BVous trouverez les tunnels des kobolds et leurs terriers à l'ouest de Thelsamar, disséminés à flanc de montagne.", t = "Chasse au rat"},
    [417] = {ot = "Tuer Griffe galeuse.$B$BRapporter la griffe à laquelle il doit son nom et le Journal de Hildelve au pilote Hammerfoot.", st = "Hildelve écrit dans son journal qu'il a été attaqué par Griffe galeuse, un \"gigantesque ours Griffeglace\". Il a repoussé la bête mais pas avant d'avoir été gravement blessé.$B$BD'après l'état du corps de Hildevel, Griffe galeuse a dû revenir et le tuer.$B$BNéanmoins, Hildevel a écrit dans son journal sa dernière volonté :$B$BVengez-moi ! Tuez Griffe galeuse !", t = "La revanche du pilote"},
    [418] = {ot = "Apporter 3 morceaux de Viande d’ours, 3 Tripes de sanglier et 3 Ichors d'araignée à Vidra Hearthstove à Thelsamar.", st = "On n'a jamais manqué d'estomacs vides à Thelsamar, avec les gamins qui courent partout et les ouvriers qui reviennent de leur journée de travail après un dur labeur. Nos boudins sont réputés, vous les avez déjà essayés ?$b$bNon ? Eh bien, par ici, il faut travailler pour mériter sa pitance et ce n'est pas parce que vous êtes bien $ghabillé:habillée; que l'on fera une exception pour vous, $c.$b$bJe vais avoir besoin de viande d'ours, d'intestins de sanglier pour la cuisson et d'ichor d'araignée pour épicer le tout. Trouvez-moi cela et laissez la cuisine à Vidra !", t = "Les boudins de Thelsamar"},
    [419] = {ot = "Trouver le pilote Hildeve.", st = "Mon ami et camarade Mori Hildelve, qui est Sapeur, a disparu dans les collines. Nous étions en train de chercher un minerai rare qui est nécessaire pour une poudre explosive de grande qualité. Durant nos recherches, il a essayé de monter une pente avec son engin lorsque le moteur a explosé !$B$BConvaincu que le minerai était dans ces montagnes, Hildelve m'a confié la garde des engins tandis qu'il poursuivait la prospection à pied.$B$BCela fait maintenant des jours de cela et j'ai entendu les grognements de bêtes dans la montagne la nuit. Mori est dur comme l'acier mais je suis inquiet.$B$BS'il vous plaît, $n. Trouvez-le.", t = "Le pilote perdu"},
    [420] = {ot = "Apporter le rapport de Grelin à Senir Whitebeard à Kharanos.", st = "Les troggs qui infestent le tunnel sont extrêmement hostiles et n'hésitent pas à attaquer tout intrus. Vous avez l'air suffisamment solide, vous devriez donc vous en tirer.$b$bLa route à suivre ? Si vous voulez parler à Senir, vous le trouverez à Kharanos.$b$bPassez par le tunnel et une fois dehors à l'autre extrémité, suivez la route, elle vous conduira à Kharanos.", t = "Les observations de Senir"},
    [421] = {ot = "Tuer 5 Poils-blancs Ragelune pour Dalar Dawnweaver au Sépulcre.", st = "Dame Sylvanas a chargé Varimathras de la conquête des terres humaines et naines se trouvant vers le sud.$b$bMais Arugal, ci-devant charlatan de Dalaran et aujourd'hui bête maudite du donjon d'Ombrecroc, a tristement utilisé sa magie. Il a créé le chaos dans la forêt des Pins argentés qui est d'une grande importance stratégique.$b$bJ'ai besoin de quelqu'un de doué dans les arts du combat pour rétablir l'ordre. Prouvez-moi votre valeur en tuant 5 Poils-blancs Ragelune. Ces bêtes dégénérées se trouvent généralement près de la route, en bas de la colline.", t = "Prouver votre valeur"},
    [422] = {ot = "Retrouver le Remède d'Arugal pour Dalar Dawnweaver au Sépulcre.", st = "Comment Arugal a-t-il pu entrer au Kirin Tor ? C'est au-delà de ma compréhension. Son savoir semblait aussi léger qu'une bulle de savon.$b$bCe qui importe maintenant, c'est de savoir quelle magie Arugal a utilisée afin que je puisse la retourner contre lui et rendre la forêt des Pins argentés saine pour la Dame noire.$b$bArugal a longtemps habité dans la ferme juste au nord du pont. Retrouvez-moi le sort appelé le Remède d'Arugal dans ses livres.", t = "La folie d'Arugal"},
    [423] = {ot = "Rapportez 6 Bracelets de Gloutons et 6 Bracelets de Ténébreux à Dalar Dawnweaver au Sépulcre.", st = "Après examen des travaux d'Arugal, mes pires hypothèses se sont confirmées. Le vieux fou n'était même pas bon à vider des pots de chambre à Dalaran. Alors, représenter le Kirin Tor dans ses heures les plus sombres...! Les fous !$b$bArugal a utilisé des reliques magiques pour renforcer ses faibles pouvoirs. J'ai besoin d'étudier ces objets avant toute chose. Allez au nord et tuez des Gloutons Ragelune et des Ténébreux Ragelune jusqu'à ce que vous ayez récolté suffisamment de leurs bracelets enchantés. J'en ai besoin pour mes recherches. Vous trouverez ces créatures infâmes au nord et à l'est.", t = "La folie d'Arugal"},
    [424] = {ot = "Tuer Grimson le Pâle et ramener sa tête à Dalar Dawnweaver au Sépulcre.", st = "Découvrir les sombres secrets des enchantements d'Arugal va me prendre plus de temps que je ne le pensais.$b$bPendant ce temps, j'aimerais que vous vous occupiez d'un problème que nos Traqueurs noirs ont découvert. Il semble qu'Arugal ait laissé sa magie s'étendre jusqu'à la mine du gouffre d'Elem dans les collines du sud-est.$b$bCette mine serait d'une aide précieuse pour Varimathras.$b$bJe veux que vous décapitiez le contremaître de cette mine, Grimson le Pâle. Avec sa mort, la mine sera nôtre.", t = "La folie d'Arugal"},
    [425] = {ot = "Tuer Ivar l'Infect et ramener sa tête à Rane Yorick au lopin d'Ivar.", st = "Mon frère Quinn et moi avions pour mission de reconnaître la forêt des Pins argentés et de rendre compte au Grand exécuteur Hadrec. Mais nous ne sommes pas allés loin. En passant par cette ferme, nous avons été attaqués par la goule nommée Ivar l'Infect.$B$BNous avons réussi à nous échapper mais Quinn a été grièvement blessé par Ivar. Il récupère en ce moment grâce à la potion que vous lui avez donnée mais Ivar pourrait revenir avant qu'il soit guéri.$B$BTuez Ivar de manière à donner le temps à Quinn de récupérer. Ivar se trouve généralement dans la grange, attendant que je baisse ma garde.", t = "Ivar l'Infect"},
    [426] = {ot = "Rassemblez 5 Côtes ébréchées et 3 Crânes noircis et rapportez-les au garde noir Dillinger à Brill.", st = "Les forces du Fléau essayent de construire une base aux moulins d'Agamand. Si elles réussissent, elles pourront lancer d'autres attaques sur Tirisfal.$B$BLes ordres sont clairs. Les forces du Fléau positionnées là-bas doivent être détruites.$B$BAllez aux moulins. Collectez des côtes ébréchées sur les soldats et les squelettes Cliquethorax, ainsi que des crânes noircis d'Ossomanciens Sombroeil.$B$BPour rejoindre les moulins, suivez la route ouest. Après avoir traversé le pont, prenez la route nord au premier croisement. Lorsque vous verrez les moulins, la bataille commencera.", t = "La chute des moulins"},
    [427] = {ot = "Tuer 10 Guerriers écarlates pour l'Exécuteur Zygand.", st = "Les documents que l'Exécuteur Arren nous a apportés sont juste ce qui nous manquait pour notre bataille contre la Croisade écarlate. Nous savons maintenant où ils se trouvent dans les Clairières de Tirisfal.$b$bMais la Garde noire a d'autres soucis. L'armée du roi-liche s'accroît chaque nuit. Nous avons besoin de quelqu'un capable \"d'initiatives\" personnelles tel que vous pour s'occuper de la Croisade écarlate.$b$bProuvez-moi que vous êtes digne de servir la Dame noire ! Allez vers l'ouest jusqu'à la tour après la ferme des Solliden et tuez 10 guerriers écarlates.", t = "En guerre avec la Croisade écarlate"},
    [429] = {t = "Cœurs sauvages"},
    [430] = {ot = "Apporter le remède à Quinn Yorick au lopin d'Ivar, au nord du Sépulcre.", st = "Voici la potion qui guérira Quinn Yorick.$B$BMaintenant, si vous voulez bien m'excuser, j'ai un important travail à terminer...", t = "Retour vers Quinn"},
    [432] = {t = "Ces satanés troggs !"},
    [433] = {ot = "Tuer 10 Briseurs d'os Mâcheroc pour le sénateur Mehr Stonehallow à la carrière de Gol'Bolar.", st = "En tant que membre du Sénat et de la Ligue des Explorateurs, j'ai la charge de m'occuper des troggs qui infestent nos terres. Ils ont dévasté la carrière de Gol'Bolar, sans raison apparente. Comme nous forions profondément, ils ont jailli, détruisant notre équipement et chassant les mineurs. Nous n'avons d'autre solution que d'en exterminer un maximum, reconstruire et retourner au travail.$b$bSi vous m'aidez à nous débarrasser de ces troggs, je vous récompenserai en conséquence.", t = "Le serviteur public"},
    [434] = {ot = "Rester dans le jardin jusqu'à ce que le seigneur Gregor Lescovar et Marzon Lame silencieuse aient eu leur conversation. Après, les tuer tous les deux puis retourner voir Elling Trias à Stormwind.", st = "Après avoir passé le déguisement à l'Espion, il entrera pour parler à Lescovar. Les gardes devraient le laisser passer sans problème.$B$BPendant que vous cherchiez le matériel pour moi, j'ai pris soin d'informer Marzon qu'il était temps de rencontrer à nouveau Lescovar. Je lui ai aussi glissé de fausses informations.$B$BLescovar congédiera ses gardes et attendra Marzon dans le jardin. Dès que vous entendrez parler des Defias, agissez. Vous devez les tuer tous les deux. C'est compris ?$B$BQuand cela sera fait, allez parler à Trias.", t = "L'attaque !"},
    [435] = {ot = "Escorter Erland jusqu'à Rane Yorick.", st = "Les loups ne partiront pas, et leurs yeux me fixent avec avidité dès que je fais un pas dehors. Ils doivent avoir une sacrée fringale pour penser que je suis comestible !$B$BJ'ai un rapport à remettre à mon équipier, le Traqueur noir Rane Yorick, mais il faudra d'abord se tailler une route à travers ces loups.$B$BEscortez-moi ! C'est une véritable meute qui attend dehors ; si vous appeliez des amis en renfort, nous doublerions nos chances de réussite...", t = "Une escorte pour Erland"},
    [436] = {ot = "Parler à l'Explorateur Fellhew.", st = "Le Prospecteur Ironband dirige l’exploration de ruines à l'est du lac. Malgré notre approvisionnement, sa progression s'est ralentie dernièrement.$B$BIronband est un solide et honnête nain qui aime à faire du bon travail, c'est pourquoi je crains que des forces contraires soient à l'œuvre pour le ralentir.$B$BAllez aux fouilles d'Ironband et parlez à Magmar Fellhew. C'est lui qui gère le site, et il saura sûrement pourquoi le rythme de travail a décru.$B$BPour rejoindre les fouilles, contournez la pointe sud du lac, puis marchez droit vers l'est.", t = "Les fouilles d'Ironband"},
    [437] = {ot = "Tuer des gnolls Poils-putrides au Champ des morts.$B$BDétruire Cinglenuit quand elle apparaît.$B$BRapporter son essence au Grand exécuteur Hadrec au Sépulcre.", st = "Nos premiers rapports de reconnaissance dans la forêt des Pins argentés indiquent que les Poils-putrides ont une base dans une vieille ferme, le Champ des morts. Nous les avons attaqués à plusieurs reprises, mais à chaque fois ils reçoivent l'assistance de la banshee Cinglenuit dont la magie désorganise et disperse nos forces.$B$BNous voulons la voir détruite.$B$BAllez dans le Champ des morts et attaquez les Poils-putrides. Si vous ne voyez pas la banshee, massacrez les Poils-putrides jusqu'à ce qu'elle apparaisse, puis tuez-la.$B$BSon essence même deviendra de la poussière. Rapportez-moi cette poussière comme preuve de sa destruction", t = "Le Champ des morts"},
    [438] = {ot = "Aller au bac délabré.$B$BChercher la raison de la présence du Fléau.", st = "$n, nous avons découvert une nouvelle infestation du Fléau : le bac délabré. Le bac se trouve à l'est du Sépulcre, et fourmille de patrouilles de Poils-putrides et autres morts-vivants.$B$BLe Fléau a sans doute une bonne raison pour occuper la zone. Allez au bac délabré et trouvez pourquoi le Fléau est là-bas.", t = "Le bac délabré"},
    [439] = {ot = "Rapporter la Bague de Deliah au Grand exécuteur Hadrec au Sépulcre.", st = "De la pile de corps dépasse une main de femme, marquée par la peste, mais encore relativement fraîche.$B$BUn doigt porte une bague. L'observation de cette bague révèle une inscription :$B$B\"Pour Deliah\"", t = "Un indice vers les Poils-putrides"},
    [440] = {t = "La bague ciselée"},
    [441] = {ot = "Apporter la Bague de Deliah à Raleigh.", st = "Deliah avait un mari, Raleigh, qui maintenant habite à Fossoyeuse. Si la Deliah qui vivait à Brill est bien celle à qui appartient la bague, alors Raleigh le saura.$B$BRaleigh est dans le quartier des Marchands à Fossoyeuse.", t = "Raleigh et Fossoyeuse"},
    [442] = {ot = "Rapporter la Tête de Thule au Grand exécuteur Hadrec au Sépulcre.", st = "Il est maintenant temps d'attaquer le bastion du Fléau dans les Pins argentés : l'île de Fenris.$B$BVous devez aller sur l'île et tuer Thule Ravenclaw. Apportez-moi sa tête !$B$BCette mission est aussi importante qu'elle est vitale, $n. Vous ne pouvez échouer.", t = "L'attaque de l'île de Fenris"},
    [443] = {ot = "Rapporter 8 bouteilles d'Ichor de Poil-putride à l'apothicaire Renferrel.", st = "Avant que nous lancions notre offensive contre l'île de Fenris, nous devons déterminer qui dirige les gnolls Poils-putrides. Nos Apothicaires pensent que leur origine est liée au fluide étrange qui coule dans leurs corps.$B$BAllez sur l'île de Fenris, à l'est du Bac délabré, et collectez de lichor de Poil-putride sur les gnolls. Portez-le à l'apothicaire Renferrel, qui se trouve à l'extérieur du Sépulcre", t = "L'ichor de Poil-putride"},
    [444] = {ot = "Apporter l'Echantillon d'ichor à Bethor Iceshard à Fossoyeuse.", st = "J'ai réduit l'ichor que vous m'avez ramené et en ai séparé les principaux composants. Mes découvertes ne laissent aucun doute sur au moins un point : la magie des démonistes et des nécromanciens a été utilisée dans sa création.$B$BPendant que je pousserai mes recherches sur ce sujet, je veux que vous en apportiez un échantillon à Bethor Iceshard à Fossoyeuse. Bethor n'est pas un apothicaire, mais sa connaissance de la magie pourrait nous aider à comprendre le mystère des Poils-putrides.$B$BPartez ! Vous trouverez Bethor dans le Quartier de la magie de Fossoyeuse.", t = "L'origine des Poils-putrides"},
    [445] = {ot = "Apporter les découvertes de l'Apothicaire Johaan à l'Apothicaire Renferrel dans la forêt des Pins argentés.", st = "Le temps n'est pas un luxe que peuvent s'offrir ceux qui travaillent pour Dame Sylvanas, mais vous le savez certainement.$b$bEn tant que membre de la Société royale des apothicaires, il est de mon devoir de partager mon savoir avec mes confrères afin que nos efforts conjoints puissent un jour offrir à la Dame noire cette Peste nouvelle qu'elle désire si ardemment.$b$bPortez ces découvertes à l'apothicaire Renferrel qui réside au Sépulcre dans la forêt des Pins argentés.", t = "Livraison dans la forêt des Pins argentés"},
    [446] = {ot = "Porter le parchemin de Bethor à l'Apothicaire Renferrel au Sépulcre des Pins argentés.", st = "Cet ichor a été créé par un vieux confrère : Thule Ravenclaw. C'était un jeune homme prometteur avant la Grande Guerre, mais quand le roi-liche vint au pouvoir, il trahit ses camarades en s'alliant au Fléau.$B$BJe n'avais pas réalisé qu'il était encore en vie, ni qu'il menait les Poils-putrides contre nous !$B$BJe connais beaucoup de ses sorts, et je peux aider à concocter une potion pour les contrer. Rapportez ce parchemin à l'apothicaire Renferrel. Il contient les incantations nécessaires à la potion.", t = "Thule Ravenclaw"},
    [447] = {ot = "Se rendre au Grouillement et y collecter 6 Cœurs de vieil ours et 6 échantillons de Sang du Grouillement, puis les apporter au maître apothicaire Faranell de la Société royale des apothicaires, à Fossoyeuse.", st = "Les troupes d'Arthas sont en nombre, mais avec une Peste nouvelle nous pourrions éradiquer à la fois l'armée du Fléau et les humains.$b$bMes études ont prouvé que du sang d'araignée associé à une toxine présente dans le cœur des vieux ours devient un élixir mortel. Collectez ces échantillons sur les araignées du Grouillement, au nord-ouest, et sur les ours qui arpentent la forêt des Pins argentés. Livrez ensuite ces ingrédients au maître apothicaire Faranell de la Société royale des apothicaires, à Fossoyeuse.", t = "Une recette mortelle"},
    [448] = {ot = "Faire un rapport au Grand exécuteur Hadrec au Sépulcre.", st = "Avant que vous n'attaquiez l'île de Fenris, faites un rapport au Grand exécuteur Hadrec. Il aura sans doute les informations et l'équipement complémentaires dont vous aurez besoin.", t = "Un rapport pour Hadrec"},
    [449] = {ot = "Apporter le rapport du Traqueur noir au Grand exécuteur Hadrec au Sépulcre.", st = "Bien que les blessures de Quinn soient en train de guérir, je veux que notre rapport parvienne au Grand exécuteur Hadrec le plus vite possible. Il contient des informations vitales pour maintenir l'occupation de la forêt des Pins argentés par les Réprouvés.", t = "Le rapport des Traqueurs noirs"},
    [450] = {ot = "Récupérer le Journal de Berard à l’Auberge de Bois-du-Bûcher et le rapporter à l'apothicaire Renferrel au Sépulcre.", st = "Vous pouvez encore être utile à la Société royale des apothicaires, $n.$b$bQuand Arugal a jeté sa misérable magie sur la forêt, il a maudit l'un de nos membres les plus prometteurs, l'apothicaire Berard. Devenu un serviteur décérébré d'Arugal, Berard ne nous sert plus à rien, mais ses découvertes pourraient être utiles. Il étudiait une ancienne peste qui a décimé toute la faune aquatique du lac de Lordamere, il y a longtemps.$b$bRécupérez le Journal de Berard dans son bureau à l'auberge de Bois-du-Bûcher et rapportez-le à l'Apothicaire Renferrel.", t = "Une recette mortelle"},
    [451] = {ot = "Apporter 6 Echantillons de Mousse de Rampant du lac, 6 échantillons de Mousse de Furtif du lac et une Tumeur durcie au Maître Apothicaire Faranell à Fossoyeuse.", st = "D'après le journal de Berard, la mousse de Furtifs et de Rampants du lac pourrait intervenir dans la composition d'une Peste nouvelle. Ces bêtes vivent sur les îles du lac de Lordamere, à l'est.$b$bLe journal évoque aussi une rarissime Tumeur durcie qu'il a découverte sur un murloc Aileron noir. Apparemment cette tumeur est tellement rare que Berard n'a pu en prélever qu'une.$b$bRecueillez des échantillons de mousse ainsi que de la Tumeur durcie et rapportez-les au Maître Apothicaire Faranell à Fossoyeuse.", t = "Une recette mortelle"},
    [452] = {ot = "Aider le Traqueur noir Faerleia à tuer les Membres du Conseil de Bois-du-Bûcher.", st = "Vous avez fait vite, $n !$b$bLes Conseillers de Bois-du-Bûcher vont revenir dans un instant. Arugal utilise les membres du Conseil comme autant de marionnettes pour garder la main mise sur le village. Mais je pense que sans le Conseil, les partisans d'Arugal se retourneraient contre leur maître.$b$bJe ne peux faire cela toute seule, j'ai besoin de votre aide. Ensemble, nous dévasterons le Conseil au nom de Dame Sylvanas.", t = "Embuscade à Bois-du-Bûcher"},
    [453] = {ot = "Retrouver l'Obscure Silhouette. Indices :$B$BIl n'est pas né à Darkshire.$B$BC'est un individu nerveux et craintif.$B$BIl a quitté Darkshire pour faire route vers l'ouest.", st = "Bonne chance, $n. J'espère que vous retrouverez le bonhomme, et vivant si possible.$B$BS'il a fui la sécurité de Darkshire, il pourrait être la proie des bêtes sauvages.", t = "À la recherche de l'Obscure Silhouette"},
    [454] = {ot = "Parler à Miran.", st = "Avant toute cette...histoire, nous étions en train de convoyer les barils de poudre. Mais maintenant nous devons répartir les tâches, Miran prenant les barils et moi veillant sur les autres.$b$bJe n'aime pas l'idée que Miran transporte le reste de la cargaison tout seul. Pourriez-vous l'escorter quand il sera prêt à partir ?", t = "Après l'embuscade"},
    [456] = {ot = "Tuer 7 Jeunes sabres-de-nuit et 4 Jeunes sangliers des chardons, puis retournez voir le Conservateur Ilthalaine.", st = "Salutations, $n. Je suis le Conservateur Ilthalaine. Mon rôle à Sombrevallon est de m'assurer que l'équilibre naturel est maintenu.$b$bLes pluies printanières furent particulièrement abondantes cette année, et certains animaux de la forêt en ont profité pour prospérer quand d'autres ont dépéri.$b$bMalheureusement la population des sabres-de-nuit et des sangliers des chardons s'est trop accrue. Sombrevallon ne peut produire plus d'une quantité donnée de nourriture pour les animaux. En route, jeune $c, réduisez la population des sabres-de-nuit et des sangliers des chardons afin de garantir l'harmonie de la nature.", t = "L'Equilibre de la nature"},
    [457] = {ot = "Le Conservateur Ilthalaine voudrait que vous tuiez 7 Sabres-de-nuit galeux et 7 Sangliers des chardons.", st = "Réguler les populations d'animaux à Sombrevallon est un bon début $n, mais il y a encore beaucoup à faire.$b$bLes ressources forestières seront bientôt épuisées si nous ne réglons pas rapidement le problème. Tuer les créatures de la nature est parfois un mal nécessaire pour le bien de tous ceux qui partagent cette terre. Aventurez-vous dans la forêt et éliminez les sabres-de-nuit et les sangliers des chardons malades, au nom de l'équilibre naturel.", t = "L'Equilibre de la nature"},
    [458] = {t = "La Protectrice sylvestre"},
    [459] = {t = "La Protectrice sylvestre"},
    [460] = {ot = "Apporter la tête d'Alaric jusqu’à sa tombe.", st = "Vous n'avez pas l'air d'un Poil-putride. C'est déjà ça. J'avais perdu espoir...$B$BMon nom est Alaric, j'étais naguère le serviteur et garde du corps de Thule. Il a tenté d'utiliser sa magie pour me \"protéger\" du Fléau mort-vivant, mais en fait, son sort m’a donné une forme de mort-vivant. Après avoir créé les maudits Poil-putride, Thule m’a décapité et donné ma tête aux gnolls pour qu'ils jouent avec !$B$BJe vous supplie de me ramener près de mon corps. Je suis sûr que les gnolls l'ont enterré ici, au donjon de Fenris, près des étables, dans une tombe anonyme.", t = "Reposer en… pièces"},
    [461] = {ot = "Amener Alaric à l’alcôve secrète.", st = "Je connais une alcôve secrète dans le donjon, qui contient un objet cher à Thule et ses anciens confrères. Il y a également quelque chose qui pourrait vous servir. Amenez-moi sur place !$B$BL’alcôve se trouve dans la tour la plus au sud-ouest du donjon, derrière une étagère poussiéreuse.$B$BPrenez mon corps, mais laissez mes bottes. De toute façon elles ne m'allaient pas...", t = "L’alcôve secrète"},
    [463] = {t = "Le Gouverneur vert"},
    [470] = {ot = "L'un des Limons dans le Tombeau d'Ironbeard a le sac de Sidonie. Le retrouver et le lui rapporter au Port de Menethil.", st = "A l'occasion de ma visite hebdomadaire au Tombeau d'Ironbeard, j'ai été attaquée par de redoutables Limons visqueux ! Naturellement, j'ai paniqué.$B$BJ'ai jeté mon sac sur l'un d'eux, qui l'a littéralement aspiré, ce qui m'a laissé le temps de m'enfuir.$B$BLa mauvaise nouvelle, c’est que j'ai absolument besoin du contenu de mon sac !$B$BEt je ne sais pas sur quel Limon je l'ai jeté : ils se ressemblent tous ! Le Tombeau d'Ironbeard est au nord-est, près de Dun Modr. Merci mille fois !", t = "En creusant dans la vase"},
    [471] = {ot = "Collecter 6 Peaux de crocilisque géant, et les apporter à James Halloran, au port de Menethil.", st = "J'ai envoyé mon apprenti dans les marécages pour chasser les fameux crocilisques géants des Paluns. Comme il ne revenait pas, je suis parti à sa recherche et l'ai retrouvé. Tout ce que je peux dire c'est que ce n'était pas... plaisant à regarder.$b$bLa rebouteuse dit qu'il va s'en sortir, mais entre-temps, j'ai toujours besoin de mes peaux !$b$b... Si vous tuiez quelques-uns de ces monstres, je n'y ferais aucune objection ; après ce qu'ils ont fait... Vous trouverez les crocos au nord de la côte, derrière les taudis des murlocs.", t = "Les devoirs de l'apprenti"},
    [475] = {ot = "Chercher Gaerolas Talvethren au village de Brise-stellaire.", st = "Une brise étrange souffle à travers la forêt.$b$bGaerolas Talvethren est le Grand gardien des druides de la Serre qui hibernent dans le Refuge des saisons de Ban'ethil. Son devoir en tant que protecteur des Dormants est de veiller à leur sécurité, afin que le pacte avec Ysera ne soit pas rompu.$b$bMais je n'ai toujours pas de nouvelles de Gaerolas. Allez à l'est, au village de Brise-stellaire et revenez avec des nouvelles de Gaerolas, que je puisse calmer mes craintes en apprenant que mon vieux camarade est sain et sauf.", t = "Une brise étrange"},
    [476] = {ot = "Retourner auprès d'Athridas Bearmantle à Dolanaar.", st = "La tribu des Pins-tordus a été corrompue !$b$bLes furbolgs, jadis paisibles, se sont retournés contre les protecteurs de la forêt. Ils m'ont tendu une embuscade tandis que je partais pour le Refuge des saisons de Ban'ethil, puis ils ont pillé le village de Brise-stellaire. Ursal le Mutileur, leur chef, utilise les pouvoirs malfaisants des gangremousses pour les rendre fous.$b$bJe suis trop gravement blessé pour aller voir Athridas et lui communiquer ces graves nouvelles. Cette tâche vous incombe à présent, jeune $c. Nous n'avons plus qu'à espérer que les Pins-tordus ne sont pas encore arrivés jusqu'à Ban'ethil !", t = "La corruption des Pins-tordus"},
    [477] = {ot = "Récupérer le contenu de l’une des caisses des Sorciers de Dalaran. Vous trouverez Bois-du-Bûcher au sud.", st = "Comme vous devez le savoir, Moulin-de-l'Ambre reste un bastion de l'opposition humaine. La ville est soutenue par les Sorciers de Dalaran qui l’approvisionnent.$b$bJe ne connais pas leurs plans, mais s'ils portent autant d'intérêt à ce trou perdu, c'est que cela doit être de première importance.$b$bIls transportent quantité de caisses depuis Hillsbrad. Beaucoup de ces convois ont pour terminus un petit camp au nord du village de Bois-du-Bûcher. Récupérez le contenu de l'une de ces caisses et apportez-le moi.", t = "Frontières"},
    [478] = {ot = "Apporter l'étrange pendentif au prêtre des ombres Allister au Sépulcre.", st = "<Vous retirez rapidement le Pendentif de la caisse et rabattez le couvercle.>", t = "Des cartes et des runes"},
    [479] = {ot = "Récupérer 8 Pendentifs de Dalaran pour le prêtre des ombres Allister du Sépulcre.", st = "Dalar essaie de localiser la source de la magie des sorciers. Pour l'heure, nous devons nous efforcer de ralentir leurs progrès...$b$bIl ne fait aucun doute que les conjurateurs, les mages et les protecteurs portent ces pendentifs. Récupérez-en.$b$bSuivez la route principale au sud, puis prenez à l'est à l'embranchement qui conduit à Moulin-de-l'Ambre.", t = "Enquête à Moulin-de-l'Ambre"},
    [480] = {ot = "Tuer l'archimage de Dalaran, puis récupérer son Bâton pour le prêtre des ombres Allister du Sépulcre.", st = "Un archimage de grand pouvoir supervise la réactivation du nœud d'énergie Ley. Vu les progrès qu'ils ont faits, notre seule chance de les arrêter est de tuer cet archimage. Ce sera difficile, car il est certainement protégé par d'autres mages et gardiens.$b$bVous devez partir et le neutraliser au plus vite. Quand il sera mort, récupérez son Bâton et apportez-le-moi. En avant !", t = "Le Tisserand"},
    [481] = {ot = "Apporter le Pendentif marqué de runes à Dalar Dawnweaver au Sépulcre.", st = "Apporter le Pendentif à Dalar Dawnweaver. Peut-être pourra-t-il anticiper les plans des Sorciers.", t = "L'analyse de Dalar"},
    [482] = {t = "Les intentions de Dalaran"},
    [483] = {ot = "Récupérer les Reliques d'éveil et les rapporter à Athridas Bearmantle à Dolanaar.", st = "Les Pins-tordus ont été vus ravageant le Refuge des saisons de Ban'ethil, à l'ouest.$b$bLes druides dormants vont être pris dans le Rêve d'émeraude pour l'éternité, à moins que nous n'intervenions. Leur très délicate hibernation ne peut pas être interrompue sans les quatre Reliques d'éveil.$b$bRendez-vous au Refuge et récupérez le Talisman Ravenclaw, la Plume noire, le Saphir des cieux et la Rune de nidification. Les druides les gardent dans des coffres sacrés. Apportez-les-moi afin que je prépare le rituel d'éveil.", t = "Les Reliques d'éveil"},
    [484] = {t = "Les peaux de jeune crocilisque"},
    [486] = {ot = "Tuer Ursal le Mutileur et retourner voir Athridas Bearmantle à Dolanaar.", st = "Le temps est venu de sauver les druides de la Serre. Si nous échouons maintenant, $n, ils resteront à jamais captifs de leur sommeil.$b$bJe pourrais préparer les reliques d’éveil et pratiquer le rituel, mais mon travail ne peut prendre effet tant que le responsable de cette horrible situation est en vie. Le rituel ne sera achevé que lorsqu’il aura été terrassé.$b$bC’est Ursal le Mutileur qui a perturbé notre cycle, c’est Ursal le Mutileur qui doit payer pour qu’ils puissent être libérés. Voyagez jusqu’au camp des Pins-tordus, au sud-ouest, et exécutez-le.", t = "Ursal le Mutileur"},
    [487] = {ot = "Tuer 6 Embusqués Pins-tordus et retourner voir la Sentinelle Amara Nightwalker à l'extérieur de Dolanaar.", st = "La route de Darnassus doit être sécurisée. Des voyageurs qui cheminaient entre Dolanaar et Darnassus y ont été témoins d'attaques de furbolgs de la tribu Pins-tordus.$b$bD'importantes informations et des convois commerciaux en provenance de Darnassus empruntent cette voie quotidiennement. Nous ne pouvons tolérer qu'une bande de brigands y terrorise les gens.$b$bAu nom de la Forêt sacrée, prenez les armes, $c. Leur repaire est quelque part au-delà de ce point. Tuez 6 de ces Embusqués Pins-tordus et revenez faire votre rapport.", t = "La route de Darnassus"},
    [488] = {ot = "Rapporter 3 Crocs de sabre-de-nuit, 3 Plumes de Hibou Strigid et 3 Echantillons de Soie d'araignée Tissebois à Zenn Foulhoof à l'extérieur de Dolanaar.", st = "Volontaire pour des missions, à ce que je vois. Heureusement, il n'y a pas un jour sans que je n'aie besoin d'un courageux $c prêt et armé pour répondre à mes demandes.$b$bVoyez-vous, $n, je puis vous rendre riche et vous offrir ce dont vous n'osez rêver. Mais en échange vous devez me rapporter certains objets.$b$bMon travail dans la forêt requiert souvent certains... réactifs. Rapportez-moi 3 Crocs de sabre-de-nuit, 3 Plumes de hibou Strigid et 3 échantillons de Soie d'araignée Tissebois.$b$bEt que tout cela reste entre nous, $n.", t = "Les commandements de Zenn"},
    [489] = {ot = "Collecter 3 Gangrenoix et les offrir à Zenn Foulhoof à l'extérieur de Dolanaar.", st = "Le Conseil de la forêt a eu vent que vous aviez aidé Zenn Foulhoof. Ce satyre est un ennemi de la forêt. Un $r devrait avoir mieux à faire que de la fragiliser en tuant ses créatures.$B$BVous devez vous racheter aux yeux du Conseil si vous désirez rester $gun ami:une amie; de Teldrassil.$B$BDonnez une bonne leçon à Foulhoof et vous serez $gracheté:rachetée;. Les gangrenoix sont des graines malades qui tombent des arbres. De la fumée verte en sort.$B$BApportez-en à Foulhoof. Il croira qu’il s’agit d’un inoffensif casse-croûte.", t = "En quête de rédemption !"},
    [490] = {t = "Prime : Furbolgs pins-tordus"},
    [492] = {ot = "Apporter la Boisson spéciale de Johaan au Montagnard captif.", st = "Selon le Garde noir, un autre de ces Montagnards nains insensés vient juste d'être capturé. Le Garde noir aime utiliser la cave de la taverne des Pendus comme cellule, jusqu'à ce qu'on puisse \"correctement\" s'occuper des prisonniers.$b$bPourquoi n'iriez-vous pas voir comment le captif apprécie la boisson spéciale que j'ai concocté pour lui ? Il contient un soupçon du traitement que la Dame noire a réservé au reste d'Azeroth.", t = "Une Peste nouvelle"},
    [493] = {ot = "Livrer les découvertes de l'Apothicaire Renferrel à l'Apothicaire Lydon à Moulin-de-Tarren dans les contreforts d'Hillsbrad.", st = "La Société royale des apothicaires est sous la constante pression de la Dame noire pour le développement de la Peste nouvelle. Nous travaillons sans relâche et avons fait de grands progrès. Nous pensons que le succès de notre entreprise serait plus rapide si nous partagions les informations au sein de la Société.$b$bPour cette raison, je veux que vous portiez mes dernières recherches à l'apothicaire Lydon à Moulin-de-Tarren, une petite ville nichée dans les contreforts d'Hillsbrad. Le voyage sera long.$b$bAllez au sud sans quitter la route. Suivez de près les panneaux !", t = "Voyage jusqu’aux contreforts d'Hillsbrad"},
    [494] = {ot = "Se rendre à Moulin-de-Tarren et délivrer le message du Traqueur noir Lesh à la Grande Exécutrice Darthalia.", st = "Taisez-vous et écoutez, $c.$b$bJ'ai été envoyée ici pour surveiller la ville d'Hillsbrad. C'est une mission de reconnaissance. Il est impératif que vous envoyiez immédiatement des nouvelles à la Grande Exécutrice Darthalia à Moulin-de-Tarren. Dites-lui que moi, le Traqueur noir Lesh, je lui transmets le message suivant :$b$b\"Le cri du corbeau retentit à l'ouest.\"$b$bSuivez la route vers l'est et faites bien attention aux panneaux. Allons, vite, partez pour Moulin-de-Tarren, et en toute hâte !", t = "Prêts à frapper"},
    [496] = {t = "L'élixir de souffrance"},
    [498] = {ot = "Selon les ordres de Krusk à Moulin-de-Tarren, libérer Drull et Tog'thar du donjon de Fort-de-Durn.", st = "Moi et d'autres guerriers avons été envoyés par le Chef de guerre pour récupérer un objet à Fort-de-Durn et enquêter sur ce prétendu Syndicat.$b$bNous sommes allés à Fort-de-Durn pour jeter un coup d'œil, mais nous avons été surpris par un grand nombre d'humains. Nous nous sommes bravement battus, mais ils étaient plus nombreux. Ils se sont emparés de nous, mais je suis parvenu à m'échapper.$b$bFort-de-Durn est au sud-est, de l'autre côté de la rivière. Drull et Tog'thar sont retenus là-bas, vous devez aller leur porter secours.", t = "Sauvetage"},
    [499] = {t = "L'élixir de souffrance"},
    [501] = {t = "L'élixir de douleur"},
    [502] = {t = "L'élixir de douleur"},
    [516] = {ot = "Localiser le Péril de Beren, tuer 6 Manouvriers Ravenclaw et 6 Gardiens Ravenclaw puis retourner voir le prêtre des ombres Allister au Sépulcre.", st = "J'ai reçu des rapports indiquant qu'un groupe de morts-vivants se cache pour préparer une attaque contre nous. Armés de cette information, nous pouvons retourner la situation en les attaquant les premiers et réduire leur plan minable à un simple souvenir cocasse.$b$bMalheureusement, les informations dont nous disposons sont incomplètes, au mieux. On dit qu'ils se cachent dans un endroit appelé Péril de Beren. La localisation exacte est inconnue, mais nous savons que c'est une caverne dans les collines, près d'une enclave des sorciers de Dalaran.$B$BJ'ai confiance en vos ressources. Trouvez-les et tuez-les.", t = "Le Péril de Beren"},
    [527] = {ot = "Tuer 6 Garçons de ferme, 6 Fermiers, le Fermier Ray et le Fermier Getz, puis retourner voir Darthalia à Moulin-de-Tarren.", st = "Mettez-vous au garde-à-vous lorsque vous vous adressez à moi, $c ! Je suis sous le commandement direct de Varimathras. Nous devons neutraliser la prolifération des humains jusqu'à ce que nos apothicaires développent la Peste nouvelle.$b$bNos services de renseignements pensent que la ville d'Hillsbrad serait vulnérable à une attaque. Votre première mission consiste à perturber leur approvisionnement et le stockage de nourriture.$b$bPartez à l'ouest. Faites une incursion dans les fermes les plus au nord des Champs d'Hillsbrad. Assurez-vous que leurs propriétaires, les fermiers Ray et Getz, soient exécutés.", t = "La bataille d'Hillsbrad"},
    [528] = {t = "La bataille d'Hillsbrad"},
    [530] = {ot = "Tuer Valdred Moray.$b$bApporter ses mains à Raleigh Andrean à Fossoyeuse.", st = "Valdred, autrefois un bon ami à moi, est le meurtrier de ma femme. Bien que je sois incapable de ressentir de la peine, j'aspire à la vengeance. Si vous tuez Valdred et me rapportez ses mains maudites, alors je vous récompenserai.$b$bLa dernière fois que j'ai entendu parler de lui, il se trouvait au mur de Grisetête, dans le sud des Pins argentés, essayant de fuir vers le royaume de Gilnéas.", t = "La vengeance d'un mari"},
    [531] = {ot = "Amener la tête du vieux Noiraud à Vyrin Swiftwind au pavillon des pérégrins.", st = "Par la Lumière ! N'apportez pas de choses comme ça dans le pavillon… c'est insalubre, insupportable, in… in… insalubre !$b$bSortez-moi ça de là, voulez-vous ? Personne ne veut voir votre fichu petit trophée, vraiment !", t = "La vengeance de Vyrin"},
    [544] = {t = "L'invasion de la prison"},
    [545] = {t = "Les patrouilles de Dalaran"},
    [546] = {ot = "Le Garde noir Samsa du Moulin-de-Tarren veut 30 Crânes d'humains d'Hillsbrad.", st = "J'ai entendu dire que vous étiez $grecruté:recrutée; par Darthalia pour mener l'offensive contre les humains d'Hillsbrad. Je vous envie tellement…$b$bTandis que vous vous amuserez – à tuer des humains, à piller, à terroriser les innocents – je resterai coincé ici, à Moulin-de-Tarren, à monter la garde et à me morfondre.$b$bPeut-être prendrez-vous en pitié un vieux Garde noir comme moi ? Vous remarquez que je fais la collection de crânes. Et vous allez combattre des humains pendant quelque temps, je crois. Au gré de votre longue bataille, vous récolterez bien quelques crânes, apportez-moi-en 30 et je vous rendrai la pareille d'une belle façon.", t = "Souvenirs de morts"},
    [549] = {ot = "Tuer 10 Voleurs et 10 Gardiens du Syndicat, puis aller voir la Grande Exécutrice Darthalia à Moulin-de-Tarren pour votre récompense.", st = "Au nom de l'autorité de Dame Sylvanas, tous les membres de l'organisation connue sous le nom du Syndicat sont recherchés. Ceux conduits à la garde ou faits prisonniers seront sommairement exécutés. Nous savons qu’actuellement ils se rassemblent dans les ruines du donjon de Fort-de-Durn, au sud-est de Moulin-de-Tarren.$b$bUne récompense est offerte à quiconque apporte la preuve de ses actions à la Grande Exécutrice Darthalia.", t = "ON RECHERCHE : Personnel du Syndicat"},
    [556] = {ot = "Apporter 10 Runes gravées au Conservateur Bel'varil à Moulin-de-Tarren.", st = "Un sérieux atout des sorciers de Dalaran est leur familiarité avec les élémentaires, ces créatures puissantes venant d'autres dimensions. Les sorciers utilisent des Runes gravées pour contrôler ces élémentaires. Le magus Voidglare aimerait étudier certaines de ces runes.$B$BPénétrez sur le territoire des sorciers de Dalaran, à l'ouest d'Hillsbrad, et trouvez-en.$B$BIl se peut que vous les trouviez sur n'importe quel citoyen de Dalaran, mais je suggère que vous vous les procuriez au camp d'internement. C'est un endroit moins dangereux que Dalaran.", t = "Les Runes gravées"},
    [557] = {ot = "Apporter 4 Brassards de liaison de terre au Conservateur Bel'varil à Moulin-de-Tarren.", st = "Le magus sera très occupé à étudier ces runes gravées que vous avez apportées, mais je sais que tôt ou tard il voudra des échantillons de leurs contreparties : des brassards de liaison. Ce sont des brassards qui, passés aux poignets des élémentaires, les lient au service des mages.$b$bChassez des élémentaires dans les ruines de Dalaran et récupérez leurs brassards de liaison de terre. Le magus en sera très satisfait.", t = "Les Bracelets de liaison"},
    [590] = {t = "Un marché de voleur"},
    [729] = {ot = "Aller vers le sud et vérifier l'état de santé du Prospecteur Remtravel.", st = "Quel honneur cela a été quand Maître Greywhisker m'a affecté aux ordres du grand Prospecteur Remtravel. À l'Académie de Forgefer tout le monde connaît les grandes découvertes de Remtravel.$b$bMais le Prospecteur est plutôt... hum... inconscient... de son environnement.$b$bNous avons découvert les traces d’une grande société. D'horribles Golems sont sortis du sol et ont envahi le site. Remtravel n'a pas semblé s'en apercevoir. J'ai fui à Auberdine pour demander de l'aide.$b$bS'il vous plaît, allez vers le sud pour voir si le prospecteur va bien !", t = "Les absences du Prospecteur"},
    [730] = {ot = "Aller à Auberdine et chercher des indices sur les nains de l'équipe de fouilles.", st = "Il est plaisant de voir qu'un $c s'intéresse à l'archéologie et aux grandes merveilles de notre monde.$b$bBien souvent, notre métier est considéré comme un simple passe-temps par nos amis de l'Alliance. Mais ce que la plupart d'entre eux ne comprennent pas, c'est que les récentes découvertes dans Khaz Modan ont prouvé que de grandes et mortelles puissances menacent tout Azeroth, de Lordaeron à Kalimdor.$b$bJe suis vraiment inquiet pour le groupe que j'ai envoyé à Sombrivage. Je suis sans nouvelles de lui depuis des semaines.$b$bAllez à Auberdine et cherchez des indices sur ce qu'il lui arrive.", t = "Des problèmes à Sombrivage ?"},
    [731] = {t = "Les absences du Prospecteur"},
    [741] = {ot = "Apporter le Mystérieux fossile au Chef archéologue Greywhisker, à Darnassus.", st = "Alors le prospecteur veut envoyer le mystérieux fossile à la Ligue des Explorateurs à Darnassus ? Quitter Sombrivage sans lui… ce n'est pas bien.$b$bVoilà, $n, apportez le mystérieux fossile au Chef Archéologue Greywhisker à Darnassus.", t = "Les absences du Prospecteur"},
    [743] = {ot = "Apporter 8 Serres de Furie-des-vents à Ruul Eagletalon, à Sabot-de-Sang.", st = "Merci de prendre le temps de me parler, $n. Je suis Ruul, guerrier et professeur.$B$BVous avez atteint l'âge où il vous faut vous préparer à de dures épreuves si vous comptez vous aventurer hors de Mulgore.$B$BSi vous voulez éprouver votre force, commencez par aller chasser les harpies Furie-des-vents au sud-est. Elles nichent le long des crêtes des montagnes, loin de la route.$B$BElles sont l'un de nos ennemis naturels, ici en Mulgore. Les affronter éprouvera vos compétences.", t = "Le danger des Furies-des-vents"},
    [744] = {t = "Préparation à la cérémonie"},
    [745] = {ot = "Tuer 10 Tanneurs crins-pâles, 8 Ecorcheurs crins-pâles et 5 Braconniers crins-pâles, puis retourner voir Baine Sabot-de-Sang, à Sabot-de-Sang.", st = "$n, il y a beaucoup de conflits qui ont dévasté cette terre. J'espère seulement que vous n'aurez pas à être le témoin du même nombre de batailles que je le fus, moi-même. Il y a pourtant une chose que je voudrais que vous fassiez ; cela vous montrera comment une menace, même minime, peut blesser ce pays, si elle n'est pas endiguée à temps.$B$BDes crins-pâles gnolls ont colonisé le sud de Sabot-de-Sang et une grotte à l'ouest. Ils ne répondent pas à nos tentatives de communication et massacrent les animaux sauvages de Mulgore.$B$BAvec cette engeance, la diplomatie n'est, hélas, plus une solution satisfaisante.", t = "Partager la terre"},
    [746] = {ot = "Collecter 5 Piolets de prospecteur.$B$BÀ la forge, brisez les Piolets du prospecteur pour obtenir des Outils cassés.$B$BRapporter 5 Outils cassés à Baine Sabot-de-Sang, à Sabot-de-Sang.", st = "Il y a des nains qui préparent des fouilles au nord-ouest. Ils pensent que la terre abrite des secrets et ils ont raison. Mais creuser et souiller le pays n'est pas un bon chemin vers la sagesse.$B$BCollectez les outils de forage des nains, fracassez-les et revenez avec les outils brisés.$B$BVous ne pourrez détruire les outils que dans une forge. Vous en trouverez une à Thunder Bluff, bien que n'importe quelle forge (même une forge dans le camp des nains) suffise à la tâche.", t = "Les fouilles des nains"},
    [747] = {ot = "Grull Hawkwind, à Camp Narache voudrait que vous lui apportiez 7 Plumes de trotteurs des plaines et 7 morceaux de Viande de trotteur des plaines.", st = "Vous avez un air prometteur, et vous allez avoir l'occasion de prouver votre valeur au sein de la tribu. Peut-être le jour est-il proche où l'on vous accueillera dans la grande ville de Thunder Bluff. Mais avant, vous devrez démontrer votre valeur à mon père, le Chef Hawkwind.$b$bIci, à la Mesa de Nuage rouge, nous sommes fiers de nos talents de chasseurs. Les taurens chassent par nécessité et par goût du sport. Notre stock de viande a diminué et nous avons besoin de plumes pour nos vêtements. Chassez les trotteurs des plaines du voisinage et faites vos preuves en réapprovisionnant le village.", t = "La chasse commence"},
    [748] = {t = "Eau empoisonnée"},
    [749] = {ot = "Examiner le contenu d'une caisse de provisions à la caravane dévastée, pour Morin Cloudstalker.", st = "Il y a quelques jours, nous avons intercepté une caravane de la KapitalRisk qui se déplaçait sous escorte sur les rives du lac Taureau-de-pierre. Nous avions déjà perdu deux des nôtres dans une bataille antérieure ; aussi avons-nous attaqué sans hésiter. La caravane fut dévastée.$b$bNous avons laissé leurs caisses de provisions sur place, pensant que nos torches détruiraient toute chose de valeur. Mais comme des sauveteurs de la KapitalRisk ont été repérés à côté des caisses brûlées, il se peut que nous nous soyons trompés.$b$bPeut-être pourriez-vous aller sur place et examiner le contenu de ces caisses.", t = "La Caravane dévastée"},
    [750] = {ot = "Grull Hawkwind, à Camp Narache, voudrait que vous lui apportiez 10 Peaux de puma des montagnes.", st = "Un tauren compétent dans l'art de la chasse sait que ses proies ne sont pas de simples trophées. Les animaux des plaines nous fournissent ce dont nous avons besoin pour survivre. Vous ferez grosse impression sur les plus âgés si vous réussissez à revenir avec quelques-unes de ces précieuses Peaux de puma des montagnes. Vous pourrez trouver ces bêtes dans les collines plus au sud.$b$bNos enfants ont besoin de vêtements et nos tentes d'être raccommodées.", t = "La chasse continue"},
    [751] = {ot = "Rapporter les Documents de la KapitalRisk à Morin Cloudstalker, à côté de Sabot-de-Sang.", st = "L'ouverture de la caisse révèle un assortiment de minerais divers, soigneusement empaquetés. Ceci est une preuve supplémentaire de l'activité minière de la KapitalRisk dans Mulgore. Sur les minerais, vous récupérez des rouleaux de papier, étroitement ficelés.$b$bLa-haut, dans les collines, vous pouvez presque entendre les bruits des outils de forage qui fendent les roches et voir la fumée des gigantesques feux d'alimentation.", t = "La Caravane dévastée"},
    [752] = {ot = "Partir chercher la mère du Chef Hawkwind, près du puits, au sud-est de Camp Narache.", st = "Tous les membres de la tribu prennent part à l'harmonie naturelle de la vie. Nous vivons et travaillons tous ensemble.$b$bNotre engagement les uns pour les autres implique une grande responsabilité envers autrui. Je voudrais vous demander une humble contribution.$b$bMa mère est partie ce matin pour tirer et rapporter de l'eau d'un puits qui est au sud-est de Narache. Le temps passe et elle n'est toujours pas rentrée. Peut-être pourriez-vous aller à sa rencontre ? Je suis, hélas, retenu ici par les affaires de la tribu.", t = "Une humble contribution"},
    [753] = {ot = "Prendre une Cruche d'eau du puits.$b$bApporter la cruche au Chef Hawkwind, à Camp Narache, au nord-ouest du puits.", st = "J'en ai vu et parcouru du pays, dans ma vie. Ces jambes fatiguées n'ont plus la vigueur d'antan, mais je peux encore servir la tribu... en prenant le temps qu'il faut.$b$bVous avez l'air d'un de ces $cs enthousiastes. Voici de quoi tester votre jeunesse et votre vitalité : prenez une cruche d'eau et apportez-la à mon fils, le Chef, à Camp Narache.$b$bRappelez-vous que même la tâche la plus humble peut parfois vous attirer la reconnaissance des aînés.", t = "Une humble contribution"},
    [754] = {t = "Purification de Winterhoof"},
    [755] = {ot = "Aller voir le Prophète Graytongue qui vit dans les collines au sud de Camp Narache.", st = "La volonté dont vous avez fait preuve en acceptant cet humble travail pour les taurens de Narache, ainsi que votre goût pour l'apprentissage révèlent la noblesse de votre caractère, $n. Je suis sûr qu'un jour vous serez $gconnu:connue; à Thunder Bluff comme l'un des $cs les plus valeureux.$b$bAvant cela, vous serez mis à l'épreuve des trois Rites de la Terre-mère.$b$bLa première épreuve est le Rite de force. Allez voir le Prophète Graytongue et dites-lui que le Chef Hawkwind vous envoie.$b$bVous trouverez la demeure du Prophète directement au sud de Camp Narache.", t = "Les Rites de la Terre-mère"},
    [756] = {ot = "Rapporter 6 Griffes de Traqueur et 6 Griffes de puma à Mull Thunderhorn.", st = "Pour créer le totem de purification de Corne-tonnerre, vous devez collecter les griffes des prédateurs qui hantent les plaines de Mulgore. Chassez les traqueurs des prairies et les pumas des basses plaines pour leurs griffes, puis revenez me voir.$B$BVous trouverez les traqueurs des prairies et les pumas des basses plaines à l’est et à l’ouest.", t = "Le Totem de Thunderhorn"},
    [757] = {ot = "Tuer des Dos-hirsute dans le Ravin de Roncelame et apporter 12 Ceintures de Dos-hirsute au chef Hawkwind au camp Narache.", st = "Les rites de la Terre-mère sont un passage obligé pour tout jeune tauren qui se respecte, à Thunder Bluff.$b$bLa première épreuve est le rite de Force. Vous devrez y démontrer votre bravoure en tuant des ennemis de la tribu.$b$bLes Dos-hirsute du ravin de Roncelame à l'est, empiètent sur nos terres tribales. Ils nous tendent des embuscades lors de nos parties de chasse et volent dans les villages, à la nuit tombée.$b$bProuvez votre valeur en massacrant ces vauriens et retournez voir le Chef, à Camp Narache, avec leurs ceintures pour prouver que vous les avez tués.", t = "Le Rite de force"},
    [758] = {ot = "Utilisez le Totem de purification de Thunderhorn au puits Thunderhorn, puis retournez voir Mull.", st = "Le totem est prêt, $n. Il vous faut encore pratiquer le rituel de purification.$B$BAllez au puits Corne-tonnerre, au nord du village et utilisez le totem de purification de Corne-tonnerre pour le rituel. Revenez me voir quand cela sera fait.$B$BQue les esprits soient avec vous.", t = "Purification de Thunderhorn"},
    [759] = {t = "Le Totem de Wildmane"},
    [760] = {t = "Purification de Wildmane"},
    [761] = {ot = "Apporter 8 Trophées de plumes de Rapace à Harken Windtotem, à Sabot-de-Sang.", st = "Le rapace est un oiseau rusé, difficile à trouver et à chasser, qui plus est. Une collection de plumes de rapace est signe d'intelligence et de détermination pour un chasseur.$B$BSi vous êtes $gprêt:prête; à entreprendre ce travail, pénétrez les plaines et chassez les rapaces.$B$BRapportez-moi leurs plumes et faites honneur à votre clan.$B$BVous trouverez les rapaces partout dans Mulgore, mais vos yeux doivent être affûtés pour les localiser et vos jambes, agiles pour les attraper.", t = "Chasse aux Rapaces"},
    [763] = {ot = "Apporter le Totem de Hawkwind à Baine Sabot-de-Sang à Sabot-de-Sang. Suivre la route hors du camp Narache.", st = "Il vous faut encore subir deux épreuves pour achever les Rites de la Terre-mère. Il est temps pour vous d'élargir votre expérience, $n.$b$bVoyagez jusqu’à Sabot-de-Sang et trouvez le Chef, Baine Sabot-de-Sang, fils de Cairne. Là, vous devrez continuer votre périple et gagner l'approbation des aînés de Thunder Bluff.$b$bPortez ce totem à Baine ; il reconnaîtra mes gravures et vous aidera dans votre quête.$b$bSuivez la route hors de Camp Narache et hâtez vous. Ne vagabondez pas de-ci de-là, vous vous perdriez.", t = "Les Rites de la Terre-mère"},
    [764] = {ot = "Tuer 14 Travailleurs de la KapitalRisk et 6 Superviseurs de la KapitalRisk pour Morin Cloudstalker de Sabot-de-Sang.", st = "Ceci explique l'accroissement des effectifs et des équipements de la KapitalRisk à Mulgore. Ces gobelins... leur nombre augmente bien trop vite. Comme on dit : quand on montre quelque chose à un gobelin, les bruits de la monnaie et du profit ne tardent pas à retentir.$b$bLes avides petites créatures... malheureusement pour eux, nous, les taurens, ne permettrons pas à leur entreprise de se développer sur nos terres. Allez à leur mine, au nord de la caravane dévastée, et portez leur un message.", t = "La KapitalRisk"},
    [765] = {ot = "Tuer le Superviseur Fizsprocket et rapporter son Ecritoire à Morin Cloudstalker, à Sabot-de-Sang.", st = "A en croire les documents que vous avez sauvés de la Caravane, la KapitalRisk a conçu plusieurs projets pour nous chasser de nos terres afin de pouvoir les piller et les exploiter en toute liberté.$b$bJe suis épouvanté de voir à quelles extrémités ces odieuses créatures sont prêtes à en venir pour accomplir leurs desseins. Le cerveau qui est à l'origine de leurs plans doit être tué. Son nom est Superviseur Fizsprocket et vous le trouverez à la mine de la KapitalRisk, à l'est de la Caravane dévastée. Rapportez-moi son écritoire ; peut-être nous apprendra-t-il quelque chose.", t = "Superviseur Fizsprocket"},
    [766] = {ot = "Apporter un Coeur de loup des plaines, un Fémur de puma des basses plaines, une Ecaille de trotteur des plaines et un Gésier de rapace à Maur Raincaller, à Sabot-de-Sang.", st = "Mon grand-père m'a conté sa bataille avec la créature nommée Mazzranache. Il m'a parlé de ses yeux rouges, démoniaques, de ses serres aiguisées comme des rasoirs et de sa morsure venimeuse.$b$bJ'ai eu la malchance de rencontrer la bête tandis que je cheminais à travers les plaines. Elle était exactement comme mon grand-père me l'avait décrite ; elle m'a attaqué et m'a profondément mordu à l'épaule. Son poison coule à présent dans mes veines et j'aurais besoin d'ingrédients rares pour réaliser un antidote : un coeur de loup, un fémur de puma, une écaille de trotteur des plaines et un gésier de rapace.$b$bHâtez-vous, le temps m'est compté.", t = "Mazzranache"},
    [767] = {ot = "Parler à Zarlman Deux-Lunes, à Sabot-de-Sang.", st = "Réussir le Rite de vision, un des rites de la Terre-mère, vous attirera le respect des aînés de Thunder Bluff.$b$bNotre peuple a compris que la terre était pourvoyeuse de ressources. Pour faire l'expérience de la vision rituelle, vous devez parler au chef spirituel du village, Zarlman Deux-Lunes.", t = "Le Rite de vision"},
    [768] = {ot = "Apporter 12 pièces de Cuir léger à Veren Tallstrider, à Thunder Bluff.", st = "Salut, $gmon:ma; jeune $gami:amie; ! Votre oeil brille d'une flamme farouche et je vois que vous avez hâte de retourner dans les plaines pour chasser. Puissiez-vous faire l'honneur de votre clan !$B$BJe travaille les peaux de bêtes ; j'en fais des vêtements et des armures pour les gens de Thunder Bluff.$B$BSi vous alliez chassez des bêtes et m'en rapportiez les peaux, je pourrais vous confectionner quelque chose.", t = "La chasse aux peaux"},
    [769] = {ot = "Apporter 4 pièces de Cuir léger et 4 Bobines de fil grossier à Veren Tallstrider, à Thunder Bluff.", st = "Les kodos de Mulgore sont puissants et robustes, qualités que nous respectons beaucoup. Si vous savez travailler le cuir et souhaitez apprendre à confectionner un sac en peau de kodo, apportez-moi les fournitures nécessaires.$B$BFaites cela et je partagerai mes connaissances avec vous.", t = "Sac en peau de kodo"},
    [770] = {ot = "Trouver quelqu'un qui puisse vous en apprendre davantage au sujet du Hurleur fantomatique.", st = "Cette peau déchiquetée de Hurleur fantomatique porte toujours la terrible blessure reçue lors de la bataille des loups contre la Légion ardente.$B$BPeut-être quelqu'un à Sabot-de-Sang sait-il quelque chose au sujet de la malédiction du Hurleur fantomatique...", t = "La Cape de démon balafrée"},
    [771] = {ot = "Collecter 2 Pierres de puits et 2 Pommes de pin et les rapporter à Zarlman Deux-Lunes, à Sabot-de-Sang.", st = "Pour passer le Rite de vision, vous devez collecter les ingrédients nécessaires à la réalisation de l'Eau des Prophètes.$b$bJ'aurai besoin de Pierres de puits, qui se trouvent autour des puits, à Mulgore. Je les combinerai aux pommes de pin, qui tombent des arbres majestueux de notre pays.$b$bCes ingrédients sont porteurs de grands principes magiques ; quand vous en consommerez les décoctions devant le feu tribal, leurs essences vous donneront une vision. Suivez-la et vous accéderez à l'étape suivante de votre quête sacrée.", t = "Le Rite de vision"},
    [772] = {ot = "Consommer l'Eau des Prophètes devant le feu tribal, à Sabot-de-Sang et suivre la vision quand elle apparaîtra.", st = "Vous allez maintenant être $gconfronté:confrontée; à l'Eau des Prophètes.$b$bQuand vous vous sentirez $gprêt:prête;, consommez-la en face du feu tribal. Une fois bue l'eau sacrée, la vision se matérialisera rapidement devant le feu.$b$bA ce moment-là, vous serez $gseul:seule; avec votre destin...", t = "Le Rite de vision"},
    [773] = {ot = "Voyager aux Rochers rouges, à l'est de Thunder Bluff et parler à Esprit ancestral.", st = "Pour gagner l'approbation des aînés de Thunder Bluff, vous devez désormais réussir le Rite de sagesse.$b$bMaintenant que vous avez achevé le Rite de vision, les esprits ancestraux des Rochers rouges vous donneront la bénédiction des ancêtres. Seuls ceux qui ont bu l'Eau des Prophètes accèdent à cette bénediction.$b$bVoyagez à l'est de Thunder Bluff, jusqu'aux Rochers rouges et cherchez l'Esprit ancestral, $n.", t = "Le Rite de sagesse"},
    [775] = {ot = "Parler à Cairne Sabot-de-Sang à Thunder Bluff.", st = "Vous allez maintenant être $grévéré:révérée; dans notre grande ville. Chaque $r qui passe avec succès les Rites de la Terre-mère a droit à cet honneur.$b$bPour votre quête finale, trouvez notre noble chef, Cairne Sabot-de-Sang, qui demeure au sommet de la plus haute mesa de Thunder Bluff.", t = "Voyage à Thunder Bluff"},
    [776] = {ot = "Apporter la Corne d'Arra'chea à Cairne Sabot-de-Sang, à Thunder Bluff", st = "Vous avez passé les rites de la Terre-mère et avez désormais votre place parmi nous, à Thunder Bluff.$b$bMais pour maintenir un prestige si durement gagné, vous devez continuer à prouver votre valeur auprès de votre peuple.$b$bNous sommes des chasseurs, $n. Plus bas, à Mulgore, vit une formidable bête kodo nommée Arra'chea. Prouvez votre habileté à la chasse ; traquez la bête et rapportez-moi la Corne d'Arra'chea.", t = "Les Rites de la Terre-mère"},
    [780] = {ot = "Grull Hawkwind, à Camp Narache, voudrait que vous tuiez des sangliers de guerre, et que vous rapportiez 8 Groins de sanglier de guerre et 8 Flancs de sanglier de guerre.", st = "Les sangliers de guerre apprivoisés du ravin de Roncelame se répandent sur nos terrains de chasse. Ils sont entraînés au combat et rendus agressifs par les hurans Dos-hirsute contre lesquels nous sommes en guerre.$b$bPartez ; massacrez ces infâmes créatures et revenez avec leurs groins et leurs flancs, que nous puissions en faire un bon ragoût pour les jeunes.", t = "Les sangliers de guerre apprivoisés"},
    [781] = {ot = "Apporter les Plans d'attaque Dos-hirsute au chef Hawkwind, au camp Narache.", st = "Après une analyse attentive de la carte, vous comprenez que vous avez découvert les plans du chef de guerre Dos-hirsute pour assiéger le camp Narache.$b$bLe chef Hawkwind pourrait certainement tirer profit de ces informations !", t = "L'attaque du Camp Narache"},
    [783] = {ot = "Parler au maréchal McBride.", st = "J'espère que vous avez le coeur bien accroché, jeune $c, car il y a du travail à faire à Comté-du-Nord.$B$BEt ce n'est pas du travail de ferme.$B$BLes gardes de Stormwind ont beaucoup à faire afin de maintenir la paix en ces lieux, tandis que nombre d'entre nous sont en des terres lointaines et que tellement de dangers nous menacent. Aussi acceptons-nous l'aide de tous ceux qui souhaitent défendre leur demeure. Et leur alliance également.$B$BSi votre volonté est de répondre à cet appel, allez parler à mon supérieur, le maréchal McBride. Il se trouve dans l'abbaye qui est derrière moi.", t = "Menace intérieure"},
    [784] = {ot = "Tuer 10 Marins de Kul Tiras, 8 Soldats de marine de Kul Tiras et le Lieutenant Benedict, puis retourner voir Gar'Thok à Tranchecolline.", st = "Guidés par l'amiral Proudmoore, les humains de Kul Tiras prirent pied en Durotar, en violation du pacte signé des années auparavant entre le Chef de guerre et Jaina Proudmoore pour vaincre Archimonde.$b$bL'attaque humaine fut repoussée et le donjon de Tiragarde tomba. Mais, récemment, les troupes de réserves de l'amiral, menées par le lieutenant Benedict, ont repris le donjon et menacent nos terres, une fois de plus. Ces humains ne montrent décidément aucun respect pour la diplomatie.$b$bDémontrez votre bravoure et voyagez vers le sud, jusqu'au donjon de Tiragarde, pour éliminer ses envahisseurs humains.", t = "Vaincre les traîtres"},
    [786] = {ot = "Détruire 3 Jeux de Plans d'attaque dans la combe des Kolkar, pour Lar Prowltusk à l'extérieur du village de Sen'jin.", st = "Parlez plus doucement, $c. Les centaures kolkar sont juste derrière la crête, à l'ouest, dans la combe des Kolkar.$b$bLa nuit dernière, alors qu'ils étaient en manœuvres, je me suis glissé dans leur village et j'ai découvert que ces tristes créatures envisageaient une attaque massive contre les trolls et les orcs de Durotar.$b$bNous ne pouvons leur permettre de mener leurs desseins à terme. Peut-être avez-vous les capacités requises pour vous infiltrer dans la combe des Kolkar et y détruire leurs plans d'attaque ?$b$bAux dernières nouvelles, ces plans ont été répartis entre trois de leurs chefs.", t = "Déjouer l'agression des Kolkar"},
    [788] = {ot = "Tuer 10 Sangliers tachetés, puis retourner voir Gornek, dans l’Antre.", st = "La première chose à faire sera de tremper un peu ce corps trop tendre. Je pourrais vous envoyer dans les Tarides pour y chasser des kodos ; mais en toute honnêteté, vous nous êtes plus utile $gvivant que mort:vivante que morte;.$b$bEn revanche, je pense que les sangliers tachetés seront des adversaires à votre hauteur. Vous les trouverez plus au nord.", t = "La dent tranchante"},
    [789] = {ot = "Apporter 10 Queues de scorpides ouvriers à Gornek, dans l’Antre.", st = "De piètres novices comme de grands guerriers ont succombé au dard venimeux des scorpides. Vous trouverez un grand nombre de ces créatures au nord-ouest. Apportez moi dix de leurs queues comme preuve que vous les avez affrontées.$b$bL'antidote à leur venin est préparé à partir de leur aiguillon. Nous conservons de grandes quantités de ce remède pour sauver de jeunes vies comme la vôtre...$b$bMais vous n'aurez certainement aucun besoin de ce contre-poison, n'est-ce pas ?", t = "L'aiguillon du scorpide"},
    [790] = {ot = "Tuer Sarkoth et rapporter sa pince à Hana'zua.", st = "$C ! Je me voyais déjà mort ici, ignoré de tous. Alors que je chassais les scorpides de la vallée, je fus soudain confronté à un spécimen particulièrement puissant. Je parvins à lui porter un grand coup avant qu'il ne referme ses pinces autour de ma jambe.$b$bJe fus, hélas, distrait par cette attaque et en oubliai le redoutable aiguillon, qui se ficha dans ma poitrine. Je vous en prie, tuez ce scorpide pour moi ! Mon honneur doit être lavé. J'ai combattu la créature sur le plateau, plus au sud.", t = "Sarkoth"},
    [791] = {ot = "Apporter 8 Morceaux de canevas à Furl Scornbrow, dans la la tour de guet de Tranchecolline.", st = "Mon âge me rend inapte au maniement des armes, mais j'ai appris à me rendre utile par d'autres moyens.$b$bDe ce poste d'observation, je guette les envahisseurs. Nos forces s'accroissant de jour en jour, je me trouve de moins en moins souvent à devoir donner l'alarme en soufflant dans le cor.$b$bAussi, pour passer le temps, je confectionne du matériel et aide de plus jeunes guerriers que moi à défendre leur pays.$b$bJe peux fabriquer un sac pour vos affaires. Si cela vous intéresse, apportez-moi du canevas, un matériau qu'on trouve communément chez les humains et les centaures.", t = "Assumer ses responsabilités"},
    [792] = {ot = "Tuer 12 Vils quasits.$B$BRetourner voir Zureetha Fargaze, à l’extérieur de l’Antre.", st = "Je suis sûre que la Vallée des épreuves vous enseignera beaucoup, jeune $c.$B$BJ'ai été envoyée dans la Vallée pour vous guider, mais j'y ai découvert une menace croissante.$B$BUn groupe qui se fait appeler la Lame ardente a un convent, ici, dans la Vallée des épreuves. Ils se cachent dans une grotte, au nord-est, d'où leurs vils quasits partent se répandre sur les terres pour les ravager.$B$BComme première action contre la Lame ardente, je vous demande de vaincre ces quasits. Massacrez-les en nombre et, si vous y avez survécu, revenez me voir.", t = "Les vils quasits"},
    [794] = {ot = "Rapporter le Médaillon de la Lame ardente à Zureetha Fargaze, à l'extérieur de l'Antre.", st = "Mes divinations me font voir qu'un objet de puissance se trouve loin à l'intérieur du convent de la Lame ardente, et qu'il est gardé par des bêtes et de la magie noire.$B$BVous devez trouver cet objet, le Médaillon de la Lame ardente et le prendre au convent.$B$BAttention, il sera probablement entre les mains d'un agent de la Lame ardente autrement plus puissant que les quasits.$B$BPartez, $n. Vous trouverez le Convent dans une caverne, au nord puis à l'ouest.", t = "Le médaillon de la Lame ardente"},
    [804] = {ot = "Informer Gornek, à l'Antre, de la situation critique dans laquelle se trouve Hana'zua.", st = "Ce que vous avez fait pour moi remplit mon cœur de courage. Je ne peux pas me laisser mourir comme ça, je dois me battre !$b$bJe ne puis, cependant, regagner l'Antre sans assistance. S'il vous plaît, $n, retournez à l'Antre et informez Gornek de ma situation. Peut-être saura-t-il m'aider.", t = "Sarkoth"},
    [805] = {ot = "Parler à Maître Gadrin au village de Sen'jin.", st = "Vos épreuves contre la Lame ardente sont finies… ici dans la Vallée. Mais je veux que vous rendiez compte de vos découvertes.$B$BAllez au village troll de Sen'jin et cherchez Maître Gadrin. Le village est à l'est de la vallée, puis à droite à l'embranchement.$B$BParlez-lui de la Lame ardente, dites-lui que ses membres ont atteint la Vallée des épreuves. Apprenez de lui s'ils ont déjà atteint Sen'jin.$B$BAllez, $n, et faites vite. J'ai peur que le mal découvert au convent de la Lame ardente ne présage un plus grand danger.", t = "Faire un rapport au Village de Sen'jin"},
    [806] = {ot = "Apporter la Griffe de Fizzle à Orgnil Soulscar à Tranchecolline.", st = "Nous ne pouvons permettre à la Lame ardente de prendre pied en Durotar ! Nous devons les détruire avant que ce mal ne suppure !$B$BJ'ai mené mes propres enquêtes et j'ai découvert qu'un démoniste de la Lame ardente, le gobelin Fizzle Darkstorm, s'est établi dans les falaises du Tonnerre au nord-ouest. Là-bas, lui et ses sectateurs répandent le chaos.$B$BTrouvez Fizzle, et éliminez-le. Apportez-moi alors sa griffe !", t = "Noirs orages"},
    [808] = {ot = "Récupérer le Crâne de Minshina dans le Cercle de puissance, sur les îles de l'Écho.$B$BLe rapporter à Maître Gadrin, au village de Sen'jin.", st = "J'entends la voix de mon frère Minshina qui m'appelle dans mes rêves.$B$BIl a été enlevé par Zalazane, le démoniste des îles de l'Écho, à l'est. Et il est mort.$B$BMais la mort ne l’a pas libéré. Car Zalazane a emprisonné son esprit dans son propre crâne. Dans mes rêves, je peux le voir parmi d'autres crânes, dans un cercle de puissance situé sur la plus grande des îles de l'Écho. Tant qu'il y reste, son esprit est condamné.$B$BJe vous en prie, $n. Trouvez le cercle et le Crâne de Minshina. Rapportez-le.$B$BLibérez-le !", t = "Crâne de Minshina"},
    [809] = {ot = "Parler à Ak'Zeloth, dans les Tarides.", st = "Depuis la dernière grande guerre où la Légion ardente fut défaite, j'ai recherché les sources de corruption démoniaque dans la société des orcs. Le collier que vous m'avez apporté confirme mes craintes.$B$BIl appartient à la Lame ardente, un culte en possession d'un objet de grand pouvoir maléfique qu'on appelle la Graine démoniaque. Vous pouvez la trouver dans les Tarides, au sommet du pic de Brume-funeste. La Graine doit absolument être détruite !$B$BAllez au Poste de garde extérieur, à l'ouest sur la frontière des Tarides et parlez avec mon assistant, Ak'Zeloth. Il vous donnera les prochaines directives.", t = "Ak'Zeloth"},
    [812] = {ot = "Trouver Kor'ghan à Orgrimmar et obtenir l'Antidote du Queue-venin. L'apporter ensuite à Rhinag près de la frontière nord-ouest de Durotar.", st = "$n... votre minutage est parfait. J'espère que je pourrai en dire autant de votre célérité.$B$BJ’ai manqué d'attention en combattant des Queues-venin aux alentours, et j'ai été piqué par l'un d'entre eux. Le poison m'affaiblit au moment même où je parle. A ce rythme, il me reste peut-être une heure à vivre. Mais je vais avoir besoin de vous...$B$BKor'ghan, à Orgrimmar, sait comment confectionner l'antidote. Trouvez-le... et faites vite, $n. Je ne vais pas pouvoir tenir beaucoup plus longtemps. Il devrait se trouver dans la Faille de l'ombre.", t = "Besoin d'un remède"},
    [813] = {ot = "Apporter 4 Glandes à venin de Queue-venin à Kor'ghan à Orgrimmar.", st = "Les scorpides Queue-venin sont parmi les plus dangereux en Durotar. Rhinag a manqué de sagesse lorsqu'il a les a chassés sans emporter d'antidote, mais à présent, une remontrance est vraiment la dernière chose dont il a besoin.$B$BApportez-moi des Glandes à venin de n'importe quel Queue-venin, et je lui préparerai un antidote. Vous en trouverez près de l'entrée d'Orgrimmar.$B$BDépêchez-vous, $n. L'un d'entre nous a besoin de votre aide.", t = "La recherche de l'antidote"},
    [815] = {ot = "Rapporter 3 Oeufs de fouette-queue au cuisinier Torka, à Tranchecolline.", st = "Bah ! J'allais presque oublier... faut qu'je ficelle le p'tit déjeuner$B$B$n, bougez- vous l'train et allez m'trouver quelques oeufs de fouette-queue. M'en faut au moins trois si j'veux en avoir aussi pour le déjeuner de demain.$B$BLe fouette-queue Griffesang peut être farouche et protège ses oeufs jusqu'à la mort, ça oui. Ils les enfouissent parfois bien trop profondément pour pouvoir les déterrer ; mais, bon, si vous fouinez un peu du côté des îles de l'Écho, au sud-est du village de Sen'jin, vous en trouverez d'accessibles à foison, partout sur ces îles.", t = "Des oeufs pour l'omelette"},
    [816] = {ot = "Trouver un indice du sort de Kron et en informer Misha Tor'kren, à la ferme, au nord-ouest de Tranchecolline.", st = "$n, pouvez-vous m'aider ? Mon fils, Kron, est parti chasser il y a quelques jours et il n'est toujours pas revenu. Il est allé à l'ouest, vers les Tarides, pour traquer des crocilisques, le long du fleuve Furie-du-Sud. Je crains le pire.$B$BAussi fort soit-il, sa fierté mal placée l'a toujours conduit dans les pires situations. Lorsque je lui ai dit que les crocilisques étaient puissants et brutaux, il s'est emporté et est parti.$B$BSi vous ne le ramenez pas, découvrez au moins ce qu'il est devenu...Même si vous devez pour cela ouvrir le ventre de chaque crocilisque, le long des bancs de sable de la Furie-du-Sud.", t = "L'égaré"},
    [817] = {ot = "Apporter 4 Peaux de tigres de Durotar à Vel'rin Fang, au village de Sen'jin.", st = "La plupart des peaux que nous utilisons proviennent des tigres de Durotar, $n. Couvertures, armures, tentes, nous avons beaucoup de raisons de chasser ces bêtes, et autant de les laisser prospérer.$B$BLe temps est venu de cueillir la récolte, pour ainsi dire. Nos rangs grandissent et les besoins de mon peuple sont supérieurs à nos provisions. Il me faut plus de peaux pour subvenir à ces besoins.$B$BApportez-moi 4 Fourrures de tigres de Durotar, et je vous récompenserai. Vous pourrez les trouver sur les îles au sud d'ici.", t = "Proie nécessaire"},
    [818] = {ot = "Apporter 4 Yeux de makrura intacts et 8 Fioles de mucus de clampant à maître Vornal, au village de Sen'jin.", st = "Même si mes yeux sont faibles, j'y vois encore suffisamment clair. Je me repose souvent sur mes compétences en alchimie pour les magies qui autrefois m'étaient aisées. Mais je refuse de prendre $gun apprenti:une apprentie;. Aucun orc ou troll assez digne ne s'est jamais présenté.$B$BEt vous, en êtes-vous digne ? Bien sûr que vous en êtes digne... que vous croyez l'être.$B$BJ'ai besoin de certaines choses. Pouvez-vous les obtenir ?$B$BIl me faut des yeux de makruras intacts, et des fioles de mucosités de clampants. De n'importe quels makruras ou clampants en Durotar. Nous nous reparlerons bientôt.", t = "Un esprit parfaitement éduqué"},
    [819] = {ot = "Trouver quelqu'un qui en sache davantage au sujet du Tonneau vide de Chen.", st = "Un petit écriteau, placé sur l'un des bouts du tonneau, dit :$B$B\"Chen Stormstout-$B$BQue laper règne sur la terre comme au ciel, et que les spiritueux soient avec votre esprit.\"", t = "Tonneau vide de Chen"},
    [821] = {t = "Tonneau vide de Chen"},
    [822] = {ot = "Apporter 5 Glandes de corne-éclair, 1 Glande salivaire de faucon-tonnerre et 1 Foie de kodo au brasseur Drohn à Ratchet.", st = "Sacré caractère, cette Brune d’Orage, hein ?$B$BJ’ai une autre recette que j’ai apprise de Chen. Ça vous intéresse ? Ça ne sera pas long, et ça peut même vous être utile si vous comptez poursuivre vos aventures.$B$BApportez-moi cinq glandes d’éclair d’orageux, une glande salivaire de faucon-tonnerre et un foie de kodo. Vous trouverez tout ça dans les Tarides.$B$BComme je l'ai dit, ce breuvage décoiffe. C'est la tête de Trogg dont je vous ai parlé.", t = "Tonneau vide de Chen"},
    [823] = {ot = "Parler à Orgnil Soulscar à Tranchecolline.", st = "Nous autres au village de Sen'jin avons nos problèmes, et nous vous remercions pour votre aide. Mais les nouvelles que vous apportez à propos de la Lame ardente pourraient annoncer des ennuis pour tout le monde.$B$BUn orc nommé Orgnil Soulscar est posté à Tranchecolline. Il protège Durotar de maux tels que la Lame ardente. Allez lui parler et informez-le de notre demande. Donnez-lui également des nouvelles de la Vallée des épreuves. Il voudra savoir ces choses.$B$BTranchecolline est au nord.", t = "Un rapport à Orgnil"},
    [824] = {ot = "Apporter le Globe d'eau souillée à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", st = "Le Cercle terrestre est un groupe de chamans dédié à l'étude et à la préservation des éléments. Ils en savent plus sur les dieux anciens fous, les vieilles légendes et les savoirs antiques que la plupart des savants de ce monde.$B$BHeureusement pour vous, je connais quelqu'un du Cercle terrestre, ici, à Ashenvale. Allez à l'avant-poste de Zoram'gar, sur la côte de la grève de Zoram. Montrez à Je'neu Sancrea ce que nous avons trouvé. Si quelqu'un peut découvrir quelle est la signification de ce globe, c'est bien lui.", t = "Je'neu du Cercle terrestre"},
    [825] = {ot = "Gar'Thok de Tranchecolline veut que vous retrouviez 3 Outils gnomes parmi les épaves près de la côte.", st = "L'un de mes éclaireurs les plus observateurs me rapporte que les épaves de la flotte de Proudmoore sont toujours près de la côte de Durotar, juste à l'est du donjon de Tiragarde.$b$bCe n'est un secret pour personne que les humains, alliés à ces petites bêtes idiotes que sont les gnomes, possèdent des connaissances avancées en mécanique. Nous devons apprendre précisément les savoirs de tous nos ennemis potentiels. Et notre peuple bénéficiera de ces nouveaux savoirs, également.$b$bNagez à travers les épaves, $n, et trouvez pour moi les outils de l'Alliance.", t = "Des épaves"},
    [826] = {t = "Zalazane"},
    [827] = {ot = "Prendre les Colliers brûlants des sectateurs au Rocher du crâne.$b$bLes apporter à Margoz à son camp.", st = "$n. La Lame ardente a infesté la caverne appelée le Rocher du crâne, à l'est d'Orgrimmar. Ils y accomplissent des rituels abominables, et brûlent leur propre chair avec des Colliers brûlants.$b$bEn portant ces colliers, je pense que les sectateurs s'harmonisent avec la puissance démoniaque. Mais pour le confirmer, je dois en posséder une collection afin de les étudier.$b$bPartez pour le Rocher du crâne et prenez les Colliers brûlants que vous trouverez sur les membres du culte. Apportez-les-moi, et je dévoilerai leurs mystères.", t = "Rocher du crâne"},
    [828] = {ot = "Parler à Margoz.", st = "L'un de nos chamans, Margoz, en sait plus sur la corruption de la Lame ardente. Il parle d'une caverne appelée Rocher du crâne dans les montagnes, juste à l'extérieur d'Orgrimmar, qui abrite un important groupe de sectateurs.$b$bAvant que vous ne partiez pour le Rocher du crâne, parlez à Margoz. C'est un sage et son conseil est précieux.$b$bIl campe au nord-est, entre la côte et le Ravin asséché.$b$bSuivez son avis, mais quoi qu'il dise, $n, je veux que vous écrasiez ce culte !", t = "Margoz"},
    [829] = {ot = "Apporter un Spécimen de collier à Neeru Fireblade à Orgrimmar.", st = "Les Colliers brûlants que vous m'avez apportés sont des instruments puissants et démoniaques. Deviner leur origine est cependant, je le crains, au-delà de mes capacités de chaman. Nous aurons besoin qu'un démoniste les étudie.$b$bApportez un Collier brûlant à Neeru Fireblade. Bien qu'il soit un redoutable démoniste, il professe qu'il utilise ses pouvoirs pour contrecarrer les démons, et proclame que ses recherches sur l'occulte sont bénignes. Que cela soit vrai ou pas, nous pouvons avoir besoin de son aide contre le culte démoniaque en Durotar. Vous trouverez Neeru à Orgrimmar, dans la Faille de l'ombre.", t = "Neeru Fireblade"},
    [830] = {ot = "Apporter les Ordres de l'amiral Proudmoore à Gar'Thok de Tranchecolline.", st = "Vous ouvrez la vieille enveloppe décolorée et découvrez un document d'apparence officielle. Vous reconnaissez le sceau de l'amiral Proudmoore.$b$bÇa a l'air important. Peut-être que Gar'Thok, le commandant de Tranchecolline, serait intéressé par cette information.", t = "Les ordres de l'amiral"},
    [831] = {ot = "Porter les Ordres de l'amiral Proudmoore à Nazgrel, dans les appartements de Thrall à Orgrimmar.", st = "On ne peut pas faire confiance aux humains. Nous avons combattu à leurs côtés le cœur empli de lassitude, sachant qu'ils nous trahiraient un jour.$b$bLa mort de l'amiral Proudmoore n'a pas été suffisante pour clore cette longue tradition de tromperie. Cette vermine avait bien préparé ses plans avant qu'il ne rencontre la mort.$b$bSon influence ne s'éteindra pas non plus avec Benedict. Qui sait combien de temps il reste avant que la prochaine vague d'hommes de Proudmoore ne déferle sur nos rivages ?$b$bNous devons apporter ces ordres à Nazgrel à Orgrimmar immédiatement ! On peut le trouver dans les logements de Thrall.", t = "Les ordres de l'amiral"},
    [832] = {ot = "Apporter cet Oeil à Neeru Fireblade.", st = "<Des mots émanent du pendentif et dans votre esprit.>$B$BGazz'uz ?$B$BGazz'uz… au rapport !$B$BOn raconte que vous avez été découvert au rocher du crâne. Vous devez vous préparer à une attaque !$B$BGazz'uz, je vous ordonne de parler ! Parlez ou je m'assurerai que Neeru Fireblade apprenne votre présence, et il vous tombera dessus comme la misère sur le monde.$B$BNe testez pas vos capacités contre Neeru...$B$B... Gazz'uz, vous êtes là ?", t = "Ombres ardentes"},
    [833] = {ot = "Le Gardien du savoir Raintotem veut que vous tuiez 8 Intrus Dos-hirsute aux Rochers rouges.", st = "Seuls les plus vaillants taurens sont enterrés aux Rochers rouges, notre terre funéraire sacrée. C'est un honneur accordé aux grands guerriers qui ont aidé à construire et à défendre Thunder Bluff et à ceux qui ont donné leur vie pour le bien de leur tribu et de leurs chefs.$b$bMais il apparaît qu'un infâme danger menace notre terre sacrée. Un groupe d'Intrus Dos-hirsute ravage le cimetière et je suis trop vieux et trop faible pour les repousser.$b$bIls doivent pourtant être chassés sans pitié, $n.", t = "Cimetière sacré"},
    [834] = {ot = "Retrouver 5 Sacs de marchandises et les rendre à Rezlak près d'Orgrimmar.", st = "Je suis Rezlak, l'un des gars de Gazlowe. Le patron m'a envoyé pour donner un coup de main aux orcs, ici en Durotar. Les choses se sont bien passées, à part pour les caravanes. Je n'arrive pas à assurer leur sécurité ! Ça rend mon boulot un peu plus difficile, vous savez ?$b$bLa dernière livraison – ils ont promis que je passerais ! – a été chipée par les harpies Terrevent au... c'était où déjà... au canyon de Tranchevent ?$b$bFaut que je récupère ces marchandises ou je n'arriverai jamais à rien ! Suivez le grand canyon vers le sud, vous trouverez le ravin coupant exactement les parois à l'est et à l'ouest.", t = "Des vents dans le désert"},
    [835] = {ot = "Tuer 12 Terrevent farouches et 8 Sorcières des tempêtes Terrevent pour Rezlak près du Ravin asséché.", st = "Gazlowe m'a dit une fois \"Rezlak, il y a une chose que tu dois savoir dans la vie : si tu veux qu'une chose soit faite de manière correcte, fais-la toi-même.\"$B$BJe ne peux supporter la perte de nos caravanes, alors je vais m'occuper des choses en personne. Le Ravin asséché est quelque part dans la partie est du canyon de Tranchevent. Si nous y tuons toutes les harpies, les routes seront sûres.$B$BBien sûr, il y a autre chose que Gazlowe m'a enseigné, et c'est \"En payant bien, tout est possible.\" Alors, vous allez m'aider, $N ?", t = "Des lignes sécurisées"},
    [837] = {ot = "Tuer 4 hurans Tranchecrin, 4 Eclaireurs Tranchecrin, 4 Lève-poussière Tranchecrin et 4 Gardes de guerre Tranchecrin pour Gar'Thok de Tranchecolline.", st = "Quand nous sommes arrivés, les hurans Tranchecrin possédaient la majeure partie de la terre, et étaient comme une épine dans notre flanc. Par des efforts constants, nous sommes parvenus à en chasser une grande partie, mais ils restent toujours bien fortifiés dans certains secteurs.$b$bCela a suffisamment duré, cependant. Pour notre propre sécurité, nous ne pouvons tolérer la présence des Tranchecrins sur notre territoire. On peut trouver leurs camps à l'ouest d'ici. Cherchez les roncières et vous les trouverez. Aujourd'hui, nous les chassons de Durotar, et demain, peut-être, de tout Kalimdor.", t = "Empiètement"},
    [840] = {t = "Sous les drapeaux de la Horde"},
    [842] = {ot = "Suivre la route à l'ouest à partir du Poste de garde extérieur de Kargal.$b$bA l'intersection en T, tourner à gauche et suivre la route vers le sud.$b$bTrouver Sergra Darkthorn où les routes se croisent à l'intérieur de la Croisée.", st = "Apportez cette lettre de recrutement signée à la Croisée.$b$bSergra Darkthorn, que sa peau soit maudite, est la responsable là-bas. C'est une affreuse chaman qui vous saoulera de paroles avant de vous laisser faire quoi que ce soit d'utile. Thrall est convaincu qu'elle est spéciale, mais je n'en suis pas si sûr.$b$bVous aurez à vous faire votre propre opinion, $gmorveux:morveuse;...", t = "Conscription à la Croisée"},
    [843] = {ot = "Gann Stonespire veut que vous tuiez 15 Excavateurs de Bael'dun et 5 Surveillants de Bael'dun.$b$bApporter le Journal de Khazgorm à Gann Stonespire.", st = "Je foule ces chemins dans la solitude.$b$bLes nains de Bael Modan n'ont aucun respect pour ma terre. D'horribles explosions creusent profondément le sol tandis que des machines éventrent les collines. La terre qui autrefois était le foyer et la nourrice de ma tribu est aujourd'hui grouillante de ces nains destructeurs.$b$bLes tentatives diplomatiques pour arriver à un accord ont échoué. À présent l'heure de l'action radicale a sonné.$b$bRepoussez par la force les nains de Bael Modan et apportez-moi le journal de leur chef, le Prospecteur Khazgorm.", t = "La réclamation de Gann"},
    [844] = {ot = "Collecter 7 Becs de trotteurs des plaines et les apporter à Sergra Darkthorn à la Croisée.", st = "Votre première proie sera une proie facile.$B$BLes trotteurs des plaines, à l'est, attaquent constamment nos réserves de nourriture et sont devenus une véritable nuisance.$B$BAbattez-les et revenez me voir avec leurs becs.", t = "La menace des trotteurs des plaines"},
    [845] = {ot = "Tuer des Messagers zhévras et apporter 4 Sabots de zhévra à Sergra Darkthorn à la Croisée.", st = "Les zhévras ne sont pas les bêtes les plus redoutables des Tarides, mais ils sont un peu plus dangereux que les trotteurs des plaines. Ne vous en faites pas, nous vous enverrons combattre des proies plus conséquentes en temps utile, mais vos dents ont encore besoin d'être aiguisées.$B$BChassez les zhévras au nord et au sud, et récupérez leurs sabots. Apportez-les-moi et peut-être que la prochaine fois nous vous indiquerons quelque chose de plus coriace.", t = "Les zhévras"},
    [846] = {ot = "Gann Stonespire veut que vous lui apportiez 6 Fioles de Nitroglycérine, 6 Paquets de Pulpe de bois, et 6 Echantillons de Nitrate de sodium.", st = "Il est évident que le prospecteur dépendait des explosifs et des véhicules bruyants pour déchirer le sol. Nous pouvons nous attendre à ce qu'un nouveau contremaître le remplace bientôt.$b$bJ'aimerais faire goûter aux nains leur propre médecine. D'après ces plans, si nous combinons de la nitroglycérine avec de la pulpe de bois et du nitrate de sodium, nous pouvons créer une charge explosive. Les fusiliers, les soldats et les officiers du donjon possèdent ces ingrédients.$b$bRécupérez ces objets et apportez-les-moi. Je confectionnerai une charge que les nains ne sont pas près d'oublier.", t = "La revanche de Gann"},
    [848] = {ot = "Apporter 4 Spores fongiques à l'Apothicaire Helbrim à la Croisée.", st = "Les oasis des Tarides abritent un mystère. L'énergie de la vie coule dans leur eau, revigorant les plantes et les bêtes qui la boivent.$b$bRevigorante et stimulante.$b$bUn champignon pousse près de ces oasis. Ses spores détiennent des propriétés que nous, les Apothicaires de Lordaeron, trouvons utiles.$b$bApportez-moi ces spores et vous obtiendrez ma gratitude.", t = "Spores fongiques"},
    [849] = {t = "La revanche de Gann"},
    [850] = {ot = "Apporter la Tête de Barak à Regthar Deathgate, à l'ouest de la Croisée.", st = "Les centaures nuisent aux taurens depuis des années. Et récemment, les centaures Kolkar des Tarides sont devenus un danger réel. D'habitude, ils étaient désorganisés, mais de nouveaux chefs ont émergé. Et les ont unis.$b$bAfin de préserver nos possessions ici, ces chefs centaures doivent être éliminés.$b$bApportez-moi la tête de Barak Kodobane. Il campe près des Bassins oubliés au nord.$b$bBattez-le, puis revenez me voir.", t = "Les chefs des Kolkar"},
    [851] = {ot = "Apporter la Tête de Verog à Regthar Deathgate, à l'ouest de la Croisée.", st = "Le centaure Verog le Derviche rôde dans les Tarides, et il va être difficile à trouver. Mais il est basé à la tente de commandement des centaures, à l'Oasis stagnante au sud-est. Il peut être possible de l'attirer.$B$BPartez pour l'Oasis stagnante au sud-est et attaquez les centaures près de la tente de commandement. Ce sera dangereux, mais si vous tuez suffisamment de centaures, ils sonneront l'alarme. Et Verog viendra.$B$BApportez-moi sa tête et je la mettrai avec celle de Barak Kodobane.", t = "Verog le Derviche"},
    [852] = {ot = "Apporter la Tête d'Hezrul à Regthar Deathgate, à l'ouest de la Croisée.", st = "Hezrul Marque-de-sang est le chef des centaures Kolkar dans les Tarides. Il est féroce, brutal et malin. L’éliminer sèmerait la confusion et briserait l’unité des Kolkar. Le danger qu'ils représentent serait ainsi largement diminué.$B$BAussi tuez-le. Tout comme pour Barak et Verog, apportez-moi sa tête.$B$BHezrul dirige son peuple depuis l'Oasis luxuriante, au sud.", t = "Hezrul Marque-de-sang"},
    [853] = {t = "Apothicaire Zamah"},
    [854] = {ot = "Parler à Thork, à la Croisée des Tarides.", st = "J'avais prédit votre arrivée, jeune $c. Bien que peut-être vous ne soyez plus si jeune.$b$bJe crois qu'il est temps de vous aventurer plus profondément dans ces terres. Je sens que vous êtes $gdestiné:destinée; à de grandes choses.$b$bC'est la Croisée que vous devez chercher à présent, dans la mesure où nos vies se sont mêlées à celles des orcs et qu'ils ont besoin de notre aide. Descendez cette route vers l'est et suivez-la vers le nord en direction de la Croisée. Trouvez Thork dans ses murs, il est béni par la Terre-mère.", t = "Un voyage à la Croisée"},
    [855] = {ot = "Apporter 15 Bracelets de centaures à Regthar Deathgate, à l'ouest de la Croisée.", st = "Les Kolkar représentent une menace pour les ambitions de la Horde dans les Tarides ; nous devons réduire leur nombre. De fait, j'ai une mission pour vous, en échange d'une récompense.$B$BAllez sur les terres des Kolkar, tuez leurs guerriers et récupérez des bracelets de centaures. Revenez quand vous en aurez un tas ; la Horde vous récompensera largement.", t = "Les bracelets de centaures"},
    [857] = {ot = "Feegly l’Exilé veut que vous retrouviez pour lui la Larme des lunes.", st = "La puissance était mienne ! Dans mes propres mains ! Et je veux la retrouver ! La retrouver, je vous dis !$b$bCes fichus Excavateurs l'ont découverte… Elle était tellement belle. Avoir trouvé la Larme des lunes, c'était la première grande découverte qu'on avait faite à Bael Modan.$b$bElle aurait dû être mienne ! Mienne je vous dis !$b$bMais le général Twinbraid devint jaloux de la puissance qu'elle me donnait. Il l'a enfermée à clé dans le donjon. L'a traitée de maudite, il l'a fait ! L'imbécile !$b$bD'autres la voulaient et ils devaient être arrêtés ! Ce bâtard de Twinbraid m'a chassé.$b$bMaintenant, je la veux à nouveau ! Je la veux je vous dis !", t = "La larme des lunes"},
    [858] = {ot = "Récupérer la Clé de contact et l'apporter à Wizzlecrank.", st = "Ce n'est sûrement pas Sputtervalve qui vous a $genvoyé:envoyée; ? Je suis coincé ici. Je suis entré sans réaliser que j'avais besoin d'une clé pour déverrouiller la colonne de mouvement du déchiqueteur. L'un des autres opérateurs m'a demandé si tout allait bien, et j'ai paniqué ! Au lieu de lui dire que je n'avais pas la clé, je lui ai dit qu'il y avait un genre de problème mécanique.$b$bNous devons sortir d'ici au plus vite ! Montez à la salle de contrôle au sommet du derrick, le superviseur devrait avoir une clé pour ce déchiqueteur.$b$bSortez-moi de là !", t = "Contact"},
    [862] = {ot = "Apporter 8 Rats fouisseurs à Boustiff' à l'est de la Croisée.", st = "Les $cs comme vous doivent plutôt avoir faim ici dans les Tarides. Moi, je crève la dalle tout au long de la journée.$b$bJe vais vous mitonner un chouette brouet. J'ai juste besoin de quelques rats fouisseurs.$b$bIl semble que ces sales nains de Bael Modan soient submergés par le festin favori de tout un chacun. À présent descendez vers le sud, à Bael Modan, et apportez-moi quelques rats fouisseurs.$b$bVous ne pouvez pas vous prétendre $gaventurier chevronné:aventurière chevronnée; si vous n'avez pas passé du temps à tuer des rats ! Ha !", t = "Brouet de rat"},
    [863] = {ot = "Protéger Wizzlecrank et le Déchiqueteur gobelin volé jusqu'à Sputtervalve à Ratchet.", st = "Je suppose que j'apprendrai en le faisant… Ça ne devrait pas être trop difficile. Juste quelques boutons par-ci par-là, et un levier ou deux… Alors, êtes-vous $gprêt:prête; à y aller ?", t = "La fuite"},
    [865] = {ot = "Collecter 5 Cornes de raptors intactes prises sur des Faucheurs solécaille, et les apporter à Mebok Mizzyrix à Ratchet.", st = "Les raptors des Tarides sont plus malins que les autres. Et je pense que cette intelligence se trouve dans leurs cornes ! Si tel est vraiment le cas, alors je pourrais réduire leurs cornes en poudre et les utiliser pour en faire une \"potion d'intelligence\". Je pourrais en tirer une fortune !!!$B$BEt vous pouvez m'aider. Trouvez-moi des Cornes de raptors intactes sur des Faucheurs solécailles. Ils parcourent les Tarides septentrionales, et le nord des Tarides près de la frontière avec la forêt d'Ashenvale.", t = "Les cornes de raptors"},
    [866] = {ot = "Apporter 8 Echantillons de Racines à Mebok Mizzyrix, à Ratchet.", st = "Les herbes qui poussent dans les Tarides ne sont pas tout à fait pareilles à celles des autres contrées. Leurs propriétés sont à peu près semblables, mais l'eau des oasis les transforme légèrement. Elles sont juste un peu différentes.$b$bJ'aimerais étudier ces différences... pour voir si nous pouvons les exploiter !$b$bSi vous êtes $gun herboriste compétent:une herboriste compétente;, cueillez les herbes que vous trouvez dans les Tarides. Apportez-moi ces échantillons que je puisse les comparer aux herbes des autres régions.", t = "Les échantillons de racines"},
    [867] = {ot = "Collecter 8 Griffes d'Ensorçaile.$b$bLes apporter à Darsok Swiftdagger à la Croisée.", st = "Ces maudites harpies massacrent nos caravanes d'approvisionnement depuis trop longtemps déjà. Il est temps que nous tranchions quelques-unes de leurs gorges et que nous réduisions leur nombre.$b$bJ'ai jeté des coups d'œil discrets à leurs nids et j’ai compris leur hiérarchie. L'attaque la plus dévastatrice devra détruire une bonne partie de leur chaîne inférieure de commandement, pour que nous puissions ensuite remonter jusqu'au sommet.$b$bNous allons commencer en douceur. Tuez des harpies et des Volplumes Ensorçaile au nord-ouest, et apportez-moi 8 Griffes d'Ensorçaile. Ce sera bien pour commencer...", t = "Les harpies pillardes"},
    [868] = {t = "La chasse aux œufs"},
    [869] = {ot = "Apporter 12 Têtes de raptor à Gazrog, à la Croisée.", st = "Il y a peu, une cargaison d'argent a été volée à notre tour de garde. Cet argent était destiné à payer les gardes de la Croisée, et nous voulons le récupérer.$B$BLe point étrange est que… nous avons arrêté un voleur la nuit même du vol. Et il s'agissait... d'un raptor ! Incroyable !$B$BJe ne sais pas quels raptors seraient intéressés par cet argent. Mais qu’importe ! Je veux qu’ils soient tués afin qu'ils ne nous volent pas à nouveau !$B$BPartez à leur recherche dans les Tarides et récupérez leurs têtes !", t = "Les raptors voleurs"},
    [870] = {ot = "Rendre compte de vos découvertes à Tonga Runetotem.", st = "Il y a longtemps de cela, les Tarides étaient un endroit luxuriant, fourmillant de vie. Mais la guerre et le chaos ont ravagé la terre, l'ont brûlée et finalement laissée telle une bogue desséchée. Ainsi se sont passées les choses, et cela chagrine mon cœur.$b$bMais ces dernières années, de nouvelles oasis se sont formées dans les Tarides, et la vie frémit à nouveau. Et loin sous le sol, nous les druides sentons une puissance se frayer un chemin vers la surface.$b$bNous devons en trouver la source. Partez pour les Bassins oubliés, au nord-ouest de la Croisée. Parcourez les eaux et cherchez la source de cette puissance, puis revenez me voir.", t = "Les Bassins oubliés"},
    [871] = {ot = "Dans la tribu Tranchecrin, tuer 8 Sourciers, 8 Tisseuses d’épines et 3 Chasseurs, puis retourner voir Thork.", st = "Tous les hurans sont nos ennemis, $n. Certains ne représentent simplement qu'une nuisance plus importante que les autres.$B$BLa tribu Tranchecrin a attaqué nos lignes d'approvisionnement en provenance de Durotar, nous causant des soucis sans nombre. J'ai des éclaireurs qui recherchent le chef de ces expéditions, mais en attendant, toutes les pertes que vous pourriez leur infliger nous seraient d'une grande aide.$B$BCommencez au nord-est, en direction de Durotar. Vous pouvez toujours repérer leurs tanières grâce aux ronces géantes qui sortent de la terre. Cherchez-les. Trouvez-les. Et tuez-les.", t = "Stopper les attaques des hurans"},
    [872] = {ot = "Tuer 8 Géomanciennes Tranchecrin, 8 Défenseurs Tranchecrin et Kreenig Grondegroin.$b$bPuis apporter la Défense de Kreenig Grondegroin à Thork à la Croisée.", st = "L'un de mes éclaireurs a été témoin d'une attaque sur une caravane en provenance de Durotar, $n. Les coupables sont effectivement des hurans de la tribu Tranchecrin. L'un d’eux en particulier dirige les attaques : Kreenig Grondegroin. On l'a vu au nord-est d'ici, juste au sud de la route venant de Durotar. Pour régler le problème, Kreenig doit mourir.$b$bPour s'assurer que les attaques cessent, je suggérerais quand même que l'on fasse un exemple.$b$bTuez Kreenig et des membres de sa tribu, puis revenez me voir lorsque vous aurez sa Défense.", t = "La perturbation cesse"},
    [873] = {ot = "Apporter le Cœur d'Isha Awak à Mahren Skyseer.", st = "Le grand Isha Awak est le seigneur de ces eaux. Grande est sa force et solennelle est sa fierté. Les humains de la côte le craignent, car il en a occis beaucoup parmi eux.$b$bMais il ne me fait pas peur. Je suis reconnaissante de son existence. Il est un digne défi et une proie honorable.$b$bSi vous êtes $gprêt:prête; alors partez nager et cherchez Isha Awak, le Destin des profondeurs.$b$bSon esprit demeure dans son cœur, et l'entendre battre, c'est voir votre destinée.", t = "Isha Awak"},
    [874] = {ot = "Parler à Mahren Skyseer.", st = "Vous avez chassé les bêtes des Tarides. Votre esprit est fort. Mais un chasseur doit toujours être prêt. Un véritable chasseur doit être capable de traquer une proie sur n'importe quelle piste. Des montagnes ou des marais ne sauraient le rebuter.$B$BEt pas même la mer.$B$BAllez trouver ma soeur, Mahren. Elle chasse les grandes bêtes maritimes le long de la côte. Ce sera votre professeur.$B$BMais soyez $gprudent:prudente; tandis que vous la recherchez, car la côte des Tarides est détenue par des humains.", t = "Mahren Skyseer"},
    [875] = {t = "Lieutenants harpies"},
    [876] = {ot = "Tuer Serena Plumesang et apporter sa tête à Darsok Swiftdagger à la Croisée.", st = "Vous vous en êtes tellement bien $gsorti:sortie; avec les lieutenants et autres harpies subalternes que j'aimerais que vous fassiez une dernière chose pour moi.$b$bSerena Plumesang est la sœur d'une harpie nommée Plumesang qui a été tuée par Rexxar il y a longtemps. Apparemment, ces attaques sur les caravanes de la Horde sont une vengeance pour la mort de sa sœur.$b$bJ'ai besoin que vous lui tranchiez la gorge et que vous me rapportiez sa tête. Je la placerai sur la prochaine caravane que nous enverrons... Histoire de donner aux harpies un sujet de réflexion.", t = "Serena Plumesang"},
    [877] = {ot = "Retourner voir Tonga Runetotem à la Croisée, après avoir enquêté à l'Oasis stagnante.", st = "Tout comme celle que vous avez trouvée aux Bassins oubliés, il se peut qu'il y ait des fissures dans les autres oasis des Tarides. Si tel est le cas, alors peut-être que ces fissures sont la source de vie des oasis.$b$bNous devons tester cette hypothèse.$b$bTenez, prenez ces graines. Elles sont mortes et stériles, mais emportez-les à l'Oasis stagnante, au sud-est. S'il y a une fissure là-bas, alors placez-y les graines... et observez.", t = "L'oasis stagnante"},
    [878] = {ot = "Tuer 6 Sourciers Dos-hirsute, 12 Tisseurs d’épines Dos-hirsute et 12 Géomanciennes Dos-hirsute puis retourner auprès de Mangletooth au camp Taurajo dans les Tarides.", st = "Vous devez frapper mes ennemis <grogne>. Vous devez aider Mangletooth et les Tranchecrins en affaiblissant les Dos-hirsute Les deux tribus accordent beaucoup d'importance à la spiritualité et sont très liées à la terre et à ses pouvoirs <grogne>. Cela nous apporte de la force en tout, et pour la guerre en particulier.$B$BSi vous voulez découvrir qui a causé à Thork <grogne> et à la Horde un tel supplice, alors aidez Mangletooth ! Attaquez les chefs spirituels des Dos-hirsute au nord. Affaiblissez-les afin que les Tranchecrins puissent les vaincre et régner sur les Tarides.", t = "Tribus en guerre"},
    [879] = {ot = "Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mangletooth au Camp Taurajo dans les Tarides.", st = "Trois membres de ma tribu sont venus du Kraal pour diriger les raids contre la Horde, $n <grogne>. Ils sont brutaux et malins, et si vous parvenez à les vaincre, alors votre Croisée et même la plus grande partie des Tarides seront en paix... <grogne>.$B$BNak, Kuz et Lok Plaie-des-orcs sont ceux que vous recherchez. Ils se trouvent loin au sud des Tarides. L'un lance des sorts, l'autre est un pisteur, et leur chef, celui qu'on nomme Plaie-des-orcs <grogne> est un guerrier. Tuez-les, $n, tout comme ils m'ont tué.", t = "Une trahison de l'intérieur"},
    [880] = {ot = "Apporter 8 Carapaces de Gueules d'acier altérées à Tonga Runetotem à la Croisée.", st = "Vos découvertes sont incroyables, $n. Ces oasis détiennent des propriétés qui doivent provenir d'une source extérieure. Ou peut-être intérieure.$B$BJe veux savoir comment ces fissures affectent les bêtes qui boivent aux eaux des oasis.$B$BChassez les gueules d'acier des oasis à l'Oasis luxuriante et à l'Oasis stagnante. Apportez-moi leurs carapaces pour que je les examine.", t = "Source de vie"},
    [881] = {ot = "Apporter la Peau d'Echeyakee à Sergra Darkthorn à la Croisée.", st = "Blanchebrume, Echeyakee dans la langue des taurens, est le roi des lions des savanes. Il chasse si furtivement qu’il est comme une brume légère et blanche sur la terre. Et il tue si vite que ses proies n'ont pas le temps d'avoir peur ni de souffrir.$B$BLes taurens disent qu'il est à la fois la miséricorde et la mort.$B$BVous apprendrez si cela est vrai, car je vous lance sur la trace d'Echeyakee. Son repaire est au nord-est de la Croisée, parmi les os des kodos géants.$B$BRendez-vous à son repaire, soufflez dans cette corne, et il viendra.", t = "Echeyakee"},
    [882] = {ot = "Apporter le Croc d'Ishamuhale à Jorn au Camp Taurajo.", st = "Ishamuhale, Lancecroc, est le plus redoutable des raptors solécaille. Il ne chasse pas pour se divertir, ni pour se nourrir. Il chasse par passion. Il tue car sa nature est de tuer.$B$BEt vous allez apprendre de cette nature, $n, car votre voie suit à présent les traces griffues d'Ishamuhale.$B$BCommencez la chasse. Tuez sa proie favorite, un zhévra, puis emmenez sa carcasse à l'arbre mort au nord-ouest de Ratchet. Ishamuhale sera attiré par l’odeur.$B$BSoyez $gprêt:prête; lorsqu'il arrivera.", t = "Ishamuhale"},
    [883] = {ot = "Apporter le Sabot de Lakota'mani à Jorn au Camp Taurajo.", st = "Le Sabot de Lakota'mani est un symbole de la force du grand kodo.", t = "Lakota'mani"},
    [884] = {ot = "Apporter l'Epine caudale d'Owatanka à Jorn au Camp Taurajo.", st = "Lorsqu'on le touche, des étincelles jaillissent de l'épine caudale d'Owatanka.", t = "Owatanka"},
    [885] = {ot = "Apporter la Plume de Washte Pawne à Jorn Skyseer au Camp Taurajo.", st = "La Plume de Washte Pawne est douloureuse au toucher.", t = "Washte Pawne"},
    [886] = {ot = "Parler à Tonga Runetotem à la Croisée.", st = "Les druides de Thunder Bluff sentent une étrange puissance qui fuit dans les Tarides, à l'est de Mulgore.$b$bNous avons envoyé Tonga Runetotem pour enquêter sur la source de cette puissance, mais nous craignons qu'il ait besoin d’aide.$b$bVoyagez jusqu'aux Tarides et parlez à Tonga. Il sera à la Croisée. Pour atteindre cet endroit, prenez la route à l'est en sortant de Sabot-de-Sang. Entrez dans les Tarides, puis tournez vers le nord lorsque la route se divise. Continuez dans cette direction et vous trouverez la Croisée.$b$bEt ne quittez pas la route, $n, car les Tarides sont hostiles.", t = "Les oasis des Tarides"},
    [887] = {ot = "Tuer 12 Brigands et 6 Canonniers des Mers du Sud pour Gazlowe de Ratchet.", st = "J'aurais vraiment souhaité que le vice-amiral Grezzlik fasse un meilleur travail pour que nos navires marchands puissent sillonner les mers en toute sécurité. Avec tout l'or que les princes marchands ont versé, voir autant de pirates attaquer mes navires et voler mes marchandises me rend malade !$b$bJ'ai entendu dire que les Flibustiers des Mers du Sud ont établi un camp juste au sud d'ici. Ils ont été une source d'irritation constante et si Grezzlik ne s'en occupe pas, alors, vous, peut-être, pourriez m'en débarrasser.", t = "Les flibustiers des Mers du sud"},
    [888] = {ot = "Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazlowe de Ratchet.", st = "J'aimerais récupérer toutes mes marchandises. Hélas, je suis sûr que ce n'est pas possible. Mais il y a des choses que je dois absolument récupérer !$b$bComme vous pouvez le constater, mon observatoire est prêt à fonctionner, mais il manque la plus petite des deux lentilles. La première est arrivée de Durotar par caravane, mais la deuxième a été envoyée par bateau, et elle ne m'est jamais parvenue ! Je n'ai pas non plus reçu mes bottes de chez Drizzlik à Baie-du-Butin !$b$bPartez pour le camp des pirates, et voyez si vous les trouvez.", t = "Course à la lentille"},
    [890] = {ot = "Apporter le Grand Livre de Gazlowe au Maître des quais Dizzywig.", st = "J'ai attendu durant une éternité l'arrivée de mon dernier chargement de marchandises de Baie-du-Butin ! Je suis à peu près sûr qu'il a dû être volé par les Flibustiers, mais pour que je le sois complètement, pourriez-vous descendre du côté des docks et demander à Dizzwig si mes marchandises ont déjà été livrées à mon entrepôt sans que je le sache ?$B$BTenez, descendez mon Grand livre à Dizzwig et demandez-lui de vérifier à nouveau mes inventaires par rapport à ses registres.", t = "La livraison perdue"},
    [891] = {ot = "Le capitaine Thalo'thas Brightsun de Ratchet veut que vous collectiez 10 Médailles de Theramore et que vous tuiez le Capitaine Fairmount, le Canonnier Whessan et le Canonnier Smythe.", st = "J'ai encore perdu un navire contre ces humains trop zélés du Fort du Nord !$b$bNous devons nous occuper de ces bâtards. Leur paranoïa les met dans un état de totale frénésie. Ces gâchettes faciles, ces rustres insouciants canardent tout ce qui passe dans leur ligne de mire.$b$bPartez vers le sud, le long de la Côte des marchands, vers le Fort, et persécutez-les. Apportez les médailles de leurs soldats comme preuve. Et pour l'amour de ma flotte marchande, tuez le capitaine Fairmount et ses canonniers trop enthousiastes.", t = "Sous le feu de l'ennemi"},
    [892] = {t = "La livraison perdue"},
    [893] = {ot = "Apporter un Poignard de Tranchecrin, une Baguette Tranchecrin carbonisée et un Bouclier Tranchecrin à Tatternack Steelforge au camp Taurajo dans les Tarides.", st = "Les hurans Tranchecrin, au sud, au-delà du Champ des géants, n'ont pas de forgerons compétents, que je sache. Mais ils ont apparemment commencé à construire des armes plus solides. J'aimerais mettre la main sur différents types de ces armes pour acquérir leurs techniques, si possible.$B$BSi vous souhaitez œuvrer pour l'honneur de la Horde, apportez-moi des exemples de leurs armes. Obtenez une dague de leurs traqueurs, une baguette de leurs prophètes, et un bouclier de leurs frénétiques. Cela devrait parfaitement faire l'affaire.", t = "Des armes de choix"},
    [894] = {ot = "Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk.", st = "La KapitalRisk a construit un petit centre de recherches loin au nord, au sud-ouest de la Videfange. Je ne sais pas vraiment ce qu'ils y font, mais j'ai quand même réussi à découvrir qu'ils font des expériences avec quelque chose qu'ils appellent \"Samophlange\".$B$BÀ présent, que diable est le Samophlange ? Eh bien, quoi que ce soit, je veux l'examiner, et j'ai besoin que quelqu'un le prenne.$B$BJ'ai réussi à obtenir une copie de leur Manuel de la console de contrôle, vous devriez ainsi comprendre comment en désengager le Samophlange.", t = "Samophlange"},
    [895] = {ot = "Apporter la tête du baron de Longrivage à Gazlowe à Ratchet.", st = "ON RECHERCHE !$b$bBaron de Longrivage, capitaine de \"l'Insouciant\".$b$bLe capitaine Longrivage de Gilnéas commande des navires pour le compte des Flibustiers des Mers du sud, il est recherché pour actes de piraterie. Ses restes doivent être identifiables !$b$bGazlowe", t = "ON RECHERCHE : baron de Longrivage"},
    [896] = {ot = "Prendre l'Emeraude œil-de-chat à l'un des Surveillants ou l'un des Massacreurs de la KapitalRisk pour le Maître des quais Dizzywig à Ratchet.", st = "Etant Maître des quais d'un port plein d'activité comme Ratchet, je prends toujours le pouls de l'information. Je sais tout des échanges de biens et d'argent entre ici et Baie-du-Butin.$B$BLa dernière nouvelle que j'ai entendue concerne la mine des Pierriers de la KapitalRisk, au nord-est de la Videfange. L'un des mineurs y a découvert une émeraude aussi grosse que votre poing. Je connais quelques acheteurs qui voudraient mettre la main sur un tel joyau, et je suis prêt à faire 50-50.", t = "La bonne fortune d'un mineur pauvre"},
    [897] = {ot = "Apporter la Tête du Moissonneur à Jorn Skyseer.", st = "Cette étrange créature, qui ressemble à un insecte, n'a pas l'air de faire partie de l'ordre naturel, comme si elle n'appartenait simplement pas aux Tarides.", t = "Le Moissonneur"},
    [898] = {ot = "Escorter en toute sécurité Gilthares Firebough jusqu'au capitaine Brightsun à Ratchet.", st = "Enfin ! Quelqu'un est venu me sauver !$B$BIl est incroyable que vous ayez passé les gardes. Ces fanatiques de Theramore sont devenus fous. Ils ont coulé notre navire et m'ont emprisonné. Je suis le seul survivant. Ils ont dit que j'étais leur ennemi et un danger pour l'Alliance.$B$BMoi ! Un danger pour leur parodie d'Alliance ? J'étais matelot sur un transport de gnôle entre Ratchet et Baie-du-Butin.$B$BMais assez parlé. Aidez-moi à retourner à Ratchet, voulez-vous ? Dites-moi lorsque vous serez $gprêt:prête; et nous prendrons la fuite.", t = "Hors du fort"},
    [899] = {ot = "Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée.", st = "Connaissez-vous l’affliction du doute, $c ? Sachez seulement que je suis là toute la journée à scruter l’horizon pour repérer ces monstres. J’ai tué chaque homme-sanglier que j’ai rencontré depuis, mais ma soif de sang est loin d’être étanchée. Peut-être qu’au lieu d’aller au nord, vers la Croisée, j’aurais dû me diriger sur Taurajo.$B$BVous, $c, vous pourriez m’aider.$B$BTuez-en autant que vous pourrez. Apportez-moi leurs défenses et nous boirons ensemble à leur destruction.", t = "Consumé par la haine"},
    [900] = {ot = "Fermer la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utiliser à nouveau la console de contrôle.", st = "Les trois valves de contrôle sont à présent ouvertes. Les indications sur le panneau de contrôle vous amènent à penser qu'elles doivent être fermées pour que l'appareil puisse être arrêté.", t = "Samophlange"},
    [901] = {ot = "Obtenir la Clé de la console de l'artisan Sniggles, puis l'utiliser sur la console de contrôle.", st = "Maintenant que l'appareil est désactivé, le panneau de contrôle peut s'ouvrir et on peut sortir le Samophlange de la console. À présent que tout est en place, il reste à trouver la clé qui déverrouillera la console.", t = "Samophlange"},
    [902] = {ot = "Rapporter le Samophlange à Sputtervalve à Ratchet.", st = "Ouvrir la console de contrôle révèle des entrelacs de fils, de tubes et d'autres objets mécaniques étranges, dont la plupart ne semblent avoir aucune utilité. En les écartant et en fouillant au fond le la console, vous découvrez le Samophlange. Vous le retirez d'un coup sec de son réceptacle.", t = "Samophlange"},
    [903] = {ot = "Collecter 7 Griffes de Rôdeur des savanes pour Sergra Darkthorn à la Croisée.", st = "Il est temps à présent de courir après quelque chose qui mord vraiment. Les rôdeurs des Tarides sont une espèce résistante. Résistante, pleine de ressources, sournoise… et mortelle. Vous les trouverez parmi les herbes hautes. Ils sont nombreux au sud-ouest de la Croisée.$B$BSoyez $gprudent:prudente; tandis que vous les chassez, $N, ou vous ne serez plus $gle prédateur:la prédatrice;, mais bien la proie.", t = "Les rôdeurs des Tarides"},
    [905] = {ot = "Tuer des raptors solécaille et récupérer leurs plumes. Placer ces plumes dans les 3 nids de Faucheurs solécaille, puis retourner voir Sergra Darkthorn à la Croisée.", st = "À présent, $n, la chasse devient plus difficile. Vous devez battre votre proie, et trouver le chemin jusqu'à son repaire.$B$BChassez les raptors solécaille au sud. Tuez-les et enlevez leurs plumes. Placez les plumes dans les nids des Faucheurs au sud-ouest de l'oasis stagnante. Montrez à leurs semblables que vous ne les craignez pas !", t = "Les Faucheurs furieux"},
    [906] = {ot = "Apporter le Crâne de Lok à Thork à la Croisée des Tarides.", st = "Apportez la tête de Lok à Thork à la Croisée, $n <grogne>. Il devrait savoir ce qu'il est advenu de ma tribu sans le moindre mot--ha, mais je ne m'attends pas à ce qu'il croie que Mangletooth y a <grogne> contribué. Mais il est certain qu'il vous récompensera pour vous être $goccupé:occupée; de tels actes <reniflement>.$B$BJe vais continuer à vous bénir du pouvoir d'Agammagan aussi longtemps que je resterai dans cette cage, $n. Jusque-là, adieu.", t = "Une trahison de l'intérieur"},
    [907] = {ot = "Apporter 3 doses de Sang de lézard-tonnerre à Jorn Skyseer, à Camp Taurajo.", st = "À présent, $n, vous devez combattre les grands lézards-tonnerre. Ces bêtes sont si imposantes que le sol tremble lorsqu'ils parcourent les plaines. Prenez garde lorsque vous les combattez, car un faux pas peut vous jeter directement sous leurs pattes.$B$BVous trouverez les lézards-tonnerre au sud des Tarides. Ils sont connus sous les noms de Groins-tempête, Orageux et Têtes-tonnerre. Revenez me voir lorsque vous les aurez vaincus.", t = "Les lézards-tonnerre enragés"},
    [913] = {ot = "Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Skyseer, au Camp Taurajo.", st = "Le faucon-tonnerre, $n, est une bête féroce. Il est temps pour vous d'en affronter. Vous devez trouver où il rôde, puis m'apporter ses ailes comme preuve de votre chasse fructueuse.$B$BParvenez-y, et l'heure de notre séparation sonnera bientôt.", t = "Le cri du faucon-tonnerre"},
    [914] = {ot = "Apporter les Gemmes de Cobrahn, d'Anacondra, de Pythas et de Serpentis à Nara Wildmane à Thunder Bluff.", st = "Les druides des Cavernes des lamentations, les druides du Croc, sont une aberration. Ils appartenaient à un ordre de druides nobles voulant soigner les Tarides, mais ils tentent maintenant de plier cette terre à leurs fantasmes.$B$BIls ont quatre chefs, et chacun possède une gemme de rêve. Même à présent, leurs visages me hantent ! Vous devez les tuer et m'apporter les gemmes. Ces terres pourront peut-être ainsi connaître à nouveau la paix.$B$BAllez, $n. Vous les trouverez, tapis, au fond des Cavernes des lamentations.", t = "Les druides du Croc"},
    [916] = {ot = "Apporter 10 Glandes à venin Tissebois à Gilshalan Windwalker, à Aldrassil.", st = "Je suis venu à Sombrevallon pour observer les araignées Tissebois qui vivent dans la grotte de Sombrefil. Elles sont cousines d'une variété bien plus petite. Je pense que l'arbre-monde a eu un profond effet sur elles, et j'aimerais des spécimens à étudier pour confirmer cette hypothèse.$b$bD'abord, j'aimerais un peu de leur venin. Prélevez des glandes à venin de Tissebois sur les araignées à l'intérieur et autour de la grotte de Sombrefil, au nord. Je pourrai alors étudier les similitudes avec le venin de leurs cousines plus petites.", t = "Le venin des Tissebois"},
    [917] = {ot = "Apporter un Œuf d'araignée Tissebois à Gilshalan à Aldrassil.", st = "À présent que j'ai le venin de ces araignées, j'aimerais étudier des spécimens vivants. Malheureusement, capturer une araignée géante est plus que je ne peux vous demander, jeune $c. Et je ne pourrais pas moi non plus maîtriser une araignée géante.$b$bSi vous pouvez trouver un œuf non encore éclos, alors il sera plus facile de posséder des spécimens, et je peux organiser les choses pour les enfermer avant que les araignées ne sortent.$b$bIl doit y avoir un nid, au plus profond de la grotte de Sombrefil. S'il vous plaît, partez chercher un œuf dans ce nid et rapportez-le-moi.", t = "L'œuf d'araignée Tissebois"},
    [918] = {ot = "Apporter 8 Graines de sylvain à Denalan au lac Al'Ameth.", st = "Les sylvains de Teldrassil sont des élémentaires de la Nature. D'une certaine manière, ils reflètent l'ordre naturel des plantes et des animaux sur notre Grand Arbre.$b$bAussi est-ce inquiétant de voir les sylvains devenir furieux.$b$bJe pense que cela a quelque chose à voir avec la terre. J'ai travaillé à différentes méthodes pour alimenter les plantes et aimerais les essayer sur des graines de sylvains. S'il vous plaît, pouvez-vous collecter des graines de sylvain autour du lac Al'Ameth et me les apporter ?", t = "Les graines de sylvain"},
    [919] = {ot = "Apporter 12 Pousses de sylvain à Denalan au lac Al'Ameth.", st = "De petits sylvains poussent près des eaux du lac Al'Ameth. J'ai bien peur que nous ne puissions plus rien faire pour ces jeunes sujets. Nous devons les arracher avant qu'ils ne grandissent trop et causent des problèmes.$B$BLorsque vous serez près du lac, arrachez les pousses de sylvains que vous verrez. Aidez-nous à garder une terre propre !", t = "Les pousses de sylvain"},
    [920] = {ot = "Parler à Tenaron Stormgrip au sommet d'Aldrassil à Sombrevallon.", st = "$n, n'est-ce pas ? J'ai entendu dire que Tenaron vous cherchait. Vous le trouverez à l'endroit le plus haut d'Aldrassil.$b$bIl se peut que nous vivions longtemps encore, mais ce serait mieux de ne pas le faire attendre trop longtemps.", t = "Les appels de Tenaron"},
    [921] = {ot = "Remplir la Fiole de cristal et la rapporter à Tenaron Stormgrip au sommet d'Aldrassil.", st = "Il est temps pour vous de partir en quête de votre destinée, $n. Mais avant que vous ne soyez $gprêt:prête; à vous aventurer au-delà de nos forêts enchantées, il y a beaucoup à apprendre de notre histoire récente.$b$bNotre peuple a beaucoup changé depuis la Bataille du mont Hyjal. Nordrassil n'est plus que l'ombre pâle de ce qu'il était autrefois... Son pouvoir avait battu Archimonde et repoussé la Légion ardente...$b$bIl y a une tâche que vous devez accomplir. Partez pour le Puits de lune au nord d'Aldrassil et apportez-moi une fiole de son eau.", t = "La couronne de la Terre"},
    [922] = {t = "Rellian Greenspyre"},
    [923] = {ot = "Apporter 5 Tumeurs moussues à Rellian Greenspyre à Darnassus.", st = "Une maladie décime les sylvains. Nous essayons d'en trouver la cause, mais tant que nous n’y parvenons pas nous devons arracher les sylvains contaminés, pour la sécurité de Teldrassil. Ceux qui poussent près du lac d'Aigue-vive, au nord de Teldrassil, sont les plus atteints. Nous devons les arracher !$b$bDétruisez les sylvains que vous trouvez, et prélevez la Tumeur moussue qui se développe sur eux. Apportez-moi les tumeurs afin qu'elles soient brûlées.", t = "Tumeurs"},
    [924] = {ot = "Prendre une Pierre de puissance imparfaite. L'apporter à l'autel de feu avant que le pouvoir de la pierre n'expire, puis revenir à Ak'Zeloth.", st = "La Graine démoniaque est un outil puissant au service de la Légion ardente. Elle repose dans une caverne du pic de Brume-funeste, au-dessus d'un diabolique autel de feu.$b$bJ'ai préparé des Pierres de puissance qui, lorsqu'elles seront placées près de la graine, couperont sa connexion avec la Légion.$b$bPrenez une pierre sur la table et portez-la à l'autel de feu au sommet du pic de Brume-funeste. Voyagez à l'ouest, puis au nord lorsque la route se divise. Le pic sera sur votre gauche. L'escalade la plus sûre s'effectue par la face nord.$b$bEt faites vite, le pouvoir de la pierre faiblit avec le temps.", t = "La Graine démoniaque"},
    [926] = {t = "Pierre de puissance imparfaite"},
    [927] = {ot = "Apporter le Cœur moussu à Denalan au lac Al'Ameth.", st = "Le cœur de Noiremousse le Fétide est couvert d'une mousse sombre et huileuse. En fait, ce qui permet d’identifier ce cœur, c’est sa pulsation, lente et rythmée.$b$bPeut-être que Denalan voudra voir ce cœur ?", t = "Le cœur moussu"},
    [928] = {ot = "Apporter le Récipient à moitié plein à Corithras Moonrage à Dolanaar.", st = "Bien que je puisse vous entretenir encore longtemps des Puits de lune et de Teldrassil, je dois vous faire partir. Corithras Moonrage va vous attendre. J'ai versé l'eau de la fiole que vous m'avez apportée dans ce récipient que vous devez lui remettre.$b$bCherchez Corithras. Vous le trouverez au Puits de lune à Dolanaar. Suivez la route vers le sud à partir d'Aldrassil et vers Sombrevallon, et continuez à suivre les pavés ronds lorsque la route se dirige vers l'ouest.$b$bAttention, restez toujours sur la route, $n. Il y a de dangereuses bêtes, le soir, dans les forêts.", t = "La couronne de la Terre"},
    [929] = {ot = "Remplir la Fiole de jade et la rapporter à Corithras Moonrage à Dolanaar.", st = "Tout d'abord, laissez-moi vous en dire plus à propos de la quête que vous devez accomplir. Les druides de Darnassus utilisent l'eau des Puits de lune de Teldrassil, et leurs Puits de lune doivent être remplis de temps en temps. En utilisant ces fioles spécialement conçues, vous pouvez collecter l'eau des Puits de lune.$b$bApportez ce récipient jusqu'au Puits de lune à l’extérieur du village de Brise-stellaire à l'est, et remplissez-le d'un peu de ses eaux. Puis revenez me voir. Lorsque vous aurez accompli votre tâche, je reprendrai l'histoire là où Tenaron s’est arrêté.", t = "La couronne de la Terre"},
    [930] = {ot = "Apporter le Fruit luminescent à Denalan au lac Al'Ameth.", st = "Pendu à cette plante, sous ses feuilles, se trouve un grand fruit rond.$B$BDenalan voudra étudier ce fruit, c'est certain.", t = "Le fruit luminescent"},
    [931] = {ot = "Apporter les Racines flamboyantes à Denalan au lac Al'Ameth.", st = "Les feuilles de la plante flamboient dans la lumière de la forêt, lui donnant une aura pulsante et sinueuse.$B$BVous pensez que Denalan en souhaiterait un spécimen.", t = "Les racines flamboyantes"},
    [932] = {ot = "Tuer le seigneur Melenas et apporter sa tête à Tallonkai Swiftroot à Dolanaar.", st = "Je vous avertis, $N, cette affaire doit rester entre nous. Les satyres nous embarrassent déjà suffisamment, et celui-ci est beaucoup trop proche.$B$BIl s'appelle le seigneur Melenas. Il réside dans la caverne proche de Gangreroche où il a rassemblé de nombreux guerriers grells. Son cœur est aussi noir que la nuit, et il prépare quelque chose d'abominable.$B$BVous devez le trouver à l'intérieur de sa caverne proche juste au nord d'ici, et m'apporter sa tête.", t = "Haine folle"},
    [933] = {ot = "Remplir la Fiole de tourmaline et la rapporter à Corithras Moonrage à Dolanaar.", st = "Il y a un autre Puits de lune au sud-est de l'entrée vers Darnassus, sur les rives des bassins d'Arlithrien. Les Sentinelles ont des problèmes lors de leurs patrouilles dans ce secteur. Ils sont attaqués par les furbolgs du clan Pin-tordu, de plus en plus sauvages.$b$bSoyez $gprudent:prudente; quand vous chercherez le Puits, et gardez la main près de vos armes.", t = "La couronne de la Terre"},
    [935] = {ot = "Apporter le Récipient plein à l'archidruide Fandral Staghelm à Darnassus.", st = "Sans la bénédiction d'Alexstrasza la Lieuse de vie et celle de Nozdormu l'Éternel, la croissance de Teldrassil ne fut pas parfaite. On rapporte que des bêtes étranges sortaient de ses racines et que des furbolgs enragés attaquaient des voyageurs.$b$bJe ne peux qu'espérer que l'archidruide trouvera rapidement la solution. Je vais verser le contenu de toutes les fioles que vous m'avez amenées dans ce récipient, pour que vous l'apportiez à Darnassus.$b$bApportez-le à Fandral Staghelm, vous le trouverez dans le bosquet des druides.", t = "La couronne de la Terre"},
    [937] = {ot = "Acquérir 6 Ceintures plumesang et les apporter à la Sentinelle Arynia Cloudsbreak à la clairière de l'Oracle.", st = "On m'a envoyée ici avec un petit groupe de Sentinelles pour protéger l'arbre-oracle des harpies qui ont construit leurs nids tout autour de la clairière. Nous essayons de les repousser petit à petit.$b$bLorsque l'arbre-oracle a tenté d'envoyer un messager avec un rapport, il a été attaqué par un groupe de harpies et tué.$b$bSi vous vous sentez suffisamment $gpréparé:préparée; pour cette tâche, allez à leurs nids, tuez-les et rapportez-moi leurs ceintures en guise de preuves de vos exploits.", t = "La clairière enchantée"},
    [938] = {ot = "Escorter Brume vers la Sentinelle Arynia Cloudsbreak au puits de lune, près de l'arbre-oracle.", st = "La fourrure du tigre à dents de sabre est d'un gris particulier, tranchant avec les couleurs de la forêt environnante. Tandis qu'elle repose là, vous remarquez qu'elle est gravement blessée, de profondes lacérations déchirent son dos et son ventre.$b$bElle lève la tête et vous regarde, ses yeux bleus brillant d'intelligence. Elle a l'air de souhaiter vous suivre.", t = "Brume"},
    [940] = {ot = "Apportez l’écorce gravée à l’archidruide Fandral Forteramure à Darnassus.", st = "On entend murmurer la forêt qui loue vos grandes prouesses, $n. Les harpies une fois délogées de leurs nids, un grand calme s'est répandu sur la forêt, ses créatures se sentant à nouveau en sécurité. J'ai eu peur d'envoyer un autre messager à l'archidruide, mais je sais que vous, vous parviendrez à lui remettre un message.$b$bApportez-lui ceci et sachez que la forêt veillera à votre sécurité le long du chemin menant à la Forêt de pierre.", t = "Teldrassil"},
    [941] = {ot = "Planter le Cœur corrompu dans le Pot de Denalan.", st = "J'ai débarrassé le cœur de cette ignoble mousse, mais il reste contaminé…$b$bEssayez de placer le cœur dans ce pot. Il est rempli d’un terreau spécial qui pourrait le nettoyer et le guérir.", t = "Une belle plante"},
    [942] = {ot = "Apporter le mystérieux Fossile à l'Archéologue Flagongut au Port de Menethil.", st = "Le fossile ressemble de manière frappante à un autre que j'ai vu une fois à Forgefer. Un Archéologue du nom de Flagongut l'avait apporté à notre conférence annuelle de la Ligue des Explorateurs. Il croyait que le fossile détenait un pouvoir que l'on aurait pu réveiller d'une certaine façon.$b$bLa dernière fois que j'ai entendu parler de lui, Flagongut s'était installé à la taverne de l'Eau-profonde, au Port de Menethil, attendant une escorte pour le mener à l'Excavation de Whelgar. Recherchez-le et montrez-lui le Fossile de Remtravel. Peut-être pourra-t-il révéler les secrets du passé.$b$bLe bateau pour le Port de Menethil part d'Auberdine.", t = "Les absences du Prospecteur"},
    [943] = {ot = "L'archéologue Flagongut au Port de Menethil veut que vous lui apportiez la Pierre de Relu et le Fossile de Flagongut.", st = "Le Prospecteur Whelgar détient à présent le fossile original, en son site des marécages. Quand j'ai découvert la Pierre de Relu, j'ai cru y voir la solution à l'énigme du fossile.$b$bAlors que je taillais la route pour aller à la rencontre de Whelgar, j'ai subi une attaque de raptors et la relique fut perdue. J'ignore laquelle des ces créatures chamarrées a bien pu l'avaler, mais si vous pouvez la retrouver, je peux libérer le pouvoir de ces artefacts.$B$BApportez-moi donc la Pierre de Relu, et le fossile original que Whelgar possède.", t = "Les absences du Prospecteur"},
    [944] = {ot = "Trouver des informations, puis utiliser la Fiole de divination pour créer une Coupe de divination. Utiliser la coupe pour parler à Onu.", st = "C'est étrange que des nagas soient là, à Sombrivage. Mais... la présence du Marteau du crépuscule l'est encore plus. Ce culte vénère de très anciens seigneurs de la terre. Des seigneurs vaincus il y a longtemps de cela.$b$bLe Glaive du Maître, au sud, est un endroit où est tombé l'un de ces anciens seigneurs.$b$bAllez-y et cherchez d'autres sectateurs du Marteau du crépuscule.$b$bPrenez cette fiole de divination. Utilisez-la pour créer une coupe de divination après avoir enquêté au Glaive du Maître. Puis parlez-moi par l'intermédiaire de cette coupe.", t = "Le Glaive du Maître"},
    [945] = {ot = "Aider Therylune à s'échapper, puis dire à Therysil au Sanctuaire d'Aessina que sa sœur est saine et sauve.", st = "Au secours !$b$bJe me promenais autour du Glaive du Maître, et ces infâmes sectateurs m'ont entourée. Encore heureux que je sois douée pour me cacher !$b$bPouvez-vous m'aider à m'échapper ? Et j'aurais aussi besoin de dire à ma sœur Therysil que je vais bien. Elle est à Ashenvale au sud, au sanctuaire d'Aessina.", t = "L'évasion de Therylune"},
    [947] = {ot = "Apporter 5 Pédoncules d'Amanite et 1 Amanite phalloïde à Barithras Moonshade à Auberdine.", st = "Je prépare une potion qui nécessite des champignons rares, des champignons qui ne poussent que dans une certaine caverne. La caverne en question se trouve au-delà des Chutes de la Bondissante, à l'est et légèrement au nord le long des montagnes.$b$bJ'irais bien moi-même, mais le Bosquet des Anciens m'a conseillé de me tenir à l'écart de cet endroit. Nos vénérables alliés pressentent que cette caverne est l'antre d'une nouvelle créature maléfique, ici à Sombrivage.$b$bS'il vous plaît, $n, ramassez ces champignons pour moi. Et pendant que vous y êtes, explorez la caverne pour confirmer le pressentiment des Anciens.", t = "La caverne aux champignons"},
    [948] = {ot = "Parler à Onu au Bosquet des Anciens.", st = "Onu, un Ancien du savoir au Bosquet des Anciens, est au courant de votre voyage vers les Chutes de la Bondissante et souhaite vous parler. Le bosquet se trouve au sud, blotti près des montagnes.$b$bLes Anciens sont patients et sages, $n. Mais si Onu souhaite votre conseil à propos de ce que vous avez vu aux chutes, alors j'ai peur que ce soit urgent.", t = "Onu"},
    [949] = {ot = "Trouver un indice au Camp du Marteau du crépuscule au Glaive du Maître.", st = "Nous ne connaissons pas le but du Marteau du crépuscule au Glaive du Maître.$b$bFouillez leur camp au Glaive… Essayez de trouver quelque chose qui puisse nous indiquer leurs intentions.$b$bCar nous devons les connaître avant d'établir un plan.", t = "Le camp du Marteau du crépuscule"},
    [950] = {ot = "Apporter les Gribouillages déments à Onu.", st = "Consulter le Tome du crépuscule rend fou. Au premier regard, le texte commence à flotter et danser ; images et enluminures s'entremêlent pour créer des formes grotesques.$b$bVous arrivez tout juste à déchirer une page de ces gribouillages déments avant qu'un vertige ne vous submerge.", t = "La page qui rend fou"},
    [951] = {ot = "Apporter 6 Reliques de Mathystra à Onu, au Bosquet des Anciens.", st = "Le parchemin que vous avez découvert au Glaive du Maître est la page d'un texte ancien… écrit par des elfes ! Il est souillé de la corruption du Marteau du crépuscule. Ainsi, le culte utilise l'ancienne magie des elfes pour ramener ses vieux maîtres dans notre monde.$b$bVoyagez jusqu'aux ruines de Mathystra au nord-est, et cherchez d'anciennes reliques, dans l'herbe et parmi les pierres brisées. En les étudiant, il se peut que nous comprenions comment le Marteau du crépuscule compte exploiter la magie des elfes.", t = "Les Reliques de Mathystra"},
    [952] = {ot = "Livrer le message de Fandral à Onu, au bosquet des Anciens, à Sombrivage, au sud d’Auberdine.", st = "Si vous avez suffisamment de temps pour servir de $gmessager:messagère; pour l'arbre-oracle, je pourrais vous demander de remettre un message au bosquet des Anciens, à Sombrivage, au sud d'Auberdine.$b$bVous aurez probablement à effectuer le voyage en hippogryphe, mais j'ai foi en vos compétences. Apportez ceci à Onu, l'Ancien du savoir. Il attend un mot de ma part, tout comme j'attendais un mot de la Clairière de l'Oracle.", t = "Bosquet des Anciens"},
    [953] = {ot = "Étudier les tablettes qui parlent d'Ameth'Aran et de sa chute, puis retourner voir la Sentinelle Tysha Moonblade à Sombrivage.", st = "Vous trouverez à l'est les ruines d'Ameth'Aran. Elles sont habitées par les Esprits sans repos des Bien-nés qui vivaient autrefois dans ces murs, quand les serviteurs d'Azshara y pratiquaient librement leur puissante magie.$b$bOn m'a envoyée pour explorer les ruines et trouver deux grandes tablettes, sur lesquels sont racontées les histoires d'Ameth'Aran et de sa chute. Alors que je lisais les runes, j'ai été surprise par les Esprits, et je me suis enfuie.$b$bS'il vous plaît, si vous le pouvez, aventurez-vous dans les ruines et déchiffrez les tablettes pour moi.", t = "La chute d'Ameth'Aran"},
    [954] = {ot = "Trouver la source de l’aura bleue dans les Ruines de Bashal'Aran.", st = "Les ruines de Bashal'Aran à l'est sont infestées de serviteurs démoniaques. Les fées et les satyres qui ont élu domicile dans la région se nourrissent des énergies magiques du secteur, et leurs pouvoirs augmentent avec le temps passé sur place.$b$bMais malgré cela, j'ai remarqué un sanctuaire dont ils ne s'approchent jamais. A l’ouest des ruines, au sommet d'un petit promontoire, filtre une étrange aura bleue... Il doit y avoir une explication à la répugnance des démons.$b$bJ'aimerais que vous enquêtiez à ce propos.", t = "Bashal'Aran"},
    [955] = {ot = "Acquérir 8 Boucles d'oreilles de grell pour Asterion à Bashal'Aran.", st = "Si j'avais à raconter l'histoire de ma vie, il ne fait pas de doute qu'elle dépasserait les limites de votre patience. Disons que ma vie a été longue et douloureuse, et cette forme spectrale qui est la mienne à présent est peut-être le pire de tous ces tourments.$b$bJe suis retenu ici par les pouvoirs de la magie. Bien que mes mots puissent sonner faux, je vous assure que je vous serais reconnaissant au-delà de tout si vous pouviez m’aider à identifier ce qui me retient prisonnier. Un sceau fait partie de ce dispositif, et en examinant les boucles d'oreilles des fées et des grells, je pourrais en trouver la trace.", t = "Bashal'Aran"},
    [956] = {ot = "Obtenir l'Ancien sceau de pierre de lune et l'apporter à Asterion à Bashal'Aran.", st = "Si les grells sont entrés en contact avec le sceau qui verrouille ma prison éternelle, je crois en connaître la cause. Il ne fait pas de doute que le sceau est en la possession du satyre qui les dirige.$b$bJe ressens fortement que cela doit être vrai, $n. L'un des satyres le possède à présent. Si vous pouvez l'obtenir, je serais si proche de pouvoir passer les barreaux de ma prison que les larmes me monteraient aux yeux.", t = "Bashal'Aran"},
    [957] = {ot = "Détruire l'Ancien sceau de pierre de lune à la flamme antique qui se trouve dans Ameth'Aran, puis retourner voir Asterion à Bashal'Aran.", st = "C'est le savoir de l'un des plus puissants Bien-nés qui a créé le sceau fermant ma prison. À Ameth'Aran, dans les ruines au sud, jumelles de celles-ci, brûle une flamme antique, de couleur bleue. Dans cette flamme, ce sceau pourrait être détruit.$b$bSoyez $gprudent:prudente; dans les ruines, $n.", t = "Bashal'Aran"},
    [958] = {ot = "Retrouver 7 Reliques de Bien-né pour Thundris Windweaver à Auberdine.", st = "$C. J'aurais quelque chose à vous demander.$b$bConnaissez-vous les ruines d'Ameth'Aran ? Si ce n'est pas le cas, vous les trouverez à l’est de la route principale, à quelque distance au sud. Alors qu'elles abritaient de nombreux Bien-nés puissants, elles ne sont plus à présent que l’image de la destruction à laquelle leurs expériences ont abouti.$b$bLes Sentinelles disent que les esprits des Bien-nés sont toujours là, et qu'ils manient toujours leurs instruments magiques. Nous devons nous emparer de ces reliques, afin de les détruire.", t = "Les outils des Bien-nés"},
    [959] = {ot = "Le grutier Bigglefuzz de Ratchet veut que vous repreniez la Bouteille de porto vieille de 99 ans à Magglish le Dingue, qui se cache dans les Cavernes des lamentations.", st = "Oups !$b$bJ'ai eu une petite mésaventure, comme vous pouvez le voir ! La cargaison du matin venant de Baie-du-Butin était énorme. Enorme je dirais ! J'ai jamais vu autant de caisses. Bien, j'essayais d'expédier rapidement les choses alors j'ai commencé à décharger un peu plus que je ne pouvais soutenir. C'est à ce moment-là que tout s'est cassé la gueule.$b$bAvant que je sache ce qu'il se passait, j'ai vu cette peste de Magglish le Dingue filer avec une bouteille de porto vieille de 99 ans. Je l'ai poursuivi jusqu'aux Cavernes des lamentations. Pas question d'y rentrer, quand même.$b$bPeut-être êtes-vous suffisamment $gcourageux:courageuse; pour aller le retrouver ?", t = "Fuite de porto aux docks"},
    [962] = {ot = "L'Apothicaire Zamah à Thunder Bluff veut que vous récoltiez 10 Fleurs de serpent.", st = "La Société royale des apothicaires, basée dans la grande ville de Fossoyeuse de Lordaeron, m'a envoyée ici pour une mission très particulière, $n. Peut-être souhaitez-vous m'aider, et ainsi aider la Dame noire, dans nos efforts pour faire progresser les Réprouvés.$b$bJ'ai récemment étudié un spécimen rare de flore appelé Fleur de serpent. Je crois qu'en grande quantité cette herbe a un bon potentiel.$b$bMalheureusement, elle ne pousse qu’au plus profond des Cavernes des lamentations, un réseau de cavernes situé dans les Tarides.", t = "Fleur de serpent"},
    [963] = {ot = "Libérer l'esprit d'Anaya Dawnrunner et rapporter son pendentif à Cerellean Whiteclaw à Auberdine.", st = "À la suite des batailles au Puits d'éternité, j'ai appris qu'Ameth'Aran avait été détruit, et son peuple tué, y compris mon bel amour Anaya.$b$bJe n'aurais jamais cru, des milliers d'années plus tard, que des souvenirs d'Anaya hanteraient toujours mes rêves. Frappé de stupeur, j'ai erré dans les bois de Sombrivage, et j’ai retrouvé les ruines d'Ameth'Aran... Là j’ai vu l'esprit hanté de ma bien-aimée.$b$bElle doit être libérée, mais je n'ai pas le cœur de faire cela. Son esprit doit être détruit.", t = "Un amour éternel"},
    [965] = {ot = "Trouver Balthule Shadowstrike près de la Tour d'Althalaxx à Sombrivage.", st = "Salutations, jeune $r. Je m'appelle Elissa Starbreeze, et il est de mon devoir de protéger Auberdine de tout mal.$b$bÀ cette fin, j'ai envoyé Balthule Shadowstrike observer les événements étranges qui se produisent près de la Tour d'Althalaxx au nord-est.$b$bIl aurait déjà dû revenir. J'ai peur qu'il ait rencontré un danger imprévu dans la forêt. J'apprécierais beaucoup si vous pouviez le trouver et vous assurer qu'il va bien.", t = "La Tour d'Althalaxx"},
    [966] = {ot = "Collecter 4 Parchemins passés pour Balthule Shadowstrike près de la Tour d'Althalaxx.", st = "Un groupe de démonistes s'est établi autour et à l'intérieur de la tour. Je serais retourné à Auberdine pour rendre compte à Elissa plus tôt, mais j'avais peur de rater quelque chose une fois parti.$b$bDelgren suspectait qu'une telle compagnie puisse se rassembler à la tour, mais il n’en savait pas la cause.$b$bQuelques morceaux de parchemins appartenant à ces démonistes ont atterri entre mes mains, mais j'en ai besoin d'autres pour compléter le puzzle. Je vous avertis cependant de ne pas vous aventurer dans la tour, les démonistes qui s'y trouvent sont beaucoup trop puissants !", t = "La Tour d'Althalaxx"},
    [967] = {ot = "Remettre la Lettre de Balthule à Delgren le Purificateur dans la forêt d'Ashenvale.", st = "Mon maître, Delgren le Purificateur, est un paladin qui a gracieusement offert son assistance pour défendre nos forêts contre les démons et les morts-vivants. Il m'a beaucoup appris sur le Feu sacré et sur l'art de la bataille.$b$bDelgren doit être mis au courant des opérations du culte immédiatement.$b$bVous le trouverez loin au sud, au poste de Maestra dans la forêt d'Ashenvale. Faites vite, j'ai peur que la menace que représente la Rive noire n'augmente d'heure en heure.", t = "La Tour d'Althalaxx"},
    [968] = {ot = "Apporter le Livre : Les puissances d'en bas à Gerrig Bonegrip, dans la caverne lugubre de Forgefer.", st = "Bien qu'affreusement usé et égratigné, le titre est encore lisible sur la couverture :$B$BLes puissances d'en bas.$B$BÀ l'intérieur du livre écorné se trouve une liste de noms imprononçables affublés d'horribles titres, des méthodes de culte, des sacrifices conseillés... dont beaucoup incluent des créatures humanoïdes, vivantes.$B$BAu verso de la couverture, sont inscrits les mots suivants : \"Runes et malédictions de Bonegrip, la caverne lugubre, Forgefer. Propriétaire : Gerrig Bonegrip.\"$B$BSi Bonegrip vend de tels livres, peut-être qu'il rachètera celui-ci.", t = "Les puissances d'en-bas"},
    [970] = {ot = "Trouver une Gemme d'âme luminescente et la rapporter à Delgren le Purificateur au poste de Maestra.", st = "La lettre de Balthule est désespérée. Ce culte de la Rive noire m'irrite au plus haut point et doit être éradiqué. J'ai eu affaire à quelques vermines de la Rive noire au nord-est d'ici à Ordil'Aran. L'un d'entre eux possède une gemme d'âme, qui je crois détient le secret de la puissance de ce culte.$B$BApportez-la-moi, et je serai capable de déchiffrer les secrets qu'elle contient.", t = "La Tour d'Althalaxx"},
    [971] = {t = "La connaissance des profondeurs"},
    [973] = {t = "La Tour d'Althalaxx"},
    [982] = {t = "Océan profond, mer immense"},
    [983] = {t = "Bigobox 827"},
    [984] = {ot = "Trouver un camp de furbolgs corrompus à Sombrivage et retourner voir Terenthis dans Auberdine.", st = "Certains de mes frères ont été sauvés de justesse d'un furbolg corrompu à Teldrassil, et je me suis juré d'arrêter ces atrocités avant que d'autres ne soient blessés... ou pire.$B$BJ'ai déjà vu des prémices de corruption à Sombrivage, mais il faut que je cherche d'autres signes ailleurs. Je pense qu'il serait logique de poursuivre les investigations auprès des furbolgs. Pourriez-vous trouver un de leurs camps et me dire s’il y a des signes de corruption ?", t = "Quelle est l'ampleur de la menace ?"},
    [985] = {ot = "Tuer 8 Guides et 5 Messagers du vent Noirbois puis retourner voir Terenthis à Auberdine.", st = "Vous avez déjà prouvé vos qualités dans le domaine de la reconnaissance, $n. Avez-vous aussi les qualités nécessaires pour affronter l'adversaire ?$B$BLes aventuriers ne préfèrent pas tous le combat direct à l'art de la ruse et de l'évasion.$B$BSi vous pensez être à la hauteur de la tâche, sachez que la plus grande menace pour notre peuple est aujourd'hui le camp furbolg au sud d'Auberdine. Vous y trouverez des furbolgs de la tribu Noirbois. Tuez 8 Guides et 5 Messagers du vent et revenez me voir.", t = "Quelle est l'ampleur de la menace ?"},
    [986] = {ot = "Trouver 5 Belles peaux de traquelune et les apporter à Terenthis, à Auberdine.", st = "$n, votre habileté m'a déjà été utile. Puis-je à nouveau vous demander d'aider Griffe-sinistre et son maître Volcor ? Je vais vous fabriquer une cape magique qui vous permettra de vous déplacer librement au milieu des créatures de Sombrivage pendant que vous le chercherez.$B$BPour faire cette cape, j'ai besoin de cinq belles peaux de géniteur ou de matriarche traquelune. Vous trouverez ces tigres au sud de la Sinueuse ou beaucoup plus au sud, non loin d'Ashenvale.", t = "Un maître perdu"},
    [990] = {ot = "Trouver Raene Wolfrunner dans Ashenvale.", st = "$n, ma maîtresse, Raene Wolfrunner, vous attend à la cité d'Astranaar dans Ashenvale. Peut-être que grâce à vous, nous pourrons réduire la corruption qui y règne.$B$BEn partant d'ici, vous devez prendre plein sud en restant près de la route ; vous trouverez sans problème votre chemin en suivant cette direction.", t = "Voyage vers Ashenvale"},
    [991] = {ot = "Trouver Teronis dans Ashenvale.", st = "$n, l'un de mes vieux amis est aussi venu à Ashenvale pour aider les Sentinelles, mais il est déjà reparti.$B$BIl cherchait un objet qui pourrait retarder les attaques des furbolgs contre notre peuple : un Bâtonnet créé par un sorcier diabolique, aujourd’hui mort.$B$BAvant de partir, il a dit qu'il cherchait une gemme pour ce Bâtonnet.$B$BIl pensait que la gemme était cachée dans le sanctuaire près du lac Falathim, au pied de la montagne à l'ouest. La gemme était là avant l’invasion.$B$BTrouvez mon ami, je vous en prie, $n.", t = "Le nettoyage selon Raene"},
    [993] = {ot = "Trouver Volcor, à Sombrivage, et lui donner la Cape enchantée de traquelune.", st = "La cape est terminée, $n. Nous devons trouver Volcor à présent. J'espère seulement que nous sommes encore dans les temps.$B$BLa magie de la cape, une fois invoquée, ne durera pas longtemps. Cinq minutes, peut-être. Ce sera à vous de choisir quand l'utiliser. Je suggèrerais d'attendre de trouver Griffe-sinistre.$B$BSi ce qu'il m'a dit est vrai, vous trouverez son maître dans une caverne au sud d'ici. Griffe-sinistre vous attendra le long de la route. Faites-lui un signe de la main lorsque vous le verrez et il vous indiquera la direction de son maître.", t = "Un maître perdu"},
    [995] = {ot = "S'échapper de la grotte des furbolgs et aller voir Terenthis à Auberdine.", st = "D’accord... si vous le voulez, nous nous échapperons d’ici.$B$BRappelez vous, une fois que vous aurez quitté ce lieu, allez à Auberdine et rencontrez Terenthis. C’est là que je vais me rendre aussi, et j’y serai probablement avant vous.", t = "Évasion par la ruse"},
    [997] = {ot = "Rapporter le paquet de Terre rare à Denalan au lac Al'Ameth.", st = "Vous allez vers le sud ? Au lac Al'Ameth ? Si c'est le cas, j'ai une tâche à vous confier... $B$BMon collègue Denalan campe le long du rivage oriental du lac, où il étudie la flore de Teldrassil. Il a demandé qu'on lui envoie un paquet de Terre rare de Darnassus, mais il y a eu du retard et le paquet vient seulement d'arriver à Dolanaar.$B$BPouvez-vous le lui apporter ?", t = "La terre de Denalan"},
    [1001] = {t = "Bigobox 411"},
    [1002] = {t = "Bigobox 323"},
    [1003] = {t = "Bigobox 525"},
    [1007] = {ot = "Apporter l'Ancienne Statuette à Talen, dans son camp près de la grève de Zoram.", st = "Je vais vous charger d'une mission, $n.$B$BJ'étais sur mon petit bateau, voguant sur les ruines englouties de Zoram, quand les nagas ont émergé des eaux et m'ont attaqué en me déchirant avec leurs griffes ! Je me suis enfui, en transportant tout ce que je pouvais pour le camp.$B$BEt lorsque j'ai atteint le rivage, je me suis mis à courir... J'ai perdu ma précieuse cargaison.$B$BJe vous en prie, $n, retrouvez l’endroit où je suis tombé dans cette embuscade et cherchez une ancienne statuette. C'est pour elle que j'ai bravé les dangers de la grève de Zoram.", t = "L'ancienne statuette"},
    [1008] = {t = "La grève de Zoram"},
    [1009] = {ot = "Apporter l'Anneau de Zoram à Talen près de la grève de Zoram.", st = "J'ai peur que les secrets de l'ancienne statuette ne restent un mystère tant que vous n'aurez pas trouvé la clé qui ouvre cette vieille serrure.$B$BCette clé est un anneau, l'Anneau de Zoram. Il a appartenu aux dirigeants de cette cité avant que les ondes du Fractionnement ne l'aient noyée.$B$BL'anneau a été perdu pendant des années, mais les nagas viennent de le retrouver.$B$BLeur chef, Ruuzel, se trouve sur une île, sur le côté nord de Zoram. Je vous en prie, $n, trouvez-moi cet anneau !", t = "Ruuzel"},
    [1010] = {ot = "Rapporter 5 Cheveux de Bathran à Orendil Broadleaf dans Ashenvale.", st = "Il y avait une plante qui poussait autrefois dans les vieilles ruines du repaire de Bathran au nord. On l'appelait Cheveux de Bathran et elle était réputée guérir les maux de l'esprit.$B$BIl y a un enfant malade dans le village et je crois qu'il s'agit d'autre chose que d'une simple maladie physique. Accepteriez-vous d'aller au repaire de Bathran pour y chercher des Cheveux de Bathran ? Il se peut que j'en ai besoin pour soigner cet enfant.$B$BLe repaire de Bathran se trouve au nord du Poste de Maestra, juste au sud de la frontière de Sombrivage.", t = "Les Cheveux de Bathran"},
    [1011] = {ot = "Apporter une Bouteille des maladies à Kayneth Stillwind au Chant des Forêts.", st = "Les Réprouvés, le bras mort-vivant de la Horde, ont rampé jusqu'en Ashenvale, et rôdent près de nos ruines et de nos refuges des saisons. Nous pensons que leur objectif est de répandre la maladie sur les terres des elfes de la nuit. Nous devons nous en assurer !$B$BLes Réprouvés ont un camp au sud d'ici, près du refuge des saisons de Dor'danil. Ils y conçoivent poisons et maladies et les placent dans des bouteilles. Frayez-vous un passage jusqu'à ce camp et volez une de ces bouteilles pleines. Revenez alors me voir. J'expérimenterai cette maladie et découvrirai à quelles fins elle a été conçue.", t = "Les maladies des Réprouvés"},
    [1013] = {t = "Le Livre d'Ur"},
    [1014] = {ot = "Tuer Arugal et apporter sa Tête à Dalar Dawnweaver au Sépulcre.", st = "Arugal se trouve toujours dans le Donjon d'Ombrecroc. Nous ne pouvons pas faire des Pins argentés une forteresse stratégique pour la Dame noire tant qu'Arugal est vivant.$b$bJe vais me débrouiller pour que sa magie soit annihilée, $n. Mais je vous laisse le soin de faire en sorte qu'Arugal rencontre la mort qu'il sert si bien.$b$bAllez au Donjon d'Ombrecroc pour mettre fin une fois pour toutes aux charmes crasseux d'Arugal. Apportez-moi la tête de ce vil sorcier !", t = "Arugal doit mourir"},
    [1016] = {ot = "Récolter 5 Bracelets élémentaires intacts et utiliser le Parchemin de divination sur eux. Ensuite, apporter le Parchemin de divination à la Sentinelle Velene Starstrike au Refuge de Vent-argent.", st = "Prenez ce Parchemin de divination, il pourra nous apprendre qui a créé ces élémentaires. Mais vous aurez besoin d'une chose qui leur appartienne et que l’on pourra utiliser comme réactif pour focaliser la magie du parchemin ; leurs bracelets, par exemple, devraient faire l’affaire.$B$BQuelques bracelets intacts suffiront. Les autres bracelets ne serviront pas nos desseins mais pourront être revendus auprès d’un marchand. Une fois que vous aurez les bracelets intacts, essayez d’utiliser le Parchemin. Revenez avec le résultat de l'expérience et nous verrons quelle suite donner aux événements.", t = "Les bracelets d'élémentaire"},
    [1017] = {ot = "Tuer Sarilus Foulborne et apporter sa Tête à la Sentinelle Velene Starstrike au Refuge de Vent-argent.", st = "Il n'y a qu'un seul mage mort-vivant dans les Tarides capable de souiller autant d'élémentaires d'eau. C'est aussi le seul suffisamment idiot pour le faire. Sarilus Foulborne est probablement assis au sommet du pic de Brume-funeste, en train de se moquer de moi.$B$B$n, vous devez pénétrer en territoire ennemi et éliminer ce scélérat. J'en ai assez de sa stupidité et nous devons lui montrer ce qui arrive à ceux qui s'en prennent aux Sentinelles.$B$BTuez-le et apportez-moi sa tête. Mais soyez $gprudent:prudente;, il se peut que la Horde vous surveille.", t = "Mage invocateur"},
    [1020] = {ot = "Apporter la Jouvence d'Orendil à Pelturas Whitemoon dans Astranaar.", st = "$n, j'ai mis au point un traitement qui, je pense, devrait guérir cette pauvre enfant. Apportez-le à Astranaar et donnez-le à son père, Pelturas Whitemoon.$B$BPour atteindre Astranaar, suivez la route par le sud puis par l'est.", t = "Jouvence d'Orendil"},
    [1021] = {ot = "Trouver Anilia dans Xavian.", st = "Écoutez, je ne sais pas qui vous êtes, mais j'ai besoin de votre aide. Mes sœurs sont allées reprendre la branche de Cénarius au satyre. Elles ont dit qu'elles seraient vite de retour, mais il y a deux jours entiers qu'elles sont parties !$B$B$n, vous devez les trouver ! Elles cherchaient les ruines d'un temple des elfes de la nuit au nord-est de Xavian. Je ne sais que penser. Cherchez Anilia, c'est elle qui menait la recherche.", t = "Vil satyre ! dryades en danger !"},
    [1022] = {t = "Le Val hurlant"},
    [1023] = {ot = "Trouver la Gemme luminescente et retourner voir Raene Wolfrunner dans Astranaar avec le Journal de Teronis.", st = "En fouillant les affaires de Teronis, vous trouvez un journal qui est encore en bon état.$B$BVous prenez le journal et laissez le cadavre de Teronis comme il est.$B$BIl ne vous reste plus qu'à trouver la gemme que Teronis cherchait. Raene a dit qu'elle était dans le secteur. Peut-être que les murlocs l'ont prise...", t = "Le nettoyage selon Raene"},
    [1024] = {t = "Le nettoyage selon Raene"},
    [1025] = {ot = "Tuer 1 Protecteur, 2 Ursas, 10 Totemiques et 12 Guerriers de la tribu Vile-sylve, puis retourner voir Raene Wolfrunner, à Astranaar.", st = "Avant que vous n'alliez au Puits de lune, j'ai une autre tâche à vous confier pour aider les habitants d'Ashenvale, si ça vous dit de tester vos compétences.$B$BLe long de la route qui commence à l'est, avant le fleuve Falfarren, les furbolgs ont attaqué des voyageurs. Leurs esprits tordus se nourrissent de la peur qu'ils causent et seul le sang des innocents les rassasie.$B$BAidez les Sentinelles à protéger nos terres en rendant à ces monstres la monnaie de leur pièce.$B$BJe crois que leurs camps sont au sud de la route... Faites preuve de prudence.", t = "Une défense agressive"},
    [1026] = {ot = "Trouver la Clé en bois et un morceau du Bâtonnet de Dartol avant de retourner voir Shael'dryn au Puits de lune.", st = "Je regrette que vous n'ayez pas de meilleures nouvelles.$B$BRaene a raison, je sais ce qu'avait créé Dartol et je connais les tréants du secteur – du moins je les connaissais. Désormais, ils sont corrompus et leur nature a changé.$B$BVotre mission est de rapporter le morceau suivant du bâtonnet, mais vous devez d’abord trouver la clé qui ouvre le coffre qui contient le morceau.$B$BLa Clé en bois est sur l'un des tréants au nord-est, près de Gangrebois. Une fois que vous l'aurez, cherchez une petite clairière à l'ouest de la route près de la lisière de Gangrebois... Le coffre devrait être caché par là.", t = "Le nettoyage selon Raene"},
    [1027] = {ot = "Trouver le dernier morceau du Bâtonnet de Dartol et retourner voir Shael'dryn au puits de lune.", st = "Le dernier morceau du Bâtonnet a été donné aux druides de Dor'danil, qui en assurent la garde. Je n'ai aucune idée de l'endroit où ils l'ont caché. Je suis désolée de ne pas pouvoir mieux vous aider.$B$BTout ce que je peux vous dire, c'est de suivre la route qui mène aux Tarides. Les druides se sont réfugiés à l'est de cette route, mais ils ne vous seront pas très utiles : ils ont été tués récemment... C'est une chose à laquelle j'évite de penser.$B$BQuand vous aurez trouvé le dernier morceau, apportez-le-moi et je vous aiderai à réparer le Bâtonnet.", t = "Le nettoyage selon Raene"},
    [1028] = {ot = "Trouver l'Autel caché et recharger le Bâtonnet de Dartol.", st = "Le Bâtonnet est terminé, $n. Le réparer, c'était facile... Ce qui va nous donner plus de mal, c'est d’atteindre l'Autel qui a le pouvoir de le recharger.$B$BAvec de la concentration et des efforts, cela ne devrait pas être trop dur pour quelqu'un comme vous, qui a déjà tant accompli.$B$BPartez vers le sud-est, il y a très peu de chemins, et ne perdez pas le nord de vue – et faites preuve de prudence. L'Autel est caché dans les montagnes qui entourent cette prairie.$B$BUne fois arrivé, placez le Bâtonnet sur l'Autel... Le reste relève de la magie.", t = "Le nettoyage selon Raene"},
    [1029] = {ot = "Retourner voir Raene Wolfrunner à Astranaar.", st = "Je vous suggère d'aller trouver Raene pour lui dire que le bâtonnet est terminé. Elle saura vous dire quelle est votre prochaine mission. $B$BBonne chance, $n.", t = "Le nettoyage selon Raene"},
    [1030] = {ot = "Trouver un furbolg non corrompu et lui parler en utilisant le pouvoir du Bâtonnet de transformation de Dartol.", st = "Hélas, je ne sais pas ce qu'il comptait faire ensuite.$B$BSi ce qu'il a dit sur le pouvoir du bâtonnet est vrai, alors il devrait vous permettre de prendre une autre forme. Laquelle, je ne sais pas.$B$BPeut-être qu'il voulait utiliser ces pouvoirs pour approcher les furbolgs infectés, mais même les créatures non corrompues l'auraient abattu s'il avait manqué de prudence. Transformé par le bâtonnet, Dartol aurait pu parler à un furbolg ayant échappé aux effets de la gangremousse.$B$BVous devriez commencer vos recherches au sud-est du lac Mystral.", t = "Le nettoyage selon Raene"},
    [1031] = {t = "La branche de Cénarius"},
    [1032] = {ot = "Apporter 16 Cornes de satyre à Illiyana, au Sanctuaire d'Aessina.", st = "Je n'arrive pas à croire qu'Anilia ne soit plus là. Nous avions l'habitude de jouer ensemble dans la forêt. Je me sens presque... triste.$B$BJe sais ce qui pourrait me faire me sentir mieux. Si vous pouviez massacrer les satyres qui m'ont pris Anilia ! Rapportez-moi leurs cornes comme preuve de leur mort ; si vous faites cela, vous gagnerez mon éternelle gratitude.", t = "Mort aux satyres !"},
    [1033] = {ot = "Apporter une Larme d'Elune à Pelturas Whitemoon à Astranaar.", st = "J'espérais que le remède d'Orendil sauverait Relara, mais je crains qu'il ne puisse que ralentir la progression de la maladie qui terrasse mon enfant. Nous devons trouver des médicaments plus efficaces ! Heureusement, Orendil m'a parlé d'un autre remède à essayer au cas où le premier échouerait.$B$BLa Larme d'Elune est une variété de pierre qu'on ne trouve qu'en un seul endroit : l'île du lac Iris, à l'est d'Astranaar. Orendil a dit que cette pierre soignerait Relara... Je vous en prie, $n, apportez-moi la Larme d'Elune et priez pour qu'elle guérisse mon enfant !", t = "Larme d'Elune"},
    [1034] = {t = "Les ruines de Chimétoile"},
    [1035] = {ot = "Reprendre une Pierre de lune tombée à l'Oracle Sombretaillis puis l'apporter à Pelturas Whitemoon à Astranaar.", st = "La fièvre de Relara est tombée, mais elle est toujours très faible. Je ne crois pas que sa force reviendra avec le temps. Il va falloir le pouvoir d'une pierre de lune.$B$BNous avions l'habitude d'en ramasser au lac Tombeciel au sud-est... jusqu'à ce que les Sombretaillis s'y installent.$B$BLeur chef, un oracle, a ramassé toutes les pierres tombées de la lune et les conserve. Vous devez maintenant lui reprendre une pierre de lune.$B$BMais pour ça, je crains que vous ne soyez dans l'obligation de le tuer.", t = "Le lac Tombeciel"},
    [1037] = {ot = "Parler à Thyn'tel Bladeweaver à la Terrasse des guerriers de Darnassus.", st = "Velinde Starsong m'a précédé dans la forêt d'Ashenvale. Au début, elle semblait contrôler la situation dans Gangrebois, mais peu à peu ses résultats ont faibli. Un beau jour, elle a tout simplement disparu.$b$bOn m'a envoyé ici pour continuer sa mission. Cependant, j'ai bien peur de ne rien savoir d'elle. Peut-être que Thyn'tel Bladeweaver, l'un des commandants des Sentinelles, a du nouveau sur sa disparition, des détails que j’ignorerais.$B$BElle comprendra certainement l'importance de ce genre d'informations.", t = "Velinde Starsong"},
    [1038] = {t = "Les effets personnels de Velinde"},
    [1039] = {ot = "Aller voir le Maître des docks Dizzywig à Ratchet.", st = "Ratchet est le seul port des Tarides. L'hypothèse la plus probable est que Velinde a trouvé à Ratchet un navire de commerce pour la conduire à la crique des Flots noirs, en Azeroth. Nous avons des relations limitées avec les gobelins qui gèrent le port, mais le Maître des docks devrait avoir des informations sur les arrivées et les départs des passagers des bateaux.$b$bSuivez la route au sud-est d'Ashenvale et vous arriverez dans les Tarides. Faites preuve de prudence, $n, les guerriers de la Horde patrouillent dans le secteur. Mais au port, vous serez en sûreté.", t = "Le port des Tarides"},
    [1045] = {t = "Le nettoyage selon Raene"},
    [1046] = {ot = "Apporter le Crâne de Ran Dent-rouge et le Bâtonnet de transformation de Dartol à Raene Wolfrunner à Astranaar.", st = "Retournez dans votre tribu pour raconter votre victoire.$B$BMontrez-leur votre trophée et appréciez la gloire que vous venez de conquérir…", t = "Le nettoyage selon Raene"},
    [1054] = {t = "Diminution de la menace"},
    [1055] = {ot = "Retourner voir Shael'dryn au puits de lune.", st = "Le Bâtonnet, maintenant achevé, repose entre vos mains. Shael'dryn va vouloir apprendre votre réussite.", t = "Le nettoyage selon Raene"},
    [1056] = {ot = "Voyager pour aller voir le Gardien Albagorm au pic des Serres-Rocheuses.", st = "Les Esprits de la forêt m'ont dit que vous aviez du courage et que vous vouliez voyager.$b$bAu sud, près du lac Mystral, il y a un tunnel nommé la Perce des Serres. Par ce tunnel, vous arriverez dans un secteur connu sous le nom de la Combe des Cisailles, dans les Serres-Rocheuses. Une fois là-bas, faites route vers le sud-ouest, devant le lac de la Combe et ensuite vers le nord, en prenant la montée jusqu'au pic des Serres-Rocheuses.$b$bLe Gardien Albagorm vous y attend. Tenez compte de ce qu'il vous proposera, $N.$b$bLe voyage sera périlleux.", t = "Voyage au pic des Serres-Rocheuses"},
    [1057] = {t = "À la reconquête du Val calciné"},
    [1058] = {t = "Magie de la forêt de Jin'Zil"},
    [1060] = {ot = "Remettre la lettre de Darsok à Jin'Zil dans sa caverne des Serres-Rocheuses.", st = "Vous avez tellement fait pour moi, $n. Vous me portez vraiment chance et j'aimerais que vous voyiez quelque chose.$b$bLes harpies ne viennent pas des environs des Tarides. Elles viennent d'un endroit appelé les Serres-Rocheuses, loin au nord-ouest d'ici. Bien qu'il s'agisse probablement d'un endroit dangereux pour vous, j'ai besoin que cette lettre soit remise à l'un de mes vieux amis qui y réside, un sorcier-docteur du nom de Jin'Zil.$b$bIl sera content d'apprendre que Serena Plumesang est morte, et je crois que vous trouverez les Serres-Rocheuses intéressantes.", t = "Lettre à Jin'Zil"},
    [1061] = {ot = "Parler à Seereth Stonebreak dans les Serres-Rocheuses.", st = "Les esprits des Serres-Rocheuses sont courroucés, car les gobelins et leurs serviteurs pillent et brûlent cette région. Ainsi la Terre a appelé à grands cris, et ceux qui sont à son écoute, ont entendu.$b$bSeereth Stonebreak, un chaman prometteur de la Horde, a été envoyée dans les Serres-Rocheuses. Elle témoigne d’une large déforestation perpétrée par les gobelins, et elle demande de l'aide.$b$bRencontrez Seereth dans les Serres-Rocheuses. Pour la trouver, suivez la route à l'ouest de la Croisée des Tarides. Elle s'est établie près du val de Grandbois.", t = "Les esprits des Serres-Rocheuses"},
    [1062] = {ot = "Tuer 15 Déboiseurs de la KapitalRisk, puis retourner auprès de Seereth Stonebreak à la frontière des Serres-Rocheuses et des Tarides.", st = "La KapitalRisk, dirigée par des gobelins, s'est installée dans les Serres-Rocheuses, où ils coupent les arbres et brûlent des secteurs entiers de la forêt. Les esprits de cette terre sont quasiment aveuglés par la douleur et par la haine. Nous devons l'arrêter !$B$BPartez pour le nord-ouest, au-delà du Val de Grandbois et dans la combe des Cisailles. Vous trouverez les gobelins et leurs serviteurs à l'oeuvre. Montrez-leur que la Horde ne permettra pas l'exploitation des Serres-Rocheuses. Prouvez-le avec les arguments qu'ils comprennent le mieux...$B$BLa violence.", t = "Les invasions gobelines"},
    [1063] = {ot = "Parler à Magatha à Thunder Bluff.", st = "Pour vraiment soigner les esprits des Serres-Rocheuses, nous devons consulter les anciens esprits des taurens.$b$bLe seul chef dont j’ai entendu parler est Magatha. Elle est très vieille et ses connaissances sont grandes. Si quelqu’un peut canaliser une aide spirituelle des taurens, c'est bien elle.$b$bMagatha réside à Thunder Bluff, la capitale des taurens, sur la Cime des Anciens, la cité au nord-est du promontoire. Parlez à Magatha, et racontez-lui les périls encourus par les Serres-Rocheuses.", t = "L'Ancienne"},
    [1064] = {ot = "Parler à l'Apothicaire Zamah aux Bassins de la vision.", st = "Les taurens ont un lien avec cette terre, et apprendre la mauvaise santé des Serres-Rocheuses me peine. Mais j'ai peur que pour soigner cette terre, nous devions d'abord éradiquer la maladie qui l’envahit.$b$bN'est-ce pas heureux, alors, que les Réprouvés soient nos alliés ? Ils en savent beaucoup à propos des maladies. Je pense qu'ils peuvent nous aider, et en nous aidant ils consolideront la confiance qui existe entre nos deux peuples.$b$bParlez à l'Apothicaire Zamah. C'est une érudite et un émissaire des Réprouvés. Vous la trouverez aux Bassins de la vision sous la Cime des Esprits.", t = "L'aide des Réprouvés"},
    [1065] = {ot = "Apporter la Note de Zamah à l'Apothicaire Lydon à Moulin-de-Tarren.", st = "Pour débarrasser les Serres-Rocheuses de la KapitalRisk, nous devons employer des mesures extrêmes. Extrêmes, mais sans effusion de sang.$b$bIl se peut que l'un de mes confrères ait exactement l'outil dont nous avons besoin. Il se nomme Lydon, et réside dans la ville de Moulin-de-Tarren, dans les contreforts d'Hillsbrad, dans la terre lointaine de Lordaeron.$b$bPour atteindre Hillsbrad, voyagez par zeppelin vers notre capitale, Fossoyeuse. Puis allez au nord vers les Clairières de Tirisfal, au sud-ouest vers les Pins argentés, et enfin au sud vers Hillsbrad.$b$bCherchez Lydon et donnez-lui cette note. Elle explique ce que nous attendons de lui.", t = "Un voyage vers Moulin-de-Tarren"},
    [1066] = {ot = "Apporter 5 Fioles de Sang d'innocent à l'apothicaire Lydon à Moulin-de-Tarren.", st = "Je vais créer une toxine pour annihiler la violence de la KapitalRisk, et la rendre faible et docile. Cela devrait régler le problème de la Horde dans les Serres-Rocheuses, pas vrai ?$b$bMais pour créer la toxine, je vais avoir besoin de sang d'innocent, un ingrédient difficile à trouver.$b$bHeureusement le Syndicat, un groupe de brigands humains, emploie des mages de l'ombre... Et ces mages stockent du sang d'innocent pour leurs propres desseins, peu recommandables.$b$bVous trouverez les mages de l'ombre du Syndicat au donjon de Fort-de-Durn, au sud-est.", t = "Le sang des innocents"},
    [1067] = {ot = "Apporter la Toxine de Lydon à l'Apothicaire Zamah à Thunder Bluff.", st = "Voici la toxine. Si vous l'utilisez contre la KapitalRisk, cela devrait produire des effets intéressants, et peut-être même contagieux. Je dois dire que c'est très excitant de voir mon travail appliqué sur le terrain !$b$bMais avant de l'utiliser, apportez-la à l'Apothicaire Zamah. Elle doit concevoir une méthode de diffusion particulière pour optimiser les effets de la toxine.", t = "Le retour à Thunder Bluff"},
    [1068] = {ot = "Détruire les Déchiqueteurs XT4 et XT9, puis retourner voir Seereth Stonebreak à la frontière entre les Serres-Rocheuses et les Tarides.", st = "Il existe une relation entre la magie spirituelle des chamans et la magie naturelle des druides. C'est pourquoi nous, les chamans, nous pouvons entendre la complainte des esprits des Serres-Rocheuses. Beaucoup de leurs murmures m'échappent, mais un message – une vision – est clair...$b$bJ'ai eu la vision de deux machines à forme humaine, dans la Combe des cisailles, au nord-ouest du val de Grandbois, coupant les arbres à une vitesse incroyable. Ces bêtes de métal doivent être stoppées !$b$bDans ma vision, il y avait d'étranges symboles gravés sur les machines :$b$bXT4 et XT9.", t = "Les machines à déchiqueter"},
    [1069] = {ot = "Apporter 15 Œufs des mousses profondes à Mebok Mizzyrix à Ratchet.", st = "L’omelette aux oeufs d'araignée est la nouvelle mode culinaire à Baie-du-Butin ! Le problème c'est qu'il n'y a pas le moindre oeuf dans toute la ville.$b$bUne possibilité se profile !$b$bÀ la combe des Cisailles et dans le canyon de Sishir, dans les Serres-Rocheuses, au nord-ouest, vit l'araignée des mousses profondes. Apportez-moi ses oeufs et je vous payerai un sacré paquet !$b$bÀ la combe des Cisailles, vous trouverez les oeufs groupés sous les arbres qui restent.$B$BEn ce qui concerne le canyon de Sishir... eh bien, si vous avez un estomac fragile, vous feriez bien de vous en tenir à la combe des Cisailles pour collecter les oeufs...", t = "Omelette à la mousse profonde"},
    [1070] = {ot = "Retrouver Kaela Shadowspear qui surveille la vallée à l'entrée de la combe des Cisailles dans les Serres-Rocheuses.", st = "Salutations, $n.$b$bVotre apparence semble indiquer que vous avez envie de parcourir le monde. Êtes-vous $gallé:allée; dans les Serres-Rocheuses ? C'est une région tourmentée par la KapitalRisk et par d'autres ennemis des elfes de la nuit.$b$bRécemment, la sentinelle Wolfrunner y a envoyé mon amie Kaela Shadowspear enquêter sur place, et je n'ai toujours pas reçu de ses nouvelles. L'inquiétude me ronge, d'autant que l'Alliance a envoyé un mage gnome avec elle... Mauvais présage, pour sûr.$b$bPourriez-vous la retrouver et revenir m'informer ?", t = "De garde dans les Serres-Rocheuses"},
    [1071] = {ot = "Tuer 10 Déboiseurs de la KapitalRisk et 10 Défricheurs de la KapitalRisk, puis retourner voir Gaxim Rustfizzle dans les Serres-Rocheuses.", st = "Vous voyez, $n, je suis un membre de l'Assemblée illuminée d'arcanologie, d'alchimie et de sciences d'ingénierie, et c'est mon but… non, il est de mon DEVOIR de montrer aux elfes de la nuit que l’association de magie, de mixtures et de mécanique peut aider à sauver leurs forêts.$b$bMais c'est un combat acharné, et les gobelins semblent se reproduire comme des lapins. Je n'ai même pas eu le temps de construire mes dernières inventions !$b$bJ'ai besoin de temps pour planifier et organiser. Mais vous pouvez m’aider à retenir les gobelins à quai à la combe des Cisailles, à l'est.", t = "Du répit pour un gnome"},
    [1072] = {ot = "Parler à Lomac Gearstrip à Forgefer.", st = "L'appareil auquel je pense est à ce jour ma version la plus avancée. Mais nous aurons besoin d'une potion spéciale si nous voulons que ça marche. Je pense que nous pourrons avoir la bonne dose également puisque cette mission sera votre dernière.$b$bEt pour ça, il nous faut un puissant explosif : le Nitromirglyceronium.$b$bLa seule personne qui puisse faire du NG-5 est un de mes vieux amis : Lomac Gearstrip. Cherchez-le à Brikabrok.$b$bDemandez-lui de nous faire du NG-5, je vais travailler au placement de mes appareils en attendant.", t = "Un vieux collègue"},
    [1073] = {t = "Inaptitude + Produits chimiques = Rigolo"},
    [1075] = {t = "Un parchemin de Collin Mauren"},
    [1076] = {t = "Des diables dans la marche de l'Ouest"},
    [1078] = {ot = "Apporter 8 Ecailles de cristal à Collin Mauren à Stormwind.", st = "Les voyageurs m'interrogent toujours au sujet des Serres-Rocheuses. C’est une région populaire pour qui cherche l'aventure, qu’il s’agisse de traquer des wyverns, des élémentaires, ou du personnel de la KapitalRisk.$b$bDans le Val calciné, loin à l’intérieur des montagnes, vivait autrefois une espèce de basilic dont les écailles, une fois plantées dans la poussière, produisaient un merveilleux réactif pour certains des sorts que j'ai créés.$b$bSi ces basilics vivent toujours, j'aimerais avoir quelques-unes de leurs écailles.$b$bPrenez votre temps, ce n'est pas urgent, mais je paye bien.", t = "Des retrouvailles pour Mauren"},
    [1085] = {ot = "Parler à Gaxim.", st = "La situation ici dans les Serres-Rocheuses est suffisamment grave pour qu'une elfe de la nuit et un gnome travaillent ensemble.$b$bLa KapitalRisk a dévasté cette région et j'ai passé la majeure partie de mon temps à mettre un terme à cette destruction.$b$bNe jugez pas Gaxim trop vite, il comprend la nécessité de notre travail commun.$b$bSi vous souhaitez nous aider, alors commencez par parler à Gaxim.$b$bJe suis désolée de ne pas encore pouvoir vous renvoyer à Tara avec de bonnes nouvelles. Bientôt peut-être…", t = "De garde dans les Serres-Rocheuses"},
    [1086] = {ot = "Apporter le Brouillard toxique à l'aéroport de la KapitalRisk, puis retourner voir l'Apothicaire Zamah.", st = "La toxine est prête. Tout ce qu'il reste à faire est de la livrer. Vous devez vous en occuper, $n.$b$bLa KapitalRisk doit avoir un moyen d'envoyer des messages et de petites cargaisons entre ses quartiers généraux et ses sites d'opérations dans les Serres-Rocheuses. Il s'agit probablement d'un petit aéroport, pas suffisamment important pour un zeppelin, mais assez pour une machine volante. Cherchez dans les Serres-Rocheuses les secteurs sous contrôle de la KapitalRisk et trouvez cet aéroport, s'il existe. Placez-y alors la toxine.$b$bPlacez-la, et courez !", t = "L'aéroport de la machine volante"},
    [1087] = {ot = "Tuer 4 Fils de Cénarius, 4 Filles de Cénarius et 4 Botanistes cénariens pour Braelyn Firehand, près de la retraite de Roche-Soleil.", st = "Vous ne pouvez pas imaginer la haine que je ressens pour cette terre misérable. Au pic, les semblables de Cénarius et les druides kaldorei emploient leurs pouvoirs minables pour étouffer le flot de magie, même jusqu'au sud de leurs possessions pathétiques... leurs forêts bien-aimées.$b$bJe voudrais retourner à Jaedenar et exulter dans le flot de magie, mais mon maître ne le permettra pas tant que mon travail ici ne sera pas achevé.$b$bIl ne fait aucun doute que vous aimez les elfes de la nuit et leurs alliés aussi peu que je les aime. Aidez-moi, et notre but commun pourra être atteint.", t = "L'héritage de Cénarius"},
    [1088] = {ot = "Apporter la Tête d'Ordanus à Braelyn Firehand, près de la Retraite de Roche-Soleil.", st = "Ils ont cru qu'ils pourraient arrêter le flot de magie. Ils se sont trompés. Ils ont cru pouvoir cacher Ordanus, mais j'aurai sa tête !$b$bLa magie m'accorde la vision véritable. Oui… il est là. Un croisement… Au sommet d'un grand arbre dans la forêt d'Ashenvale. Un nom... Raynewood. L'un des fils aînés du dieu de la Forêt. Ils l'ont fait disparaître du pic avant que je puisse le trouver, mais son temps est compté.$b$bApportez-le-moi et je vous offrirai un puissant cadeau.", t = "Ordanus"},
    [1090] = {ot = "Obtenir le minerai mystérieux de Piznik après qu'il l’aura extrait.", st = "Vous savez, avant j'étais la seconde personne la plus importante ici sur ce site. Tout a changé quand Gerenzo est arrivé. Il a viré mon patron, Ziz Fizziks, et m'a envoyé bosser dans les mines. Ziz m'a dit de rester ici et de rassembler des renseignements. Son nouveau patron nous paiera bien si nous pouvons découvrir les plans de Gerenzo.$b$bMais bon, ce que je sais c’est que Gerenzo a ordonné que des quantités importantes de ce minerai or-vert soient extraites. Je peux vous trouver un échantillon pour que vous l'apportiez à Ziz, mais faites attention aux patrouilles le temps que j’aille en chercher.", t = "Les ordres de Gerenzo"},
    [1092] = {ot = "Remettre le Minerai non identifié à Ziz Fizziks dans les Serres-Rocheuses.", st = "Je pense que je ferais mieux d’envisager de ficher le camp d'ici, aussi. Ça ne va pas prendre beaucoup de temps avant que la nouvelle de ce qui s'est passé ici se répande au-dessus, et je suis sûr qu'ils ne seraient pas ravis de me revoir.$b$bJe vais dégager d’ici et aller voir Ziz. J'espère qu'il pourra me trouver du boulot !$b$bJe vais essayer de nettoyer ce bordel, mais vous devez apporter l'échantillon de minerai à Ziz tout de suite. Il m'a dit qu'il établirait un camp quelque part du côté ouest de la Combe des Cisailles. Bonne chance.", t = "Les ordres de Gerenzo"},
    [1093] = {ot = "Trouver le Plan du Super-Découpeur 6000 pour Ziz Fizziks dans les Serres-Rocheuses.", st = "C'est terrible ce que la KapitalRisk a fait ici, hein ? Mais à quoi donc pensaient-ils ? Une compagnie de gobelins qui embauche un gnome !$b$bHeureusement pour moi, Sputtervalve reconnaît un génie lorsqu'il en voit un. M'a embauché juste après que je me suis fait virer !$b$bIl me dit qu'ils construisent une énorme machine pour découper le bois, et Sputt veut que je vole les plans pour lui. Malheureusement, Gerenzo – maudit gnome – veut ma peau... Peut-être que vous pourriez voler les plans pour moi ? Vous devriez les trouver sur l'un de leurs opérateurs.", t = "Super-Découpeur 6000"},
    [1094] = {t = "D'autres instructions"},
    [1095] = {ot = "Apporter les nouveaux ordres à Ziz Fizziks dans les Serres-Rocheuses.", st = "L’embauche de ce gnome par la KapitalRisk a créé quelques remous à Undermine. Les princes marchands n'approuvent pas que Razdunk fasse des affaires avec ce Gerenzo.$b$bRiddlevox m'a demandé de m'occuper du problème, et il est certain qu'il a reçu, d'un ou de plusieurs princes marchands, les mêmes instructions. Bien sûr, le directeur ne me l'a pas dit. Disons que j'ai simplement une intuition.$b$bQuoi qu'il en soit, nous devons faire en sorte de supprimer Gerenzo, et ce serait le test parfait de voir Fizziks s'en occuper.", t = "D'autres instructions"},
    [1096] = {ot = "Apporter le Bras mécanique de Gerenzo Wrenchwhistle à Ziz Fizziks dans les Serres-Rocheuses.", st = "J'ai rencontré Gerenzo une fois, mais laissez-moi vous dire qu'il n'est pas très beau à voir. On dirait que sa chair est en train de pourrir, et il s'est fait greffer du métal et des accessoires sur le corps. Il a remplacé certains membres naturels par des membres mécaniques.$b$bAu nord-est d'ici, loin au-dessus du lac de la Combe, près de la roue hydraulique, Gerenzo surveille le site entier.$b$bJe ne pourrais pas monter là-haut, je ne survivrais pas aux combats. Sans parler de me charger de Gerenzo... Mais vous semblez être capable de réussir.$b$bSi vous le tuez pour moi, je ferai en sorte que ça en vaille le coup !", t = "Gerenzo Wrenchwhistle"},
    [1097] = {ot = "Parler à Grimand Elmore.", st = "Il y a un fabricant d'armes à Stormwind, un nain du nom de Grimand Elmore, qui nous a envoyé un mot disant qu'il avait besoin d'aide avec une livraison. Je crois qu'il veut qu'un paquet soit envoyé dans son pays d’origine, dans le nord.$b$bVous avez des jambes robustes ! Si vous êtes $gintéressé:intéressée; par un peu de marche à pied, alors parlez à Grimand. Nous pourrions vous utiliser ici, mais nous devons également entretenir nos bonnes relations avec les nains.$b$bVous trouverez Grimand Elmore au magasin d'armes dans le quartier des nains de Stormwind, dans la partie nord-est de la ville.", t = "La quête d'Elmore"},
    [1098] = {ot = "Trouver les Traqueurs noirs Adamant et Vincent.", st = "En préparation d'un assaut sur Ombrecroc, deux Traqueurs noirs ont été envoyés au donjon pour réunir des renseignements. Plusieurs jours ont passé, et ils ne sont toujours pas revenus. Nous devons cependant prendre connaissance de leur rapport si nous voulons que notre attaque ait la moindre chance de réussir !$b$bAussi voici votre tâche, $n. Partez pour le donjon d'Ombrecroc au sud et trouvez les Traqueurs noirs Adamant et Vincent. Trouvez-les, et s'ils ont besoin d’aide, aidez-les !$b$bCette mission est aussi dangereuse qu'elle est critique, $n. N'échouez pas.", t = "Des Traqueurs noirs à Ombrecroc"},
    [1100] = {ot = "Lire le Journal de Henrig Lonebrow.", st = "Vous ouvrez lentement le journal décoloré de Henrig Lonebrow…", t = "Journal de Lonebrow"},
    [1101] = {ot = "Apporter le Médaillon de Trancheflanc à Falfindel Waywarder à Thalanaar.", st = "Pauvre Heralath ! Et ce nain... Lonebrow. Quel esprit courageux il avait.$b$bNous ne devons pas laisser leur vaillance périr pour rien. Cette mégère… Charlga Trancheflanc… doit être arrêtée.$b$bIl ne fait pas de doute qu'infiltrer le Kraal sera périlleux. Nous n'avons pas le temps d'envoyer un mot à Darnassus. $n, rassemblez un groupe et tuez la mégère.$b$bApportez-moi le médaillon de Trancheflanc comme preuve de son décès.", t = "La mégère du Kraal"},
    [1102] = {ot = "Apporter le Cœur de Trancheflanc à Stonespire le Vieil, à Thunder Bluff.", st = "Cairne est un noble chef qui a unifié notre peuple, ici, à Thunder Bluff.$b$bMais je ne peux pas pardonner aussi facilement à ceux qui nous ont éloignés de nos terres ancestrales. Mon peuple a habité les Tarides du sud pendant des décennies. Cette terre est sacrée pour nous. Mais nous en avons été chassés par de nombreux ennemis.$b$bUn destin funeste attend la sinistre mégère, Charlga Trancheflanc, qui rameute une ignoble armée depuis le Kraal de Tranchebauge.$b$bApportez-moi le coeur de Trancheflanc et je pourrai mourir en paix, $n.", t = "Un destin funeste"},
    [1109] = {ot = "Apporter 1 tas de Guano du kraal au Maître Apothicaire Faranell à Fossoyeuse.", st = "Comme vous pouvez le constater, $N, nous préparons de très… intéressantes expérimentations à la Société royale des apothicaires.$B$BEn tant que Maître, mon travail est de superviser les plus ambitieuses de nos tentatives alchimiques. Tellement de travail et si peu de temps !$B$BVous avez l'air d'avoir beaucoup voyagé, $c. Peut-être pourriez-vous m'aider.$B$BJ'ai besoin d'une substance rare. C'est un matériau infect, qui provient d'une espèce rare de chauves-souris que l'on trouve dans la fosse connue sous le nom de Kraal de Tranchebauge. Apportez-moi du guano de chauve-souris du kraal afin que nous puissions nous mettre au travail...", t = "Corvée de guano"},
    [1111] = {ot = "Apporter la Commande de Kravel au Maître des quais Dizzywig à Ratchet.", st = "Mon boulot, c'est que les gens obtiennent ce dont ils ont besoin, et les gnomes par-là ont besoin qu'une commande soit passée. Leurs pièces sont arrivées à Ratchet il y a une semaine, mais je n'ai pas pu faire le voyage.$b$bAlors, êtes-vous $gprêt:prête; à marcher un peu ? Allez à Ratchet, et donnez cette commande de pièces au Maître des quais Dizzywig. Il se trouvera probablement sur les docks.$b$bFaites cela pour moi, et j'aurai plus de boulots à vous confier.$b$bDes boulots, mon $gami:amie; avec de sérieux bénéfices à la clé...", t = "Maître des quais Dizzywig"},
    [1112] = {ot = "Apporter les Pièces détachées de Kravel à Kravel Koalbeard dans les Salines.", st = "Voici le paquet de Kravel, $n. Et lorsque vous lui remettrez, dites-lui que s'il veut plus de commandes spéciales, alors il doit payer l'addition !", t = "Les pièces détachées de Kravel"},
    [1131] = {ot = "Apportez 1 Côte de Broie-l'acier à Melor Stonehoof à Thunder Bluff.", st = "Parfois, nous chassons pour vivre. Parfois, nous chassons pour l'honneur. Et parfois, nous chassons pour mériter le savoir de la Terre-mère. $B$BMais la chasse qui vous attend n'est pas de celles-là. Il s'agit de détruire une créature qui refuse les bénédictions de la Terre-mère. $B$BLes Mille pointes, au sud des Tarides, sont le terrain de chasse de la hyène Broie-l'acier. C'est un tyran, qui attire à lui les autres hyènes, répand la terreur et massacre les bêtes plus paisibles. $B$BTrouvez Broie-l'acier, $n. Trouvez-le et tuez-le.", t = "Broie-l'acier"},
    [1134] = {t = "Les Ailes-fières des Serres-Rocheuses"},
    [1138] = {ot = "Collecter 6 morceaux de Belle chair de crabe pour Gubber Blump, à Auberdine.", st = "J’adore le crabe, ce fruit de mer par excellence ! Vous pouvez le faire griller, l’ébouillanter, le braiser, en faire des beignets frits, des acras, le déguster en salade ou le consommer en soupe ; voilà tout ce qu’on peut faire avec.$B$BJe suis ici en train de pêcher en ce moment, et je ne peux donc pas me procurer les morceaux de belle chair de crabe dont j'ai besoin. Vous pouvez en trouver sur les clampants des récifs et sur les clampants des marées incrustés. Vous pouvez en faire plein de choses. Vous pouvez le faire griller, l’ébouillanter, le braiser...", t = "Fruit de la mer"},
    [1140] = {ot = "Libérer les Âmes de Bien-nés captives au défilé de la Nuit et à Satyrnaar, puis retourner voir Delgren le Purificateur au poste de Maestra.", st = "L'écriture des orcs est à peine plus lisible que le gribouillage d'un enfant. J'ai essuyé bien des moqueries lorsque j'ai décidé d'apprendre leur langue, mais il est toujours utile de connaître l'ennemi. $b$bSi j'en crois les griffonnages d'Ilkrud, il semble qu'Athrikus possède toujours deux gemmes d'âme captives, au défilé de la Nuit et à Satyrnaar, des régions tenues par les satyres au nord-est d'Ashenvale. $B$BFaites attention, $n, les temples baignés de sang des satyres peuvent être effrayants, même pour des $cs aguerris !", t = "La tour d'Althalaxx"},
    [1141] = {ot = "Attraper 6 Mérous de Sombrivage pour Gubber Blump, à Auberdine.", st = "J’adore pêcher. La famille Blump est connue comme une grande famille de pêcheurs. Je m’appelle Gubber Blump ; je pêche.$B$BIl y a un poisson que j’aime attraper dans le coin, le mérou de Sombrivage. J’avais l’habitude d’aller en bateau pour pêcher Ie mérou, mais les bateaux ne sortent plus depuis que ces maudits murlocs sont arrivés. Je suppose qu’ils ont aussi dévoré tous les mérous.$B$BVoulez-vous m’aider à attraper des mérous de Sombrivage ? Si vous m’aidez, je vous donnerai une authentique canne à pêche de la famille Blump ! C’est une excellente canne pour attraper le poisson.", t = "La famille à la canne à pêche"},
    [1142] = {ot = "Trouver et rapporter le Pendentif de Treshala à Treshala Fallowbrook à Darnassus.", st = "Il ne me reste plus beaucoup de temps... Tellement... Tellement faible... $b$bLe brave Lonebrow a été envoyé pour avertir Falfindel... $b$bMais avant que je ne m-m-meure... $b$b... Ma femme, Treshala... Son pendentif de mariage avec moi... V-v-volé... par un de ces sauv-v-vages agresseurs... $b$bTrouvez-le, j-j-je vous en prie... Et rapportez-le à Treshala, à Darnassus...$b$b... Et racontez-lui ma mort... solitaire.", t = "Le déclin et la mort"},
    [1144] = {ot = "Escorter Willix l'Importateur hors du Kraal de Tranchebauge.", st = "Enfin de l'aide ! $b$bVous n'avez pas idée du temps que j'ai passé prisonnier ici ! Je n'arrive plus à me rappeler quand j'ai vu le monde extérieur pour la dernière fois. $b$bVous voyez, je suis un entrepreneur. Prêt à tout en échange d'un sou, si vous voyez ce que je veux dire. J'avais entendu dire que Mizzyrix payait bien pour les Racines de Feuillerouge locales, de ce trou à rats ! Je pensais que ce serait de l'argent facile. Je me trompais et pas qu'un peu ! $b$bEnfin... Merci de m'avoir sorti de là, je vous le revaudrai...", t = "Willix l’Importateur"},
    [1145] = {ot = "Remettre la Note scellée de Korran à Belgrom Rockmaul à Orgrimmar.", st = "Bien des voyageurs qui sont passés par la Croisée m'ont aidé à ramasser des oeufs dans le Champ des géants, et nombreux sont ceux qui ont rapporté des récits effrayants sur les créatures. J'en ai assez entendu pour considérer ces insectes comme plus dangereux que ne l'avaient cru mes maîtres de prime abord. $B$BJ'ai besoin d'un courrier pour aller à Orgrimmar trouver Belgrom Rockmaul. Cela ne sera pas simple et celui qui ira devra prendre cette tâche au sérieux. $B$BOn trouve généralement Belgrom devant la maison des guerriers.", t = "L'essaim s'agrandit"},
    [1146] = {ot = "Apporter la Note scellée de Belgrom à Moktar Krin aux Mille pointes.", st = "Ainsi, Korran est arrivé aux mêmes conclusions que nous sur ces insectes... On dirait qu'il s'agit d'une menace plus grande que nous ne le pensions au départ. $B$BIl y a quelques jours, un chasseur est rentré à moitié mort des Mille pointes. Il accompagnait un groupe chargé de déloger une équipe de fouille naine hors des Salines. Une nuée de ces insectes a jailli d'une grotte pendant l'attaque et les a presque anéantis.$B$BIls étaient sous les ordres de Moktar Krin et ils se sont réfugiés à la lisière des Salines. Apportez-lui cette note.", t = "L'essaim s'agrandit"},
    [1149] = {ot = "Si vous avez la Foi, sautez des planches qui dominent les Mille pointes.", st = "Vous me cherchiez, ou peut-être est-ce le destin qui vous mène à moi ? Aucune importance. Vous voilà et un nouveau voyage commence pour vous. $B$BIl y a différents aspects dans un être : l'esprit, le corps, l'âme. Certains peuvent être améliorés par les traditions d'une culture. Pour d'autres... Nous pouvons simplement espérer qu'elles existent en nous. Si vous êtes d'accord, je vais mettre à l'épreuve quelques-unes de vos qualités. $B$BSi vous réussissez, vous y gagnerez en force. Si vous échouez, vous comprendrez l'immensité du Néant. $B$BLa première épreuve est l'Epreuve de la Foi.", t = "L'épreuve de la Foi"},
    [1150] = {ot = "Apporter la Griffe de Grenka au traqueur des plaines Dorn, aux Mille pointes.", st = "Il me plaît de constater que votre courage reste entier à la lumière de ce que vous avez déjà réalisé. Puisque votre foi est grande, il est temps de mettre les capacités de votre corps à l’épreuve.$B$BAllez avec des amis jusqu’à la tanière des Volplumes, à l’ouest du poste de Librevent. Plongez au cœur de leur tanière et détruisez leurs réserves de nourriture. Cela devrait provoquer leur colère, et si vous êtes capable de survivre assez longtemps à leur furie, Grenka Hurlesang elle-même s’attaquera à vous… Tuez-la et apportez-moi sa griffe en accomplissement de votre épreuve.", t = "L’épreuve de l’Endurance"},
    [1151] = {ot = "Apporter des Fragments de Rok'Alim au traqueur des plaines Dorn dans les Mille pointes.", st = "Au temps des Dieux très anciens, les élémentaires peuplaient ce monde. Ils adoraient les Dieux très anciens, et le pouvoir de ces derniers maintenait les élémentaires attachés à ce monde. Lorsque les Dieux très anciens furent bannis, les élémentaires disparurent de notre monde et ils n’y reviennent que s'ils sont appelés par de puissants mages. $B$BIl y a pourtant des exceptions. Certains élémentaires étaient suffisamment puissants pour rester. L'un d'eux est Rok'Alim. $B$BPour mettre votre force à l'épreuve, trouvez Rok'Alim dans les Mille pointes et tuez-le.", t = "L'épreuve de la Force"},
    [1153] = {ot = "Trouver un échantillon de minerai brut sur un Mineur ou un Géomètre Mufle-de-gravier et l’apporter à Tatternack Steelforge, à Camp Taurajo dans les Tarides.", st = "Vous m'avez apporté une aide précieuse par le passé, $c. Le Chef de guerre apprécie, au moins jusque-là, ce que j'ai accompli, et me demande de continuer avec une nouvelle détermination. Mon honneur me commande de vous envoyer au Chef de guerre avec une recommandation pour tout ce que vous avez fait, mais avant je voudrais vous demander votre aide une nouvelle fois. $B$BDes voyageurs, récemment revenus d'un endroit appelé les Mille pointes, ont tué un kobold porteur d'un échantillon d'un minerai inhabituel. Ils n'ont pas voulu le vendre. Je voudrais que vous me rapportiez un échantillon de ce minerai.", t = "Un nouveau minerai"},
    [1167] = {ot = "S'entretenir avec Balthule Shadowstrike près de la Tour d'Althalaxx.", st = "Il serait sage de vous entretenir avec Balthule avant d'affronter Athrikus. Il a certainement observé la Tour avec une grande vigilance et il pourrait avoir des renseignements intéressants.", t = "La tour d'Althalaxx"},
    [1195] = {ot = "Rapporter une Fiole d'Eau forte remplie à Zangen Stonehoof à Thunder Bluff.", st = "Les centaures du clan Galak, dans les Mille pointes, protègent un artefact du temps de la création de leur espèce.$B$BNous aimerions le voir de plus près, mais il nous faut d’abord une fiole d'eau provenant d’un des puits de lune des elfes de la nuit.$B$BPour puiser l'eau, vous aurez besoin d'une des fioles que transportent les dryades près de la retraite de Raynewood, au cœur de la forêt d'Ashenvale. Il existe un puits de lune près de la rive ouest de la rivière Falfarren, au sud de la route principale. Vous pourrez y remplir la fiole.", t = "La flamme sacrée"},
    [1196] = {ot = "Remettre la Fiole d'Eau forte remplie à Rau Cliffrunner au Poste de Librevent.", st = "Apportez la Fiole remplie à Rau Cliffrunner au Poste de Librevent dans le sud-est des Mille pointes. Vous pouvez atteindre les Mille pointes en empruntant la Grande élévation à la limite sud des Tarides. $b$bJe ne serais pas surpris que vous puissiez nous aider davantage.", t = "La flamme sacrée"},
    [1197] = {ot = "Retrouver le Sabot fendu pour Rau Cliffrunner du Poste de Librevent.", st = "En l'aspergeant avec l’eau que vous avez apportée, vous pourrez temporairement éteindre la flamme qui protège la relique des centaures. L'effet sera provisoire, vous devrez faire vite.$b$bVous trouverez la combe du Sabot fendu, la ville fortifiée des centaures, plus au nord. La flamme est gardée dans le bastion du Sabot fendu, une zone très solidement gardée.$b$bFaites attention, les centaures du clan Galak sont très nombreux à cet endroit et ils combattront férocement pour protéger une chose aussi importante à leurs yeux.", t = "La flamme sacrée"},
    [1198] = {ot = "Aller chercher le Garde d'argent Thaelrid dans les Profondeurs de Brassenoire.", st = "De nombreuses rumeurs circulent ces jours-ci sur l'union entre le Marteau du crépuscule et les nagas dans les Profondeurs de Brassenoire sur les côtes d'Ashenvale.$B$BMon rôle ici avec l'Aube d'argent est de collecter autant d'informations que possible, afin que nous sachions où et quand on a besoin d'aide.$B$BCela fait des semaines à présent que j'ai envoyé un éclaireur espionner les activités menées dans les Profondeurs de Brassenoire. Le Garde d’argent Thaelrid n'est toujours pas revenu.$B$BMes autres éclaireurs sont très pris par d'autres tâches pressantes.$B$BRecherchez et venez en aide à Thaelrid pour moi, $N.", t = "À la recherche de Thaelrid"},
    [1199] = {ot = "Apporter 10 Pendentifs du Crépuscule au Garde d'argent Manados à Darnassus.", st = "Les membres du Marteau du crépuscule, se servant des vieux rites des chaotiques Dieux très anciens, se battent pour les ramener en ce monde et pour y répandre la mort et la terreur.$B$BNous pensons que le Marteau du crépuscule s'est allié aux nagas et se regroupe en masse dans les Profondeurs de Brassenoire sur la côte d'Ashenvale.$B$BQuels que soient les plans maléfiques qu'ils préparent dans les profondeurs du temple ancien, ils doivent être contrecarrés.$B$BLancez un assaut sur le Marteau et rapportez la preuve de vos actes. Vos efforts se verront récompensés de grandiose manière.", t = "Le crépuscule descend"},
    [1200] = {ot = "Apporter la Tête du Seigneur du crépuscule Kelris au Veilleur de l'aube Selgorm, à Darnassus.", st = "Mes forces me quittent. J'ai besoin de votre aide ! $b$bIl y a longtemps, ce site était un grand temple d'Elune. Mais la malchance l'a conduit à sa ruine, quand un Dieu très ancien, en contaminant la terre, a corrompu le Puits de lune sacré. $b$bAku'Mai, serviteur du Dieu très ancien, est sorti des eaux.$b$bLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Les sectateurs, conduits par Kelris, sacrifient des innocents à Aku'Mai pour augmenter son pouvoir. $b$bTuez Kelris et apportez sa tête à Selgorm, à Darnassus, je vous en prie, $n.", t = "L'infamie de Brassenoire"},
    [1221] = {ot = "Prendre une Caisse percée.$BPrendre un Bâton de commandement de Sniffetarin.$BLire le Manuel d'utilisateur de Sniffetarin.$B$BAu Kraal de Tranchebauge, utiliser la Caisse pour invoquer un Ecureuil Sniffetarin et utiliser le Bâton de commandement pour ordonner à l'Ecureuil de chercher les racines.$B$BRamener 6 Racines de Feuillebleue, le Bâton de commandement de Sniffetarin et la Caisse percée à Mebok Mizzyrix, à Ratchet.", st = "Les racines de feuillebleue sont une friandise universellement appréciée ! Mais elles sont rares, très rares. On ne peut les trouver qu'ici, dans les Tarides, profondément enterrées au kraal de Tranchebauge.$B$BEt même ici, vous ne pourriez pas les trouver à moins de savoir comment les chercher ! C'est pourquoi j'ai entraîné ces Ecureuils Sniffetarin à les trouver. Ils ont un grand nez et peuvent sentir une racine à cinquante pas.$B$BCela ne sera pas facile, mais si vous me ramenez quelques racines, je vous paierai grassement.", t = "Racines de Feuillebleue"},
    [1275] = {ot = "Gershala Nightwhisper d'Auberdine veut 8 Souches de cerveau corrompu.", st = "Ces imbéciles d'elfes de sang peinent avec la magie démoniaque. N'ont-ils pas vu ce qui est arrivé aux nagas et aux satyres de Kalimdor ?$B$BJe crains que les elfes de sang ne rencontrent pareille déformation. Azeroth ne supporterait pas la naissance d'une autre race de monstres infects.$B$BJe souhaite étudier les Souches de cerveaux des satyres et des nagas afin d'en déduire la voie que prennent les elfes. Vous trouverez des satyres et des nagas dans les Profondeurs de Brassenoire, sur la côte d'Ashenvale.$B$BC'est un long voyage, $N.", t = "Recherches sur la corruption"},
    [1338] = {ot = "Porter la commande de Foudrepique à Furen Longbeard à Stormwind.", st = "Il y a un forgeron nain dont j'admire beaucoup le travail. Il s'appelle Furen Longbeard et ses compétences sont inégalables. J'ai besoin d'un nouveau bouclier et je veux l'un des siens !$B$BLe problème… Furen est loin dans le sud, dans le quartier des nains de Stormwind. Chez les humains ! Je ne comprends pas pourquoi il vit là-bas, si loin de Forgefer. Les humains doivent lui faire un pont d’or pour qu'il accepte de rester !$B$BSi vous avez envie de voyager, et ne pensez pas à demander une récompense, alors pourquoi ne porteriez-vous pas ma commande de bouclier à Furen ?", t = "La mission de Foudrepique"},
    [1339] = {ot = "Parler au Montagnard Foudrepique.", st = "J'ai entendu dire que le montagnard Foudrepique a besoin d'un coursier. Quelqu'un pour voyager à sa place. Qu'en pensez-vous, $N ? Êtes-vous capable de ce travail ?$B$BSi c'est le cas, vous trouverez Foudrepique au sommet de la tour de garde la plus au nord.", t = "La mission du Montagnard Foudrepique"},
    [1358] = {ot = "Apporter l'échantillon de coeur de loup à l'Apothicaire Helbrim dans les Tarides.", st = "Un collègue de Kalimdor, l'apothicaire Helbrim, étudie les effets des toxines de Lordaeron sur les animaux de Kalimdor. Il serait très intéressé par un échantillon de coeurs de loups que Renferrel m'a envoyés.$B$BHelbrim se trouve dans les Tarides, dans un village connu sous le nom de la Croisée. Pour le rejoindre, vous voyagerez par zeppelin jusqu'à Orgrimmar, la capitale des orcs, puis à pied vers le sud en Durotar. Allez à l'ouest, dans les Tarides, et vous trouverez rapidement la Croisée.", t = "Un échantillon pour Helbrim"},
    [1359] = {ot = "Apporter les Echantillons de coeurs de loups à l'apothicaire Zinge à Fossoyeuse.", st = "Les Coeurs de loups que vous avez là possèdent une qualité inouïe pour ces spécimens. Ils possèdent une toxicité telle qu'elle tuerait net les loups vivants !$B$BC'est fascinant, il faut approfondir l'étude. J'ai gardé quelques échantillons de ces coeurs. Apportez-les à ma collègue, l'Apothicaire Zinge. Vous la trouverez dans notre quartier général à Fossoyeuse.", t = "Une livraison pour Zinge"},
    [1431] = {ot = "Parler à Keldran à Orgrimmar.", st = "Tenez-vous tranquille, $c, et permettez-moi de partager avec vous quelque chose d'important pour notre peuple, mais loin d'être évident.$b$bNous sommes une race fière, et la guerre contre les humains a mis à rude épreuve même la grande patience de Thrall. Vous voyez, notre Chef de guerre est sage et prudent, et il continue à placer son peuple en premier. Il est, en fin de compte, un diplomate, et le temps qu'il a passé avec les humains lui a appris leur façon d'être.$b$bSi l'histoire que je viens de commencer éveille votre intérêt, alors trouvez Keldran près de la sortie ouest de la ville. Sa masure s'y trouve.", t = "Les relations de l'Alliance"},
    [1442] = {t = "À la recherche de la gemme de Kor"},
    [1470] = {ot = "Apporter 3 Crânes de Cliquethorax à Venya Marthand.", st = "Salutations, enfant. Je peux voir que vous êtes encore novice dans les arts du démoniste, le pouvoir échappant toujours à votre contrôle. Je peux aussi sentir votre désir d'apprendre.$b$bEt vous apprendrez.$b$bLa force ne réside pas dans l'ignorance. La connaissance est notre pouvoir le plus puissant. Par l'application du savoir, nous pouvons contrôler les magies et les êtres chaotiques du vide, et les soumettre à notre volonté.$b$bJe peux vous montrer comment soumettre un servant, mais d'abord vous devez m'apporter trois crânes pris sur les squelettes Cliquethorax qui rôdent près de la forge abandonnée.", t = "Lever le voile"},
    [1471] = {ot = "Utiliser les Runes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Runes d’invocation à Carendin Halgar, au Temple des Damnés.", st = "Vous avez sûrement vu le cercle d'invocation en dessous. C'est le seul endroit d’où vous pourrez tirer un marcheur du Vide libre.$b$bEn utilisant ces runes, vous pourrez l'attirer ici. Vous devrez alors le dominer par la force des armes et de la magie. Lorsqu'il sera assujetti, il sera lié à vous. Venez alors me voir, et je vous expliquerai le sort d'invocation, pour que vous puissiez vous en servir, pour quelque objectif que ce soit.", t = "Le lien"},
    [1473] = {ot = "Retrouver le Grimoire d'Egalin et l'apporter à Carendin Halgar au Temple des damnés.", st = "Il semble acquis que vous êtes $gprêt:prête; à apprendre à invoquer un marcheur du Vide.$b$bUn être créé par le chaos qui l'entoure. Si vous en invoquez un, mais que vous ne pouvez pas le contrôler, vous serez $gannihilé:annihilée;.$b$bLe premier marcheur du Vide a été invoqué par Egalin, et le procédé est expliqué dans son grimoire.$b$bMalheureusement, il nous a été volé par un agent de la Croisade écarlate, qui l'a caché dans sa base, dans une tour de l'ouest. Rapportez-le-moi, et je vous transmettrai cette connaissance.", t = "La créature du Vide"},
    [1478] = {ot = "Parler à Carendin Halgar à Fossoyeuse.", st = "Ah, $n ! Je viens juste de recevoir un mot de Carendin Halgar disant qu'il voulait vous voir pour continuer l'entraînement.$b$bVous devriez être $gfier:fière; de vous, $n. Ce n'est pas tous les jours que Maître Halgar daigne instruire personnellement un jeune démoniste.$b$bVous le trouverez dans le Quartier de la magie à Fossoyeuse, près du Temple des damnés.", t = "Les invocations de Halgar"},
    [1483] = {ot = "Parler à Ziz Fizziks dans la Combe des Cisailles.", st = "La KapitalRisk a détourné un grand nombre de savants gobelins, mais de temps en temps, nous avons l’occasion de les leur reprendre.$b$bIl y a quelque temps, l'équipe de la KapitalRisk des Serres-Rocheuses a embauché Gerenzo Wrenchwhistle. Un gnome ! Leur autre ingénieur, Ziz Fizziks, en a été tellement dégoûté qu'il a essayé de trouver un nouveau travail auprès du Syndicat des Artisans. Je lui ai confié quelques travaux à faire, mais il a peut-être besoin de renfort.$b$bPeut-être que vous pourriez voir ça pour moi ? On peut le trouver à la lisière ouest de la combe des Cisailles.", t = "Ziz Fizziks"},
    [1485] = {ot = "Apporter 6 Têtes de vils quasits à Ruzan.", st = "Ces démonistes qui sont passés avant nous ont engendré la méfiance parmi la Horde, et bien que nous soyons tolérés, nous ne sommes pas aimés.$b$bCela n'a pas poussé les démonistes à s’unir pour autant, et beaucoup choisissent de vivre reclus, marinant seuls dans leur magie. Je ne vais pas tenter de vous faire choisir un chemin ou l'autre, mais seulement vous aider pendant votre progression.$b$bAvant que je vous apprenne l'art de l'Invocation, apportez-moi six têtes de vils quasits. Vous en trouverez dans la grotte au nord-est.", t = "Les vils quasits"},
    [1486] = {ot = "Napalk dans les Cavernes des lamentations veut 20 Peaux communes.", st = "Tandis que Naralex s'enfonçait toujours plus profondément dans son cauchemar, des bêtes étranges émergèrent de sous les Tarides, jusqu'aux Cavernes des lamentations.$b$bCes créatures perverties possèdent des propriétés étranges, comme venues d'un autre monde. Bien qu'elles soient maléfiques de nature, je pense qu’il y a des avantages à tirer de leur présence ici. Leur peau peut certainement être travaillée.$b$bSi vous vous considérez à la hauteur, partez dans les cavernes, en dessous, et trouvez des écailles communes.", t = "Les peaux communes"},
    [1487] = {ot = "Ebru, des Cavernes des lamentations, veut que vous tuiez 7 Ravageurs Déviant, 7 Vipères Déviant, 7 Glacials Déviant et 7 Crocs-d'effroi Déviant.", st = "Naralex poursuivait un noble but.$b$bNotre grand chef aspirait à entrer dans le Rêve d'émeraude pour faire reverdir ces terres arides, qui étaient autrefois une forêt luxuriante. Mais quelque chose s'est mal passé.$b$bLe rêve de Naralex s'est transformé en cauchemar et des créatures perverties ont commencé à envahir les cavernes.$b$bDes Disciples de Naralex tentent de le réveiller, mais mon souci est de débarrasser les cavernes de ces bêtes maléfiques.$b$bBravez les cavernes, $n, et éradiquez cette vermine étrangère.", t = "L'éradication des Déviants"},
    [1489] = {ot = "Parler à Hamuul Runetotem.", st = "Les carapaces que vous m'avez apportées portent une souillure que je n'ai jamais vue auparavant. Je pense que l'eau des oasis en est la cause, et je peux ressentir le désordre qu'ils causent à cette terre. C'est comme si la terre rêvait et ne pouvait s'éveiller.$b$bLes Cavernes des lamentations doivent être à l’origine de cette souillure. Mais avant de vous y rendre, allez parler à Hamuul Runetotem, le druide ancien. Je lui ai envoyé un message décrivant les événements dans les Tarides. C'est un sage, et il peut vous donner de bons conseils.$b$bVous le trouverez à Thunder Bluff, sur la Cime des Anciens.", t = "Hamuul Runetotem"},
    [1490] = {ot = "Parler à Nara Wildmane.", st = "J'ai pénétré sur la terre des rêves et j’ai vu un groupe de druides dans les Cavernes des lamentations. J'ai vu qu’autrefois leurs buts étaient nobles, mais qu'ils ont perdu le chemin depuis. Ils sont à présent serviteurs de la souillure qui sourd dans les Tarides.$b$bJe ne suis plus jeune et les forces me manquent. Je ne pourrai pas rester plus longtemps sur cette terre des rêves pour en apprendre davantage sur ces druides souillés. Mais Nara est jeune et son esprit est féroce. Elle est restée à rêver tandis que je me retirais.$b$bParlez-lui. Elle est dans la tente, là-bas.", t = "Nara Wildmane"},
    [1491] = {t = "Les potions d'intelligence"},
    [1492] = {ot = "Apporter la Caisse sûre au Maître des quais Dizzywig à Ratchet.", st = "J'ai besoin d'envoyer une caisse de potions, de réactifs et d’objets divers à mes associés dans l'Ancien Monde. J'ai en fait assez peu de temps et je ne peux pas vérifier moi-même qu'elle est bien embarquée aux docks de Ratchet. De plus, la dernière caravane est déjà partie.$b$bSi vous pouvez, apportez-la au Maître des quais Dizzywig. Il veillera à ce qu'elle soit chargée sur le prochain bateau en partance pour la crique des Flots noirs.", t = "Maître des quais Dizzywig"},
    [1499] = {ot = "Parler à Zureetha Fargaze.", st = "Zureetha envoie des novices comme vous réduire le nombre des créatures de la caverne près de laquelle vous avez combattu les vils quasits.$b$bJe pense qu'il serait bon pour vous de l'aider et ainsi de gagner de l'expérience. Dites-lui également que vous avez participé à la résolution du problème posé par ces diablotins, elle aura probablement une récompense pour vous.", t = "Les vils quasits"},
    [1501] = {ot = "Récupérer la Tablette de Verga pour Gan'rul Bloodeye à Orgrimmar.", st = "Il reste si peu de démonistes… Nous risquons beaucoup, mais cela en vaut la peine. Vous devez rapidement atteindre la pleine possession de vos capacités pour être utile à la Horde et au Chef de guerre.$b$bIl est temps pour vous d'apprendre un nouveau sort d'invocation.$b$bD'abord, vous devez récupérer la Tablette de Verga, qui a été volée par des démonistes de la Lame ardente et qui est à présent détenue dans leur antre du Rocher du crâne à l'est de la ville. Une fois que j'aurai la tablette, je vous montrerai les runes nécessaires à l'invocation d'un marcheur du Vide.", t = "La créature du Vide"},
    [1504] = {ot = "Utiliser les Glyphes d'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Glyphes d'invocation à Gan'rul Bloodeye, à Orgrimmar.", st = "À présent, observez la Tablette de Verga, car elle contient les glyphes nécessaires à l'invocation. Apportez-les au cercle sous la tente de Neeru Fireblade de l'autre côté de la grotte. Vous serez alors capable d'invoquer un marcheur du Vide.$b$bVous devez le battre en utilisant tous les moyens physiques et magiques que vous avez à votre disposition. Une fois qu'il sera battu, revenez me voir avec les glyphes d'invocation et je vous apprendrai comment soumettre la créature.", t = "Le lien"},
    [1506] = {t = "Les invocations de Gan'rul"},
    [1507] = {t = "La dévoreuse d'âmes"},
    [1508] = {ot = "Parler à Zankaja à Orgrimmar.", st = "Si Gan’rul vous envoie, ce doit être parce que vous devez invoquer une succube, une femelle de l’espèce des Sayaads, et qu’il vous faut de quoi la séduire.\n\nHmm… si vous acceptez de faire confiance à un aveugle, $n, alors écoutez-moi. Zankaja vit à l’ouest de la tour des Cavaliers célestes, dans les hauteurs d’Orgrimmar. Elle attend le retour de son compagnon.\n\nAllez la voir.", t = "Cazul l'aveugle"},
    [1509] = {ot = "Parler à Gazrog à la Croisée.", st = "Mon compagnon, Dogran, a été récemment envoyé à la Croisée pour y accomplir son devoir. Il avait obtenu une promotion, et il était très fier.$b$bMoi, j'étais triste, mais je n'en ai rien laissé paraître. Et j'étais inquiète, aussi. Les Tarides sont une région bien plus dangereuse qu'Orgrimmar, et je craignais le pire.$b$bÀ présent, cela fait une semaine qu'il aurait dû renter, et je n'ai toujours reçu aucune nouvelle...$b$bPeut-être pourriez-vous vous rendre à la Croisée et voir s'ils ont des nouvelles de lui ? Il travaillait avec Gazrog, qui devrait toujours y être assigné.", t = "Des nouvelles de Dogran"},
    [1510] = {ot = "Parler à Ken'zigla, au village de Malaka'jin.", st = "Il était en poste au Camp Taurajo, où nous essayions de nous débarrasser des hurans. Il a dirigé quelques grunts sur l'un de leurs campements, mais il a été alors grièvement blessé. Les autres sont revenus et ont essayé de lui porter secours. Mais il allait très mal, ses blessures saignaient et ils hésitaient à le déplacer avant de le panser correctement.$B$BIls ont envoyé un message ici, demandant un breuvage de soin des trolls de Malaka'jin, au pied des Serres-Rocheuses. Nous avons envoyé quelqu'un pour le chercher, mais personne n'est encore revenu.", t = "Des nouvelles de Dogran"},
    [1511] = {t = "Breuvage de Ken'zigla"},
    [1512] = {ot = "Rapporter le Pendentif de poussière à Gan'rul Bloodeye à Orgrimmar.", st = "Zankaja est jeune et belle. Etre enchaînée à un invalide… Je ne permettrai pas qu'elle souffre de cette injustice.$b$bLaissez-moi, $n. Et merci. Je peux ainsi terminer ma vie dans une glorieuse bataille, et non comme un légume.$b$bEt je vous en prie, je souhaiterais que vous ne disiez rien à ma compagne... Je ne veux pas quelle se sente coupable.", t = "Le cadeau de l'amour"},
    [1513] = {ot = "Utiliser le Pendentif de Dogran pour invoquer et soumettre une succube, puis rapporter le Pendentif de Dogran à Gan'rul Bloodeye, à Orgrimmar.", st = "Apportez cela au cercle d'invocation dans la tente de Neeru, $n. Invoquez une ignoble succube, et dominez-la. Comme toujours cependant, soyez $gprudent:prudente;, car la fierté et une trop grande confiance en soi ont terrassé de nombreux démonistes prometteurs.$b$bUne fois que vous l'aurez vaincue, venez me rendre le pendentif, pour que je puisse donner des nouvelles à Zankaja.", t = "Le lien"},
    [1515] = {ot = "Apporter le Breuvage de Ken'zigla à Dogran dans les Tarides.", st = "Vous êtes $garrivé:arrivée; jusque-là, alors si vous voulez voir la fin, je ne vais pas vous arrêter. Cependant, je ne peux pas vous fournir de forces supplémentaires, vous êtes $gseul:seule;.$b$bDogran est prisonnier dans un camp de hurans au nord d'ici. Cherchez une paire de huttes. Il sera surveillé de près... À condition qu’ils ne l'aient pas encore tué et qu’il n’ait pas succombé à ses blessures.$b$bBonne chance.", t = "La captivité de Dogran"},
    [1516] = {ot = "Apporter 2 Sabots de traqueur corrompu à Canaga Earthcaller dans la Vallée des épreuves.", st = "Le temps est venu, jeune $c. Vous êtes $gdevenu plus fort:devenue plus forte; et votre esprit est aussi endurant que la terre. Votre choix de suivre la voie du chaman montre votre sagesse, avant même de devoir faire vos preuves.$b$bL'élément de la terre guidera votre destinée, et fera partie intégrante de votre être, si vous y êtes $gprêt:prête;. Mais vous devez vous présenter devant la terre elle-même. Si vous êtes $gprêt:prête;, vous verrez des choses dont seuls les chamans ont connaissance.$b$bCherchez les traqueurs corrompus au nord, et prenez-leur deux de leurs sabots. Revenez alors me voir, et nous parlerons de votre avenir.", t = "L'appel de la terre"},
    [1517] = {ot = "Trouver le Rocher des esprits et boire le Sapta de terre.", st = "Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits forts de percevoir les éléments comme nul autre ne le peut. Votre esprit contactera l'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.$b$bIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs, ne l’oubliez pas.$b$bCherchez le rocher des esprits au sud-ouest d'ici, au bout du chemin secret. Buvez-y votre sapta et... et vous verrez.", t = "L'appel de la terre"},
    [1518] = {ot = "Apporter le Quartz brut à Canaga Earthcaller dans la Vallée des épreuves.", st = "Prenez ce quartz brut et apportez-le à Canaga Earthcaller. Il attestera de notre rencontre. Il créera un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre à bien d'autres.$b$bSoyez $gpatient:patiente;, $n. Restez $gfort:forte;. Et recherchez la sagesse. C'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu'un avec elle. Respectez-la comme elle vous respecte.", t = "L'appel de la terre"},
    [1519] = {ot = "Apporter 2 Applications de Baume rituel au Prophète Ravenfeather au Camp Narache.", st = "Il est temps à présent, jeune $c. Votre corps s’est aguerri et votre esprit est aussi endurant que la terre. Je le vois, vous possédez déjà la sagesse.$B$BLa terre guide notre peuple, et nous parle, de la même manière qu'elle vous parlera lorsque le temps sera venu. Mais vous devez être $gmis à l'épreuve:mise à l'épreuve;. Si vous êtes $gprêt:prête;, alors vous verrez des choses que nous seuls connaissons.$B$BPartez à la recherche des chamans Dos-hirsute dans leur ravin à l'est, et procurez-vous le baume qu'ils utilisent lors de leurs rituels. Ne revenez me voir que lorsque vous en aurez suffisamment pour votre propre potion.", t = "L'appel de la terre"},
    [1520] = {ot = "Trouver le Rocher des kodos et boire le Sapta de terre.", st = "Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits ouverts de voir les éléments comme personne d’autre ne peut les voir. Votre esprit sera lié à jamais à l'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.$b$bIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs.$b$bCherchez l'autel du chaman à l'est d'ici et buvez-y le sapta.", t = "L'appel de la terre"},
    [1521] = {ot = "Apporter le Quartz brut à la prophétesse Ravenfeather au Camp Narache.", st = "Prenez ce quartz brut et apportez-le à la prophétesse Ravenfeather. Il attestera de notre rencontre. Elle concevra un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre aux montagnes.$b$bSoyez $gpatient:patiente;, $n. Restez $gfort: forte;. Et recherchez la sagesse. C'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu'un avec elle. Respectez-la comme elle vous respecte.", t = "L'appel de la terre"},
    [1524] = {ot = "Apporter la Torche de la flamme dormante à Telf Joolam en Durotar.", st = "Vous êtes suffisamment $gpuissant:puissante; pour manier le totem de feu, mais cela ne signifie pas que vous êtes $gprêt:prête;.$b$bLe long de la Furie-du-Sud en Durotar, avant la Grande Mer, se trouve un sentier caché menant aux hauteurs les plus élevées de cette terre. Trouvez le chemin menant au sommet et vous découvrirez l'un de nos autels sacrés, surveillé par Telf Joolam : l'Autel de la flamme dormante.$b$bApportez-lui cette torche, cela voudra dire que vous tentez d'apprivoiser le feu. Rapportez-la-moi lorsqu'elle sera enflammée au brasero de l’autel et je veillerai à ce que le totem de feu vous soit remis.", t = "L'appel du feu"},
    [1525] = {ot = "Apporter 1 Goudron de feu et 1 Bourse de réactifs à Telf Joolam en Durotar.", st = "Mais vous n'êtes pas là pour recevoir un cours d'histoire, n'est-ce pas ? Vous êtes $gvenu:venue; pour la flamme éternelle et le totem de feu.$B$BLa première étape consiste à créer un sapta et à vous lier à la flamme.$B$BJe peux m'en occuper si vous m'apportez deux choses. La première est du goudron de feu, un objet simple à se procurer et généralement porté par les lanceurs de sorts Tranchecrin dans les Tarides de l'est.$B$BIl sera plus dangereux de se procurer la seconde : une bourse de réactifs que vous trouverez sur l'un des sectateurs de la Lame ardente. Ils sont dans une caverne au-dessus des ravins, au nord-est de Tranchecolline.", t = "L'appel du feu"},
    [1526] = {ot = "Vaincre la Manifestation de feu mineure, et placer sa Braise rougeoyante dans le brasero, en haut de l'Autel de la flamme éternelle.", st = "Le sapta de feu est terminé. Il est temps pour vous de vous confronter à la flamme. Utilisez le sapta à l'autel et rendez-vous au sommet de la montagne pour affronter la manifestation. Elle n'attaquera pas tant que vous ne serez pas $gprêt:prête;, mais elle sait que vous pouvez la voir.$b$bFrappez bien, et frappez vite, $n, car sa puissance grandira si vous tardez à la tuer. Quand vous l'aurez vaincue, placez ses braises dans le brasero et allumez la torche.", t = "L'appel du feu"},
    [1527] = {ot = "Apporter la Torche de la flamme éternelle à Kranal Fiss dans les Tarides.", st = "Tenant fermement la torche, vous vous détournez du brasero et embrassez Durotar du regard. Vous sentez la fièvre battre dans votre esprit tandis que le vent avive les flammes qui dansent furieusement.$b$bVous prenez le chemin du retour vers les Tarides, pour trouver Kranal Fiss.", t = "L'appel du feu"},
    [1530] = {ot = "Trouver Brine dans les Tarides du sud.", st = "S'il y a une leçon à apprendre de l'eau, la voici : l'eau est la renaissance.$b$bSon pouvoir coule, érode et rend propre toute chose. Ses propriétés de guérison et de ressourcement sont incomparables, mais seulement lorsqu'elle est pure.$b$bLorsque vous comprendrez que l'eau, quand elle est polluée, peut dévaster tout ce qu'elle touche, vous apprécierez à quel point cette ressource est vitale.$b$bSi vous souhaitez le sapta de l’eau, trouvez Brine loin dans les Tarides du sud. Sa maison est constamment la cible des hurans.", t = "L'appel de l'eau"},
    [1531] = {ot = "Trouver Prate Cloudseer aux Mille pointes.", st = "Y faut que vous y alliez, là. Préparez-vous à montrer qu'vous êtes digne de r'cevoir vot' totem d'air. Mais déjà, vous d'vez trouver Prate Cloudseer aux Mille pointes. Elle vous dira comment obtenir vot' totem d'air.$b$bPassez au sud par les Tarides, puis aux Mille pointes, à l'est. Vous la trouverez cachée dans un trou, avec son p'tit copain. Haha, ne lui dites pas qu'je la salue pas, elle aimerait pas trop.", t = "L'appel de l'air"},
    [1534] = {ot = "Remplir l'Outre bleue vide aux Ruines de Chimétoile à Ashenvale et la rapporter à Brine dans les Tarides.", st = "Prenez cette outre et enfoncez-vous au cœur de la forêt luxuriante que les elfes de la nuit appellent Ashenvale. C'est à l'extrême nord des Tarides.$b$bUne fois dans la forêt, allez à l'ouest. Le long des montagnes qui séparent les Serres-Rocheuses d'Ashenvale, au-delà du lac Mystral, vous trouverez un lieu sacré : les ruines de Chimétoile. Une petite fontaine jaillit au centre du lac.$b$bApportez-moi un échantillon de l'eau de cette fontaine. Ce sera le dernier ingrédient que vous devez obtenir avant que je ne vous renvoie à Islen.", t = "L'appel de l'eau"},
    [1535] = {ot = "Remplir l'Outre marron vide au trou d’eau, derrière la hutte de Brine, puis rapportez-lui la, dans les Tarides.", st = "Pour trouver la compréhension et obtenir le sapta, vous devez trouver les eaux les plus pures. Tandis que vous rassemblerez les échantillons pour moi, observez les lieux qui vous entourent. Soyez $gattentif:attentive; aux créatures qui ont besoin d'eau, et qui la protègent. Voyez comment elle affecte les forêts et les déserts. Soyez témoin de la manière dont la substance même qui maintient la vie force les créatures à ôter la vie.$b$bNous commencerons par une tâche simple : en bas de ma hutte, vous trouverez un bassin de ce précieux liquide. Remplissez-en cette outre et revenez me voir.", t = "L'appel de l'eau"},
    [1536] = {ot = "Remplir l'Outre rouge vide au puits de Moulin-de-Tarren et retourner voir Brine dans les Tarides.", st = "Il y a longtemps, j'ai suivi quelques compagnons jusqu'aux contreforts d'Hillsbrad. Nous nous sommes défendus contre des humains tenaces qui s'y sont établis et nous nous sommes retrouvés dans une petite ville occupée par les Réprouvés : Moulin-de-Tarren.$b$bC'est là que j'ai découvert une chose des plus étranges : en pleine ville, un petit puits offrait une belle eau fraîche. Je ne crois même pas que ces pestiférés comprennent sa valeur. C'est une goutte de pureté au cœur d’une mer de malédiction.$b$bRemplissez cette outre avec cette eau et rapportez-la-moi.", t = "L'appel de l'eau"},
    [1578] = {ot = "Apporter 6 Haches en cuivre et 6 Ceintures en anneaux de cuivre à Thorvald dans la Tour de garde méridionale du Loch Modan.", st = "Les montagnards de Loch Modan combattent les troggs, et cela les occupe beaucoup. Ils ont constamment besoin d'être approvisionnés en armures et en nouvelles armes.$b$bC'est pourquoi mon collègue Thorvald est ici, pour maintenir l'équipement des montagnards en bon état. Aussi, si vous pouviez fabriquer des haches en cuivre et des ceintures en anneaux de cuivre, puis les apporter à Thorvald, il vous en serait reconnaissant. Il se peut même qu'il partage une partie de son savoir avec vous.$b$bThorvald est basé dans la tour de garde méridionale de Loch Modan.", t = "Rééquiper le front"},
    [1579] = {ot = "Apporter 8 Rouages électriques à Wizbang Cranktoggle à Auberdine.", st = "Je suis venu à Auberdine parce que c'est calme. Je veux créer dans le calme. Forgefer est décidément trop bruyante après une nuit passée à boire !$b$bAlors j'ai pris un bateau pour Auberdine et j’ai bu un petit peu trop pendant le voyage. J'ai laissé tomber ma boîte de rouages électriques par-dessus bord ! J'en ai besoin !$b$bJe ne sais pas exactement où je l’ai laissée tomber, mais si vous pêchez quelque part dans l'océan, il se peut que vous ayez de la chance...", t = "Rouages électriques"},
    [1580] = {ot = "Apporter 12 Electropellers à Wizbang Cranktoggle à Auberdine.", st = "Nous savons que vous êtes $gchanceux:chanceuse;, mais à quel point l'êtes-vous vraiment, $n ?$b$bUne nuit, je marchais sur les routes de Sombrivage. J'essayais de trouver une bonne rivière ou un bon lac pour tester mon nouvel appeau à canard explosif et à propulsion automatique, et je pense que j'étais un peu... parti. Je me suis endormi et je me suis réveillé des heures plus tard à Auberdine. Mes cheveux étaient roussis et je ne trouvais plus mon sac d'Electropellers ! J'avais dû le laisser tomber dans l'eau !$b$bIl me faut ces Electropellers ! Peut-être pourriez-vous les pêcher quelque part dans un lac ou dans un cours d'eau quelconque à Sombrivage...", t = "Pêche aux Electropellers"},
    [1581] = {ot = "Apporter 6 Elixirs de force du lion et 2 Elixirs de défense mineure à Syral Bladeleaf à Dolanaar.", st = "Notre magasin d'herbes et d'alchimie est un succès, mais mon mari passe tellement de temps à préparer ses potions qu'il ne nous en reste plus pour nous deux.$b$bPouvez-vous nous aider ?$b$bSi vous m'apportiez une provision d'élixirs déjà faits, alors je serais heureuse de commercer avec vous. J'ai ici quelques herbes rares qui pourraient vous intéresser.", t = "Les élixirs pour les Bladeleaf"},
    [1598] = {t = "Le Tome dérobé"},
    [1599] = {ot = "Apporter 3 Charmes de plume à Alamar Grimm à Courbenclume.", st = "Vous devez être $gle nouveau:la nouvelle; démoniste dont tout le monde parle. Quelqu'un doit vous apprécier pour qu’on m'arrache à mes recherches et me demande de vous enseigner.$b$bNe vous inquiétez pas, je vais vous consacrer du temps.$b$bLe plus simple des sorts d'invocation est celui du diablotin. Mais avant que je vous le livre, vous devez prouver que vous avez les capacités physiques et mentales nécessaires.$b$bApportez-moi trois Charmes de plume que portent les novices Frostmane de la caverne au sud-ouest.", t = "Les débuts"},
    [1618] = {ot = "Tormus Deepforge veut que vous apportiez 4 Ceintures runiques en cuivre et 4 Grands maillets en cuivre à Verner Osgood, dans les Carmines.", st = "Nous les nains ne sommes pas les seuls à nous battre. Nos alliés humains sont très occupés également.$b$bLes Carmines subissent régulièrement des attaques des orcs rochenoires, et leur réserve d'équipement est constamment très basse. Si vous vouliez leur venir en aide, je suis sûr que leur forgeron permanent, Verner Osgood, vous apprendrait un ou deux trucs.", t = "Le rééquipement des Carmines"},
    [1638] = {t = "L'entraînement du guerrier"},
    [1639] = {t = "Bartleby le poivrot"},
    [1640] = {ot = "Battre Bartleby, puis lui parler.", st = "Vous voulez quoi ? Vous êtes $gfou:folle; !$b$bLa seule façon pour vous d'obtenir cette chope serait de la prendre entre mes doigts froids et morts…", t = "Battre Bartleby"},
    [1641] = {t = "Le Tome de divinité"},
    [1642] = {ot = "Parler à Duthorian Rall à Stormwind.", st = "En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.$b$bBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c'est en aidant les autres que vous vous démarquerez véritablement des citoyens d'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.$b$bPrenez-en conscience, et ne l'oubliez pas.", t = "Le Tome de divinité"},
    [1643] = {ot = "Chercher Stephanie Turner dans le Quartier commerçant de Stormwind.", st = "Votre tâche, à présent, $n, est de trouver quelqu'un ici, à Stormwind, qui a besoin de votre aide. Quelqu'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu'un ayant besoin d'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.$b$bAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière.", t = "Le Tome de divinité"},
    [1644] = {ot = "Apporter 10 morceaux d'étoffe de lin à Stephanie Turner à Stormwind.", st = "Qu’ils soient bénis. La plupart ont perdu leur famille dans les attaques du Fléau, ces dernières années.$B$BMon mari, John, collecte des matériaux qui me servent à confectionner des chemises et des pantalons pour les enfants, ce que je n’ai malheureusement pas eu le temps de faire dernièrement.$B$BMais peut-être voudriez-vous m'aider ? Oh, merci mille fois, $n.$B$BSi vous pouviez m’apporter de l’étoffe de lin pour que je puisse en faire des vêtements pour les enfants, je vous en serai reconnaissante.", t = "Le Tome de divinité"},
    [1645] = {t = "Le Tome de divinité"},
    [1646] = {ot = "Parler à Tiza Battleforge à Forgefer.", st = "En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.$b$bBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c'est en aidant les autres que vous vous démarquerez véritablement des citoyens d'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.$b$bPrenez-en conscience, et ne l'oubliez pas.", t = "Le Tome de divinité"},
    [1647] = {ot = "Chercher John Turner à la périphérie de Forgefer.", st = "Votre tâche, $n, consiste à trouver quelqu'un ici à Forgefer qui ait besoin d'aide. Quelqu'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu'un ayant besoin d'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.$b$bAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière. Je resterai ici, au temple, dans l'attente de votre retour. D'autres paladins auront besoin que je les guide, également.", t = "Le Tome de divinité"},
    [1648] = {ot = "Apporter 10 morceaux d'étoffe de lin à John Turner à Forgefer.", st = "Ma femme et moi nous nous occupons d'un orphelinat à Stormwind, principalement pour des enfants qui ont perdu leurs parents au cours des attaques du Fléau cette dernière décennie. Je passe à Forgefer à peu près tous les mois afin de collecter des vivres offerts par des citoyens d’ici, et j’essaie de convaincre certaines associations de soutenir notre action vis-à-vis des enfants.$b$bCe voyage a été horriblement lent, et pas très productif.$b$bSi je pouvais simplement trouver des pièces de lin pour que ma femme puisse coudre quelques vêtements, je pourrais enfin envoyer quelque chose à la maison.", t = "Le Tome de divinité"},
    [1649] = {ot = "Parler à Duthorian Rall à Stormwind.", st = "La bravoure et toutes les vertus qui vont avec sont comme les minerais rares : pour leur valeur vous devez les chérir, mais vous devez aussi prendre le temps de les entretenir, de les polir. Quand vous les associez judicieusement, vous obtenez un alliage résistant, qui peut résister même aux coups les plus violents.$B$BCette force, votre foi, votre bravoure doivent être éprouvées. Vous devez apprendre à ne jamais perdre la foi et comprendre qu'avec le pouvoir de la Lumière à vos côtés, vous pourrez surmonter plus d’obstacles que la plupart des gens.", t = "Le Tome de la bravoure"},
    [1650] = {t = "Le Tome de la bravoure"},
    [1651] = {ot = "Défendez Daphne Stilwell contre les attaques des Défias.$B$BAucun de vous deux ne doit mourir, si vous voulez réussir la quête.$B$BQuand vous aurez réussi, reparlez à Daphne Stilwell.", st = "Je suis sûre qu'ils seront là dans peu de temps maintenant, préparez-vous.$B$BJ'ai une arme à la maison. Je vais la chercher et je reviens vous donner un coup de main, mais vous allez devoir faire le plus gros du travail j'en ai peur.$B$BJe n'ai aucune idée de leur nombre, mais pour sûr ils seront plus nombreux que la dernière fois.$B$BPriez la Lumière de vous accorder ses faveurs parce que... Vous avez entendu ça ? Je pense qu'ils arrivent.$B$BNous allons nous replier près de la maison !", t = "Le Tome de la bravoure"},
    [1652] = {t = "Le Tome de la bravoure"},
    [1653] = {ot = "Parler à Jordan Stilwell à Forgefer", st = "Je pense que Jordan voudra vous remercier lui-même, et comme j'ai besoin de quelqu'un pour lui porter le message disant que sa femme est en sécurité, ce serait bien que vous le lui apportiez.$B$BJordan a été un paladin de la Lumière avant que son dévouement au métier de son père le fasse changer de voie. Il connaît nos coutumes et il est considéré parmi nos meilleurs fidèles.$B$BIl doit être encore à Forgefer. Dans la journée, il aime travailler hors de l'enceinte de la ville, sans doute pour profiter du grand air de la montagne.", t = "Le test de droiture"},
    [1654] = {ot = "Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Forgefer.", st = "J'aimerais vous récompenser, si vous voulez bien l'accepter ? Ne vous y trompez pas, ma générosité sera tributaire de votre contribution, mais je sens que cette association sera bénéfique pour nous deux.$B$BJe vous fabriquerai une arme à la hauteur de vos actions, un symbole des paladins et de la Lumière, mais vous devez me procurer les composants dont j'ai besoin pour la forger. J'ai déjà fait la liste de ce qui est nécessaire, il manquait juste une personne de qualité comme vous pour me les procurer. Qu'en pensez-vous, $c ?", t = "Le test de droiture"},
    [1656] = {ot = "Livrer le Ballot de fourrures à l'aubergiste Kauth à Sabot-de-Sang.", st = "$n, s'il vous plaît, je vous en supplie, pouvez-vous m'aider ? Je n'ai pas fini ce que j'ai à faire ici sur le Plateau – je suis au milieu de mon rite de force – et mon père veut que je livre ces fourrures à l'auberge de Sabot-de-Sang.$B$BJe ne suis pas suffisamment reposée pour finir mon rite et faire ce que mon père m'a demandé. Cela vous embêterait-il d'y aller pour moi ?$B$BL'auberge est agréable et c'est l'endroit parfait pour se reposer après un long voyage. Vous en conviendrez lorsque vous l'aurez vue.", t = "Une tâche inachevée"},
    [1665] = {t = "Tasse de Bartleby"},
    [1680] = {ot = "Parler à Tormus Deepforge.", st = "Maintenant que vous avez appris de nouvelles passes, il est temps pour vous d'avoir une arme digne de ce nom. Parlez à Tormus Deepforge. Il peut vous fabriquer une arme dont vous me donnerez des nouvelles.$B$BVous trouverez Tormus ici, à Forgefer, à la Grande Forge.", t = "Tormus Deepforge"},
    [1683] = {ot = "Rapporter la Corne de Vorlus Vilehoof à Elanaria à Darnassus.", st = "Avant de vous apprendre quoi que ce soit, vous devez me prouver votre résolution.$B$BLe satyre Vorlus Vilehoof a découvert un de nos lointains Puits de lune, au sud-est du Refuge des saisons de Ban'ethil. Il est en train d’y barboter, souillant l'eau pure avec sa crasse.$B$BTrouvez Vorlus au Puits de lune et détruisez-le. Ramenez-moi sa corne comme preuve, et je vous entraînerais.$B$BLe chemin vers le Puits de lune est bien caché, $n, restez $gconcentré:concentrée; et alerte, et vous le trouverez.", t = "Vorlus Vilehoof"},
    [1684] = {t = "Elanaria"},
    [1685] = {t = "Convocation de Gakin"},
    [1688] = {ot = "Retrouver l’Écharpe de Surena pour Gakin le Tisse-noir à Stormwind.", st = "J'ai eu une étudiante du nom de Surena Caledon. Elle était là où vous êtes en ce moment, enthousiaste à apprendre la magie des démonistes, et talentueuse. En plus, elle était jeune et belle. Quand j'y repense, quelle traînée !$b$bCette voleuse s'est enfuie avec un Defias, Erlan Drudgemoor. Sa perte est négligeable, mais je lui avais offert une Echarpe de Pierre de sang que je veux absolument récupérer.$b$bSa vie m'importe peu maintenant. Vous la trouverez au Champ de Potirons des Brackwell. Rapportez-moi ce qui m'appartient.", t = "Surena Caledon"},
    [1689] = {ot = "Utiliser l’Echarpe de Pierre de sang pour invoquer et soumettre un marcheur du Vide, puis la rapporter à Gakin le Tisse-noir, à Stormwind.", st = "En retrouvant mon écharpe et en éliminant Surena, vous avez prouvé que vous étiez au moins aussi $gtalentueux:talentueuse; qu'elle.$b$bCela dit, vous avez terriblement besoin d'entraînement. Vous pouvez manier les flux magiques, bien sûr, mais être démoniste, c'est bien plus que cela.$b$bJe vais vous montrer comment contrôler un marcheur du Vide, mais avant, vous devez en invoquer un dans le cercle d'invocation et le maîtriser avec les armes – physiques et magiques – dont vous disposez. Utilisez la magie que contient l'écharpe sur le cercle d'invocation en bas.", t = "Le lien"},
    [1699] = {ot = "Entrer dans les Cavernes de Rethban jusqu'à la première fourche, et revenir voir Barleybrew dans le temps imparti.$B$BVous ne devez pas mourir.", st = "J'ai appelé cette épreuve le \"défi de Rethban\". Pour passer l'épreuve, tout ce que vous avez à faire c'est d'entrer dans les Cavernes de Rethban, jusqu'à la première fourche. Facile ! Sauf qu'il y a certaines conditions...$B$BVous devez être de retour dans moins d'une heure.$B$BEt il y a un tas de gnolls des Carmines sur le chemin.$B$BAvant de commencer, il faut que vous preniez une lampée de ma boisson personnelle : du Barleybrew Scalder !$B$BAlors qu'en dites-vous ? Les Cavernes de Rethban sont dans les collines, au nord de Comté-du-Lac. Êtes-vous $gprêt:prête; à relever le défi de Rethban ?", t = "Le défi de Rethban"},
    [1701] = {t = "Une cotte de mailles en acier trempé"},
    [1702] = {ot = "Apporter le Tonneau de Scalder à Furen Longbeard.", st = "Vous avez montré vos talents en relevant le défi de Rethban, $n. Et je respecterai ma parole. Je vais vous donner votre récompense...$B$BSauf qu'elle est à Stormwind.$B$BParlez à mon ami, Furen Longbeard, dans le quartier des nains de Stormwind. C'est le meilleur fabriquant de boucliers que vous rencontrerez, et il me doit une faveur.$B$BTenez, apportez-lui ce tonneau de Barleybrew Scalder et demandez-lui un bouclier. Il vous en donnera un bon.", t = "Fabricant de bouclier"},
    [1716] = {ot = "Parler à Takar le Prophète dans les Tarides.", st = "Les Sayaad dévorent les âmes, dominent les esprits et séduisent sans distinction. Ils ne connaissent rien d’autre que le Mal.\n\nLa littérature grivoise les désigne par leur nom populaire, à savoir succubes pour les démons femelles et incubes pour les mâles.\n\nPour attirer une telle créature, vous allez devoir l’appâter à l’aide d’un symbole d’amour. Ensuite, vous n’aurez plus qu’à la maîtriser avant d’en faire votre esclave.\n\nIl va toutefois être difficile de vous procurer un objet de cette nature. Vous devriez parler à Takar le Prophète. Vous le trouverez dans les Tarides de Kalimdor, près du camp Taurajo.", t = "La dévoreuse d'âmes"},
    [1718] = {ot = "Parler à Klannoc Macleod.", st = "Votre renommée en tant que $gguerrier:guerrière; s'accroît, $n. Il est temps de vous mesurer à l'un de vos pairs.$B$BIl existe une île près des côtes des Tarides, au sud de Ratchet : l'île de la Dispute. Les guerriers s’y retrouvent.$B$BS’y retrouvent et s’affrontent.$B$BParlez au chef des guerriers de l'île, Klannoc Macleod. S’il pense que vous le méritez, alors il vous guidera plus avant sur la voie du guerrier.$B$BPour atteindre l'île de la Dispute, cherchez des bancs de sable à faible profondeur le long de la Côte des marchands.", t = "L'île mortelle"},
    [1719] = {ot = "Tuer le Grand Will et parler à Klannoc Macleod sur l'île de la Dispute.", st = "Si vous voulez que je sois votre Maître, vous devez d'abord passer la Dispute. C'est une épreuve que nous, sur l'île de la Dispute, aimons faire passer aux guerriers qui pensent être forts, et si vous réussissez ce test alors nous saurons que vous l'êtes.$B$BPour commencer, marchez à travers cette foule là-bas, et allez jusqu'à l'âtre. Dites à Twiggy Flathead que vous êtes $gprêt:prête;, il vous enverra des partenaires de combat.$B$BBattez-les tous, et il appellera le Grand Will. Tuez le Grand Will, et revenez me voir.", t = "La Dispute"},
    [1738] = {ot = "Trouver le Cœur du bois en Ashenvale et le porter à Gakin le Tisse-noir dans le quartier des mages de Stormwind.", st = "En prévision de votre arrivée, j'ai utilisé ma vision pour regarder à travers le monde et à travers le temps. J'ai trouvé ce que vous cherchez.$b$bLors de la guerre des Anciens, deux amoureux sont tombés ensemble lors d'une bataille. Là où ils sont morts, un arbre connu sous le nom de cœur du bois poussa, symbole de leur amour éternel.$b$bCe sera assez pour attirer une succube. Vous le trouverez dans les ruines d'Ordil'Aran, dans la partie nord-ouest de la forêt d'Ashenvale.", t = "Le cœur du bois"},
    [1739] = {ot = "Utiliser le Noyau du cœur du bois pour invoquer et soumettre une succube, puis rapporter le Noyau de cœur du bois à Gakin le Tisse-noir, à l'Agneau assassiné.", st = "En utilisant le noyau du cœur du bois, vous serez en mesure de jeter le sort dans le cercle d'invocation qui se trouve dans la crypte en bas afin d'ouvrir un portail d'où la succube arrivera.$b$bAttention, $n, les succubes arrivent à contrôler les esprits les plus forts.$b$bUne fois que vous l'aurez vaincue et renvoyée dans le néant, revenez me voir pour que je vous apprenne comment l'appeler et la contrôler.", t = "Le lien"},
    [1740] = {ot = "Trouver 3 Fragments de Soran'ruk et 1 Grand Fragment de Soran'ruk et les rapporter à Doan Karhan dans les Tarides.", st = "Quand les démons de la Légion sont tombés, leurs esprits furent emprisonnés dans des orbes et distribués à leurs mages et leurs démonistes.$b$bBeaucoup furent apportés en Azeroth par leurs serviteurs. Même fragmentés, ils gardent les pouvoirs du démon emprisonné à l'intérieur.$b$bL'orbe de Soran'ruk a été brisé en deux morceaux, l'un a été fragmenté pour être utilisé par les acolytes du Marteau du crépuscule dans les Profondeurs de Brassenoire. L'autre, le plus gros morceau, est en possession d'un sorcier dans le donjon d'Ombrecroc. Retrouvez les fragments et je pourrai réparer l'orbe.", t = "L'Orbe de Soran'ruk"},
    [1778] = {ot = "Parler à Tiza Battleforge à Forgefer.", st = "Je vais devoir rentrer chez moi le plus rapidement possible. Heureusement, Stephanie fait de même pour rentrer à Stormwind. J'ai hâte de la revoir. A bientôt, $c.", t = "Le Tome de divinité"},
    [1779] = {t = "Le Tome de divinité"},
    [1780] = {ot = "Parler à Duthorian Rall à Stormwind.", st = "J'amènerai ça aux enfants dès aujourd'hui. Merci beaucoup, $c. Il est rare de nos jours qu'$gun homme:une femme; de votre trempe se montre dans cette ville, mais vous avez prouvé que les paladins à Stormwind ne tourneront jamais le dos à ceux qui sont dans le besoin.$B$BAdieu.", t = "Le Tome de divinité"},
    [1781] = {t = "Le Tome de divinité"},
    [1783] = {ot = "Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh.", st = "J'espionnais des nains Sombrefer qui se terrent au sud du lac du Lit d'Helm. Nous savions qu'ils n'étaient pas là pour rien, alors Narm et moi nous nous sommes rapprochés – assez près pour voir leur chef donner des ordres à ses hommes.$B$BNarm et moi nous avons tenté d'en tuer quelques-uns, mais ils se sont révélés plus résistants que nous le pensions, et beaucoup plus nombreux. Narm m'a dit de partir et de ramener du renfort, donc voilà pourquoi je suis là.$B$BNarm a besoin d'aide, et je ne me reposerai pas tant qu'il n'en n'aura pas trouvé.$B$BAllez-vous m'aider, $n ?", t = "Le Tome de divinité"},
    [1784] = {ot = "Récupérer un Script des nains Sombrefer près du lac du Lit d'Helm et le rapporter à Muiredon Battleforge à Forgefer.", st = "Avant de tomber, Muiredon et moi avions presque vaincu un des espions Sombrefer près de cette petite maison. Nous avons vu le capitaine leur passer des ordres, et nous avons cherché à le tuer pour récupérer ces ordres.$B$BCertaines personnes au conseil de Forgefer ne croient pas à la présence des Sombrefer à Dun Morogh. En récupérant un de ces scripts, nous aurions non seulement la preuve de leur présence ici, mais nous aurions aussi une idée de ce qu'ils trament.$B$BRécupérez un de ces scripts et rapportez-le à Muiredon, $n.", t = "Le Tome de divinité"},
    [1785] = {t = "Le Tome de divinité"},
    [1786] = {ot = "Apporter le Symbole de vie et ressusciter Henze Faulk à Elwynn.", st = "Henze et moi sommes allés à la Veillée des héros, une île au milieu du lac du Cairn au nord-est d'Elwynn. Nous avions entendu dire que des Défias avaient infiltré nos frontières et nous voulions le prouver aux conseillers du roi.$B$BNous en avons surpris en possession de documents, et nous les avons attaqués. Malheureusement, nous avons été rapidement submergés par des mages.$B$BHenze les a retenus pendant que je m'enfuyais... C’était cinglé de sa part, mais il était brave.$B$BIl est mort à présent. Pourriez-vous nous aider, $n ?", t = "Le Tome de divinité"},
    [1787] = {ot = "Retrouver un Script Défias sur les Sorciers-voleurs défias d'Elwynn et le rapporter à Gazin Tenorm à Stormwind.", st = "Nous aurons le temps de parler du Symbole plus tard. Ce qui importe c'est de récupérer les papiers que les Défias avaient sur eux. Si nous pouvons mettre la main dessus, nous serons en mesure de prouver que la Confrérie a infiltré Elwynn et nous aurons une idée de ce qu'elle trame.$B$BJe ne suis pas assez remis pour combattre maintenant, $n. Pensez-vous pouvoir récupérer $gseul:seule; ces papiers dans l'île ?$B$BSi vous pouvez les récupérer, apportez-les à Gazin et dites-lui que je vais bien.", t = "Le Tome de divinité"},
    [1788] = {ot = "Parler à Duthorian Rall à Stormwind.", st = "Je vais porter le Script aux conseillers du roi après que Duthorian y aura jeté un coup d'oeil, ensuite allez parler à Duthorian. Il voudra sûrement vous féliciter !$B$BMerci encore, $n. J'espère que l'on se reverra. Je suis fier de vous avoir comme $gallié:alliée;... et comme $gami:amie;.", t = "Le Tome de divinité"},
    [1791] = {ot = "Parler à Bath'rah la Vigie des vents.", st = "À présent que vous avez appris la posture berserker, vous aurez besoin d'une belle arme avec laquelle l'utiliser.$B$BAllez parler à Bath'rah la Vigie des vents, un troll ermite qui vit entre les montagnes d'Alterac et les Maleterres de l'est. C'est un fabricant d'armes très versé dans son métier et un puissant chaman.$B$BPour le trouver, allez à la rivière qui coule le long du côté est de Moulin-de-Tarren. Remontez-la vers le nord. Bath'rah campe près des ruines jonchant la rive est de la rivière.", t = "La Vigie des vents"},
    [1793] = {t = "Le Tome de la bravoure"},
    [1818] = {ot = "Parler au Garde noir Dillinger à Brill.", st = "J'ai entendu dire que Dillinger le Garde noir avait un travail pour quelqu'un comme vous. Si vous voulez prouver votre valeur aux forces de la Dame noire, alors présentez-vous devant Dillinger immédiatement.$B$BLe poste de Dillinger le Garde noir est à la frontière ouest de Brill, près du cimetière.", t = "Parler à Dillinger"},
    [1819] = {ot = "Tuer Ulag le Fendeur, puis parler au Garde noire Dillinger.", st = "Lorsque le Fléau s'est abattu sur les Clairières de Tirisfal, nous avons capturé l'un de ses serviteurs pour l'étudier. C'était un esprit libre, qui se nommait Ulag le Fendeur. Pourtant, malgré sa libre conscience, le roi-liche avait gardé son emprise sur lui.$B$BNous espérions trouver un moyen de le délivrer de cette influence, mais nous avons échoué. Il est temps de le libérer, maintenant... $B$BLibérez-le et tuez-le.$B$BEn actionnant le déclencheur de la Pierre du Crâne devant le Mausolée qui se trouve au nord, vous briserez le sceau magique qui le lie.$B$BAprès... Il faudra frapper vite et fort, $n !", t = "Ulag le Fendeur"},
    [1820] = {t = "Parler à Coleman"},
    [1821] = {ot = "Rapporter à Coleman Farthing la Hache de la famille Agamand, l'Epée de la famille Agamand, la Masse de la famille Agamand et la Dague de la famille Agamand.", st = "J'ai servi la famille Agamand tout le long de ma vie et ils ont été la cause de ma mort ! S'ils sont maintenant les esclaves du roi-liche, ce n'est que justice ! $B$BÀ présent, je dois m'approprier les derniers vestiges de leur honneur perdu. Dans leur crypte, je veux que vous voliez leur héritage familial : une épée, une hache, une dague et une masse, et que vous me les apportiez. $B$BLa Crypte de la famille Agamand se trouve à la lisière nord des Moulins d'Agamand, sous la protection d'un Fléau errant et des Agamands morts.", t = "L'héritage des Agamand"},
    [1822] = {t = "Une arme en héritage"},
    [1823] = {ot = "Parler à Ruga Ragetotem.", st = "Vous êtes un guerrier compétant à la renommée croissante. Peut-être êtes-vous $gprêt:prête; pour l'épreuve de Ruga Ragetotem ? Si c'est le cas, alors allez trouver Ruga au Camp Taurajo dans les Tarides.$B$BIl cherche des guerriers qui accepteraient de passer son épreuve.", t = "Parler à Ruga"},
    [1824] = {ot = "Apporter 5 Antennes mobiles à Ruga Ragetotem au Camp Taurajo.", st = "Pour passer l'épreuve, vous devez voyager vers le sud jusqu'au Champ des géants. Là-bas, vous trouverez un grand nombre d'insectes rampants. Ils sont récemment arrivés dans les Tarides et je pense que cela ne présage rien de bon.$B$BApportez-moi leurs antennes mobiles, et ne perdez pas de temps, $n. Ces antennes ne remuent pas longtemps. Apportez-les-moi dans le temps alloué, et vous aurez passé l'épreuve.", t = "L'épreuve du Champ des géants"},
    [1838] = {ot = "Apporter à Thun'grim Firegaze 15 Lingots de Fer cendré, 10 Azurites en poudre, 10 Barres de Fer et une Fiole de Phlogiston.", st = "J'ai entendu parler de votre force et de votre courage, et je voudrais faire pour vous une armure complète qui vous aidera à mesure que vos exploits passeront à la postérité.$B$BMais faire une armure est une véritable quête en soi $n, et je vais avoir besoin de votre aide et de celle d'autres forgerons de la Horde.$B$BTenez, prenez ce parchemin. J'ai passé de nombreuses nuits à lutter avec mes yeux presque aveugles pour écrire tout ce dont j'ai besoin pour l'armure. Apportez-moi ce qui est noté sur ce parchemin et je créerai pour vous la première pièce de l’ensemble.", t = "Armure de brutalité"},
    [1858] = {t = "La Main brisée"},
    [1859] = {t = "Therzok"},
    [1860] = {ot = "Parler à Jennea Cannon à Stormwind.", st = "Nous, les mages, avons une tâche à accomplir. Une tâche essentielle pour la sécurité de Stormwind et de la forêt.$B$BJennea Cannon vous donnera plus de détails. Elle étudie dans le Sanctuaire du Sorcier, dans le quartier des mages de Stormwind. Hâtez-vous d'aller la voir.", t = "Parler à Jennea"},
    [1879] = {ot = "Parler à Bink à Forgefer.", st = "$n ! Bink, ma collègue de Forgefer, vous salue. Elle a une mission qu'elle ne veut confier qu'à un mage ! Avez-vous cette qualification, $n ?$B$BDans ce cas, adressez-vous à elle. Elle passe son temps dans le Hall des Mystères de la Garde mystique de Forgefer.", t = "Parler à Bink"},
    [1881] = {ot = "Aller voir Anastasia Hartwell.", st = "$n, Anastasia Hartwell a une tâche à proposer à quelqu'un de votre valeur. Allez la voir dans le Quartier de la magie de Fossoyeuse et préparez-vous à accomplir votre première tâche pour les mages des Réprouvés.", t = "Parler à Anastasia"},
    [1882] = {ot = "Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier de la magie de Fossoyeuse.", st = "Les Maleterres de l'est sont une aberration. Engendrées par le roi-liche, elles étendent leur magie dans le sol, corrompant et tuant tout ce qui vit. Bien que les forces destructrices de la corruption aient un certain charme, nous, les mages des Réprouvés, pensons que cette façon de faire est chaotique et doit être arrêtée.$B$BMais d'abord, nous devons mesurer leur étendue dans Tirisfal. Allez à la ferme des Balnir, à l'est de Tirisfal. Il y a des fleurs qui poussent dans le jardin, des gueules-de-loup. Cueillez-les et revenez me voir.", t = "La ferme des Balnir"},
    [1885] = {t = "Mennet Carkad"},
    [1886] = {ot = "Trouver la Lettre de recommandation d'Astor et l'apporter à Mennet Carkad dans le Quartier des voleurs.", st = "Si vous voulez rejoindre les Traqueurs noirs, la garde d'élite du Seigneur Varimathras, vous devez prouver votre valeur.$b$bJe ne vais pas vous mentir, $n, cette tâche pourrait bien signifier votre mort.$b$bIl y a certaines choses auxquelles il faut prêter attention. J'ai besoin des effets personnels d'Astor Hadren, un messager qui voyage entre les Pins argentés et Fossoyeuse. Je vous laisse le choix de la méthode.$b$bMoins vous en saurez, mieux ça vaudra pour vous. Réussissez et je vous en dirai plus.", t = "Les Traqueurs noirs"},
    [1898] = {ot = "Aller voir Andron Gant à Fossoyeuse.", st = "La lettre de recommandation devrait être suffisante pour convaincre Andron que vous êtes le messager qu'il attendait. J'ai déjà rencontré Andron, il n'est pas assez intelligent pour être soupçonneux.$b$bLe Seigneur Varimathras suspecte Andron d'avoir fourni de l'aide à un autre groupe. Il exige de savoir lequel et en veut la preuve.$b$bJe veux que vous alliez voir Andron pour obtenir cette information. Vous le trouverez à son magasin près de l'Apothicarium.", t = "Les Traqueurs noirs"},
    [1899] = {ot = "Apporter le Grand Livre d'Astor à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse.", st = "Vous trouverez les informations qui intéressent vos employeurs dans le grand livre sur l'étagère derrière moi. Apportez-leur avec mes respects et dites-leur que je préférerais que ce soit vous qu'ils envoient, si ce qu'ils trouvent leur semble avoir assez de valeur, pour continuer notre petit accord.", t = "Les Traqueurs noirs"},
    [1918] = {ot = "Apporter le Globe d'eau souillée à Mastok Wrilehiss, au Poste de Bois-brisé, à Ashenvale.", st = "Sur l'élémentaire vaincu, vous trouvez un globe d'eau, formidablement lumineux, dont le contenu semble proprement répugnant. Apparemment, l'essence qui a souillé les eaux du lac Mystral est également présente dans les eaux du globe. $B$BCe genre de découverte n'est pas en mesure d'intéresser le commun des mortels, et sans doute la personne qui vous a demandé de vous rendre au lac, Mastok Wrilehiss, au poste de Bois-brisé, pourrait bien avoir une idée plus précise à ce sujet.", t = "Les éléments souillés"},
    [1919] = {ot = "Parler à Jennea Cannon à Stormwind.", st = "Vous connaissez de mieux en mieux le métier, jeune $n. Vous vous sentez d'attaque pour commencer vos vraies leçons maintenant ? Pour prendre part à la guerre secrète que nous menons ?$B$BSi oui, allez voir Jennea Cannon au Sanctuaire du Sorcier, dans le quartier des mages de Stormwind. Elle vous confiera une tâche qui sera votre première fenêtre sur le monde invisible.", t = "Rendre compte à Jennea"},
    [1920] = {t = "Trouver le Solitaire bleu"},
    [1960] = {ot = "Obtenir une Incantation de Manifestation et une Caisse de Coffres de retenue placée derrière Anastasia Hartwell. Apporter 3 Coffres de retenue remplis, la Caisse de Coffres de retenue et l'Incantation de Manifestation à Anastasia Hartwell à Fossoyeuse.", st = "L'échoppe d'alchimiste d'Algernon, à l'Apothicarium, est l'objet de curieux troubles. Des créatures magiques, faites seulement de magie, la parcourent. Il doit bien y avoir une raison, et nous devons la découvrir !$B$BEnquêtez à ce propos et capturez ces créatures. Prenez des coffres de stockage et un parchemin, derrière moi. Utilisez-le à l'échoppe pour rendre les créatures visibles, assujettissez-les à l'aide de vos sorts, puis capturez-les dans les coffres. Rapportez les coffres pleins, ceux qui sont vides et l'incantation.", t = "Enquêter dans le magasin de l'Alchimiste"},
    [1961] = {ot = "Apporter 10 pièces de lin et 6 Gemmes de mana de Dalaran à Josef Gregorian.", st = "Il est temps pour vous de porter vos premières robes de mage, $n. Elles sont le signe de votre statut et un témoignage de votre valeur.$B$BPour gagner ces robes, il vous faudra aller dans la forêt des Pins argentés et prendre des gemmes de mana aux mages de Dalaran. Leurs croyances sont semblables aux nôtres, il est donc assez désagréable de les assassiner, mais s'ils ne sont pas assez forts pour résister, alors ils ne méritent pas de vivre.$B$BApportez les gemmes et une longueur de lin à Josef Gregorian, à sa boutique de tailleur, dans le Quartier de la magie.", t = "Rassembler les matériaux"},
    [1962] = {t = "Robe du feu-sorcier"},
    [1963] = {ot = "Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l'ombre à Orgrimmar.", st = "Le Chef de guerre utilise des méthodes trop subtiles. Par prudence, il veut éviter de déchaîner le pouvoir de la Horde. Pourtant, nous avons été plus forts, nous avons été de fiers conquérants ! Nous devons retrouver notre gloire passée et la Main brisée va la reconquérir.$B$BNous tirons notre force de l'ombre et frappons nos ennemis en secret. Une tâche que vous devez accomplir pour prouver votre valeur.$B$BLe troll Tazan est en affaires avec les pirates près de Ratchet. Il détient des informations dont j'ai besoin. Tuez-le et apportez-moi sa sacoche.", t = "La Main brisée"},
    [1978] = {t = "Les Traqueurs noirs"},
    [1998] = {ot = "Tuer Fenwick Thatros et rapporter sa Tête à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse.", st = "Le Seigneur Varimathras vient juste de m'envoyer une missive au sujet d'une menace concernant les Réprouvés, menace qui doit être immédiatement supprimée. Son nom est Fenwick Thatros, et le Seigneur Varimathras pense que c'est l'un des chefs morts-vivants qui ont pris pied dans la forêt des Pins argentés.$b$bJ'ai immédiatement pensé à vous, $n. J'ai assez confiance dans vos capacités pour penser que vous réussirez cette mission.$b$bLes derniers rapports des Traqueurs noirs dans la forêt indiquent que Thatros doit se trouver près du vieux port abandonné sur Lordamere.", t = "Fenwick Thatros"},
    [2038] = {ot = "Trouver et rapporter à Bingles son matériel :$B$BLa Clé de Bingles, le Tournevis de Bingles, le Marteau de Bingles et le Capsuleur soufflant de Bingles.", st = "Comme si le crash dans le Loch n'avait pas suffi, des troggs de l'île voisine m'ont attaqué et ont volé mes outils et mes capsuleurs soufflants Blastenheimer spéciaux ! Sans gyrocoptère et sans explosifs, le mouvement n'a aucune chance ! $B$BRapportez-moi mes outils et mes capsuleurs soufflants, $n. Pour Gnomeregan !", t = "Les fournitures perdues de Bingles"},
    [2039] = {t = "Trouvez Bingles"},
    [2040] = {ot = "Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Stormwind.", st = "Gnomeregan est tombé sous les contrôle de ces troggs maudits ! La situation est grave, mais vous pouvez peut-être nous aider, $n. $B$BAu plus profond des mortemines, il y a un Déchiqueteur gobelin en état de fonctionnement. Trouvez-le et rapportez sa source d'énergie intacte. Elle permettra à nos Excavateurs gyrodrilmatiques de percer les murailles pour l'assaut !", t = "Assaut souterrain"},
    [2041] = {ot = "Aller voir Shoni la Silencieuse à Stormwind.", st = "Peut-être... Peut-être que vous pouvez nous aider dans la bataille de Gnomeregan.$B$BVous trouverez à Stormwind le commandant de notre équipe d'assaut souterraine, Shoni la Silencieuse. Shoni a besoin d'aide pour ses excavateurs gyrodrilmatiques.$B$BVous la trouverez probablement parmi les nains de Stormwind.$B$BBonne chance, $n.", t = "Allez voir Shoni"},
    [2078] = {t = "La vengeance de Gyromast"},
    [2098] = {t = "La recherche de Gyromast"},
    [2118] = {ot = "Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun.", st = "Il y a une maladie qui s'étend à travers tout Sombrivage, contaminant les esprits et les organismes qu'elle touche.$B$BCe sont les ours des chardons qui ont été les plus touchés. Ces animaux, autrefois si nobles, sont devenus des instruments de destruction, enragés et frénétiques. J'ai peut-être trouvé un remède contre ce mal.$B$BApportez ce piège dans la forêt et placez-le au sol. N'importe quel ours des chardons enragé qui traversera cette lumière deviendra docile pour un court moment. Une fois que l'ours sera docile, il vous suivra. Ramenez-le ici, $n.", t = "Terres malades"},
    [2138] = {ot = "Débarrasser la forêt de 20 Ours des chardons enragés et retourner voir Tharnariun Treetender, à Sombrivage.", st = "Comme je le craignais, le remède ne marche pas.$B$BCela m'attriste énormément de devoir ordonner la mort de certaines créatures de la nature, mais les ours des chardons malades et infectés doivent être éliminés.$B$BRetournez dans la forêt et détruisez 20 ours des chardons enragés, $n. Cela ne suffira sans doute pas à éradiquer la contamination, mais ça permettra de limiter pendant quelque temps les dégâts que ces animaux causent à notre forêt et à ses habitants.", t = "Nettoyage de l'infection"},
    [2139] = {ot = "Trouver et tuer la Mère de la tanière.", st = "La survie de notre peuple et de nos terres a exigé des sacrifices, $n.\n\nHélas, vous avez dû verser le sang des serviteurs de la nature, et bien des animaux sont tombés sous vos coups. Le peuple d’Auberdine vous doit beaucoup, et la souffrance de la forêt est apaisée, au moins pour le moment.\n\nJ’ai une dernière tâche à vous confier, mais sachez qu’il vous faudra tuer de nouveau. J’espère de tout cœur que ce sera la dernière fois, $n.\n\nÀ côté de Bashal’Aran, dans une caverne au nord-est d’ici, habite la Mère de la tanière. Faites-la disparaître.", t = "Espoir de Tharnariun"},
    [2158] = {ot = "Parler à l'aubergiste Farley, à l'auberge de la Fierté du lion.", st = "Tous les aventuriers doivent prendre du repos s'ils veulent éviter l'épuisement... Et pour cela, le meilleur endroit, c'est bien l'Auberge de la Fierté du lion ! $B$BMon meilleur ami, l'aubergiste Farley, tient cette auberge. Si vous venez de ma part, il vous fera sûrement des réductions sur le prix de la nourriture et de la boisson ! $B$BSuivez cette route vers le sud, vous ne pouvez pas la rater !", t = "Repos et détente"},
    [2159] = {ot = "Apporter la Livraison de Dolanaar à l'aubergiste Keldamyr.", st = "Salutations, jeune $c. Pouvez-vous m'aider ? Je dois livrer ce paquet d'herbes dans la ville de Dolanaar, mais ne puis partir d'ici car j'ai une tâche à terminer avec les druides de Sombrevallon.$B$BPouvez-vous livrer ce paquet pour moi ? Il doit être remis à l'aubergiste Keldamyr, à l'auberge de Dolanaar. Elle se trouve sur cette route, au sud.", t = "Livraison à Dolanaar"},
    [2160] = {ot = "Livrer la Caisse de ravitaillement à l'auberge de Tannok Frosthammer à Kharanos.", st = "Hé ! Vous avez l'air d'être un cœur généreux. Si vous projetez de prendre le Passage, pourriez-vous apporter un paquet à l'auberge de Kharanos ?$b$bVous vouliez vous arrêter à l'auberge, non ? Si vous prenez le Passage, vous aurez certainement envie de vous y reposer.$b$bQuoi qu'il en soit, apportez ceci à Tannok Frosthammer, l'assistant de l'aubergiste. Je ne peux pas passer le Passage moi-même et il faudra des jours avant qu'une escorte de Montagnards ne passe par ici !", t = "Des provisions pour Tannok"},
    [2161] = {ot = "Apporter le Fardeau d'Ukor à l'aubergiste Grosk à Tranchecolline.", st = "Excusez-moi... Pouvez-vous m'aider ? $B$BVous voyez ce chargement ? J'ai suivi la route, j'ai bravé les scorpides, les araignées, que sais-je encore, tout ça pour apporter ces vivres à la vallée des Epreuves. Je pensais qu'ils en auraient besoin... Mais non, ils n'en ont pas voulu ! Maintenant, il ne me reste plus qu'à rapporter tout ça à Tranchecolline et ça me terrorise, à cause des bêtes... $B$BVous pourriez vous en charger pour moi ? Je ne suis qu'un malheureux péon mais vous... Vous n'avez peur de rien, vous avez l'habitude d'être héroïque ! $B$BRapportez ce paquet à l'aubergiste Grosk à l'auberge de Tranchecolline. Merci !", t = "Un Fardeau de Péon"},
    [2178] = {t = "Brouet de trotteur"},
    [2205] = {ot = "Remettre le colis de Keryn Sylvius à maître Mathias Shaw à la Caserne de Stormwind.", st = "L'insigne ? Rien... Rien qui soit pour vous... Si j'en juge par votre apparence, j'ai peur que Mathias vous prenne pour le livreur de fromage, mon enfant, au lieu du malandrin attendu. Enfin, on m'a donné un travail et j'ai promis de livrer ce travail. $B$BTiens, à propos, vous apporterez ce paquet à Mathias, et peut-être qu'il vous donnera un ou deux petits boulots à accomplir. $B$BAllez, du vent.", t = "Chercher le SI:7"},
    [2218] = {ot = "Parler à Hulfdan Blackbeard à Forgefer.", st = "Une autre âme perdue en quête de conseil, hein ?Je suppose que vous cherchez une voie, votre voie. J'ai déjà vu ça mille fois, encore un héros désœuvré qui cherche du travail.$B$BEh bien, c'est aujourd'hui votre jour de chance, mon $gami:amie;. Hogral connaît la solution à votre tourment.$B$BVoici ce qu'il vous faut faire : prenez cette route jusqu'à Forgefer et cherchez-y la caverne lugubre. Une fois sur place, localisez la guilde des voleurs et demandez entretien à Hulfdan Blackbeard. Il vous guidera vers votre salut.", t = "La voie du salut"},
    [2241] = {ot = "Porter la fleur de Jannok à Syurna à Darnassus.", st = "Ils disent que je suis fleur bleue... quoi que cela puisse vouloir dire.$B$BC'est vrai qu'à tout instant je pense à Syurna. C'est vrai, ma maison est tapissée de peintures et de dessins de Syurna. C'est vrai, je peux passer des jours sans manger, boire ou dormir en me languissant de l'amour que nous aurions pu connaître. Mais est-ce mal ?$B$BDésormais, elle ne me verra plus ! MOI ! J'ai essayé de lui envoyer des messages, mais elle ne parlera même pas à quelqu’un qui n’est pas un voleur.$B$BPourriez-vous lui porter cette fleur ? Et n'oubliez pas de dire que c'est de la part de Jannok.", t = "Pomme d'amour"},
    [2242] = {ot = "Trouver Sethir l’Ancien et rapporter tout indice découvert à Syurna.", st = "Nous pensons qu'il existe un être qui pourrait nous aider à comprendre ce qui arrive aux forêts de Teldrassil. Malheureusement, toutes les tentatives pour amener la créature à coopérer se sont soldées par un désastre.$B$BIl se cache sur une branche, sur le rebord de la clairière de l'Oracle. À ce jour, tous ceux qui ont approché le satyre, par la force ou la diplomatie, ont été anéantis. Le camouflage est peut-être la solution, $n.$B$BTrouvez ce que Sethir l'Ancien cache dans ses poches et faites-moi un rapport.", t = "L'appel du destin"},
    [2281] = {ot = "S'aventurer vers Comté-du-Lac dans les Carmines et parler à Lucius.", st = "Vous jeter maintenant sur le champ de bataille serait pur suicide. Renzik ne veut pas d'un autre cadavre de voleur dans son équipe. Mais pas d'inquiétude, $n : Renzik vous mettra à niveau.$B$BDirigez-vous vers les Carmines et discutez avec Lucius, un associé du SI:7. Vous le trouverez facilement, il traîne généralement autour des docks de Comté-du-Lac avec d'autres bons à rien.", t = "Le Rendez-vous des Carmines"},
    [2282] = {ot = "Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Comté-du-Lac.", st = "J'entraîne des voleurs depuis des années ! Après tout, c'est pas n'importe quel vaurien qu'est né avec la grâce et la finesse du vieux Lucius.$B$BUn peu plus loin, z'allez trouver la scierie d'Alther. J'y ai un coffre fermé qui contient que'q' chose d'important. Allez le récupérer pour moi. Ramenez-moi ce qui s'y trouve, et vous recevrez vot' Certificat de voleur !", t = "La scierie d'Alther"},
    [2298] = {ot = "Aller à Stormwind et chercher Renzik \"le Kriss\".", st = "Alors on était là, en train de comploter pour la phase III quand d'un coup, deux crétins de Magni se pointent en parlant de je ne sais quel coup, et d'arrêter ceux du Cercle secret.$B$BPersonne ne porte la main sur le vieux Blackbeard ! La discussion s'envenime, blabla, paf, et soudain on prononce vot' nom !$B$BV'voulez un conseil ? Prenez le premier Griffon pour Stormwind. Une fois là-bas, allez voir Renzik \"le Kriss\" dans la vieille ville. C'est un vieil ami à moi.", t = "Kingly Shakedown"},
    [2359] = {ot = "Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Stormwind. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.", st = "Je suis là, à surveiller cette tour depuis des semaines, $n. Récemment, un chargement important est arrivé du bois de la Pénombre, protégé par ces gardes. $B$BQue sont-ils ? Aucune idée. La seule chose que je puisse affirmer, c'est qu'ils ne sont pas humains. $B$BQuoiqu'il en soit, dans cette cargaison repose un coffre, et je suppose que ces abominations sont commises à sa garde. Le gros avec les piques, là, possède une clé dont nous aurons besoin.$B$BRécupérez cette clé, entrez dans la Tour et découvrez ce que contient ce coffre. Rapportez à Mathias le produit de votre recherche.", t = "La Tour de Klaven"},
    [2360] = {ot = "Se rendre dans la marche de l'Ouest et trouver l'Agent Kearnen pour un débriefing.", st = "Pas trop tôt, $n. Les éléments de reconnaissance du SI:7 nous apprennent les Défias sont inhabituellement actifs dans la marche de l'Ouest.$B$BOn dirait qu'ils ont pris une ancienne Tour de guet de l'Alliance abandonnée au sud-est de la Colline des sentinelles, et qu'ils s'en servent comme base d'opérations pour leurs trafics à partir de la route d'approvisionnement des Carmines.$B$BAllez dans la marche et contactez l'Agent Kearnen. Elle est cachée à proximité de la tour. $B$B... Oh, $n, si vous veniez à être $gcapturé:capturée;, le SI:7 nierait avoir eu connaissance, etc.", t = "Mathias et les Défias"},
    [2378] = {ot = "Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l'ombre.", st = "Vous avez bien servi les Traqueurs de ténèbres, $n, mais il est temps d'étendre votre expérience. Vous avez montré vos capacités en matière de ruse et de traîtrise, mais votre entraînement n'est pas terminé. $B$BLes Traqueurs de ténèbres ont des alliés au sein de la Main brisée. Cherchez ceux qui viennent à notre aide : trouvez Shenthul à Orgrimmar.", t = "Trouver la Main brisée"},
    [2379] = {ot = "Parler à Zando'zan à la Faille de l'ombre.", st = "Votre seule détermination ne suffira pas pour affronter les obstacles qui nous attendent. $B$BAdressez-vous à Zando'zan pour commencer votre entraînement comme opérationnel de la Main brisée. $B$BLorsque vous maîtriserez le noble art du vol et de la tricherie vous pourrez faire un pas de plus vers votre destinée.", t = "Zando'zan"},
    [2381] = {ot = "Rapporter le Trésor des Mers du sud à Wrenix le Misérable à Ratchet. Ne pas oublier d’obtenir un B.G.A.C. et des Outils de voleur de l’Appareil bidulotronique de Wreni. Ces deux éléments sont nécessaires pour accomplir la mission.$B$BEn cas d’attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C.!", st = "Sans vouloir vous effrayer, $n, les cinq derniers qui ont essayé de voler le trésor des Mers du sud ont été mis en pièces.$B$BLe long de la côte, au sud, vous trouverez le \"Tranche-les-vagues\", le navire des Flibustiers des Mers du sud. Le trésor se trouve dans la cale. Au deuxième niveau se trouve la salle des pirates, une salle d'entraînement pour leurs voleurs.$B$BMontez à bord, volez le trésor, et rapportez-le-moi. Utilisez la salle des pirates si vous voulez vous entraîner, mais attention : prudence !", t = "Piller les Pilleurs"},
    [2382] = {ot = "Aller jusqu'à Ratchet pour voir Wrenix le Misérable.", st = "Zando'zan l'a vu ! Oui, le jour vient ! La mort de l'esclave... Le poignard dans le dos, le poison suintant de chaque veine... Zando'zan en a trop dit.$B$B$n ! Zando'zan a une tâche pour $n ! $n doit aller à Ratchet, à l'est de la Croisée, pour rencontrer Wrenix le Misérable. Allez !", t = "Wrenix de Ratchet"},
    [2383] = {ot = "Lire le Simple parchemin, et parler à Frang, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l’extérieur de l’Antre, dissimulé dans l’ombre.", t = "Parchemin simple"},
    [2399] = {t = "Les racines ont poussé"},
    [2438] = {ot = "Apporter le Capturêve d'émeraude à Tallonkai Swiftroot à Dolanaar.", st = "Un jour, Gaerolas Talvethren, le Gardien des druides du Refuge des saisons de Ban'ethil, m'a donné un Capturêve d’émeraude. Cette puissante amulette est capable d'aspirer l'énergie du Rêve d'émeraude pour donner de la chance à ceux qui la portent.$B$BHélas, je n'ai pas pu la récupérer dans ma commode au village de Brise-stellaire... Autrefois, Brise-stellaire était un endroit tranquille, mais il a succombé à la corruption des furbolgs qui y résident.$B$BVoudriez-vous récupérer mon Capturêve, $c ?", t = "Le Capturêve d'émeraude"},
    [2458] = {ot = "Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule.$B$BUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).$B$BRespecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier.", st = "La KapitalRisk... Vous avez entendu parler d'eux ?$B$BDepuis un an, nous essayons d'y introduire un de nos agents. Nous avons travaillé dur, mais prudemment, et nous avons réussi.$B$BNous venons d'apprendre que la KapitalRisk projette une opération de grande envergure. Allez au nord de la Videfange, à la tour de la KapitalRisk, et contactez notre agent, le sous-chef Fizzule.$B$BUne fois sur place, utilisez ce lance-fusées, approchez Fizzule et faites-lui le salut de la Main brisée.", t = "Sous le couvert de la nuit"},
    [2459] = {ot = "Sur ordre de Tallonkai Swiftroot de Dolanaar, tuer 7 Mystiques Pins-tordus et retrouver le Bijou disparu.", st = "L'émeraude... Elle a disparu ! Mon capturêve a été endommagé !$B$BUne bande de Mystiques Pins-tordus rôde au nord de Brise-stellaire. J'ai entendu dire que leur chef, Ferocitas le Mangeur de rêves, porte un collier qui émet des lueurs vertes pendant la nuit. Vu l'état de mon capturêve, il est certain qu'il a volé mon émeraude... Il ne comprendra jamais que sa puissance lui est inutile.$B$BTrouvez mon bijou disparu, $n. Et tant que vous y êtes, profitez-en pour nous débarrasser de quelques Mystiques corrompus.", t = "Ferocitas le Mangeur de rêves"},
    [2460] = {ot = "Faire le Salut brisé à Shenthul.", st = "En tant que voleur de la Main brisée, il est impératif que vous appreniez le Salut brisé. C'est la seule façon d'identifier un autre membre de la Main.$B$BRegardez, apprenez, répétez.", t = "Le Salut brisé"},
    [2478] = {ot = "Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.$B$BAssassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.", st = "Vous devez voler la clé de la tour au contremaître Silixiz, $n. Une fois la clé en votre possession, gardez-la soigneusement, je pourrais en avoir besoin plus tard.$B$BProfitez de l'état d'affaiblissement des habitants empoisonnés, et laissez donc votre tendance au chaos et à la destruction s'exprimer librement. Tuez-les tous ! Ne montrez aucune pitié !$B$BLorsque tous baigneront dans leur sang, ouvrez le coffre de Gallywix et volez la Mixture de Zanzil. Apportez la tête de Gallywix ainsi que la Mixture à Shenthul à Orgrimmar.", t = "Mission : possible mais non probable"},
    [2479] = {ot = "Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.$B$BPour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !", st = "Apportez un échantillon du mélange à Serge Hinott à Moulin-de-Tarren.$B$BSi quelqu'un peut vous guérir, c'est bien Serge. Si vous vivez suffisamment longtemps, il vous montrera comment créer un poison et comment l'utiliser.", t = "L'aide d'Hinott"},
    [2480] = {ot = "Attendre Serge Hinott pour achever le remède.", st = "Je n'ai jamais vu d’aussi merveilleux résultats pour un poison ! Zanzil, vous dites ? Jamais entendu parler de lui, mais je m'incline devant le mélange qu'il a créé.$B$BBon, vous voulez que je vous guérisse et que je vous apprenne ensuite à utiliser le poison ?$B$BLaissez-moi un peu de temps pour examiner la toxine, $n.", t = "L'aide d'Hinott"},
    [2498] = {ot = "Sur ordre de Rellian Greenspyre, aller voir Denalan au lac Al'Ameth.", st = "Je viens de recevoir un mot de Denalan au lac Al'Ameth, disant qu'il a peut-être découvert la cause les tumeurs chez les sylvains. Allez le voir et dites-lui que je vous envoie.$B$BFaites vite, $n, il a besoin de nous.", t = "Retour vers Denalan"},
    [2499] = {ot = "Sur ordre de Denalan du lac Al'Ameth, ôter la Tumeur gargantuesque de Froncechêne.", st = "Dans une caverne le long de la rive sud du lac, un sylvain nommé Froncechêne propage la corruption parmi les créatures qui vivent au lac Al'Ameth.$B$BJe n'ai pas osé m'approcher, mais c’est visible à distance : il est parasité par la plus grande tumeur que j'ai jamais vue... On pourrait même dire gargantuesque.$B$B$n, vous m’avez déjà été d'un grand secours, mais je vous demande encore cela : pourchassez-le et débarrassez-le de sa tumeur, éliminez cette source de contamination de chez moi.", t = "Froncechêne"},
    [2518] = {ot = "Apporter les Filières d'argent de dame Sathrah à la prêtresse A'moora, au temple de la Lune, à Darnassus.", st = "Autrefois, dame Sathrah était aimée d'Elune. Gracieuse et pure, l'araignée tissait ses toiles d'argent au clair de lune pour recueillir la brume du soir. La rosée argentée avait de grands pouvoirs de guérison et on la conservait au temple.$B$BMais récemment, dame Sathrah a plongé dans la folie. Sa descendance à venir est également menacée.$B$BTrouvez dame Sathrah, $n, et mettez fin à ses souffrances. Elle demeure le long des frontières, au nord de Teldrassil, près du lac d'Aigue-vive. Prenez ses filières d'argent et apportez-les-moi.", t = "Les larmes de la Lune"},
    [2519] = {ot = "Sœur Aquinne veut que vous parliez à la prêtresse A'moora, au temple de la Lune.", st = "Une créature de la forêt, autrefois l'une des plus grandes, a besoin de votre aide, $N.$B$BC'est une tâche difficile, mais qui doit être accomplie.$B$BS'il vous plaît, allez voir la prêtresse A'moora, elle vous expliquera de quoi il s'agit. Elle est au sud-est, dans le Temple de la Lune.", t = "Le Temple de la Lune"},
    [2520] = {ot = "Sur ordre de la prêtresse A'moora, placer les Filières d'argent de dame Sathrah dans la fontaine du Temple, puis retourner la voir.", st = "Maintenant vous devez finir la tâche qui vous a été confiée. Prenez les Filières d'argent et offrez le sacrifice de dame Sathrah à Elune. Permettez à la Grande araignée de trouver le repos.$B$BDans le temple, trouvez la fontaine centrale. C'est là que vous déposerez le sacrifice. Les eaux saintes vont nettoyer et purifier la corruption qui a conduit Sathrah à la folie.$B$BQuand vous aurez fini, revenez me voir.", t = "Sacrifice de Sathrah"},
    [2541] = {ot = "Rapporter un Charme vaudou de chaman à Oben Grifferage dans le Refuge des saisons de Ban'ethil.", st = "Les chamans Pins-tordus qui habitent cet endroit ont découvert comment séparer l'esprit d'un druide dormant de son corps physique. Les furbolgs ont ranimé ma forme physique et l'utilisent pour attaquer ceux qui essaient d'explorer le refuge des saisons de Ban'ethil. Je suis impuissant, pris au piège dans le Rêve d'émeraude.$B$BVous devez m'aider. Les chamans Pins-tordus portent un charme étrange qu'ils utilisent pour exécuter ce rituel et je voudrais l'examiner. Je vous en prie, $n, il m’en faut un.", t = "Le druide dormant"},
    [2561] = {ot = "Sur ordre d'Oben Grifferage, tuer son Corps privé d'âme et utiliser ensuite le Charme vaudou.", st = "J'ai examiné ce charme, $n, et je vois maintenant ce qu'il faut faire. Prenez-le et suivez mes instructions.$B$BVous devez explorer les zones les plus reculées du Refuge des saisons de Ban'ethil pour trouver mon corps sans âme... Je regrette de devoir en arriver à cette extrémité, mais je ne vois pas d'autre moyen de me libérer du contrôle des Pins-tordus.$B$BVous devez tuer ma forme physique. Ensuite, utilisez le Charme vaudou sur mon corps. Lorsque vous aurez accompli cette tâche,revenez me voir.", t = "Le druide de la Griffe"},
    [2607] = {ot = "Aller voir le docteur Mixilpixil dans la Cave de la caserne.", st = "On dirait que vous avez rapporté plus d'informations que je n'en attendais. Les événements prennent une tournure étrange, $n.$B$BUn remède ? Hum... Rendez-vous à la Cave et allez voir le docteur Mixilpixil, il pourra peut-être vous aider.", t = "Le toucher de Zanzil"},
    [2608] = {ot = "S'allonger (/coucher) pour être $gexaminé:examinée; par le docteur Mixilpixil. Comment peut-il trouver le remède s'il ne peut pas trouver la cause ?", st = "Oh Ciel ! Vous ressemblez à la mort. Je corrige : j'ai vu la mort, vous semblez en pire état. Vous ressemblez à ce que serait la mort à son dernier instant.$B$BAh ! Vous entendez ce Noarm ? Notez-le !$B$B*soupir* Hum ! Oui, pour vous aider, je dois prendre un peu de votre sang. Ne vous inquiétez pas, ça ne fait mal que les… cinquante premières fois. Allongez-vous (/coucher) quand vous serez $gprêt:prête; pour le traitement, $n.", t = "Le toucher de Zanzil"},
    [2609] = {ot = "Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul.", st = "Le diagnostic est unanime, $n. Vous êtes $gatteint:atteinte; de “itis”. $B$BHeureusement, j'ai un remède.$B$BVoilà ce dont j'ai besoin : une brassée de fleurs sauvages simples, une fiole plombée, un tube en bronze et une bobine de fil de soie chartreuse. La vieille Emma en a laissé pour moi au \"Fil le plus fin”. Le magasin se trouve le long des canaux.$B$BDépêchez-vous $n, et ne touchez personne jusqu'à votre guérison. Oh ! Montgomery dit que vous devriez prendre une douche – c'est lui qui le dit, pas moi.", t = "Le toucher de Zanzil"},
    [2745] = {ot = "Aller voir Tyrion au Château de Stormwind.", st = "Hum ! Une histoire intéressante à ne pas prendre à la légère. Ouais, je peux vous aider, mais ce que vous devez faire n'est pas vraiment une justice... légale, si vous allez jusqu'au bout.$B$BOn doit d’abord s'occuper de Lescovar et de Marzon, et vite. Pensez-vous en être capable ?$B$BA vous de décider. Si oui, rendez-vous rapidement au château pour y rencontrer un vieil ami à moi, un gnome nommé Tyrion. Il observe Lescovar depuis maintenant quelques semaines. Il devrait pouvoir vous aider à en finir.", t = "En infiltrant le Château"},
    [2746] = {ot = "Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Stormwind.", st = "Trias veut accélérer les choses, hein ? Bien, nous pouvons le faire, mais je ne suis pas prêt. Je vais faire la partie difficile du boulot, mais c'est vous qui allez vous salir les mains, d’accord ? Bon.$B$BIl faut que vous m'obteniez certaines choses pour mettre mon plan à exécution. J'ai le déguisement parfait pour que l'Espion passe ces gardes.$B$BApportez-moi de la soie et deux pommes. Pour la soie, débrouillez-vous, mais vous trouverez des pommes parfaites à la petite ferme de Clara à l'extérieur de la ville.", t = "Des objets d’une certaine importance"},
    [2841] = {ot = "Obtenir la Combinaison du coffre de Thermaplugg, prendre les Plans de la plate-forme et les apporter à Nogg à Orgrimmar.", st = "Technologie gnome… Ce terme était autrefois brandi comme un slogan. Les temps ont changé. Ils ont désormais une nouvelle plate-forme, supérieure à tous nos modèles de Déchiqueteurs combinés. J'ai besoin des plans de cette plateforme, $n !$B$BMalheureusement ceux-ci sont enfermés dans le coffre du mekgénieur Thermaplugg. Et pour compliquer les choses, la combinaison du coffre n'est connue que de lui seul.$B$BFaites ce qu’il faut pour obtenir cette combinaison, $n. Puis ouvrez le coffre et ramenez-moi ces plans !", t = "Guerre des plates-formes"},
    [2842] = {ot = "Parler à Scooty à Baie-du-Butin.", st = "Dès que nous aurons des nouvelles de Kernobee à propos de la nouvelle plate-forme des gnomes, Scooty et moi commencerons à travailler sur le Transpolyporteur 6000 : le moyen le plus rapide et le plus sûr d’aller à Gnomeregan.$B$BIl est enfin prêt à recevoir des passagers, $n. Si vous désirez l'essayer, allez à Baie-du-Butin et parlez avec Scooty au perchoir des Cavaliers célestes. Pour aller à Baie-du-Butin, prenez le bateau depuis Ratchet.$B$BVous pouvez aussi traverser les montagnes de Dun Morogh, mais elles sont infestées de nains…", t = "L'ingénieur en chef Scooty"},
    [2843] = {ot = "Attendre que Scooty calibre le transpondeur des gobelins.", st = "Aussi longtemps que vous êtes en possession du transpondeur des gobelins, tout ce que vous avez à faire est de traverser le portail et vous vous retrouverez à Gnomeregan.$B$BIl y aura peut-être des effets secondaires bizarres, mais aucun ne devrait être permanent... plus maintenant.$B$BJ'oubliais de parler du plus important : le retour. Lorsque vous serez $gprêt:prête; à revenir, allez au portail de multitéléportation de Gnomeregan !$B$BBon, il faut maintenant régler le transpondeur selon votre poids et votre taille.", t = "Gnomer-paaarti !"},
    [2904] = {ot = "Escorter Kernobee jusqu’à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin.", st = "<Kernobee grogne>Qu… Que s'est-il passé ?$B$BLa dernière chose dont je me souviens est d'avoir été capturé par un groupe de nains Sombrefer, d'avoir été battu comme plâtre et jeté ici avec ces troggs crasseux.$B$BSortez-moi de là, $n !$B$BVoici le plan : vous me conduisez à la sortie, si nous survivons, vous allez à Baie-du-Butin prévenir Scooty que je suis allé à Ratchet pour informer Tinkerwiz de l'implication des Sombrefer dans la conception de cette super plate-forme.$B$BAllons-y !", t = "Une jolie pagaille"},
    [2922] = {ot = "Rapporter la Mémoire principale de Techbot au maître-artisan Overspark à Forgefer.", st = "Lorsque notre cité bien-aimée de Gnomeregan est tombée, une étincelle a fait disjoncter ma pauvre création, le Techbot. Il nous aidait bien, moi et mes associés, avec ses nombreux gadgets et ses banques d'informations illimitées, mais son cerveau positronique a été polarisé. Techbot est maintenant négatronique et son comportement s'est inversé. Il erre, enragé, dans Gnomeregan !$B$BMais peut-être peut-il être sauvé. Si vous retrouviez sa mémoire principale et me la rapportiez, je pourrais découvrir la cause de la polarisation et réparer mon pauvre Techbot.$B$B", t = "Sauver le cerveau de Techbot !"},
    [2923] = {ot = "Parler au maître-artisan Overspark à Forgefer.", st = "Le maître-artisan Overspark est très contrarié par la perte de sa création mécanique, le Techbot. Je me souviens du Techbot comme d’une machine gentille et serviable, très utile aux gnomes, mais Overspark dit qu'il a eu des problèmes de fonctionnement.$B$BVraiment dommage, mais avec de la chance, cela pourrait être réparé !$B$BParlez avec maître Overspark, à Brikabrok, le quartier gnome de Forgefer. Votre aide sera la bienvenue.", t = "Maître-artisan Overspark"},
    [2924] = {ot = "Rapporter 12 Cerveaux mécaniques à Klockmort Spannerspan à Forgefer.", st = "Un composant pratiquement universel, le cerveau mécanique, est d'une grande utilité pour les artisans et les forgerons de Gnomeregan. Mais durant notre exode, personne n'a pensé à en emporter ! Et j'en ai besoin d'un grand nombre pour le travail que je vais bientôt accomplir.$B$BS'il vous plaît, allez à Gnomeregan et rapportez-en. Vous les trouverez dans les profondeurs de notre cité, dans des conteneurs appelés des extrapolateurs artificiels.$B$BMerci, $n et dépêchez-vous !", t = "Les cerveaux mécaniques"},
    [2926] = {ot = "Utiliser la Fiole de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Togglevolt à Kharanos.", st = "Depuis l'accident, Gnoarn discute et palabre sur le fait de nettoyer Gnomeregan de l'infestation des troggs et de trouver un remède à la maladie, $n.$B$BPar chance, Razzle et moi sommes près de trouver quelque chose, un remède ou une recette de rhum particulièrement corsée, nous ne sommes pas sûrs… Nous le saurons après les tests ! Nous avons bien évidemment besoin de quelques ingrédients pour tester notre produit, notamment des retombées radioactives collectées sur des troggs irradiés de Gnomeregan. Remplissez cette fiole avec la Lueur verte et rapportez-la.", t = "Gnogaine"},
    [2927] = {t = "Le jour d'après"},
    [2928] = {ot = "Rapporter 24 Entrailles mécaniques de robot à Shoni à Stormwind.", st = "C'est affreux, $n. Nous n'avons pas suffisamment de pièces détachées pour notre flotte d'excavateurs gyrodrilmatiques à Dun Morogh.$B$BNous avons besoin de ces pièces, $n. Le meilleur endroit pour en trouver est Gnomeregan, mais j'ai entendu dire que les bots et les mechs grouillaient là-bas, comme les puces sur le dos d'un chien.$B$BVous devez aller à Gnomeregan et mettre en pièces quelques robots. Ramenez-moi des entrailles mécaniques. Deux douzaines devraient suffire.", t = "Excavateurs gyrodrilmatiques"},
    [2929] = {ot = "Aller à Gnomeregan et tuer le mekgénieur Thermaplugg. Puis retourner voir le Grand Bricoleur Mekkatorque.", st = "J'avais confiance en Thermaplugg, $n. Je ne pensais pas qu'il me trahirait, moi et tout le peuple gnome. Et pourquoi ? La puissance ? L'argent ? Toute chose qu'il aurait eu de toute façon. Maintenant nous avons été jetés hors de notre pays et ce malade est à sa tête. Le roi du vide...$B$BNous reprendrons Gnomeregan, $n. Nous n'arrêterons pas tant que la ville ne sera pas nôtre à nouveau. Si vous désirez vous joindre à nous, j'ai une mission simple à vous confier : tuer le traître. Détruisez le mekgénieur Thermaplugg.", t = "La grande trahison"},
    [2930] = {ot = "Apporter une Carte perforée prismatique au Maître mécanicien Castpipe, à Forgefer.", st = "Quand nous avons fui Gnomeregan, nous avons dû abandonner tant de données importantes !$B$BJ'ai besoin des données de la carte perforée prismatique d'une Matrice d'encodage 3005-D, dans Gnomeregan. C'est votre destination ; mais pour cela, vous devez d'abord accéder aux terminaux de modèles -A, -B et -C. Et ceci n'est possible qu'avec les cartes prismatiques, en commençant par les blanches... Et nous avons laissé toutes nos cartes dans la ville.$B$BPouvez-vous nous aider ?", t = "Sauvetage de données"},
    [2945] = {ot = "Trouver un moyen de nettoyer l'Anneau sali.", st = "Vous avez découvert, sur le corps d'un des nains Sombrefer, ce qui semble être un anneau. La crasse le recouvre entièrement, rendant difficile son identification et impossible son port. Il vous semble pouvoir discerner, sous les résidus, comme le chatoiement d'un métal précieux et l'éclat d'une gemme.$B$BSi vous voulez utiliser cet anneau, il vous faudra trouver un moyen de nettoyer la saleté qui le souille.", t = "Anneau sali"},
    [2947] = {ot = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres.", st = "En ouvrant la boîte, vous trouvez ce à quoi vous vous attendiez : un anneau scintillant, comme flambant neuf ! Dès que vous l'enfilez, vous sentez une vague de puissance magique traverser votre corps.$B$BDans la face intérieure de l'anneau, vous voyez le poinçon de Forgefer, accompagné de trois petites initiales gravées : \"TdK\". Ce peuvent être celles du précédent propriétaire de l'anneau ou celles de son artisan. Garder l'anneau... ou le rendre à qui il appartient. Difficiles décisions, en vérité...", t = "Le retour de l'anneau"},
    [2948] = {ot = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Talvash del Kissel, à Forgefer.", st = "Écoutez, $n, cet anneau vous appartient mais je peux l'améliorer. Sa forme est très simple et j'ai beaucoup progressé depuis. Pour la modique somme de trente pièces d'argent, je lui donnerai de nouveaux atours... bon, un peu plus de trente pièces, car je suis un peu gêné financièrement, en ce moment.$B$BTous mes stocks de matériaux sont épuisés ; si vous m'apportez une barre d'argent et une agate mousse, je pourrai ajouter un treillis de perles et d'argent qui donnera à cet anneau un sacré coup de fouet !$B$BFaites-moi confiance !", t = "Amélioration gnomique"},
    [2949] = {ot = "Garder l'anneau ou retrouver la personne qui y a gravé les lettres.", st = "En ouvrant la boîte produite par le Décapeur 5200, vous découvrez un anneau scintillant. Quand vous le passez à votre doigt, vous sentez une incroyable vague de puissance magique traverser votre corps.$B$BDans la face intérieure de l'anneau, vous pouvez voir le petit poinçon d'Orgrimmar à côté duquel les trois premières lettres gravées d'un mot sont visibles : \"NOG...\"$B$BCe sont peut-être les initiales de l'ancien propriétaire de l'anneau ou de son fabricant. Garder l'anneau... ou retrouver \"NOG\" - difficile décision, en vérité...", t = "Le retour de l'anneau"},
    [2950] = {ot = "Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Nogg, à Orgrimmar.", st = "Non, non, non, je ne suis pas en train de dire que cet anneau est à moi. Cependant, votre information sur les Sombrefer fut très utile. J'améliorerai cet anneau pour vous, bien mieux que ne le pourrait celui qui a forgé cette pauvre petite chose... sans doute un gnome, d'ailleurs...$B$BSi vous m'apportez une barre d'argent, une agate mousse et trente pièces d'argent, je pourrai ajouter un treillis de perles et d'argent qui donnera une ampleur toute nouvelle à la magie contenue dans cet anneau. Cela vous intéresse ?", t = "Nogg améliore l'anneau"},
    [2951] = {ot = "Insérer un Objet sali dans le Décapeur 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine.", st = "L'étrange objet est là, au milieu des gnomes. Une petite plaque sur la machine indique : \"Décapeur 5200\", suivit d'un texte :$B$B\"La crasse et les résidus ruinent vos objets ? Le Décapeur 5200 est l'outil qu'il vous faut pour restaurer toute la brillance et l'éclat qu'ils méritent. Veuillez placer l'objet à décaper dans la machine, ainsi que trois pièces d'argent dans la fente prévue à cet effet et attendez un petit moment : vos objets de valeur en sortiront comme neufs\"", t = "Le Décapeur 5200 !"},
    [2952] = {t = "Le Décapeur 5200 !"},
    [2962] = {ot = "Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.$B$BAprès le travail, conserver la Flasque plombée lourde, pour Ozzie.", st = "Votre échantillon n'était pas seulement insuffisant, mais impur.$B$BNous avons besoin de plus de Lueur verte. Les troggs ne sont apparemment pas encore assez irradiés. Vous devrez aller à Gnomeregan et rapporter de la matière radioactive, prélevée à la source. Je parle bien sûr de toutes ces gelées, rôdeurs et autres horreurs irradiées qui errent là-bas. Attention, la collecte et le conditionnement de telles matières est difficile ; il vous faudra faire plusieurs tentatives avant qu'un échantillon valable soit prélevé.", t = "Encore plus de Lueur verte !"},
    [2983] = {ot = "Trouver Kranal Fiss dans les Tarides.", st = "Cela fait quelque temps que vous n'avez pas été $gmis à l'épreuve:mise à l'épreuve;, $n. Vous avez fait preuve de patience dans vos études jusque-là, mais il est temps pour vous d'apprendre de plus grands pouvoirs… il est temps d'apprendre le réel pouvoir. L'élément de feu vous appartient si vous êtes $gprêt:prête; à payer pour cela.$B$BRecherchez Kranal Fiss dans les Tarides. Il réside dans une petite demeure au nord de la Croisée, mais faites attention ; si vous atteignez les terres de ces maudits elfes, c'est que vous êtes $gallé:allée; trop loin.", t = "L'appel du feu"},
    [2984] = {ot = "Trouver Kranal Fiss dans les Tarides.", st = "Cela fait longtemps que vous n'avez pas été $gmis à l'épreuve:mise à l'épreuve;, $n. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent arrivé d'apprendre la destruction et le chaos. L'élément Feu peut vous appartenir, si vous êtes $gprêt:prête; à en payer le prix.$b$bRecherchez Kranal Fiss dans les Tarides. Il vit dans une petite demeure au nord de la Croisée, mais faites attention, si vous atteignez les terres des elfes de la nuit, c'est que vous êtes $gallé:allée; trop loin.", t = "L'appel du feu"},
    [2998] = {ot = "Parler à Duthorian Rall à Stormwind.", st = "Salutations ! Duthorian Rall, l'un de nos paladins les plus influents, parlait de vous récemment. Je l'ai entendu dire qu'il était temps que vous soyez $gmis:mise; à l'épreuve... Ainsi que des compliments vous concernant.$B$BJe vous conseille de vous rendre à Stormwind et de lui parler. Je pense que vous le trouverez dans la cathédrale de la Lumière, où il passe le plus clair de son temps.", t = "Le Tome de divinité"},
    [2999] = {ot = "Parler à Tiza Battleforge, à Forgefer.", st = "Bonjour, $n. Je sais que vous êtes très $goccupé:occupée; à aider les gens de Dun Morogh, mais si vous avez le temps, allez jusqu'à Forgefer pour parler à la vénérable Tiza Battleforge. Les plus jeunes de nos paladins vont la voir lorsqu'ils veulent en apprendre plus sur la Lumière et sur leurs obligations.", t = "Le Tome de divinité"},
    [3065] = {ot = "Lire la Tablette simple, et parler à Frang, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l’extérieur de l’Antre, dissimulé dans l’ombre.", t = "Tablette simple"},
    [3082] = {ot = "Parler à Jen'shan dans la Vallée des épreuves", st = "Ah, pendant votre absence, on a apporté une tablette pour vous, $n.$B$BLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chasseurs, Jen'shan. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette gravée"},
    [3083] = {ot = "Lire la Tablette codée, et parler à Rwag, dans la Vallée des épreuves.", st = "Ah, pendant votre absence, on a apporté une tablette pour vous, $n.$B$BLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des voleurs, Rwag. Il souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette codée"},
    [3084] = {ot = "Parler à Shikrik dans la Vallée des épreuves.", st = "Ah, pendant votre absence, on a apporté une tablette pour vous, $n.$B$BLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chamans, Shikrik. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette runique"},
    [3085] = {ot = "Lire la Tablette bénie, et parler à Ken'jai, à l’extérieur de l’Antre, dans la Vallée des épreuves.", st = "Ah, pendant votre absence, on a apporté une tablette pour vous, $n.$B$BLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des prêtres, Ken'jai. Il souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette bénie"},
    [3086] = {ot = "Lire la Tablette glyphée, et parler à Mai'ah, près de l’entrée de l’Antre, dans la Vallée des épreuves.", st = "Ah, pendant votre absence, on a apporté une tablette pour vous, $n.$B$BLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des mages, Mai'ah. Elle souhaiterait s'entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette glyphée"},
    [3087] = {ot = "Lire le Parchemin gravé, et parler à Jen'shan, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chasseurs, Jen'shan. Elle souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Parchemin gravé"},
    [3088] = {ot = "Lire le Parchemin codé, et parler à Rwag, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des voleurs, Rwag. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Parchemin codé"},
    [3089] = {ot = "Lire le Parchemin runique, et parler à Shikrik, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chamans, Shikrik. Elle souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Parchemin runique"},
    [3090] = {ot = "Lire le Parchemin contaminé, et parler à Nartok, à l’intérieur de l’Antre, dans la Vallée des épreuves.", st = "Ah, pendant que vous n’étiez pas là un parchemin est arrivé pour vous, $n.$B$BJ’évite normalement de traiter avec des démonistes, si c’est possible, mais je pense que vous devriez le lire, quand vous en aurez le temps. Si je ne me trompe pas, il provient du maître qui vous a été récemment assigné, Nartok. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Parchemin contaminé"},
    [3091] = {ot = "Lire la Note simple, et parler à Harutt Thunderhorn, à Camp Narache.", st = "Il y a quelques instants, une messagère était à votre recherche, $n. Je crois qu’elle était envoyée par le Maître des guerriers, Harutt. Si ce message est bien de Harutt, je ne tarderais pas à le lire, à votre place.", t = "Note simple"},
    [3092] = {ot = "Lire la Note gravée, et parler à Lanka Farshot, sur la Mesa de Nuage rouge.", st = "Il y a quelques instants, une messagère était à votre recherche, $n. Je crois qu'elle était envoyée par le Maître des chasseurs, Lanka. Si ce message est bien de Lanka, je ne tarderais pas à le lire, à votre place.", t = "Note gravée"},
    [3093] = {ot = "Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache.", st = "Il y a quelques instants, une messagère était à votre recherche, $n. Je crois qu'elle était envoyée par le Maître des chamans, Meela. Si ce message est bien de Meela, je ne tarderais pas à le lire, à votre place.", t = "Note runique"},
    [3094] = {ot = "Lire la Note verdoyante, et parler à Gart Mistrunner, à Camp Narache.", st = "Il y a quelques instants, une messagère était à votre recherche, $n. Je crois qu’elle était envoyée par le Maître des druides, Gart. Si ce message est bien de Gart, je ne tarderais pas à le lire, à votre place.", t = "Note verdoyante"},
    [3095] = {ot = "Lire le Parchemin simple, et parler à Dannal Stern, au Glas.", st = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des guerriers, Dannal. À votre place, je prendrais le temps de le lire avant de repartir.", t = "Parchemin simple"},
    [3096] = {ot = "Lire le Parchemin codé, et parler à David Trias, au Glas.", st = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des voleurs, David Trias. À votre place, je prendrais le temps de le lire avant de repartir.", t = "Parchemin codé"},
    [3097] = {ot = "Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l’église du Glas.", st = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des prêtres, Duesten. À votre place, je prendrais le temps de le lire avant de repartir.", t = "Parchemin béni"},
    [3098] = {ot = "Lire le Parchemin glyphé, et parler à Isabella, dans l’église du Glas.", st = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des mages, Isabella. À votre place, je prendrais le temps de le lire avant de repartir.", t = "Parchemin glyphé"},
    [3099] = {ot = "Lire le Rouleau contaminé, et parler à Maximillion, au Glas.", st = "Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu'il est de quelque importance, car il porte le sceau du Maître des démonistes, Maximillion. À votre place, je prendrais le temps de le lire avant de repartir.", t = "Rouleau contaminé"},
    [3100] = {ot = "Lire la Lettre simple et parler à Llane Beshere, à l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de Llane, notre Maître des guerriers local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", t = "Lettre simple"},
    [3101] = {ot = "Lire la Lettre consacrée, et parler à Frère Sammuel, à l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de frère Sammuel, notre Maître des paladins local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'abbaye.", t = "Lettre consacrée"},
    [3102] = {ot = "Lire la Lettre codée, et parler à Jorik Kerridan, dans l’écurie, derrière l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de Jorik, l'un de nos Maîtres locaux. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", t = "Lettre codée"},
    [3103] = {ot = "Lire la Lettre bénie, et parler à la prêtresse Anetta, à l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de la prêtresse Anetta, notre Maître des prêtres local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'abbaye.", t = "Lettre bénie"},
    [3104] = {ot = "Lire la Lettre glyphée, et parler à Kheldon Bremen, à l’intérieur de l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de Kheldon, notre Maître des mages local. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", t = "Lettre glyphée"},
    [3105] = {ot = "Lire la Lettre contaminée, et parler à Drusilla La Salle, à proximité de l’abbaye de Comté-du-Nord.", st = "On m'a demandé de vous remettre cela dès que vous seriez de retour des camps des kobolds, $n. Il s'agit d'une lettre portant le sceau de Druisilla, l'un de nos Maîtres locaux. À votre place, je n'hésiterais pas à la lire avant de faire quoi que ce soit d'autre, ici, dans l'Abbaye.", t = "Lettre contaminée"},
    [3106] = {ot = "Lire la Rune simple, et parler à Thran Khorman, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des guerriers, Thran. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Rune simple"},
    [3107] = {ot = "Lire la Rune consacrée, et parler à Bromos Grummner, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des paladins, Bromos. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Rune consacrée"},
    [3108] = {ot = "Lire la Rune gravée, et parler à Thorgas Grimson, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des chasseurs, Thorgas. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Rune gravée"},
    [3109] = {ot = "Lire la Rune codée, et parler à Solm Hargrin, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des voleurs, Solm. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Rune codée"},
    [3110] = {ot = "Lire la Rune bénie, et parler à Branstock Khalder, à Courbenclume.", st = "Pendant que vous m'aidiez, on m'a donné cette rune pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des prêtres, Branstock. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Rune bénie"},
    [3112] = {ot = "Lire la Note de service simple, et parler à Thran Khorman, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des guerriers, Thran. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Note de service simple"},
    [3113] = {ot = "Lire la Note de service codée, et parler à Solm Hargrin, dans la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des voleurs, Solm. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Note de service codée"},
    [3114] = {ot = "Lire la Note de service glyphée, et parler à Marryk Nurribit, dans Courbenclume, au-dessus de la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des mages, Marryk. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.", t = "Note de service glyphée"},
    [3115] = {ot = "Lire la Note de service contaminée, et parler à Alamar Grimm, dans Courbenclume, au-dessus de la Vallée des Frigères.", st = "Pendant que vous m'aidiez, on m'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu'elle provient du Maître des démonistes, Alamar. Jetez-y un coup d'oeil et allez le retrouver, à l'intérieur de Courbenclume, quand vous en aurez le temps.$B$BEt faites attention, $n, on n'apprécie pas trop votre espèce, sur ces terres.", t = "Note de service contaminée"},
    [3116] = {ot = "Lire le Sceau simple, et parler à Alyissia, à Sombrevallon.", st = "Ce sceau m'a été donné par un messager de notre Maître des guerriers, Alyissia. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", t = "Sceau simple"},
    [3117] = {ot = "Lire le Sceau gravé, et parler à Ayanna Everstride, au sommet d'Aldrassil, dans Sombrevallon.", st = "Ce sceau m'a été donné par un messager de notre Maître des chasseurs, Ayanna. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", t = "Sceau gravé"},
    [3118] = {ot = "Lire le Sceau codé et parler à Frahun Shadewhisper, à Sombrevallon.", st = "Ce sceau m'a été donné par un messager de notre Maître des voleurs, Frahun. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", t = "Sceau codé"},
    [3119] = {ot = "Lire le Sceau béni, et parler à Shanda, à Aldrassil.", st = "Ce sceau m'a été donné par un messager de notre maître des prêtres, Shanda. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", t = "Sceau béni"},
    [3120] = {ot = "Lire le Sceau verdoyant, et parler à Mardant Strongoak, dans l'arbre Aldrassil de Sombrevallon.", st = "Ce sceau m'a été donné par un messager de notre maître des druides, Mardant. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez-le et rapportez-le-lui.", t = "Sceau verdoyant"},
    [3221] = {ot = "Parler à l'apothicaire Renferrel au Sépulcre.", st = "Tandis que vous étiez en train d'aider nos Traqueurs noirs, l'apothicaire Renferrel vous a fait appeler. Il n'a rien précisé mais a dit qu'il voulait vous parler à propos des coeurs de loup que vous lui aviez donnés.", t = "Parler à Renferrel"},
    [3261] = {ot = "Parler à Jorn Skyseer, à Camp Taurajo.", st = "Nos routes se séparent, $n. Pour en apprendre plus, vous devrez aller au Camp Taurajo, vers le sud et parler à Jorn Skyseer. Il continuera de vous guider.", t = "Jorn Skyseer"},
    [3281] = {ot = "Rapportez l'Argent volé à Gazrog à la Croisée.", st = "Vous avez peut-être tué les raptors, mais l'argent qu'ils ont volé doit être récupéré ! Des rapports indiquent que les raptors ont un important site de nidification au sud de Ratchet. Cet endroit est connu sous le nom de Terres des raptors. Il est probable qu'ils y aient apporté notre argent volé.$B$BAllez dans ce repaire de raptors et cherchez-le. Quand vous l'aurez trouvé, rapportez-le-moi.", t = "Argent volé"},
    [3301] = {ot = "Parler à Mura Runetotem au Sépulcre.", st = "Ma camarade de clan, Mura Runetotem, est partie pour les Pins argentés afin d'aider nos alliés morts-vivants. C'est une forêt qui dépérit doucement, et elle avait l'espoir d'y insuffler la vie à nouveau. Peut-être que la vie insolite que nous trouvons ici dans les Tarides l'aiderait à réaliser ses souhaits pour les Pins argentés ?$B$BPrenez avec vous une des carapaces que vous avez apportées, et donnez-la à Mura Runetotem aux Pins argentés. Elle séjourne au Sépulcre. Avec un peu de chance, l'étude de cette carapace l’aidera à trouver une solution pour guérir cette forêt à l'agonie.", t = "Mura Runetotem"},
    [3361] = {ot = "Apporter la Boîte de Felix, le Coffre de Felix et le Seau de boulons de Felix à Felix Whindlebolt, à Courbenclume.", st = "Nous avons chassé les troggs de Gnomeregan, mais c'est devenu catastrophique depuis ! Maintenant notre maison est complètement irradiée et nous, les gnomes, nous avons été dispersés dans tout Dun Morogh.$B$BDans ma hâte de fuir les radiations, j'ai perdu toutes mes affaires personnelles et mes outils. Ce sont les trolls qui les ont pris. Ils ont volé mon coffre, ma boîte et mon seau de boulons ! Ils les ont emportés dans leur camp au sud-ouest de Courbenclume.$B$BJe ne suis pas un aventurier… Pourriez-vous retrouver mes affaires et me les rapporter ici, s'il vous plaît ?", t = "Les malheurs d'un réfugié"},
    [3364] = {ot = "Apporter un Thé brûlant à Durnan Furcutter, dans Courbenclume, dans les cinq minutes imparties avant qu'il ne refroidisse !", st = "Ah ! Je devais apporter un Thé brûlant à Durnan Furcutter, à Courbenclume, mais je dois d’abord en porter un à Grelin. Je n'arriverai jamais à Courbenclume avant qu'il ne refroidisse !$B$BVous m’avez l'air rapide. Vous pouvez le faire. Cette boisson ne restera chaude que 5 minutes et Durnan n'a pas commandé un Thé \"glacé\", alors partez tout de suite. Courbenclume est un village dans la montagne, au nord-est.$B$BMerci, $n, et n'oubliez pas de me rapporter ma tasse !", t = "Une livraison de thé brûlant"},
    [3365] = {ot = "Apporter la Chope de Nori à Nori Pridedrift.", st = "Ah ! Vous êtes $garrivé:arrivée; à point nommé ! Rien de tel qu'un bon thé chaud, non, BRULANT, par une froide journée d'hiver pour réchauffer les méandres de votre esprit.$B$BTenez, $n, soyez assez aimable pour rapporter cette tasse vide à Nori pour moi, voulez-vous ?", t = "Rapporter la Tasse"},
    [3369] = {ot = "Apporter l'Eclat de cauchemar à Hamuul Runetotem à la Cime des Anciens.", st = "Cet éclat détient de grands secrets. Il s'agit de l'essence pure du Rêve d'émeraude. Ce que je vois dans cet éclat n'a rien d'un rêve cependant. On pourrait même appeler cela une vision de cauchemar.$B$BMon but n'est pas de vous alarmer, $n, mais je crois qu'il serait mieux pour vous de remettre cet éclat à un grand druide, et ce le plus tôt possible.$B$BLa personne que vous devriez rencontrer à la Cime des Anciens se nomme Hamuul Runetotem. Partez pour Thunder Bluff. Je ne peux pas vous en dire plus.", t = "Au coeur des cauchemars"},
    [3370] = {ot = "Apporter l'Eclat de cauchemar à Mathrengyl Bearwalker à Darnassus.", st = "Cet éclat détient de grands secrets. Il s'agit de l'essence pure du Rêve d'émeraude. Ce que je vois dans cet éclat n'a rien d'un rêve cependant. On pourrait même appeler ce genre de vision un cauchemar.$B$BMon souhait n'est pas de vous alarmer, $n, mais je crois qu'il serait mieux pour vous de remettre cet éclat aux mains d'un grand druide, et ce dès que vous le pouvez.$B$BLa personne que vous devez trouver au Cercle cénarien se nomme Mathrengyl Bearwalker. Partez pour Darnassus. Je ne peux vous en dire plus.", t = "Au coeur des cauchemars"},
    [3376] = {ot = "Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge.", st = "$n, j'ai entendu parler de vous. Peut-être saurez-vous nous venir en aide là où d'autres ont échoué.$B$BNous, taurens, avons fait de cette terre notre foyer. Mais cela n'a pas été sans pertes. Les hurans Dos-hirsute, du ravin de Roncelame, menés par leur chef Brochaigu Mantépine, nous accablent sans cesse. Je vous demande de me rapporter la tête de leur chef !$B$BVous pourrez le trouver dans le ravin, à l'est, dans leur village de fortune.", t = "La fin de Brochaigu !"},
    [3519] = {ot = "Parler à Dirania Silvershine, à Sombrevallon.", st = "Ahhh... J'ai été mordu par une araignée nommée Githyiss la Vile en explorant sa caverne, tout près d'ici. Une grande quantité de poison m'a été injectée ; vous devez m'aider.$B$BPrévenez Dirania Silvershine. Elle sera capable de me secourir.$B$BVite... J'ai des vertiges de plus en plus alarmants...", t = "Un ami dans le besoin"},
    [3521] = {ot = "Trouver 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d'araignée Tissebois pour Dirania Silveshine dans Sombrevallon.", st = "Nous allons pouvoir aider Iverron, je connais un antidote qui devrait combattre le poison. Il me faut cependant quelques ingrédients.$B$BJe vais avoir besoin de Champignons jacinthe. Vous pouvez en trouver sous les arbres, ou chez les grells au sud ; ils ont l'air de les aimer. J'aurai aussi besoin de Lys pétales de lune, qui ne poussent qu'autour des points d'eau.$B$BLe dernier ingrédient sera plus difficile à trouver. Il me faut de l'ichor de ces mêmes araignées sylvestres qui ont empoisonné Iverron.", t = "Antidote d'Iverron"},
    [3522] = {ot = "Apporter l’Antidote d'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord.", st = "L'antidote est prêt, $n. Faites en sorte qu'Iverron le boive.$B$BVous devez savoir une chose : l'antidote ne reste efficace que pendant 5 minutes. Vous devez le lui apporter à temps.$B$BQue la vitesse soit avec vous, $n.", t = "Antidote d'Iverron"},
    [3524] = {ot = "Récupérer des Os de créature marine sur la créature échouée, au sud d’Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine.", st = "De majestueuses créatures marines se jettent sur le littoral de Sombrivage, où elles restent échouées jusqu’à leur mort. Dernièrement, le nombre de ces bêtes n’a cessé d’augmenter. C’est le temple de la Lune qui m’envoie pour enquêter, mais la présence des murlocs, sur le littoral, a freiné mes recherches.$B$BIl y a une créature géante échouée au sud d’Auberdine, et beaucoup de ces maudits murlocs Grisebrume aux alentours. Pourriez-vous aller récupérer des os sur la carcasse de cette créature ? Ils nous serviront pour nos études.", t = "Echouage"},
    [3741] = {ot = "Trouver le Collier d'Hilary et le rapporter à Hilary à Comté-du-Lac.", st = "Mon amie Hilary a perdu son collier, et nous ne parvenons pas à le retrouver. Nous avons pêché toute la journée ici, et nous avons déjà cherché aux alentours. Je crois qu'il est tombé dans le lac. Nos parents ne veulent pas que nous y nagions... Ma maman dit qu'il y a des choses méchantes sous l'eau. Mais vous n'avez pas l'air d'avoir peur des choses méchantes.$B$BVous pouvez retrouver son collier, s'il vous plaît ?", t = "Le collier d'Hilary"},
    [3765] = {ot = "Aller voir Gershala Nightwhisper à Auberdine.", st = "Stormwind. Tellement bouillonnant d'activité !$B$BJe viens de loin pour chercher de l'aide. On dit que de courageux aventuriers foulent les rues de cette cité.$B$BMon frère, Gershala, a besoin d'aide a Sombrivage. Il demeure dans la ville côtière d'Auberdine.$B$BLe voyage est long et périlleux. C'est pourquoi je demande l'aide de $cs expérimentés.", t = "La dépravation au loin"},
    [3901] = {ot = "Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas.", st = "Vous avez montré vos capacités aux Réprouvés, dans des conditions normales, $n. À présent, voyons ce que vous pouvez faire lorsque vous êtes sous pression.$B$BLes squelettes Cliquethorax, d'autres sbires décérébrés du roi-liche, sont un peu plus résistants que les zombies auxquels vous avez fait face jusqu'alors. Réduisez leur nombre et démontrez votre appartenance aux Réprouvés. Quand vous aurez fini, ne vous attardez pas, revenez me voir.", t = "Faites cliqueter les thorax !"},
    [3902] = {ot = "Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain.", st = "Vous, là ! Si vous cherchez à vous rendre utile, écoutez bien !$B$BNous avons besoin de recrues fraîchement déterrées pour se rendre au Glas et rechercher tout équipement utile. Il est sûrement remisé dans des piles de boîtes. Nous attendons de nouvelles recrues mais, à moins que nous ne voulions les voir déambuler tout nus, nous ferions mieux de commencer à faire de la récupération !$B$BAllez-y, au travail, misérable sac d'os ! Et je ne récompenserai pas ceux qui n'y mettent pas d'ardeur.", t = "La chasse aux trésors"},
    [3903] = {ot = "Parler à Milly Osworth.", st = "Votre fiabilité est démontrée, $c. Vous n'avez pas peur de vous salir les mains, hein ?$B$BJ'ai une amie du nom de Milly Osworth, elle a un gros problème. Elle et son chariot se trouvent de l'autre côté de l'abbaye, près de l'étable. Je suis sûr que vos deux bras devraient lui être utiles, $n.", t = "Milly Osworth"},
    [3904] = {ot = "Apporter 8 seaux de la récolte de Milly à Milly Osworth à l’abbaye de Comté-du-Nord.", st = "Un gang de brigands, les Défias, s'est introduit dans le vignoble de Comté-du-Nord alors que je faisais les récoltes ! Je l'ai signalé aux gardes de Comté-du-Nord et ils m'ont assuré qu'ils faisaient le nécessaire, mais je crains le pire pour ma récolte de raisin ! Si les Défias ne la volent pas, les gardes pourraient l'écraser en poursuivant les voyous.$B$BAidez-moi, je vous en prie ! J'ai ramassé pratiquement tout mon raisin dans des seaux mais je les ai laissés dans le vignoble au sud est.$B$BRamenez-moi ces seaux ! Sauvez ma récolte !", t = "Les vendanges de Milly"},
    [3905] = {ot = "Apporter le Manifeste des vendanges à Frère Neals dans l’abbaye de Comté-du-Nord.", st = "À présent que mes vendanges sont sauvées, apportez ce Manifeste des vendanges à Frère Neals. Il s'occupe du magasin de nourriture et de boisson de Comté-du-Nord, et il est certain qu'il sera ravi d'apprendre que nous avons du raisin frais.$B$BVous trouverez Frère Neals dans la tour de l'abbaye. C'est là qu'il aime déguster son vin.", t = "Manifeste des vendanges"},
    [3921] = {ot = "Apporter le Samophlange cassé à Wenikee Boltbucket.", st = "Il se peut que j'aie cassé le Samophlange. Et ce n'est pas bon, car j'en avais déjà parlé à des collègues à Undermine et ils s'y intéressaient beaucoup. Nous devons trouver un moyen de le réparer !$B$BApportez le Samophlange à Wenikee Boltbucket, à l'avant-poste de la Horde entre les Tarides et Ashenvale. Elle est très intelligente et très curieuse. Si vous lui montrez le Samophlange, je suis sûr qu'elle sera enthousiaste à l'idée de le réparer.", t = "Wenikee Boltbucket"},
    [3922] = {ot = "Apporter 15 Rondelles de métal à Wenikee Boltbucket dans les Tarides.", st = "Je veux réparer ce Samophlange, mais pour ce faire je vais avoir besoin de certaines choses. Je n'ai plus de rondelles de dix-sept cinq et je vais en avoir besoin d'un sacré paquet pour le travail qui nous attend.$B$BL'endroit le plus proche où l'on peut s'en procurer est la Videfange, à l'est. La KapitalRisk en conserve généralement dans ses seaux d'outils. Partez pour la Videfange et cherchez les seaux d'outils qui s'y trouvent. Revenez me voir lorsque vous aurez récupéré suffisamment de Rondelles de métal", t = "Les Petites pièces"},
    [3923] = {ot = "Apporter le Samophlange cassé à Rilli Greasygob à Orgrimmar.", st = "Hmm, ça n'a pas marché. J'ai placé des jauges supplémentaires sur le Samophlange pour en mesurer l'intégrité structurelle, et elles donnent comme résultat une intégrité constante proche de zéro. Je pourrais ajouter d'autres cadrans et peut-être un ou deux leviers pour essayer de le réparer, mais... je crains que ça ne fasse qu'empirer les choses.$B$BVous devriez apporter le Samophlange à Rilli Greasygob. Il travaillait autrefois pour la KapitalRisk. Si quelqu'un est capable de le réparer, c'est bien Rilli.$B$BVous pourrez le trouver à l'Atelier de Nogg à Orgrimmar, dans la Vallée de l'Honneur.", t = "Rilli Greasygob"},
    [3924] = {ot = "Apporter le Manuel du Samophlange à Rilli Greasygob à Orgrimmar.", st = "Je pense pouvoir réparer le Samophlange, mais je vais avoir besoin du manuel d'utilisation tout d'abord. Lorsque je travaillais pour la KapitalRisk, j'avais un rival du nom de Chef Copperplug, qui connaissait des tas de secrets sur le Samophlange, et qui donnait quelques rares informations sur l'appareil à ceux envers qui il avait confiance. Je ne faisais pas partie des rares élus...$B$BLe Chef Copperplug était généralement à la mine des Pierriers dans la partie nord-est des Tarides. Parvenez à en obtenir le manuel, et s'il en a distribué des pages à quiconque, vous devrez également les récupérer.", t = "Manuel du Samophlange"},
    [4021] = {t = "La contre-attaque !"},
    [4161] = {ot = "Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar.", st = "Autrefois, les elfes de la nuit s’appelaient les kaldorei, ce qui veut dire \"les enfants des étoiles\". La connaissance du passé est une étape importante de votre cheminement de $c, $n, aussi écoutez attentivement ce que je vais vous dire.$B$BLes kaldorei ont toujours été très fiers de la relation harmonieuse qu'ils entretiennent avec la nature. Cela implique que nous ne prélevons chez elle que le nécessaire et que nous le restituons toujours. Cet équilibre nous est très bénéfique, $n.$B$BÀ présent sortez et prélevez sept petites pattes d'araignées – pas plus – puis revenez me voir.", t = "Une recette kaldorei"},
    [4402] = {t = "Surprise aux pommes de cactus de Galgar"},
    [4495] = {ot = "Trouver Iverron près de la grotte au nord.", st = "L'un de mes amis, nommé Iverron, me rend visite tous les jours à la même heure. Mais, chose étrange, il n'est pas encore venu aujourd'hui. En fait, il a plusieurs heures de retard.$B$BJe dois admettre que cela m'inquiète, $n. Iverron passe beaucoup de temps du côté de la grotte qui se trouve au nord. Vous savez certainement que c'est dangereux là-bas...des araignées, partout !$B$BSi jamais vous alliez dans cette direction, pourriez-vous jetez un oeil ?", t = "Un bon ami"},
    [4542] = {ot = "Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent.", st = "$gCourageux voyageur:Courageuse voyageuse;, les centaures ont intensifié leurs attaques dans les parages. Le Poste de Librevent doit être mis au courant de ces nouveaux assauts immédiatement ! Trouvez le garde-falaise Longhorn au Poste de Librevent, au sud-est, et faites-lui part de ce message urgent.$b$bSoyez sur vos gardes, évitez les membres du Totem sinistre qui se trouvent non loin d’ici... ils se comportent de façon étrange avec nous ces temps-ci.", t = "Un message pour le poste de Librevent"},
    [4581] = {ot = "Apporter la Note de Shindrell à Kayneth Stillwind au Chant des Forêts.", st = "Le druide Kayneth Stillwind m'a envoyé un message. Il veut savoir ce qui se passe sur notre côte et dans les forêts entourant Astranaar. Il craint que la corruption ne traverse Ashenvale… et il a raison.$B$BAllez, apportez-lui mon rapport. Vous le trouverez au sanctuaire de Chant des forêts, dans les Bois de Chantenuit à l'est.", t = "Kayneth Stillwind"},
    [4641] = {ot = "Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest.", st = "Vous avez maintenant l’âge de vous battre au nom de la Horde, $n, et de faire des conquêtes pour le Chef de guerre.$B$BOui...$B$B<Kaltunk vous considère.>$B$BVous vous en sortirez très bien.$B$BJe ne doute pas que vous aspiriez à trouver un grand dragon ou un démon et de les étrangler à mains nues, mais il serait plus sage de commencer par quelque chose de moins redoutable....$B$B<Kaltunk rit.>$B$BAllez voir Gornek, il sera en mesure de vous assigner une mission plus adaptée à quelqu’un de votre âge, $c. Vous trouverez Gornek dans l’Antre, plus à l’ouest.", t = "Votre place en ce monde"},
    [4681] = {ot = "Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l’ouest d’Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine.", st = "Cette créature échouée n’est pas un incident isolé, ici à Sombrivage. Il y en a plus le long de la côte et même dans l’eau. Je voudrais que vous alliez étudier un autre de ces cas dans les eaux à l’ouest d’Auberdine, non loin d’un navire englouti. Revenez avec tout ce que vous aurez pu récupérer qui nous aiderait dans nos recherches.$B$BDe même, pendant vos voyages, vous pourriez tomber sur d’autres créatures. Bien sûr, si vous deviez découvrir quoi que ce soit, vous n’oublieriez pas de nous en faire part !", t = "Échouage"},
    [4722] = {ot = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", st = "Vous trouvez le cadavre d’une tortue de mer qui s’est échouée sur la côte de Sombrivage, il y a quelque temps. les murlocs ont établi un campement autour de la créature et ont mis la main sur ses restes. Il apparaît cependant qu’il subsiste quelques échantillons valables à prélever sur la dépouille ; et Gwennyth Bly'Leggonde, à Auberdine, pourrait en avoir l’usage.", t = "La tortue de mer échouée"},
    [4723] = {ot = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", st = "Les restes d’un batteur gigantesque, bien plus grand que ceux qu'on s'attendrait à trouver à Sombrivage, gisent, échoués sur la côte de la Lisière des brumes. La présence de cette créature à cet endroit est un mystère ; les murlocs qui festoient sur la carcasse semblent bien trop faibles pour avoir chassé et abattu la bête tout seuls.$B$BIl reste suffisamment à prélever sur la dépouille pour en rapporter un échantillon que Gwennyth Bly'Leggonde, à Auberdine, pourrait étudier.", t = "La créature marine échouée"},
    [4725] = {ot = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.", st = "D’autres restes de tortue gisent, échoués le long de la côte. Cette dépouille a une espèce de chariot attaché à sa carapace. Il semble que la créature ait été conduite sur le littoral et qu’elle ne se soit pas échouée, à la différence des autres. Les murlocs Grisebrume habitent maintenant les restes de cette créature, se régalant sur la carcasse.$B$BDans le chariot, vous trouvez une boîte avec d’étranges inscriptions ; peut-être Gwennyth Bly'Leggonde, à Auberdine, pourrait comprendre de quoi il s'agit.", t = "La tortue de mer échouée"},
    [4727] = {ot = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", st = "Les restes d’une tortue de mer gisent sur le sable des plages du nord de Sombrivage. Les murlocs Grisebrume n'ont peut-être pas encore repéré cette carcasse ; ou alors, ils l'ont rejetée pour quelque étrange raison. Il subsiste néanmoins de quoi prélever un échantillon et le rapporter à Gwennyth Bly'Leggonde, à Auberdine, afin que ceux du temple de la Lune puissent l’étudier.", t = "La tortue de mer échouée"},
    [4728] = {ot = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", st = "La dépouille de ce qui semble être un immense mammifère marin gît, éviscérée, sur la plage. Une brouette et divers outils traînent, abandonnés, à côté de cette énorme bête échouée, comme si quelqu’un avait tenté d’en faire l’autopsie. Bien que les murlocs aient dépouillé la créature, il reste possible de prélever sur elle les échantillons qui intéressent Gwennyth Bly'Leggonde, à Auberdine.", t = "La créature marine échouée"},
    [4730] = {ot = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", st = "La carcasse à moitié dévorée de ce qui a été un mammifère géant gît sur la plage. Une bande de murlocs, plus forts que ceux qui étaient près d’Auberdine, vivent auprès des restes de la créature. Il subsiste cependant de quoi prélever sur les os de la créature des échantillons qui pourraient être apportés à Gwennyth Bly'Leggonde, à Auberdine.", t = "La créature marine échouée"},
    [4731] = {ot = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.", st = "Un autre tas de restes de tortue de mer gît, échoué, sur le littoral. Un chariot est attaché à la carapace de la tortue. Peut-être cette créature a-t-elle été conduite sur le littoral par quelqu’un et ne s'est-elle pas échouée, à la différence des autres. Les puissants murlocs Grisebrume ont fait de la carcasse leur habitation.$B$BDans le chariot, vous trouvez une boîte avec d’étranges inscriptions ; peut-être Gwennyth Bly'Leggonde, à Auberdine, pourra-t-elle les déchiffrer.", t = "La tortue de mer échouée"},
    [4732] = {ot = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.", st = "Vous trouvez le cadavre d’une tortue de mer qui s’est échouée sur la côte de Sombrivage, il y a quelque temps. Les murlocs Grisebrume ont nettoyé la carcasse et campent maintenant autour des restes de la créature. Il apparaît cependant qu’il subsiste quelques échantillons valables à prélever sur la dépouille. Gwennyth Bly'Leggonde, à Auberdine, pourrait en avoir l’usage.", t = "La tortue de mer échouée"},
    [4733] = {ot = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.", st = "Les restes de ce qui semble être un batteur géant ont échoué dans la crique rocheuse du Rivage du Crépuscule. Ce Frappeur est bien plus grand que la plupart des Frappeurs de la région. D'où qu'elle vienne, cette créature ne semble pas être native de Sombrivage.$B$BBien qu'il ne reste que des morceaux de la créature, il y a suffisamment de matière pour obtenir un échantillon correct pour Gwennyth Bly'Leggonde d'Auberdine.", t = "La créature marine échouée"},
    [4740] = {ot = "Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.$B$BAnnoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine.", st = "Votre attention !$B$BUne récompense est offerte pour la mort du murloc \"Fondeboue\". Cette bête immonde est au moins responsable de la mort d'une Sentinelle et du sabordage de deux navires de fret, dans les eaux de Sombrivage !$B$BFondeboue a été aperçu en dernier dans un camp murloc au sud d’Auberdine, et l’on pense qu’il est là pour protéger ce camp. Tous ceux qui veulent réclamer la récompense doivent le faire auprès de la Sentinelle Glynda Nal'Shea, à Auberdine.$B$BLe conseil d'Auberdine", t = "On recherche : Fondeboue !"},
    [4761] = {ot = "Parler à Thundris Windweaver, à Auberdine.", st = "Thundris Windweaver doit être averti du résultat de votre reconnaissance au camp furbolg. C’est l'un des anciens d’Auberdine qui aide à régler les affaires courantes du village. Allez lui faire part de vos découvertes sur la situation des furbolgs.$B$BIl sait certainement pourquoi ils ont été corrompus. Peut-être pourriez-vous travailler avec lui au rétablissement de l'équilibre naturel à cet endroit !", t = "Thundris Windweaver"},
    [4762] = {ot = "Aller au nord d’Auberdine, à la première chute d’eau, le long de la Bondissante et prélever un échantillon de l’eau de l’étang.$B$BRetourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante.", st = "La Bondissante est en train de se corrompre. Ce fleuve se déverse dans la Lisière des brumes, et je crains qu’il ne contamine bientôt Auberdine. Je soupçonne les furbolgs Noirbois, qui se trouvent plus haut sur le fleuve, d’être la cause de de cette infection ; bien que je ne pense pas qu’ils en soient les vrais responsables.$B$BPrenez ce tube de prélèvement et allez à l'embouchure de la rivière, au nord. Marchez jusqu’à la première cascade et faites un prélèvement d'eau sur place. Vous verrez un pont au-dessus de vous. Une fois le prélèvement effectué, revenez me voir à Auberdine.", t = "La Bondissante"},
    [4763] = {ot = "Remplir le Bol de purification vide au Puits de lune d’Auberdine.$B$BCollecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.$B$BMélanger les échantillons de nourriture à l’eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.$B$BPrendre son Talisman de corruption et l'apporter à Thundris Windweaver, à Auberdine.", st = "Les satyres sont une des sources de la corruption des furbolgs. Leur joug est assuré par des talismans qui leur servent à canaliser de la magie. Pour sauver les furbolgs, nous devons arracher son talisman au satyre corrupteur !$B$BRemplissez ce bol avec de l'eau puisée dans notre Puits de lune et collectez des échantillons de nourriture furbolg, dans leur camp, au nord. Mélangez-les à l’eau du puits et placez-les près du feu, à la rivière ; tous les furbolgs qui en mangeront seront désinfectés assez longtemps pour attirer le satyre hors de sa retraite ; et vous pourrez le tuer !", t = "La corruption des Noirbois"},
    [4767] = {ot = "Apporter 10 Oeufs de wyverne de Haut-perchoir à Elu au poste de Librevent.", st = "On m’a chargé de recruter davantage de wyvernes pour les Maîtres des Cavaliers célestes. Leur nombre grossit et j’espère moi-même un jour devenir un Cavalier céleste. Cependant, nous n’arrivons pas à dresser assez de wyvernes pour faire face à la demande. Peut-être pouvez-vous m’aider, $n.$B$BJ’aurais besoin que vous vous rendiez à Haut-perchoir pour ramasser d’autres oeufs de wyverne. En partant d’ici, dirigez-vous vers le nord-ouest le long des murs du canyon vers une épaule qui vous mènera jusqu’à Haut-perchoir. Prenez garde, les wyvernes protègent farouchement leurs oeufs et ne font pas de quartier aux intrus.", t = "Le cavalier céleste"},
    [4770] = {ot = "Escorter Pao'ka Swiftmountain à partir de Haut-perchoir, puis parler à Motega Firemane au poste de Blanc-relais.", st = "Je vous en prie, aidez-moi, $c ! Cela fait un moment déjà que je me cache dans Haut-perchoir et je n’ai pas vu d’êtres amicaux depuis des jours. Je suis venu ici pour étudier les wyvernes et je crois que je me suis approché d’un peu trop près. Après avoir été chassé d’un des nids, je me suis perdu.$B$BIl faut que je retourne au poste de Blanc-relais ! Motega ne sais pas que je suis parti et sera furieux d’apprendre que je me suis aventuré seul dans Haut-perchoir.$B$BLe poste de Blanc-relais est juste à l’est d’ici... je vous en prie, ramenez-moi là-bas !", t = "Vers le pays natal"},
    [4811] = {ot = "Voyager en direction de l’est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.", st = "Des séléniens hostiles se massent toujours en plus grand nombre à l'est. Nous croyions autrefois qu'il s'agissait de créatures inoffensives, et presque mystiques. Bien que certains continuent à leur porter révérence, la sécurité d'Auberdine me force à considérer les choses de manière plus réaliste.$B$BJ'ai reçu divers rapports m'informant que les séléniens étaient attirés par un grand cristal rouge le long de la chaîne de montagnes à l'est de Sombrivage. Personne ne sait ce qu'est ce cristal, ou même s'il existe vraiment. Je veux que vous le localisiez et que vous me rapportiez vos découvertes.", t = "Le cristal rouge"},
    [4812] = {ot = "Remplir le Tube d'eau vide au Puits de lune d’Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l’est de Sombrivage.", st = "Servez-vous de cette fiole vide et remplissez-la à l'un des Puits de Lune ici, à Auberdine. Une magie si puissante devrait fournir un indice quant à la composition du cristal. Pour ce faire, vous verserez le liquide dessus. Il devrait s'occuper du reste.$B$BBien que je ne pense pas que quoi que ce soit de mauvais puisse vous arriver, je souhaite tout de même que vous agissiez avec prudence. Au-dessus de nous, à l'est, se trouve Gangrebois. Si ce cristal est lié à cet endroit comme je le suspecte, alors il pourrait être très dangereux.", t = "Comme l'eau tombe en cascade"},
    [4813] = {ot = "Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.", st = "L'eau du Puits de Lune a révélé que quelques petits fragments d'os ainsi que la moitié d'un maxillaire sont incrustés à l'intérieur du cristal. Le maxillaire semble appartenir à un humanoïde, mais il est impossible de s'en assurer sans briser le cristal, un exploit que même la plus puissante des magies considèrerait comme quasiment impossible.$B$BCette tâche accomplie, tout ce qu'il reste à faire est de retourner informer la Sentinelle Glynda Nal'Shea à Auberdine.", t = "Les fragments à l'intérieur"},
    [4821] = {ot = "Rapporter l'Oeuf étrange à Hagar Lightninghoof au Poste de Librevent.", st = "Il y a une rumeur qui circule à propos d'un oeuf étrange ici aux Mille pointes. Ceux qui disent avoir vu cet oeuf n'ont pas réussi à s'en rapprocher assez pour pouvoir l'examiner minutieusement. Des serpents le gardent comme si c'était le leur.$B$BJe veux que vous recherchiez cet oeuf étrange et que vous me le rapportiez afin que je puisse l'examiner. Certains disent que l’oeuf se trouve dans un nid de serpents, mais il y en a plusieurs le long du bas des falaises au sud et au nord-ouest du Poste de Librevent.", t = "L'oeuf étrange"},
    [4841] = {ot = "Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longhorn au Poste de Librevent.", st = "$n, je vous en supplie, chassez ces centaures. Ils vont sentir la force de notre revanche. Attaquez le camp de centaures au nord du Poste de Librevent ! Laissez la colère guider votre main !", t = "Pacifier les centaures"},
    [4865] = {ot = "Faire un rapport de vos trouvailles à Motega Firemane.", st = "Si je n'avais pas vu ça de mes propres yeux, je ne l'aurais jamais cru. La vengeance s'abat sur les Mille pointes !$B$B<Hagar essuie son front.>$B$B$n, Vous devez agir vite ! Partez maintenant et cherchez Motega Firemane, il est au Poste de Blanc-relais, au nord-ouest du Poste de Librevent. Il saura quoi faire !", t = "Serpent sauvage"},
    [4881] = {ot = "Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace.", st = "Le tauren Kanati Greycloud est audacieux pour oser installer un camp de chasse aux Mille pointes. Nous devons le tuer pour nous débarrasser de ce camp et de tous ceux qui le suivraient. Allons vers le petit poste au sud ouest de la Grande élévation.", t = "Complot d'assassinat"},
    [4904] = {ot = "Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent.", st = "Arnak pense que nous allons nous marier… Mais après mon refus, il est revenu pendant la nuit et m'a kidnappée. Mon frère a essayé de l'arrêter, mais Arnak était trop fort. Il… il a tué mon frère puis m'a ramenée ici. Mon pauvre frère…$B$B$n, pourriez-vous me faire sortir de la cime de Noir-nuage ? Je vous supplie... Je dois retourner auprès de Thalia ! Elle doit se faire un sang d'encre à mon sujet.", t = "Libre, enfin !"},
    [4921] = {ot = "Trouver la femme de Mankrik puis retourner le voir à la Croisée.", st = "Nous combattions dans un petit camp tauren lorsque nous fûmes séparés. A elle seule, elle arrivait à tenir à distance trois des Dos-hirsute, mais leur nombre allait croissant et ils nous débordèrent. J’avais beau en repousser, je la voyais assaillie et mise à mal par les nouveaux venus. Dans ma rage, je me jetai contre mes ennemis, mais ils me maîtrisèrent grâce à la supériorité de leurs effectifs.$B$BLorsque je m’éveillai, un druide tauren soignait mes blessures. Il m'avait trouvé inanimé sur la Route de l'or.$B$BJe vous en prie, $c, retrouvez la piste de ma femme et apprenez ce qu’elle est devenue.", t = "Disparition au combat"},
    [4966] = {ot = "Protéger Kanati Greycloud contre l’attaque centaure.", st = "Mais il se peut qu'il y ait plus de centaures que je ne le croyais. Je vous le demande, $N, battez-vous à mes côtés contre ces vils assassins.", t = "Protéger Kanati Greycloud"},
    [5041] = {ot = "Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides.", st = "La caravane attaquée contenait des provisions dont nous avons désespérément besoin.$B$BVous avez été suffisamment $gcourageux:courageuse; pour en découdre avec la tribu Tranchecrin jusqu'alors, mais cette fois-ci, je me demande si je pourrais vous demander de chercher certaines de nos provisions volées. Vous les trouverez probablement un peu partout dans leurs campements, les hurans devant s'engraisser de leurs actes méprisables.$B$BLes habitants de la Croisée vous en seraient reconnaissants.", t = "Ravitaillement pour la Croisée"},
    [5052] = {ot = "Apporter un Joyau de sang à Mangletooth, à Camp Taurajo, dans les Tarides.$B$BCollectez plus de Joyaux de sang, si vous souhaitez qu’il vous gratifie de la puissance d’Agamaggan.", st = "A l’instar des ronces, le sang a modifié <grogne> certains aspects de la terre : les pierres rouge sang se sont mélangées à d'autres minéraux. Les Dos-hirsute déterrent ces pierres pointues et les portent comme des totems <grogne> représentant la force au combat et comme symbole de leurs pouvoirs. <grogne>$B$BJe connais les secrets de cette magie.$B$BRamenez à Mangletooth l'une de ces pointes rouge sang et montrez ainsi que vous avez compris. Ramenez-en plusieurs et il vous offrira la magie des hurans, la magie d'Agammagan ! <grogne>", t = "Joyaux de sang d'Agammagan"},
    [5061] = {ot = "Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Bearwalker.", st = "Vous avez terminé l'apprentissage suivi par tous les jeunes druides qui veulent adopter un Aspect aquatique. Maintenant retournez voir votre maître, Mathrengyl Bearwalker, à Darnassus. Affichez votre pendentif et prouvez-lui que vous êtes apte à recueillir son savoir. Il achèvera votre formation, pour vous permettre de communiquer avec l’eau.$B$BAu revoir, jeune druide. Nous nous reparlerons.", t = "Forme aquatique"},
    [5062] = {ot = "Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Grimtotem sur la Cime des Anciens dans Thunderbluff.", st = "Arikara est une créature implacable avec laquelle on doit agir avec prudence. Vous allez devoir allumer le feu sacré de la vie afin de la traquer. Cela aura pour effet d'invoquer Arikara.$B$BPartez dès à présent et récoltez le rare agave d'Incendia. Une fois que vous en aurez récolté suffisamment, cherchez conseil auprès de Magatha Grimtotem sur la Cime des Anciens à Thunder Bluff. C'est une chaman très puissante qui peut enchanter l'agave pour créer une poudre nécessaire à la combustion de la flamme.$B$BVoyagez au nord-est, jusqu'au Bassin bouillonnant et trouvez de l'Agave d'Incendia.", t = "Feu sacré"},
    [5064] = {ot = "Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage.", st = "$n, vous nous avez bien servi par le passé, je peux donc vous confier une importante mission. Le clan Totem-sinistre prépare quelque chose en secret. Trois agents d’origine inconnue ont été vus chez eux ces dernières semaines. Nous avons découvert que ces messages sont conservés dans plusieurs coffres de la cime de Noir-nuage. $b$b$n, si vous réussissez cette dangereuse mission, je vous récompenserai.", t = "Espionner le Totem sinistre"},
    [5088] = {t = "Arikara"},
    [5147] = {t = "ON RECHERCHE : Arnak Totem-sinistre"},
    [5151] = {ot = "Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthèse à Wizlo Bearingshiner.", st = "Je suis le seul survivant de l'attaque de notre caravane par les centaures ! Une panthère rare mais puissante garde mon meilleur bidule autour du cou ! Ha ! Même les centaures tremblent en présence de cette bête féroce !$B$BVoici la clé de la cage. Ils ont tout emporté, mais l'ont laissée seule. Tuez cette bête et rapportez-moi mon hypercapaciteur. Vous serez alors $grécompensé:récompensée;.$B$BLes restes de la caravane se trouvent juste au nord d'ici.", t = "Hypercapaciteur bidulotron"},
    [5261] = {ot = "Parler à Eagan Peltskinner.", st = "Eagan Peltskinner cherche quelqu'un qui chasserait le loup pour lui. C'est une bonne nouvelle, car il y a de plus en plus de loups ces temps-ci dans la vallée de Comté-du-Nord.$B$BSi cela vous intéresse, allez parler à Eagan. Vous le trouverez en contournant l'abbaye sur la gauche.", t = "Eagan le tanneur"},
    [5321] = {t = "Le dormeur s'est éveillé"},
    [5441] = {ot = "Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu’ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.", st = "Maudits péons ! Ils disent qu'ils travaillent dur pour ramasser du bois de charpente dans la vallée, mais ils font sans arrêt la sieste ! J'ai besoin de quelqu'un pour les remettre sur le droit chemin.$B$BVous me semblez être la bonne personne pour cette tâche, $r. Prenez cette matraque et utilisez-la sur les péons paresseux que vous trouverez en train de dormir sur leur lieu de travail. Ça leur redonnera le goût de l'effort ! Rendez-moi la matraque quand vous aurez fini.$B$BPéons flemmards et glandeurs...", t = "Les péons paresseux"},
    [5481] = {ot = "Récolter 3 herbes des ténèbres et les apporter à l’Apprenti Apothicaire Holland au cimetière de Brill.", st = "Maître veut herbes. Nous avoir grosses mains et pas bons à ramasser. Vous aider et nous pas vous faire mal. Nous avoir besoin d'herbe des ténèbres. Beaucoup alentours et près de route.$B$BQuand vous avoir beaucoup apporter à Maître Holland dans Cimetière de Brill.", t = "La tâche de Gordo"},
    [5482] = {ot = "Récolter 10 Herbes maléfiques et les apporter à l’apprenti apothicaire Holland.", st = "Ainsi vous comprenez la situation délicate dans laquelle je me trouve, $n. Cette chose est quelque part dehors en train de collecter les mauvaises herbes ! Si vous récupérez ce dont j'ai besoin, cela en vaudra la peine. Apportez-moi suffisamment d'herbes maléfiques et je vous remettrai une récompense conséquente.$B$BJe crois savoir qu'elles aiment dévaster la flore près des tombes au nord du cimetière de Brill. Hâtez-vous, et faites attention aux gnolls qui parcourent l'endroit.", t = "Herbe maléfique"},
    [5541] = {t = "Munitions pour Rumbleshot"},
    [5545] = {ot = "Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est.", st = "J'ai un vrai problème sur les bras. J'ai une commande de bois à livrer mais je n'ai plus assez de temps pour l'assurer. Les loups et les ours au nord ont éloigné mes travailleurs des tas de bois qu'ils avaient déjà coupés.$B$BJ'ai déjà dit à l'Adjoint Rainer qu'il fallait nous débarrasser de ces animaux, en attendant j'ai besoin de quelqu'un pour ramasser le bois. Si vous pouviez ramener huit fagots de bois, je tiendrais ainsi mes engagements.", t = "Un sac d'embrouilles"},
    [5621] = {ot = "Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Morninglight, à Dolanaar.", st = "J'ai besoin de votre aide, $n. Je dois rester ici pour former les autres étudiants, mais vous, vous pouvez aller porter secours à l'une de nos Sentinelles, juste au sud de Dolanaar. Elle a été blessée en patrouillant dans la ville et a besoin de notre aide. Son nom est Shaya.$B$BQuand vous l'aurez trouvée, guérissez ses blessures et fortifiez-la avec vos sorts. Cela la protégera un peu si elle a d'autres ennuis. Revenez me voir lorsque vous aurez accompli votre devoir pour Elune.", t = "Vêtements de la lune"},
    [5622] = {ot = "Parler à Laurna Morninglight à Teldrassil.", st = "$n, vous devrez partir pour Dolanaar lorsque vous en aurez terminé ici à Sombrevallon. Vous y trouverez Laurna Morninglight. Elle vous en apprendra davantage sur les voies d'Elune, et c'est avec elle que vous obtiendrez votre premier vêtement dénotant votre nature de $gprêtre:prêtresse; d'Elune.$B$BPrenez garde, et puissiez-vous être $gprotégé:protégée; durant vos voyages.", t = "Au service d'Elune"},
    [5623] = {ot = "Parler à la prêtresse Josetta dans la Forêt d’Elwynn.", st = "Salutations à nouveau, jeune $gprêtre:prêtresse;. Il est à présent temps pour vous d'en apprendre davantage sur notre religion. Une fois que vous aurez terminé ce que vous avez à faire ici à Comté-du-Nord, veuillez aller voir la prêtresse Josetta à Comté-de-l’Or. Elle a beaucoup à vous apprendre et a vent de vos grands progrès dans la voie de la Lumière. Elle est impatiente de vous enseigner plus en avant.", t = "Au service de la Lumière"},
    [5624] = {ot = "Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Comté-de-l’Or.", st = "Normalement je propose un petit défi aux disciples de la Lumière, pour tester leur compétence. Je veux savoir s'ils sont dignes de porter leurs premières robes, ce symbole de l’approbation et du soutien de l’Eglise à ses prêtres et prêtresses.$B$BMais la situation est un peu différente ici. Un des citoyens de Comté-de-l’Or a vu un garde blessé près du lac, à l'est d'ici. Son nom est Roberts. Trouvez-le, guérissez-le, fortifiez son corps et revenez ici. Si vous faites cela pour moi, je considérerai que votre examen est terminé.", t = "Vêtements de la Lumière"},
    [5625] = {ot = "Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos.", st = "Il est de coutume de tester l'un de vos pouvoirs pour savoir si vous êtes digne de porter les robes qui symbolisent votre place dans l'Eglise. Mais il y a plus urgent. Le citoyen de Kharanos qui vient d'entrer m'a parlé d'un montagnard blessé à l'extérieur de la ville, au sud.$B$BGuérissez ce Dolf, restaurez sa fortitude et je considérerai que vous avez fait vos preuves. Cela vous convient-il ?", t = "Vêtements de la Lumière"},
    [5626] = {ot = "Parler à Maxan Anvol à Dun Morogh.", st = "Eh ! $n ! Vous avez une minute ? !$B$BVous avez suivi la Lumière suffisamment longtemps pour trouver la route qui mène à Maxan Anvol à Kharanos. Il vous enseignera de nombreuses choses et si vous vous avérez courageux, il vous donnera votre première robe, pour vous démarquer en tant que $gprêtre:prêtresse;.$B$BAllez, continuez votre chemin ! Dès que vous en avez fini ici, passez par le tunnel, il vous attendra.", t = "Au service de la Lumière"},
    [5629] = {ot = "Parler à la prêtresse Alathea à Darnassus.", st = "Encore bonjour, $n. Je sais que votre temps a été bien rempli à aider les gens, mais vous devez prendre du temps pour vous. La prêtresse Alathea a envoyé quelqu'un ici pour vous chercher. Il semble que vous ayez attiré l'attention de nos aînés et ils pensent que vous pouvez accomplir de grandes choses. Allez au temple de la Lune, à Darnassus, et cherchez Alathea. Elle vous y attendra. Bonne chance et qu'Élune soit avec vous.", t = "Retour à la maison"},
    [5634] = {ot = "Parlez au grand prêtre Rohan, à Forgefer.", st = "Un prêtre est récemment venu nous voir et il vous cherchait, jeune $r. Il a dit qu’il avait pour mission de vous trouver et que vous deviez retourner au Hall des mystères à Forgefer dès que possible. Une fois sur place, cherchez le grand prêtre Rohan. Il vous en dira plus.$B$BQue la Lumière soit avec vous, $n.", t = "Prière du désespoir"},
    [5641] = {t = "Châtiment"},
    [5642] = {ot = "Parler à Ur'kyo à Orgrimmar.", st = "Il se passe quelque chose d'important à Orgrimmar, $n.$B$BLes messagers qui passent par ici à la recherche de prêtres trolls sont d'habitude tranquilles. Cette fois-ci, ils semblent plutôt pressés. Ne flânez pas trop aux Pitons-du-Tonnerre. Retournez dès que possible dans la vallée des Esprits.", t = "Garde des ténèbres"},
    [5644] = {ot = "Parler à Aelthalyste à Fossoyeuse.", st = "Ah, quel beau jour pour vous, $n. Je vois que les leçons ont été profitables mais qu’il est temps de vous renvoyer à Aelthalyste. Il y a des choses qu’elle seule peut vous apprendre, si vous en valez la peine.$B$BJe ne vais pas vous gâcher la surprise mais je me souviens quand j’étais un jeune prêtre, étudiant le vrai pouvoir... le pouvoir divin. Eh oui, des sacrés souvenirs.$B$BRetournez voir Aelthalyste à Fossoyeuse, $n. Elle vous attendra dans le quartier de la Guerre.", t = "Sombre sacrifice"},
    [5648] = {ot = "Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.", st = "V'là votre premier test, $n. Au sud de Tranchecolline, juste à l'extérieur de la ville, un d'nos fantassins a été blessé en s'battant contre les troupes de Proudmoore. Elle s'trouve pas trop bien, et faudrait qu'un d'nous aille l'aider. Trouvez-la – son nom c'est Kor'ja – soignez ses blessures et donnez-lui la bénédiction d'nos ancêtres.$B$BQuand vous aurez fait ça, ce s'ra la meilleure preuve que vous pouvez commencer à suivre notre trace.", t = "Vêtements de la spiritualité"},
    [5649] = {ot = "Parler à Tai'jin en Durotar.", st = "Salut à toi. Notre peuple a rejoint la Horde parce qu'ils sont bons pour nous. Eux loyaux et eux enseignent des trucs sur l'honneur. Mais nos traditions ont la vie dure. Ce n'est pas parce que les orcs n'approuvent pas toutes nos coutumes qu'il ne faut pas continuer à en pratiquer quelques-unes en secret.$B$BVous savez ça, c'est pourquoi je vous envoie à Tai'jin, qui vit à Tranchecolline. Elle vous apprendra les pratiques de notre tribu. Allez la voir quand vous le voudrez.", t = "Au service de la spiritualité"},
    [5650] = {ot = "Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.", st = "Notre pouvoir vient des ténèbres et de l'ombre, $n, mais ce n'est pas tout. Vous avez reconnu qu'il était intéressant de connaître les arts de la guérison. C'est sage. Aussi, avant de pouvoir connaître les ténèbres, vous devez connaître la lumière. Et pour cela, je vais vous faire passer un test.$B$BAu nord du cimetière, il y a un garde blessé : le Garde noir Kel. Il nous a protégés des gnolls pendant quelque temps et il a besoin de soins. Mais vous devrez aussi fortifier son corps avant qu'il ne puisse retourner faire son devoir. Remplissez ces deux missions avec des charmes, puis revenez me voir.", t = "Vêtements des ténèbres"},
    [5651] = {ot = "Parler au sombre clerc Beryl dans les Clairières de Tirisfal.", st = "Les Réprouvés ont appris beaucoup de choses au fil du temps, des choses que certaines races commencent seulement à entrevoir. Et bien que nos chemins restent dans les ténèbres, vous constaterez que beaucoup de choses s'appuient sur la lumière et sur l'obscurité. Vos leçons vous apprendront à utiliser les deux... et avec discrétion. Mais retenez bien ce que je vais vous dire : nous sommes nés dans la corruption et nous sommes faits de chair pourrissante. L'obscurité est notre mère.$B$BLorsque vous voudrez en savoir plus, cherchez le sombre clerc Beryl à Brill.", t = "Au service des ténèbres"},
    [5654] = {ot = "Parler à Ur'kyo à Orgrimmar.", st = "Il est temps pour vous de rencontrer Ur'kyo, $n. Il est dans la Vallée des esprits, dans la ville des orcs. Allez-y et parlez-lui. Il est temps que vous en sachiez plus sur les vieilles coutumes de notre peuple. Il est temps que vous entriez dans le cercle et que vous deveniez un vrai prêtre de notre tribu.", t = "Le maléfice de faiblesse"},
    [5658] = {t = "Toucher de faiblesse"},
    [5672] = {t = "Grâce d'Elune"},
    [5676] = {t = "Retour d'information de l'Arcane"},
    [5713] = {ot = "Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale.", st = "J’étais en route pour Auberdine chargé d’un message important quand le furbolg Marosh et ses traqueurs m’ont attaqué. Au cours du combat, j’ai été empoisonné et je peux maintenant à peine me tenir debout. Je peux préparer un antidote, mais cela va prendre du temps avant qu’il ne soit prêt.$B$BJ’aimerais vous demander de me defendre jusqu’à ce que je puisse m’administrer l’antidote. Je vous aiderai avec mon arc du mieux que je peux.$B$BSi nous survivons, je pourrai porter mon message à Auberdine, pendant que vous parlerez avec Onaeya au poste de Maestra pour l’informer de cet incident.", t = "Un tir. Un tué."},
    [5722] = {ot = "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant.", st = "Les troggs ne sont pas la seule chose qui intéresse Magatha dans le Gouffre de Ragefeu. Elle a entendu dire que l’un de ses serviteurs, un certain Maur Grimtotem, a trouvé quelque chose d’étrange dans le Gouffre, mais il n’a jamais pu en sortir pour le lui montrer. Elle aimerait qu’on retrouve le corps de Maur, s’il existe encore, ainsi que tout signe de ce qu’il avait trouvé quand il a essayé de parler aux troggs.$B$BRapportez tout élément intéressant à Magatha, et je suis sûr qu’elle vous récompensera généreusement.$B$BEncore une fois, cherchez le Gouffre dans les endroits les plus sombres d’Orgrimmar.", t = "À la recherche de la sacoche perdue"},
    [5723] = {ot = "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff.", st = "Sous la cité d’Orgrimmar, des créatures solidement bâties appelées des \"troggs\" ont commencé à faire surface, provenant d’endroits bien plus profonds que les tunnels de lave. Dans sa grande bienveillance, Magatha a cherché à faire la paix avec ces créatures, mais elles se sont retournées contre ses diplomates et les ont tués. Elle ne tolère pas que le peuple tauren soit traité ainsi et considère maintenant ces créatures comme une menace envers la Horde entière.$B$BElle demande que vous mettiez fin à cette menace trogg avant qu’elle ne submerge la Horde par en-bas. Trouvez le Gouffre de Ragefeu et détruisez-les tous.", t = "Tester la force de l'ennemi"},
    [5724] = {ot = "Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff.", st = "Vous trouvez une sacoche sous le corps du tauren. Il la tient encore serrée entre ses bras comme s’il essayait de la protéger pendant l’attaque des troggs.$B$BVous libérez la sacoche qu’il étreint, vous la placez dans votre propre équipement et vous vous préparez à quitter les tunnels et à retourner auprès de Rahauro à Thunder Bluff.", t = "Rapporter la sacoche perdue"},
    [5725] = {ot = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Fossoyeuse.", st = "Beaucoup de membres de la Légion offrent des cadeaux à leurs disciples, comme vous le savez peut-être. La Dame noire estime que certains de ces cadeaux seraient mieux placés entre ses mains plutôt qu’entres celles de ceux doués de… moins de vision.$B$BUne secte du Conseil des ombres, cachée dans les grottes sous Orgrimmar et appelée la Lame brûlante, en est un bon exemple. La Dame me dit que des membres de la Lame brûlante possèdent deux livres de magie puissants ; elle aimerait leur \"emprunter\" ces livres. Vous vous les procurerez pour elle.", t = "Le pouvoir de détruire..."},
    [5726] = {ot = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar.", st = "Je ne tolérerai pas qu’il y ait des traîtres parmi nous, $n. Mais cela serait idiot de dévoiler mon jeu si tôt : cela ne débarrasserait pas suffisamment nos terres de la corruption et ne ferait qu’empirer cette infection.$B$BMais vous, jeune $gaventurier:aventurière;, vous pourriez vous rendre là où mes agents ne peuvent pas... vous pourriez apprendre la vérité... vous pourriez identifier la vraie tête de la bête.$B$BSi vous avez assez de courage, allez au Rocher du crâne à l’est d’Orgrimmar, trouvez un insigne de lieutenant auprès de l’un des membres de la Lame ardente qui s’y trouvent, et revenez me voir.", t = "Ennemis cachés"},
    [5727] = {ot = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.", st = "Maintenant voyons voir si cet Insigne que vous avez trouvé en valait la peine.$B$BIl y a un démoniste dans la cité qui pense avoir ma confiance. Il ne sait pas que j'ai compris qu’il était loyal à d’autres. En fait, c’est lui le chef de la Lame ardente. Mais ne vous précipitez pas à sa poursuite ; il peut nous servir contre nos ennemis.$B$BApportez-lui cet insigne dans la Faille de l'ombre ici à Orgrimmar, parlez-lui et voyez s’il croit que vous êtes l’un des leurs, puis revenez me voir.", t = "Ennemis cachés"},
    [5728] = {ot = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar.", st = "Hmm, des chefs de la Lame brûlante... cela m’inquiète beaucoup. S’ils sont utiles à Neeru, alors ce sont eux qu’il faut viser en premier. Ce satyre... Bazzalan, et l’autre que Neeru a mentionné - qu’est-il, un démoniste ? - doivent être tués.$B$BRetournez à la Faille de l'ombre et pénétrez dans le gouffre de Ragefeu, $n. Trouvez ces deux chefs de la Lame brûlante et tuez-les. Mais faites attention à ce que Neeru ne sache pas que c’est vous le responsable. Il faut que vous conserviez votre identité en tant que $gfrère:sœur; de combat.", t = "Ennemis cachés"},
    [5729] = {ot = "Parler à Neeru Fireblade à Orgrimmar.", st = "Je pense que la prochaine étape devrait être de vous placer près de Neeru. S'il est aussi agité que le suggèrent les rapports, nous pourrions accomplir deux choses. D'abord, vous pourriez en apprendre davantage sur le Conseil ou au moins sur la Lame ardente. Ensuite, il se peut qu'il vous fasse suffisamment confiance pour qu'il vous demande de lui venir en aide. Il pourrait vous considérer comme quelqu'un capable d'occuper une place vacante à présent que sa direction connaît un grand bouleversement.$B$BRetournez à la Faille et parlez-lui à nouveau, mais dissimulez bien votre jeu.", t = "Ennemis cachés"},
    [5730] = {t = "Ennemis cachés"},
    [5761] = {t = "Tuer la bête"},
    [5881] = {ot = "Maggran voudrait que vous apportiez une lettre à Grish Longrunner, à la Grande élévation, dans les Tarides.", st = "La Horde a bien fait de garder nos troupes fraîches... Depuis la Grande Guerre, nous avons prospéré ici, à Kalimdor.$B$BJe voudrais que vous me fassiez une faveur : j'ai un gars du nom de Grish Longrunner qui protège la Grande élévation dans les Tarides du Sud. Donnez-lui cette lettre. Elle lui fait savoir que j'envoie un guerrier pour le remplacer, afin qu'il puisse aller voir sa famille. Il m'a demandé à être relevé il y a quelque temps et il sera heureux d'apprendre cette nouvelle.", t = "Puiser dans les réserves"},
    [5921] = {ot = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", st = "Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, indépendamment des relations actuelles tendues entre l'archidruide Staghelm et le gardien Remulos – le gardien de Reflet-de-Lune. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.$B$BPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Starblaze, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.", t = "Reflet-de-Lune"},
    [5922] = {ot = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.", st = "Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, taurens ou elfes de la nuit. Le gardien Remulos – le gardien de Reflet-de-Lune – surveille de près tous les druides qui hivernent ici. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.$B$BPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Starblaze, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.", t = "Reflet-de-Lune"},
    [5923] = {ot = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", st = "Excusez-moi, vous...$B$BJ'ai cru comprendre que Mathrengyl Bearwalker souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu'il veuille vous former personnellement. Mathrengyl est l'assistant direct de l'archidruide lui-même et l'un des druides les plus sages et les plus reconnus de Teldrassil.$B$BIl se trouve dans l'Enclave cénarienne à Darnassus, au deuxième étage de l'arbre de Fandral Staghelm.", t = "Écouter l'appel"},
    [5928] = {ot = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.", st = "Excusez-moi...$B$BJ'ai entendu dire que Turak Runetotem voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu'il veuille vous former personnellement. Turak est l'un des assistants des archidruides ; il a la réputation d’être sage et patient et il devrait bien vous former.$B$BIl est à Thunder Bluff, dans la tente principale du Cercle cénarien sur la Cime des Anciens.", t = "Écouter l'appel"},
    [5929] = {ot = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", st = "Au nord-ouest de Reflet-de-Lune se trouve la demeure d'un être sage et noble que nous appelons l'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l'ours. A un moment, tous les druides cherchent la sagesse de l'esprit et vous ne ferez pas exception.$B$BAllez voir l'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.", t = "L'esprit du Grand ours"},
    [5930] = {ot = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", st = "Au nord-ouest de Reflet-de-Lune se trouve la maison d'un être sage et noble que nous appelons l'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l'ours. A un moment, tous les druides cherchent la sagesse de l'esprit et vous ne ferez pas exception.$B$BAllez voir l'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.", t = "Esprit du Grand ours"},
    [5931] = {ot = "Retourner à Darnassus et parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne.", st = "Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Mathrengyl Bearwalker vit en complète harmonie avec l’équilibre naturel, bien que résidant à proximité de l’endroit où cet équilibre a vacillé. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l’équilibre naturel.$B$BPartez maintenant. Nous nous reverrons bientôt.", t = "Retour à Darnassus"},
    [5932] = {ot = "Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens.", st = "Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Bien que les taurens passent pour novices dans les voies de Cénarius, Turak Runetotem est en totale harmonie avec la nature. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l’équilibre naturel.$B$BPartez maintenant. Nous nous reverrons bientôt.", t = "Retour vers Thunder Bluff"},
    [6001] = {ot = "Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.", st = "A l’est d’Auberdine se trouvent plusieurs grottes de séléniens. Celle qui est la plus proche d’Auberdine contient une pierre des séléniens. Lunegriffe, le défenseur de la pierre, ne vous affrontera que si la poussière de lune cénarienne est appliquée sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme doivent le faire tous les druides de la Griffe.$B$BVous avez gagné le droit d’utiliser cette poussière de lune cénarienne, $n... Maintenant, montrez-moi que vous avez aussi gagné celui d'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !", t = "Corps et cœur"},
    [6002] = {ot = "Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.$B$BQuand cela est fait, parler à Turak Runetotem, à Thunder Bluff.", st = "À l’ouest de Taurajo, dans les Tarides, juste avant Mulgore, se trouve une pierre des séléniens. Les séléniens sont des créatures spéciales qui ne sont pas originaires de ce pays. Lunegriffe, le défenseur de la pierre, vous affrontera lorsque vous appliquerez la poussière lunaire cénarienne sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme tous les druides de la Griffe.$B$BVous avez gagné le droit d’utiliser cette poussière lunaire cénarienne, $n... Maintenant montrez-moi que vous avez aussi gagné celui d'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !", t = "Corps et cœur"},
    [6061] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", st = "En tant que taurens, il est important que nous suivions les traditions de nos ancêtres en affrontant des créatures puissantes. En battant ces créatures, nous pouvons nous nourrir de leur esprit, ce qui nous rapproche de mère Nature.$B$BDe même, apprivoiser une bête pour qu'elle combatte à nos côtés nous aide à ne faire qu'un avec la nature qui nous entoure. Vous finirez par apprendre à apprivoiser une bête. Mais tout art demande de la pratique et vous avez beaucoup à apprendre. Commencez en prenant ce Bâtonnet de domptage et allez apprivoiser un trotteur des plaines adulte.", t = "Dompter la bête"},
    [6062] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.", st = "C'est une excellente compétence que de savoir commander à la nature. En tant que chasseur, vous devez vous efforcer d'utiliser la force et le pouvoir de n'importe quelle créature.$B$BPrendre le contrôle d'un animal n'est pas facile, c'est une tâche que vous devez entreprendre avec beaucoup de détermination.$B$BPour commencer, prenez ce Bâtonnet de domptage et utilisez-le pour apprivoiser un sanglier tacheté redoutable. Vous en trouverez près de Tranchecolline. Entraînez-vous à combattre avec le sanglier à vos côtés, puis revenez me voir.", t = "Dompter la bête"},
    [6063] = {ot = "Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", st = "En tant que chasseur, vous devez prendre conscience de vos responsabilités. On ne peut pas plier la nature à ses désirs, elle doit être respectée et reconnue comme bien plus forte que votre propre existence.$B$B$n, vous devez prouver que vous avez compris cela avant de gagner la capacité d'apprivoiser un animal pour en faire votre compagnon.$B$BLa première chose à faire est de prendre ce Bâtonnet de domptage. Il vous permettra d'apprivoiser une rôdeuse Tissebois. Apprivoisez-la et entraînez-vous à chasser ensemble.", t = "Dompter la bête"},
    [6064] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos.", st = "Hé là ! Vous voulez savoir comment obtenir un animal de compagnie ?$B$BEh bien commençons ! Il n'y a rien de plus important qu'un bon équipement pour aller à la chasse, mais nous discuterons de mon nouveau crache-mitraille une autre fois. Pour le moment, concentrons-nous sur quelque chose qui vous intéresse, j'en suis sûr : un animal de compagnie !$B$BLa meilleure façon d'apprendre est d'essayer avec plusieurs créatures différentes pour voir ce que ça donne. Commencez par trouver un grand sanglier des rochers, utilisez ensuite le bâtonnet de domptage pour l'apprivoiser.", t = "Dompter la bête"},
    [6081] = {ot = "Adressez-vous à Orkmar Grimshot à Orgrimmar.", st = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez aussi acquérir celles qui sont nécessaires à son apprivoisement.$B$BVous devez parler à l’un de nos chasseurs les plus respectés, Ormak Grimshot. Il vous apprendra les techniques d’apprivoisement de votre nouveau familier. Vous le trouverez à proximité du Hall des braves.$B$BBonne chance, $n.", t = "Entraîner la bête"},
    [6082] = {t = "Dompter la bête"},
    [6083] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.", st = "L’avantage que peut vous offrir un familier en combat est certain, $n. Quand vous prenez le contrôle d'une créature, sa force vient s’ajouter à la vôtre. Votre familier doit véritablement devenir une extension de vous-même.$B$BLa mission suivante exige que vous tourniez le dos à la terre ferme ; vous trouverez la prochaine créature au large de la côte. De l’autre côté du village de Sen'jin, près des îles de l'Écho. Cherchez les crabes fougueux que l'on appelle les clampants de l'écume. Utilisez le Bâtonnet de domptage pour en dompter un, puis entraînez-vous à combattre à ses côtés.", t = "Dompter la bête"},
    [6084] = {t = "Dompter la bête"},
    [6085] = {t = "Dompter la bête"},
    [6086] = {ot = "Adressez-vous à Belia Thundergranite à Forgefer.", st = "$n, vous avez maintenant les compétences pour dompter un animal, mais je dois également vous enseigner celles qui sont nécessaires à son apprivoisement.$B$BAllez à Forgefer et trouvez le Hall des armes. Là-bas, adressez-vous à l’une de nos dresseuses d’animaux les plus respectées, Belia Thundergranite. Elle vous montrera comment apprivoiser votre Familier. Qu’attendez-vous ?$B$BBelia est amicale et avenante, vous n’aurez pas de problèmes à lui être sympathique. Bonne chance, $n.", t = "Entraîner la bête"},
    [6087] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", st = "Vous avez un esprit fougueux, impatient de se confronter à la prochaine épreuve.$B$BVotre nouvelle mission est de dompter un loup connu sous le nom de Traqueur des prairies. Cette créature est rapide et ne craint personne ; si vous la prenez comme familier, vous devrez prouver que vous avez les mêmes qualités.$B$BPendant la bataille, vous apprendrez à former une équipe de combat avec votre familier. Au terme de votre entraînement, vous aurez appris à ne faire qu'un avec lui ; un seul corps, utilisant les mêmes muscles, les mêmes idées.$B$BVoici un Bâtonnet de domptage, $n. Domptez un Traqueur des prairies et entraînez-vous à lutter en synergie avec lui.", t = "Dompter la bête"},
    [6088] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.", st = "Votre tâche finale sera d'apprivoiser une créature céleste. Le rapace est un adversaire difficile, mais comme allié, vous bénéficierez de ses attaques éclair et de sa présence menaçante.$B$BPar la volonté de mère Nature, quand vous reviendrez, je vous accorderai les compétences qui vous permettront d'apprivoiser un animal de votre choix pour en faire votre compagnon. Cette créature fera face aux mêmes défis que vous et acquerra de l'expérience à vos côtés. Je vous montrerai aussi comment l'appeler et la renvoyer à votre guise.", t = "Dompter la bête"},
    [6089] = {ot = "Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.", st = "Vous avez maintenant le pouvoir d'apprivoiser un familier, mais vous devez aussi apprendre à l'entraîner.$B$BAllez jusqu'à Thunder Bluff. Là vous irez parler à l'un de nos chasseurs les plus admirés, Holt Thunderhorn. S'il vous en juge digne, il vous apprendra à former votre nouveau familier.$B$BHolt a dressé les bêtes les plus puissantes et les plus craintes d'Azeroth et commande lui-même à de nombreuses créatures puissantes. Ses liens à la mère Nature sont forts et vous pouvez apprendre beaucoup de lui. Bonne chance, $n !", t = "Entraîner la bête"},
    [6101] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", st = "Il faut tenir compte des variations de la nature, $n. La seule chose qui est prévisible chez elle, c'est qu'elle n'est jamais la même, elle change toujours.$B$BLes tâches que je vous donnerai à accomplir vous aideront à comprendre et à apprécier les différences qu'il y a entre les créatures que vous pouvez choisir comme compagnes.$B$BPrenez ce Bâtonnet de domptage et utilisez-le pour apprivoiser un Rôdeur sabre-de-nuit, que vous trouverez dans le sud. Exercez-vous à chasser. Alors vous commencerez à comprendre les ressemblances et les différences qui forgent la nature.", t = "Dompter la bête"},
    [6102] = {ot = "Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.", st = "Vous avez dompté deux créatures qui vivent dans le pays, et maintenant vous devez en dompter une qui soit capable de filer dans les airs. Utilisez le Bâtonnet de domptage pour dompter un Hurleur Strigid que vous pourrez trouver plus à l’ouest. Entraînez-vous au combat avec ce grand hibou à vos côtés.$B$BQuand vous reviendrez, je vous laisserai dompter la créature de votre choix qui deviendra votre familier. Ce compagnon combattra, sans peur, à vos côtés, quels que soient les dangers et les adversaires que vous affronterez. Le familier engrangera de l’expérience en même temps que vous. Je vous apprendrai comment l'appeler et le renvoyer à volonté.", t = "Dompter la bête"},
    [6103] = {ot = "Parler à Jocaste, à l'enclave cénarienne de Darnassus.", st = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez également acquérir celles qui vous permettront de l'apprivoiser.$B$BAllez à Darnassus. Quand vous serez là-bas, parlez à l'un de nos meilleurs chasseurs, Jocaste. Elle vous apprendra à apprivoiser votre nouveau familier. Ne tardez pas.$B$BJocaste peut avoir l'air sévère, mais elle est toujours contente de voir un nouveau chasseur se perfectionner. Traitez-la avec respect, elle vous le rendra. Bonne chance, $n.", t = "Entraîner la bête"},
    [6121] = {ot = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.", st = "Vous êtes maintenant en mesure de faire l’apprentissage des poisons et de la maîtrise que nous, les druides, en avons, $n. Cénarius nous a gratifiés de la technique et du savoir qui nous permettent de purger tout poison d'un corps, grâce à une simple incantation. Ce don ne doit pas être pris à la légère… et pour que vous appreniez cette leçon capitale, vous travaillerez à traiter les affections du poison comme un véritable étudiant.$B$BAllez à Reflet-de-Lune et parlez à Dendrite Starblaze ; il vous attend pour commencer la leçon.", t = "Nouvelles leçons"},
    [6122] = {ot = "Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes.$B$BApporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage.", st = "Les chutes de la Bondissante, à Sombrivage, alimentent en eau potable toute la région. Je pense qu’elles sont la source de l’empoisonnement de la faune locale. Les daims, en particulier, sont très affectés par le mal. Utilisez cette Fiole d’échantillon pour collecter de l’eau, à l’entrée de la grotte. Faites attention, des nagas se sont installés dans une grotte, non loin de là.$B$BUne fois que la Fiole sera remplie, apportez-la à Alanndarian Nightsong, à Auberdine. Elle est l’un de ceux qui ont requis notre aide, et vous travaillerez avec elle pour traiter ce mal.", t = "Le principe originel"},
    [6123] = {t = "Rassembler les ingrédients du remède"},
    [6124] = {t = "Soigner la maladie"},
    [6125] = {ot = "Retourner voir Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.", st = "Vous avez appris ce que signifie guérir un empoisonnement sans en appeler à des moyens spirituels. Rappelez-vous ce que les autres doivent endurer en combattant les afflictions de l'empoisonnement, quand vous aurez définitivement acquis votre pouvoir de guérison du poison.$B$BVous devriez retourner voir Mathrengyl Bearwalker, à Darnassus, $n. Il a, à n’en pas douter, un sort de première importance à vous apprendre, maintenant que vous avez appréhendé les leçons qui vous ont été données.$B$BAdieu, jeune druide. Nous nous reparlerons un jour.", t = "Pouvoir contre le poison"},
    [6181] = {ot = "Apporter la Note de Lewis à Thor, le Maître des gryphons.", st = "Bien que Stormwind ne nous aide pas beaucoup directement, j'ai quand même un contact dans la ville qui nous permet de nous procurer des armures. Son nom est Osric Strang. Son magasin, “ Immunité limitée ”, est dans la vieille ville de Stormwind.$B$BNotre réserve d'armures diminue et je dois entrer en contact avec Osric pour en obtenir. Pouvez-vous lui porter cette note ?$B$BLa façon la plus rapide d'aller à Stormwind est de demander à Thor, notre Maître des gryphons. Il est juste en bas de la colline, apportez-lui ma note et prenez ensuite un gryphon pour Stormwind.", t = "Un message rapide"},
    [6261] = {ot = "Apportez la Caisse d'Osric à Dungar Longdrink, le Maître des gryphons.", st = "$n, j’ai mis dans cette caisse tout ce dont Lewis avait fait la demande. Pouvez-vous la lui apporter ?$B$BSi vous avez déjà parlé à Thor, dans la marche de l'Ouest, alors vous pouvez prendre un gryphon pour y retourner. Dungar Longdrink est notre Maître des gryphons, dans le Quartier commerçant.$B$BAllez voir Dungar, puis apportez cette caisse à Lewis, aussi vite que possible. Nous ne pouvons pas nous permettre de laisser nos frères qui combattent dans la marche sans ravitaillement !", t = "Dungar Longdrink"},
    [6281] = {ot = "Achetez un voyage en gryphon à Thor, Maître des gryphons, puis apportez la Note de Lewis à Osric Strang au magasin “Immunité limitée”, dans la vieille ville de Stormwind.", st = "Contre un modeste paiement, vous pouvez prendre un gryphon pour Stormwind, et livrer la note de Lewis à Osric. Il n’y a pas de moyen plus rapide pour se rendre sur place.$B$BSi cela vous convient, revenez me voir quand vous souhaiterez faire le voyage. Cela vous en coûtera quelque peu, mais, croyez-moi, cela le vaut bien !", t = "Continuer vers Stormwind"},
    [6282] = {t = "La menace des harpies"},
    [6283] = {ot = "Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit.", st = "Tailler dans les rangs des Rougefuries ne sera pas suffisant en soi. Le seul véritable remède à cette infestation serait d’exécuter leur chef, la créature appelée la Déchiqueteuse Rougefurie !$B$BElle est pratiquement une reine pour ces créatures hideuses. Tuez-la, et leur nombre s’effondrera assurément.$B$BRetournez dans le Val calciné, vous la trouverez dans les collines, à l’ouest. Elle ne sera pas facile à vaincre, mais la récompense pour sa mort est à la hauteur du danger.", t = "La lignée Rougefurie"},
    [6284] = {ot = "Tuer Besseleth, et apporter le Croc de Besseleth à Maggran, dans la Retraite de Roche-Soleil.", st = "Attention : si vous pénétrez dans le Canyon de Sishir, à l’ouest, vous le faites à vos risques et périls.$B$BBesseleth et ses enfants arachnéens de la forêt ont pris possession du territoire, et en ont fait leur repaire et leur nid.$B$BMaggran Earthbinder, dans la Retraite de Roche-Soleil, a mis la tête de Besseleth à prix. Tuez-la et apportez une preuve de sa mort à Maggran ; vous recevrez une récompense pour avoir fait disparaître cette menace à huit pattes.", t = "Arachnophobie"},
    [6285] = {ot = "Achetez un voyage en gryphon pour la Colline des sentinelles à Dungar Longdrink, Maître des gryphons, puis apportez la Caisse d'Olric à Lewis à la Colline des sentinelles.", st = "Le Maître des gryphons de la marche de l'Ouest s’appelle Thor. Si vous lui avez déjà parlé auparavant, vous pouvez prendre l’un de mes gryphons pour y retourner.$B$BC’est une bonne chose à retenir : les gryphons sont entraînés à voler vers leur capitale, mais ils ne vous porteront vers un Maître des gryphons éloigné que si vous l'avez déjà visité auparavant.$B$BVous avez déjà parlé à Thor, vous n’avez donc qu’à revenir me voir dès que vous souhaiterez prendre un gryphon pour la marche de l'Ouest. Une fois que vous serez à destination, livrez la Caisse d'Osric à l’Intendant Lewis.", t = "Aller voir Lewis"},
    [6301] = {ot = "Tammra Windfield, de la retraite de Roche-Soleil, vous demande de rassembler 10 Graines de Gaea.", st = "L'avidité des industries et la guerre permanente ont détruit les Serres-Rocheuses. Seule la bénédiction de la Terre-mère peut soigner une pareille blessure.$B$B$n, j'ai besoin que vous récoltiez des graines spéciales, aussi nommées Graines de Gaea. On ne les trouve que dans les Serres-Rocheuses, au nord de la Retraite de Roche-Soleil, au bord du Lac Mirkfallon.$B$BUne fois que vous m'aurez rapporté les graines, je les enchanterai grâce à mes pouvoirs chamaniques, pour accélérer leur croissance.", t = "Cycle de la renaissance"},
    [6321] = {ot = "Apporter l’Ordre de Podrig à Karos Razok.", st = "L'Exécuteur Hadrec m'a demandé de faire le point sur les réserves du Sépulcre. Avec le Fléau qui se cache dans les bois, et pire encore, il ne veut pas que les Gardes noirs manquent de matériel.$B$BJ'ai constaté que nous étions, généralement, bien approvisionnés, mais nous avons besoin de davantage d'armes pour remplacer celles perdues sur le champ de bataille.$B$BVoici un ordre de réquisition pour ce qui nous manque, destiné au marchand d'armes Gordon Wendham à Fossoyeuse. Portez l'ordre à notre Maître des chauve-souris, Karos Razok, et voyez avec lui comment vous rendre à Fossoyeuse.", t = "Approvisionner le Sépulcre"},
    [6322] = {ot = "Apporter la Caisse de Gordon à Michael Garret.", st = "J'ai placé l’approvisionnement pour le Sépulcre dans cette caisse. Si vous avez déjà visité le Sépulcre et parlé avec leur Maître des chauve-souris, vous pouvez chevaucher une chauve-souris pour y retourner.$B$BAllez voir le Maître des chauve-souris de Fossoyeuse, Michel Garret. Il pourra vous fournir une monture pour aller au Sépulcre.", t = "Michael Garret"},
    [6323] = {ot = "Acheter un voyage en chauve-souris pour Fossoyeuse, auprès du Maître des chauves-souris, Karos Razok, puis apporter l’Ordre de Podrig à Gordon Wendham, à Fossoyeuse.", st = "Une de mes chauves-souris peut vous conduire à Fossoyeuse, pour un prix modique. Revenez me voir quand vous serez $gprêt:prête; pour que nous arrangions votre transport.$B$BVous trouverez Gordon Wendham dans le Quartier marchand de Fossoyeuse. C'est dans ce quartier que ma chauve-souris se posera.", t = "Voyage vers Fossoyeuse"},
    [6324] = {ot = "Acheter un voyage en chauve-souris pour le Sépulcre, auprès du Maître des chauves-souris Michael Garret, puis apporter la Caisse de Gordon au Garde noir Podrig, au Sépulcre.", st = "Le Maître des chauve-souris du Sépulcre est Karos Razok. Si vous l'avez déjà rencontré, je peux vous donner une chauve-souris pour voler jusqu'à lui.$B$BNos chauves-souris savent toutes voler vers Fossoyeuse, mais pour aller plus loin, leurs cavaliers doivent avoir d'abord visité la destination et en parler au Maître des chauves-souris.$B$BVous avez déjà rencontré Karos au Sépulcre, donc vous pouvez voler jusque-là. Quand vous serez sur le point de partir, revenez me voir.", t = "Retour vers Podrig"},
    [6341] = {t = "Le don de Teldrassil"},
    [6342] = {ot = "Prenez un hippogryphe vers Auberdine chez le maître des hippogryphes Vesprystus, puis apportez la Collection de Nessa à Laird.", st = "À partir de Rut'theran, il existe deux moyens pour se rendre à Auberdine : par le bac ou par hippogryphe. Les deux sont rapides et sûrs, mais si vous n’avez pas encore voyagé vers Auberdine à dos d’hippogryphe, je vous suggère d’essayer.$B$BLorsqu'il y a un Maîtres des hippogryphes dans une ville, il est très profitable de lui parler. Une fois que vous avez parlé à un Maître, vous pouvez revenir dans la ville où il se trouve, à partir des autres villes.$B$BVoici la Collection de Nessa. Revenez me voir quand vous voudrez vous envoler pour Auberdine, et livrer la Collection de Nessa à Laird.", t = "Vol vers Auberdine"},
    [6343] = {ot = "Réponse de Laird à Nessa Shadowsong.", st = "Je dois faire parvenir une réponse à Nessa. Elle sera très intéressée de savoir à quel point les poissons ici sont différents de ceux que l’on trouve le long de la côte de Teldrassil. Nous ne pouvons que spéculer sur les raisons de ces différences, mais je pense que la présence de l’Arbre Monde affecte la faune et la flore autour de lui !$B$BS’il vous plaît, faites parvenir cette réponse à Nessa. Si vous souhaitez prendre un hippogryphe pour aller à Rut'theran, adressez-vous au Maître des hippogryphes, Caylais Moonfeather. Si vous souhaitez plutôt prendre le navire, il y en un qui part régulièrement à partir du quai, au nord-ouest.", t = "Retourner à Nessa"},
    [6344] = {ot = "Parler à Nessa Shadowsong.", st = "Une de mes amies, Nessa Shadowsong, est une marchande de poissons, dans le village de Rut'theran. Elle a besoin qu'un colis soit apporté à Sombrivage, et cherche quelqu'un qui serait d'accord pour l'aider.$B$BSi cela vous intéresse et que vous souhaitez rencontrer Nessa, il vous faut prendre le portail qui relie Darnassus et Rut'theran. Vous le trouverez à l'ouest des jardins du temple.", t = "Nessa Shadowsong"},
    [6361] = {ot = "Apporter le Tas de peaux au Maître des Cavaliers célestes, Devrak, à la Croisée.", st = "J'ai un tas de peaux d'animaux des Tarides et je dois les apporter à Thunder Bluff. Là-bas, un collègue, Ahanu, va les utiliser pour fabriquer des produits en cuir.$B$BPourriez-vous lui apporter ces peaux ?$B$BLa façon la plus rapide de rejoindre Thunder Bluff est de chevaucher un Cavalier céleste. Apportez ces peaux à Devrak, notre Maître des Cavaliers célestes, à la Croisée, et dites-lui qu'il faut les transporter à Thunder Bluff.", t = "Un Tas de peaux"},
    [6362] = {ot = "Acheter un voyage pour Thunder Bluff, auprès du Maître des Cavaliers célestes, Devrak, puis apporter le Tas de peaux à Ahanu, à Thunder Bluff.", st = "Contre un modeste paiement, je vous donnerai un Cavalier céleste pour Thunder Bluff. Il n’existe pas de moyen plus rapide pour se rendre sur place !$B$BSi cela vous convient, revenez me voir quand vous souhaiterez partir.$B$BSi vous voulez apporter ces peaux à Ahanu, vous le trouverez à l’Armurerie de Hewa, à la base de la tour des Cavaliers célestes, dans Thunder Bluff. C’est exactement là que vous atterrirez !", t = "Voyage vers Thunder Bluff"},
    [6363] = {ot = "Apporter les Marchandises en cuir d'Ahanu à Tal, à Thunder Bluff.", st = "J’ai préparé des marchandises en cuir pour Jahan, destinées à être vendues à la Croisée. Voulez-vous les lui apporter ?$B$BSi vous avez déjà été à la Croisée et si vous avez parlé au Maître des Cavaliers célestes, vous pouvez monter l’un de nos Cavaliers célestes de Thunder Bluff pour retourner le voir.$B$BApportez les marchandises en cuir à Tal, le Maître des Cavaliers célestes de Thunder Bluff, et parlez-lui d'un voyage vers la Croisée.", t = "Tal le Maître des Cavaliers célestes"},
    [6364] = {t = "Retourner vers Jahan"},
    [6365] = {ot = "Apporter la Chair de Zargh à Devrak, à la Croisée.", st = "J'ai quelques morceaux de viande de choix que je veux envoyer à une amie. Son nom est Gryshka, elle est aubergiste à Orgrimmar. Voulez-vous livrer cette viande pour moi ?$B$BLa façon la plus rapide d'aller à Orgrimmar, c'est le Cavalier céleste. Portez la viande à Devrak, le Maître des Cavaliers célestes de la Croisée, et voyez avec lui comment la transporter à Orgrimmar.", t = "Viandes vers Orgrimmar"},
    [6381] = {ot = "Planter 10 Graines de Gaea sur les Monticules de Gaea, puis parler à Tammra, à la Retraite de Roche-Soleil.", st = "Comme vous avez pu le constater, $c, le cycle de la vie demeure une instance puissante, même quand la terre souffre. Vous devez aller planter ces graines au coeur de la destruction, à l'ouest, dans le Val calciné. Sur votre chemin, prenez garde aux harpies et aux élémentaires de feu enragés, fléaux vivants qui sévissent sur cette terre scarifiée.$B$B$n, prenez ces Graines de Gaea enchantées, et allez les planter dans des monticules de sol fertile. Le cycle de la vie doit se perpétuer !", t = "Nouvelle vie"},
    [6382] = {ot = "Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.", st = "Votre force n'a de cesse de m’impressionner, $c. Votre volonté de chasser est telle que j’ai toute confiance en vous pour passer à des défis et des épreuves plus ardus.$B$BLes forêts d’Ashenvale couvrent de vastes étendues sauvages sur lesquelles la Horde cherche à étendre sa domination politique et spirituelle. Si vous voulez vraiment faire vos preuves, cherchez conseil auprès de Senani Thunderheart, au Poste de Bois-brisé. L’Avant-poste se trouve au nord du chemin qui mène hors des Tarides.", t = "La Chasse d'Ashenvale"},
    [6383] = {t = "La Chasse d'Ashenvale"},
    [6384] = {ot = "Acheter un voyage pour Orgrimmar, auprès du Maître des Cavaliers célestes, Devrak, puis apporter la Chair de Zargh à Gryshka, à Orgrimmar.", st = "Pour quelques menues pièces, je vous fournirai un Cavalier céleste qui vous portera à travers les nuages, jusqu’à Orgrimmar. Quand vous y serez, vous pourrez livrer la chair de Zargh à Gryshka. Son auberge se trouve dans la Vallée de la force, non loin de la Tour des cieux, où mon Cavalier céleste vous déposera.$B$BRevenez me voir quand vous souhaiterez faire le voyage.", t = "Trajet vers Orgrimmar"},
    [6385] = {ot = "Apporter la Lettre de Gryshka à Doras, à Orgrimmar.", st = "J’ai écrit une lettre pour remercier Zargh. Voudriez-vous la livrer pour moi ? Si vous avez déjà visité la Croisée et que vous y avez parlé avec le Maître des Cavaliers célestes, vous pouvez monter un Cavalier céleste pour vous y rendre.$B$BPortez ma lettre à Doras, le Maître des Cavaliers célestes d’Orgrimmar, et entretenez-le d’un voyage vers la Croisée.", t = "Doras le Maître des Cavaliers célestes"},
    [6386] = {t = "Retour à la Croisée"},
    [6387] = {ot = "Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar.", st = "Je vois maints jeunes nains à ma porte, avides d’apprendre l’art du minage. Et si un mineur a besoin de quelque chose, c’est bien d’une pioche !$B$BJ’ai une liste d’étudiants qui ont travaillé dur pendant leur apprentissage, et ont gagné une pioche d'honneur en échange de leurs efforts. Apportez ma liste à Golnir Bouldertoe, à Forgefer. Il aura préparé les pioches.$B$BLe moyen le plus rapide pour se rendre sur place est d’utiliser un gryphon. Apportez d’abord la liste à notre Maître des gryphons, Thorgrum Borrelson, et discutez avec lui de la possibilité d’un voyage vers Forgefer.", t = "L'honneur des étudiants"},
    [6388] = {t = "Gryth Thurden"},
    [6391] = {ot = "Acheter un billet de gryphon pour Forgefer, auprès du Maître des gryphons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Bouldertoe, à Forgefer.", st = "Pour quelques menues pièces de monnaie, l'un de mes gryphons vous conduira à Forgefer. Là, vous donnerez la liste de Brock à Golnir Bouldertoe. Vous le trouverez à la Guilde des mineurs de la montagne profonde. C'est dans le quartier de la Grande Forge de Forgefer, mon gryphon vous déposera en plein dedans !$B$BRevenez me voir quand vous serez sur le point de partir.", t = "Voyage vers Forgefer"},
    [6392] = {ot = "Acheter un billet de gryphon pour Thelsamar, auprès du Maître des gyphons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Stoneseeker, à Thelsamar.", st = "Vous pouvez vous payer un vol de gryphon jusqu'à Thelsamar pour pas grand-chose... à condition d'y être déjà $gallé:allée;. Les gryphons ne volent que vers des lieux que vous avez déjà visités, alors demandez bien à chaque Maître des gryphons si vous pourrez voler vers lui plus tard.$B$BVous avez déjà rencontré Thorgrum, le Maître des gryphons de Thelsamar, alors vous pouvez retourner le voir. Et une fois dans Thelsamar, vous pouvez livrer les pioches à Brock Stoneseeker.$B$BVenez me voir quand vous serez sur le point de partir.", t = "Retourner vers Brock"},
    [6393] = {ot = "Apporter 10 Incendrites à Tsunaman, dans la Retraite de Roche-Soleil.", st = "Le Tribunal des marées m'a envoyé pour faire la guerre aux élémentaires de feu des Serres-Rocheuses. Neptulon le Chasseur des vagues, Seigneur de tous les élémentaires d'eau, a particulièrement intérêt à voir éteints nos ardents cousins.$B$B$n, vous pouvez m'aider à gagner les faveurs du Tribunal en détruisant les élémentaires de feu dans le Val calciné. Une fois détruits, les élémentaires de feu rejettent des Incendrites. Rapportez-les-moi pour toucher votre récompense.", t = "Guerre élémentaire"},
    [6394] = {ot = "Apportez la Pioche de Thazz'rill au contremaître Thazz'rill.", st = "$n, vous êtes quelqu'un de fiable. Puis-je compter sur vous pour une autre tâche ?$B$BIl y a quelque temps, je prospectais une grotte, dans le nord, à la recherche de minéraux, et j’y ai perdu ma pioche favorite. Quand j’y suis retourné plus tard pour tenter de la retrouver, j’ai vu que la grotte était pleine de bêtes hostiles ! Pourriez-vous aller dans cette grotte, le convent de la Lame ardente, $n, et récupérer ma pioche ?$B$BJe l’ai oubliée dans la salle des chutes d’eau. Ma pioche est enchantée et vous la verrez dans l’obscurité, elle ne devrait pas être difficile à trouver... le problème c’est plutôt ce qui est chargé de la garder !", t = "La pioche de Thazz'ril"},
    [6395] = {ot = "Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth.", st = "Avant la peste, mon amie Marla Fipps et son mari Samuel vivaient heureux. Mais quand la peste est survenue, Samuel a succombé et a rejoint les rangs du Fléau.$B$BMarla n'a échappé à l’épidémie que pour mourir des mains de son mari, privé de raison. Pourtant, son amour était si fort que sa dernière volonté fut que son bien-aimé Samuel soit enterré avec elle.$B$BSamuel Fipps erre dans un camp en ruine le long de la route au nord-est du Glas. Tuez-le et accomplissez la volonté de Marla : enterrez-le dans sa tombe, dans la première rangée de notre cimetière.", t = "La dernière volonté de Marla"},
    [6401] = {ot = "Apprendre la bonne nouvelle à Tammra Windfield, dans la Retraite de Roche-Soleil.", st = "Allez apporter cette bonne nouvelle à Tammra Windfield, la tante de Kaya, qui se trouve à la Retraite de Roche-Soleil ! Kaya est vivante ! Nous la croyions perdue après l'attaque de notre village. Suivez la route de l'ouest pour arriver à la Retraite de Roche-Soleil.", t = "Kaya est en vie"},
    [6421] = {ot = "Explorer la grotte du ravin des Eboulis, et apporter 10 Cristaux de résonite à Mor'rogal, dans la Retraite de Roche-Soleil.", st = "Quelque chose ne va pas dans les Serres-Rocheuses. Vous sentez cette tension dans l'air, $n ?$B$BAu sud-est d'ici, dans le Ravin des éboulis, se trouve une profonde caverne. Les kobolds sont là-bas et passent tout leur temps à extraire un cristal rare, la résonite. J'ai besoin de vous pour m’en rapporter quelques échantillons afin de comprendre ce qui se passe dans cette caverne. J'ai aussi besoin de connaître sa profondeur.$B$BAllez, jeune $c, il est impératif que je sache quel mal se cache sous ces montagnes.", t = "Le ravin des Eboulis"},
    [6441] = {ot = "Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé.", st = "Salut ! J'ai voyagé dans tout Ashenvale, en me dirigeant vers Ratchet et j'ai décidé de faire un arrêt ici à Bois-brisé. Je suis toujours à la recherche d'une opportunité et on dirait bien que les cornes de satyre sont très demandées ces jours-ci à Ratchet.$B$BJe me suis renseignée, il semble que les satyres du défilé de la Nuit, de Satyrnaar et de Xavian ont tous le type de cornes que je cherche. Je ne suis pas de taille face à ces satyres... mais vous en revanche, on dirait bien que oui!$B$BJe vais vous dire, ramassez ces cornes pour moi et vous ne regretterez pas le temps que vous y aurez passé.", t = "Cornes de satyre"},
    [6442] = {ot = "Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram.", st = "Le mal se cache le long de cette côte, $r.$B$BC'est ce qui reste de la ville condamnée de Zoram, détruite il y a longtemps et engloutie sous les eaux. Perdue et presque oubliée.$B$BAujourd’hui les nagas y sont retournés, pour une raison que nous ne connaissons pas. Mais la raison importe peu, nous devons défendre la terre que nous avons travaillée si durement.$B$BRevenez me voir avec 20 de leurs têtes ! Rejetez les nagas dans les profondeurs !", t = "Des nagas sur la grève de Zoram"},
    [6461] = {ot = "Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes.", st = "Nous, les trolls de Malaka'Jin, nous avons prospéré sur cette terre. Les Serres-Rocheuses nous permettent de chasser pour vivre.$B$BDernièrement, nous avons eu la visite de pique-assiette... À la nuit, les araignées des montagnes ont fait un raid sur nos camps pour voler le fruit de notre chasse.$B$BSi vous nous aidez à éliminer ces bêtes horribles, les trolls de Malaka'Jin vous en seront reconnaissants à jamais. Les araignées vivent partout dans les Serres-Rocheuses. Dirigez-vous simplement vers le nord et vous pourrez le constater.", t = "Suceurs de sang"},
    [6462] = {ot = "Apporter 8 Charmes trolls à Mitsuwa, à l’Avant-poste de Zoram'gar.", st = "Mes parents voyageaient ici avec plusieurs charmes trolls sacrés, mais les furbolgs Crins-de-Chardon les ont attaqués et tués avant qu'ils n'aient atteint Zoram'gar ! Ces misérables furbolgs !$B$BMes frères et sœurs qui ont été tués me manquent, mais nous serons de nouveau réunis dans l'au-delà. Cependant, ces charmes trolls ont beaucoup de valeur dans ce monde. C'est une hérésie qu'ils soient aux mains des furbolgs !$B$B$n, vous devez récupérer ces charmes ! Ils se trouvent dans des coffres dans le repaire des Crins-de-Chardon, une caverne au bout du village des Crins-de-Chardon, au nord d'Astranaar.", t = "Charme troll"},
    [6481] = {ot = "Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté.", st = "Vous avez découvert une sombre menace pour cette terre, $c. La gangue de résonite que vous avez trouvée dans cette caverne abrite un Terrestre dormant du nom de Goggeroc.$B$BGrâce à mes pouvoirs chamaniques, j'ai modifié le mélange des cristaux de résonite que vous avez ramassés. Prenez ce cristal de résonite enchanté et servez-vous-en pour ouvrir la gangue de résonite qui abrite le Terrestre.$B$BQuand il sera réveillé, Goggeroc sera affaibli... Abattez-le, $n !", t = "Un Terrestre se lève"},
    [6482] = {t = "Liberté pour Ruul"},
    [6503] = {ot = "Tuer 9 Estafettes d'Ashenvale, puis retourner voir Kuray'bin, à l’avant-poste de Bois-brisé.", st = "Nous avons reçu des rapports selon lesquels des estafettes ont quitté l’Avant-poste d'Aile-argent il n’y a pas longtemps. Elles seraient en train de rôder à proximité de nos territoires forestiers. Nous ne voulons pas qu'elles puissent collecter des renseignements concernant nos défenses !$B$BPartez et voyagez à travers les forêts, au sud de notre position et à l’est d'Aile-argent, l'avant-poste de l’Alliance. Trouvez et massacrez ces estafettes, puis revenez me voir.", t = "Les estafettes d'Ashenvale"},
    [6522] = {ot = "Apporter le Petit parchemin à Varimathras, à Fossoyeuse.", st = "Madame,$B$BVous savez exactement ce que nous sommes en train d’offrir. L’opportunité de prendre les Tarides et les terres au-delà n’est pas à négliger. Nous ne demandons que votre aide en retour. Nous ne vous demandons que votre aval pour mener nos actions dans la zone, en toute liberté.$B$BS’il vous plaît, donnez-nous l’occasion de pouvoir en discuter plus avant. Nous possédons une grande puissance, et nous sommes prêts à la partager avec ceux qui auront la sagesse de nous rejoindre. Je resterai à l’extérieur des Souilles de Tranchebauge, pour le moment.$B$BJe vous salue respectueusement,$BAmbassadeur Malcin", t = "Une alliance impie"},
    [6523] = {ot = "Escorter Kaya Flathoof au Camp Aparaje, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres-Rocheuses.", st = "Merci de me venir en aide ! Nous devons partir avant qu’ils ne découvrent que je suis libre. Pourriez-vous m’escorter jusqu’à Camp Aparaje. Je connais la route.$b$bMon père, Makaba Flathoof, se languit de savoir comment je vais.", t = "Protéger Kaya"},
    [6541] = {t = "Rapport à Kadrak"},
    [6543] = {ot = "Apporter les Rapports du clan Chanteguerre à l’Eclaireur chanteguerre, au Messager chanteguerre et au Voltigeur chanteguerre. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides.", st = "J’ai récemment diligenté quelques éclaireurs dans Ashenvale, et j’ai besoin de quelqu’un pour leur faire parvenir les nouvelles directives et pour rapporter ce qu’ils ont pu observer sur place.$B$BAllez d’abord à l’avant-poste de Zoram'gar, le long de la côte, à l’ouest sur la grève de Zoram, pour localiser le premier d'entre eux. Vous devrez aussi passer par le poste de Bois-brisé, au nord et le long de la route vers l’est, dans Azshara. Vous trouverez un éclaireur et un voltigeur, là-bas.$B$BRemettez-leur à chacun un rapport, puis prenez note des dernières découvertes qu’ils ont faites.", t = "Les rapports chanteguerres"},
    [6544] = {t = "L'assaut de Torek"},
    [6548] = {ot = "Tuez 8 Forbans du Totem sinistre et 6 Mercenaires du Totem sinistre, puis retournez voir Makaba Flathoof, près de la lisière sud-est des Serres-Rocheuses.", st = "Le clan du Totem sinistre a fait un raid sur mon village et y a tué presque tout le monde ; j’ai lutté autant que j’ai pu, abattant autant d’ennemis que possible, mais j’ai dû battre en retraite et ai pu m’échapper de justesse.$b$b$n, je n’aspire qu’à la vengeance et à en voir toujours plus mourir sous mon épée. Aidez-moi à les massacrer, vous les trouverez un peu plus à l’ouest.", t = "Vengez mon village !"},
    [6561] = {ot = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff.", st = "Ma force m'a abandonné. Votre aide m'est nécessaire !$b$bIl y a longtemps, cet endroit était un grand temple d'Elune. Mais il a été conduit à la ruine quand la corruption d'un Dieu très ancien a suinté de la terre et souillé le Puits de lune sacré.$b$bAku'Mai, le serviteur du Dieu très ancien, est sorti des eaux.$b$bLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Ces sectateurs, menés par Kelris, sacrifient des innocents à Aku'Mai afin d’obtenir sa puissance.$b$bS'il vous plaît, $n, tuez Kelris et apportez sa tête à Bashana, à Thunder Bluff.", t = "L'infamie de Brassenoire"},
    [6562] = {ot = "Parler à Je'neu Sancrea, à Ashenvale.", st = "Je'neu Sancrea a besoin d'aide. Il est à l'avant-poste de Zoram'gar dans Ashenvale. La forêt des elfes de la nuit est au nord des Serres-Rocheuses. Vous pouvez le rejoindre en voyageant par la combe des Cisailles ou en vous dirigeant vers le nord à travers les Tarides. La grève de Zoram est à l'ouest de la forêt, assez loin. Faites preuve de prudence, $n. Il y a des forces là-bas qui ne verront pas votre présence d'un bon œil.", t = "Problèmes dans les profondeurs"},
    [6563] = {t = "L'Essence d'Aku'Mai"},
    [6564] = {ot = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale.", st = "Quelques mots sont griffonnés en haut de la note chiffonnée :$B$B\"Oui, dites à toutes les prêtresses de m'apporter les cristaux. L'esprit des élémentaires d'eau y est fort et ils aideront énormément nos aquamanciens dans leurs prédictions.$B$BEn contrôlant le pouvoir des cristaux, nous apaiserons Aku'Mai. Un jour, nous aurons assez de pouvoir pour ramener Aku'Mai et le monde connaîtra à nouveau une ère de gloire ! Une ère régie par les Dieux très anciens ! \"", t = "Allégeance aux Dieux très anciens"},
    [6565] = {ot = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale.", st = "On ne peut pas permettre au disciple du Marteau du crépuscule d'achever son plan. Le Marteau du crépuscule ne comprend pas l'esprit de la nature. Il croit aux Dieux très anciens, des créatures de chaos et de destruction qui ont été battues il y a bien longtemps. On ne peut pas permettre à ce Lorgus de réussir. Vous devez l'arrêter, $n. Je ne peux pas le faire moi-même – je suis trop faible.$B$BAllez dans les Profondeurs de Brassenoire, trouvez-le et tuez-le. Revenez me voir ici à Zoram'gar quand ce sera fait.", t = "Allégeance aux Dieux très anciens"},
    [6607] = {t = "Nat Pagle, pêcheur de l'extrême"},
    [6629] = {ot = "Tuer Grundig Darkcloud et 6 Brutes du Totem sinistre, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres Rocheuses.", st = "$n, vous avez fait un travail magnifique en tuant les membres du Totem sinistre. Grundig Darkcloud et sa bande de brutes personnelles sont de loin les pires de tous. Il était celui qui mena l'attaque sanglante contre mon village.$b$bVous le trouverez au Poste du Totem sinistre, un peu plus haut sur le chemin qui conduit vers l'ouest. Tuez-le et je vous en serai reconnaissant pour toujours.", t = "Tuer Grundig Darkcloud"},
    [6641] = {ot = "Garantir la sécurité de Muglash tandis qu’il voyage vers le brasero. L’aider à éteindre le brasero, puis le protéger, en combattant les nagas.$B$BEn cas de réussite, retourner à l’avant-poste de Zoram'gar et informer le messager chanteguerre de la mort de Vorsha la Flagellante.", st = "Vorsha la Flagellante... L'hydre diabolique qui erre dans les mers...$B$BElle a attaqué plusieurs fois notre avant-poste, chaque fois de façon délibérée, pour dévaster tout ce qui était sur son chemin.$B$BMais je suis prêt, $n. Je me suis préparé à terrasser l'hydre et à mettre fin à ses attaques sur Zoram'gar.$B$BLes nagas honorent cette mauvaise bête en laissant brûler un brasero sur une île au large de la côte. Je crois que si nous l'éteignons, la colère la fera apparaître.$B$BNous aurons besoin d'aide, faites en sorte de ramener des associés puissants.", t = "Vorsha la Flagellante"},
    [6661] = {ot = "Capturer 5 Rats des profondeurs en utilisant le Pipeau du dératiseur. Conduire les Rats vers Monty. N’oubliez pas de rendre le Pipeau quand vous aurez terminé.", st = "Graine de chenapan. Arrrr... Vous nous regardez bosser ? Nous avons un sérieux problème de rats ici et pas assez de mains sur le pont.$B$BVous dites quoi ? Y a qu'à attraper les rats en jouant d'la flûte autour de cette vermine et ils vous suivront au bout du monde !$B$BAttrapez-en juste 5 petits et rapportez-les ici. On en a besoin vivants.$B$BArrrrr...", t = "Chasse au rat dans les profondeurs"},
    [6662] = {ot = "Apporter le Carton de viande mystère à Nipsy, au Dépôt du Tram des profondeurs de Stormwind.", st = "Mon frère Nipsy, y gère la fabrication de kébabs de rat à l'aut' bout de la ligne. Faut lui apporter cette caisse de rats avant qu'y se sentent mal. Ça vous dit d'aller, pas vrai !$B$BZ'avez déjà pris le tram avant, oui ? C'est facile. Faut juste sauter dedans quand il arrive, puis apprécier le voyage. Ouais, et oubliez pas garder vos bras et vos pieds à l'intérieur pendant le trajet, si vous voulez pas les perdre.", t = "Mon frère, Nipsy"},
    [6921] = {ot = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", st = "Le Marteau du crépuscule s'est déplacé dans les ruines d'Ecrin-de-Lune des Profondeurs de Brassenoire. Leur présence forcera les élémentaires à travailler contre nous. Si nous ne nous occupons pas de cette région, ils en prendront complètement le contrôle.$B$B$n, allez à Brassenoire et trouvez la pierre de la brasse. Elle devrait se trouver quelque part, à proximité, dans l'eau. À l'intérieur, se trouve un Noyau de la Brasse, un objet qui, s'il est utilisé correctement, offrira un historique de toute l'activité des élémentaires. Si je l'avais, je pourrais, avec l'aide du Cercle terrestre, faire quelque chose pour les arrêter !", t = "Parmi les ruines"},
    [6922] = {ot = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.", st = "Sur l'élémentaire d'eau vaincu, vous trouvez un étrange globe d'eau. Vous avez la nette impression que l'objet a absorbé l'énergie de la créature. À l'intérieur du globe, vous discernez une eau aux reflets malsains. Le globe lui-même semble insensible à toute forme d'action physique.$B$BS'il y a une personne qui puisse comprendre ce qu'est cet objet, cela ne peut être que Je'neu Sancrea du Cercle terrestre. Il se trouve dans l'avant-poste de Zoram'gar de la Horde, à Ashenvale.", t = "Baron Aquanis"},
    [6981] = {ot = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.$B$BPuis livrez l'Eclat, selon les instructions.", st = "L'éclat est d'un vert brillant, et bien que compact, ce qui ressemble à de la fumée tourbillonne juste au-dessous de sa surface. Vous ne pouvez vous empêcher de contempler les profondeurs du cristal, bien qu'en même temps, vous sentiez qu'il y réside quelque chose de très inquiétant.$B$BPeut-être devriez-vous voir si quelqu'un à Ratchet pourrait vous en apprendre plus à propos de cet étrange éclat...", t = "L'Eclat luminescent"},
    [7383] = {ot = "Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar.", st = "Cependant, tout ne se passait pas parfaitement avec Teldrassil. Au début, les plans soigneusement conçus par Staghelm se déroulèrent comme il l'avait espéré, mais il y eut un petit problème, un problème auquel beaucoup des difficultés avec Teldrassil pouvaient être attribuées.$b$bJe ne vais pas m'engager dans ce propos maintenant, cependant. Vous devez aller au dernier puits de lune, au nord-ouest, dans la clairière de l'Oracle. Sous les branches de l'arbre-oracle se trouve le premier et le plus puissant de nos puits. Remplissez un flacon de son eau et revenez me voir.", t = "La couronne de la Terre"},
    [65601] = {t = "Les affres de l’amour"},
    [65602] = {t = "Qu’est-ce que l’amour ?"},
    [65603] = {ot = "Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné.", st = "L’heure est venue. Prenez la figurine et descendez dans les cryptes, où vous la placerez au centre du cercle d’invocation préparé à cet effet.\n\nVous ouvrirez ainsi un portail permettant à un incube de passer dans notre monde.\n\nPrudence toutefois, car le Sayaad vous attaquera dès qu’il aura flairé le piège. Vous allez devoir déployer toutes les compétences que vous avez acquises pour le vaincre.\n\nSi vous réussissez, revenez et je soumettrai la créature à votre volonté. Dans le cas contraire, vous pourrez dire adieu à votre âme.", t = "Le lien"},
    [65604] = {ot = "Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Bloodeye, à Orgrimmar.", st = "Oui… Je vois. Je perçois les émotions résiduelles prises au piège de la trame. L’amour imprègne chacun de ces fils. L’incube sera incapable de résister.\n\nApportez l’écharpe au cercle d’invocation de la tente de Neeru, $n. Appelez un incube maléfique, puis prouvez-lui votre supériorité, car il ne se laissera pas dominer aisément. Au contraire, préparez votre magie et attendez-vous à un combat acharné. De nombreux démonistes ont commis l’erreur fatale de sous-estimer un démon, ne les imitez pas.\n\nUne fois la créature vaincue, rapportez-moi l’étoffe. Et je raconterai tout à Magar.", t = "Le lien"},
    [65610] = {ot = "Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar.", st = "J’ai rencontré Krilge alors que je travaillais de l’étoffe lunaire en Ashenvale. Il était en poste là-bas, pour protéger les civils de tout danger… jusqu’à sa disparition…\n\nSes collègues ont mis un terme aux recherches, et il est accusé de désertion, mais je n’en crois pas un mot.\n\nNous nous donnions souvent rendez-vous au lac Tombeciel, avant que l’endroit ne grouille de bêtes agressives.\n\nJe ne suis pas du genre à quémander des services, mais ma gratitude vous sera acquise si vous décidez de vous rendre en Ashenvale afin de retrouver sa trace.", t = "Comme tu me manques"},
    [76156] = {t = "La traque de la Terre-Mère"},
    [76160] = {t = "La traque de la Terre-Mère"},
    [76240] = {ot = "Acheter ou attrapez un goujon brillant cru, puis utilisez l’ensemble de couteaux pour lever ses filets devant Boarton Ombre-Totem à Thunder Bluff.", st = "J’ai une dernière idée qui pourrait bien nous mettre sur la voie du succès. Je reste persuadé que vous cachez un certain talent, mais tentons cette fois de le révéler de façon un peu moins directe.\n\nAllez vous procurer un goujon brillant cru et rapportez-le-moi. Prenez ces dagues, nettoyez-le et levez-en les filets. Ne vous posez pas trop de questions, laissez simplement parler votre instinct.", t = "La traque de la Terre-Mère"},
    [79008] = {t = "… et cette note que vous avez trouvée"},
    [79360] = {ot = "Éliminez Charlga Trancheflanc au kraal de Tranchebauge et recueillez des renseignements sur les plans des Hurans.", st = "Maintenant que vous maîtrisez les éléments, vous avez une obligation envers eux, et donc envers Azeroth. Nous implorons leur aide, nous n’exigeons pas leur puissance. Ils vous ont accordé des bienfaits, il est temps de leur rendre la politesse. Et je crois savoir comment.\n\nLes Hurans détournent les éléments pour assouvir leurs propres desseins et étendent leur emprise à l’intérieur de ces frontières. Pénétrez dans leur kraal et mettez un terme à leurs agissements, quels qu’ils soient. Nous devons protéger ces terres, coûte que coûte.", t = "Soutien élémentaire"},
    [79364] = {ot = "Parlez à Prate Œil-des-Nuages aux Mille pointes.", st = "D’après le mot que vous avez trouvé, les Tranchecrins se sont enfouis dans les Mille pointes pour accomplir une sorte de rituel tenu secret. Tempêtes déchaînées et marées montantes…\n\nLes Hurans doivent recourir à quelque cruelle sorcellerie apprise auprès de Hirzek, un chaman qui n’a reculé devant rien pour pervertir les éléments. S’ils comptent noyer le canyon, il leur faudrait des pouvoirs élémentaires dévastateurs.\n\nNous manquons cruellement de moyens pour affronter cette menace, mais avec votre maîtrise du chamanisme, vous avez sûrement une idée. Retournez auprès des vôtres et tâchez de trouver une réponse.", t = "Surveiller les cieux"},
    [86574] = {t = "Ravitaillement des Serres-Rocheuses"},
    [86576] = {t = "Les babioles des Rougefuries"},
    [86585] = {ot = "Plantez l’étendard de Forgefer afin d’attirer le casse-tête trogg, tuez-le, puis faites votre rapport au capitaine Rudagite.", st = "La dépouille de la montagnarde porte un étendard de Forgefer. Elle effectuait peut-être une mission de reconnaissance, à moins qu’elle n’ait péri lors d’une charge désespérée. Quoi qu’il en soit, l’étendard a été jeté à terre et piétiné. La montagnarde a reçu un coup à la tête si violent que son heaume a été projeté au loin. Elle a été tuée sur le coup, probablement par un Trogg armé d’un gourdin clouté.\n\nLe Trogg qui l’a abattue est certainement encore dans les environs, et il doit se souvenir de l’étendard. Il se montrera peut-être en voyant l’étendard de Forgefer flotter au vent.", t = "La bannière des trépassés"},
    [86613] = {t = "Outils d’excavation"},
    [86614] = {t = "L’argent des vagues"},
    [86667] = {t = "Enneigement"},
    [86758] = {t = "Remuer le couteau dans la plaie"},
    [86784] = {t = "Brindilles et ossements"},
    [87288] = {t = "Fourrures soyeuses de sabre-de-nuit"},
    [87760] = {t = "Plongeur sacré"},
    [90902] = {t = "Redécouverte de la Lumière"},
    [91208] = {ot = "Trouvez la paladine effrayée au Glas.", st = "Nos paladins relevés ne s’habituent pas tous rapidement à notre nouvelle réalité. Certains ont du mal à accepter d’être à présent, d’une certaine manière, ce qu’ils ont passé toute une vie à affronter.\n\nSouvent, il ne manque à ces gens-là qu’un geste de sympathie et une oreille attentive. Malheureusement, beaucoup d’entre eux peuvent devenir violents. Trouvez le paladin effrayé qui s’est enfui dans les collines directement à l’ouest de la chapelle. Tendez-lui une main amicale et ramenez-le vers la Lumière si vous le pouvez.", t = "L’acceptation"},
    [91209] = {t = "Poursuivre votre entraînement"},
    [91282] = {ot = "Trouvez la forteresse de Bandarion et présentez-vous devant Breton Samuels.", st = "Il est encourageant de voir que mes frères et sœurs nouvellement relevés vivent bien, comme vous. Cependant, seules la communauté et la foi partagée permettront d’atteindre notre plein potentiel, et c’est pour ça que nous avons commencé à former un nouvel ordre de paladins, ici, en Tirisfal.\n\nSi vous voulez plus d’informations, venez nous voir à notre monastère à la lisière de la forêt des Murmures. La forteresse de Bandarion. Vous la trouverez sur les falaises juste au nord-ouest de la ferme des Solliden. Difficile de la rater.", t = "Un second foyer"},
    [91285] = {t = "Des Murlocs à nos portes"},
    [91294] = {ot = "Parlez aux habitants la forteresse de Bandarion.", st = "Maintenant que la menace directe d’une attaque de Murlocs est écartée, je vous encouragerais à vous montrer partout dans la forteresse. Ce n’est pas grand-chose, mais c’est chez nous.\n\nQuand vous aurez terminé l’exploration, allez voir Danitha Morr, notre cheffe. Elle vous aidera à vous poser.\n\nC’est une très heureuse rencontre, $n. Puisse la Lumière vous guider.", t = "En patrouille"},
    [91316] = {t = "Procéder aux réparations"},
    [91317] = {t = "Les ternis"},
    [91723] = {t = "Des instruments délicats"},
    [91724] = {t = "Des instruments délicats"},
    [91725] = {t = "Les fournitures d’enchantement volées"},
    [91732] = {t = "De l’acier de qualité"},
    [91733] = {t = "En aval"},
    [91740] = {ot = "Apportez la tête de Coassie à Merell Ross à la tour de la Crête.", st = "<Ce Murloc devait terroriser les gens de passage dans les environs depuis quelque temps. Vous vous dites que les gardes du coin apprécieront d’apprendre qu’il a été terrassé.>", t = "La tête de Coassie"},
    [91741] = {ot = "Rapportez le livre au frère Paxton.", st = "<Un des Kobolds a laissé échapper ce livre. Il semblerait qu’il ait essayé de le manger.\n\nFrère Paxton, de l’abbaye, tient une petite bibliothèque. Le livre devait venir de là.>", t = "Un livre grignoté"},
    [91743] = {t = "Rongeurs retors"},
    [91745] = {ot = "Allez voir Kelsey Fond devant la mine de la Crête aux échos, dans la vallée de Comté-du-Nord.", st = "Allez voir la nouvelle apprentie mineuse, Kelsey Fond. Elle travaille juste devant la mine, elle aura sans doute vu ce que les Kobolds manigancent. Et tant que vous y êtes, elle pourra peut-être vous montrer deux-trois trucs sur son métier.", t = "Consultant en minage"},
    [91746] = {ot = "Apportez la tête d’Ormepatte à Helene Tannepeau non loin de Comté-de-l’Or.", st = "Ce trophée est un impressionnant témoignage de votre victoire contre Ormepatte. Un chasseur ou dépeceur local pourrait avoir envie d’entendre cette histoire.", t = "La tête d’Ormepatte"},
    [91751] = {t = "Des peaux de loups rugueuses"},
    [91752] = {t = "Un peu de recul"},
    [91753] = {t = "Une leçon enchanteresse"},
    [91758] = {t = "Suivez ce Kobold !"},
    [91772] = {ot = "Suivez les traces des Kobolds avec le kit de pistage et allez avertir le maréchal Dughan, à Comté-de-l’Or.", st = "Bon, prenez ce kit de pistage des Kobolds, il vous permettra de retrouver celui qui tracasse McBride.\n\nRemontez sa piste et rapportez votre butin au maréchal Dughan, à Comté-de-l’Or.\n\nQuelque chose me dit que ces petites vermines préparent quelque chose qui va au-delà de Comté-du-Nord, donc vous aurez besoin de son aide.", t = "Chut, on chasse le Kobold"},
    [91775] = {t = "Restitution de livres"},
    [91777] = {t = "Des livres rares"},
    [91858] = {ot = "Rendez-vous au Sépulcre dans la forêt des Pins-Argentés et parlez à Trevan Rol des voyageurs disparus du Cercle terrestre.", st = "Les évènements ont pris un tour malheureux aux Pins-Argentés, et ça nous offre une occasion unique de prouver notre valeur à la Horde.\n\nDeux émissaires du Cercle terrestre ont disparu dans la forêt, sur la route de Moulin-de-Tarren. Nous n’en savons pas tellement plus, mais d’après certaines rumeurs, ça tournerait à l’incident diplomatique de taille. Si nous pouvons retrouver les disparus, ce serait un pas vers la légimité dont nous avons cruellement besoin.\n\nNous avons quelqu’un au Sépulcre, un certain Trevan Rol. Rendez-vous là-bas et allez le voir.", t = "Incident diplomatique"},
    [91859] = {t = "Un curieux duo"},
    [91860] = {ot = "Fouillez l’île de Fenris à l’est pour apprendre le sort des voyageurs du Cercle terrestre.", st = "La nuit dernière, pendant ma patrouille, j’ai vu une troupe de Gnolls en train de jeter un très gros corps sur un bûcher, sur la rive de l’île de Fenris. Je n’ai vu ni Elfe ni autre corps plus petit, mais je dirais quand même que ça ne se présente pas bien pour ces gens.\n\nSi vous êtes assez brave ou stupide, je vous en prie, foncez sur l’île de Fenris pour en apprendre plus. Mais si vous voulez mon avis, c’est se donner beaucoup de mal pour une bêcheuse d’Elfe qui est probablement morte depuis longtemps.\n\nJe sais bien que vous autres $gpaladins:paladines;, vous aimez bien faire de grands serments et épouser les causes perdues, mais là, ça ne vaut pas le coup. Je vous le dis.", t = "Un sort terrible"},
    [91861] = {t = "Dans le donjon de Fenris"},
    [91862] = {t = "Lumina Chantelevent"},
    [91920] = {t = "Yeux sauvages"},
    [91921] = {ot = "Apporter la potion de Quinn à Quinn Yorick au lopin d’Ivar, au nord du Sépulcre.", st = "Voici la nouvelle potion pour aider Quinn à se remettre, préparée avec l’amour extrait de six cœurs entiers.\n\nMaintenant, veuillez m’excuser avant que votre présence ne nécessite encore plus de paperasserie.", t = "Retour vers Quinn (encore une fois)"},
    [92109] = {t = "Mon premier kit d’alchimie"},
    [92110] = {t = "Ma première vraie potion"},
    [92124] = {t = "Inventaire des livres"},
    [92401] = {ot = "Enquêtez sur la disparition d’Edward Tissecœur dans les ruines de Lordaeron.", st = "C’est mon mari, Edward…\n\nIl n’est pas revenu de sa visite hebdomadaire au cimetière des ruines de Lordaeron. Nous avons perdu notre fils lorsqu’Arthas a ravagé la cité, et mon pauvre Edward est toujours rongé par la culpabilité et le chagrin de n’avoir jamais retrouvé son corps. J’ai tenté de le dissuader de poursuivre ses recherches dans ces ruines infestées, mais il refuse d’abandonner. J’essaie de ne pas m’inquiéter, mais voilà plusieurs jours qu’il est parti.\n\nDes choses rôdent là-bas auxquelles je ne saurais faire face… mais si vous acceptez de m’aider, je dois savoir ce qu’il est advenu de mon mari.", t = "Une requête apeurée"},
    [92415] = {ot = "Apportez la lettre tachée de sang à la directrice de l’orphelinat Rossignol, à Hurlevent.", st = "<Une liasse de parchemins, déchirée et maculée, a de justesse survécu aux terres du cimetière foulées par les morts-vivants. Il y est fait mention d’un enfant disparu de la famille Tissecœur. La directrice de l’orphelinat, à Hurlevent, en saura peut-être davantage.>", t = "N’oublie pas que je t’aime"},
    [92421] = {t = "Justice de la Lumière"},
    [92422] = {t = "La colère de Rath’mael"},
    [92432] = {t = "Une requête alarmante"},
    [92434] = {ot = "Trouvez un moyen d’entrer dans Dalaran sur les rives du lac Lordamere.", st = "Ce qui a entraîné l’affaiblissement de la barrière autour de Dalaran a laissé la cité en pleine agitation. Maintenant que vous vous êtes $goccupé:occupée; de leurs patrouilles, il n’y a pas de meilleur moment pour pénétrer à l’intérieur et découvrir leurs secrets.\n\nPrenez la clé que vous avez trouvée au camp d’internement et cherchez l’entrée des égouts le long de la muraille nord de la ville. Avec un peu de chance, ces mages n’avaient aucune raison de placer un sort de protection sur… un point d’entrée aussi désagréable.", t = "Du sang dans les rues"},
    [92456] = {ot = "Récupérez une floraison gangrimprégnée de la cité de Dalaran pour Shylamiir à Hurlevent.", st = "Si vous comptez m’ennuyer, autant vous rendre utile. J’ai une course à vous confier.\n\nPour une cité de mages, Dalaran porte un intérêt étonnant à la botanique. Les membres du Kirin Tor ont tendance à vivre en autarcie, mais j’aimerais beaucoup obtenir un échantillon de leur végétation imprégnée de magie.\n\nVous avez manifestement l’habitude de vous retrouver là où votre présence n’est pas la bienvenue. Vous trouverez peut-être un moyen d’entrer dans la cité. Si vous y parvenez, rapportez-moi ce qui pousse dans leur jardin central.", t = "Un échantillon vert"},
    [92457] = {t = "Arcanes affamées"},
    [92458] = {ot = "Collectez le granule arcanique pour l’image de l’archimage Modera, près de la cité de Dalaran.", st = "Quel que soit ce qui a perturbé les lignes telluriques, tout a commencé au sommet de la citadelle Pourpre. Un bruit de tonnerre a retenti des salons du haut, et nous sommes depuis envahis par un pouvoir arcanique vertigineux. Toute notre puissance est redirigée pour maintenir les sorts de protection en place.\n\nNous ne pouvons pas nous permettre de repousser une intervention plus longtemps. Nous avons besoin d’aide.\n\nLe Kirin Tor est occupé à l’intérieur, mais vous aurez toujours besoin d’une approche moins publique pour pénétrer dans la ville. Prenez cette clé et retrouvez-moi dans la citadelle dès que vous aurez réussi à entrer. Nous devons mettre un terme à cette perturbation.", t = "Cœur de la perturbation"},
    [92460] = {t = "Il est temps de grandir"},
    [92461] = {t = "Équilibre et harmonie"},
    [92462] = {t = "Enquête sur l’infestation"},
    [92463] = {ot = "Détruisez la reine mouche-cirrus dans le bosquet de Thendal.", st = "Si cette forêt est infectée à ce point, tuer les ouvrières ne suffira pas.\n\nEnfoncez-vous dans la forêt pour trouver la reine. Elle devrait être proche de la ruche et entourée d’insectes plus gros et plus agressifs pour la garder, donc prenez garde.\n\nÉliminez-la et revenez ici. Ça nous fera un problème de moins.", t = "La reine mouche-cirrus"},
    [92464] = {ot = "Parlez à Yala Veillevent dans le bosquet de Thendal.", st = "Depuis la disparition de nos bienfaiteurs élémentaires, j’ai l’impression que nous ne faisons que passer d’un trouble à l’autre. Le problème actuel est l’agitation des manifestations venteuses près des pierres dressées au nord-est.\n\nCes simples fées ne sont pas dotées de la même conscience que les esprits du vent qui vivaient autrefois ici. Elles ne font que refléter les forces, les émotions et les intentions des créatures qui les entourent. \n\nMon apprentie, Yala Veillevent, est partie les observer. Retrouvez-la et découvrez ce qu’elle a appris.", t = "Agitation élémentaire"},
    [92465] = {t = "Des agitateurs, des provocateurs, des animaux"},
    [92466] = {ot = "Apportez une chevalière d’Akir au sculpte-vent Boro.", st = "Même si c’est aux éléments du vent que nous devons une bonne partie de notre prospérité, le chemin que nous empruntons exige qu’on obéisse à l’appel des quatre éléments primordiaux et qu’on passe une épreuve pour chacun d’entre eux. Avant de vous lancer sérieusement dans votre première épreuve, vous devez toutefois prouver la force de votre détermination.\n\nRendez-vous aux pierres dressées à l’est. Un groupe de convertis al’aketh y a été repéré, il faut les chasser. Affrontez ces adeptes et apportez-moi l’une de leurs chevalières comme preuve de vos exploits.", t = "L’appel de la terre"},
    [92467] = {ot = "Trouvez la cime des esprits et buvez le sapta de terre.", st = "Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits forts de percevoir les éléments comme nul autre ne le peut. Votre esprit contactera l’élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.$B$BIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs, ne l’oubliez pas.$B$BCherchez la cime des esprits à l’est d’ici, au bout de la passe. Buvez-y votre sapta et… eh bien, vous verrez ce que vous devrez voir.", t = "L’appel de la terre"},
    [92468] = {t = "L’appel de la terre"},
    [92469] = {ot = "Signalez la présence des Al’Aketh à Rorian le Cherchejour dans le bosquet de Thendal.", st = "Vous en avez assez fait ici, $c. Je vais rester m’occuper des potentiels retardataires.\n\nRetournez au village et signalez la présence de la secte à Rorian. Cela ne lui plaira pas.", t = "Retour auprès de Rorian"},
    [92470] = {t = "Matriarche ignoble"},
    [92471] = {ot = "Parlez à Aetheen des Trombes dans le bosquet de Thendal.", st = "Vous ne vous en rendez peut-être pas compte, mais tout ce que vous avez fait jusqu’à présent était une sorte de défi. Une épreuve pour vous préparer à l’avenir. Zéphras est une île vaste, mais elle a besoin de jeunes $gaventuriers pleins:aventurières pleines; de fougue comme vous si nous voulons survivre aux épreuves de notre peuple.\n\nLa femme du nom d’Aetheen des Trombes est une des dirigeantes de notre peuple sur l’île de Zéphras, et elle vous observe depuis un certain temps. Elle a une mission pour vous. Allez lui parler pour en savoir plus.", t = "Aetheen des Trombes"},
    [92472] = {ot = "Présentez-vous à la connétable Aonda à Shen’dar.", st = "L’une des menaces les plus insidieuses de l’île de Zéphras est la secte des Al’Aketh. Il s’agit de zélotes religieux qui vénèrent le soi-disant maître élémentaire de Mur-Céleste, Al’akir le seigneur des Vents. Ce sont des brutes obsessionnelles et leur pouvoir ainsi que leurs ambitions deviennent chaque jour plus redoutables.\n\nVotre chemin vous mènera bientôt à Shen’dar, au sud. Présentez-vous à la connétable Aonda à votre arrivée. La secte menace Shen’dar et ils ont besoin d’aide. Dites à Aonda que c’est moi qui vous envoie.", t = "La prochaine étape"},
    [92473] = {t = "Intrusion agressive"},
    [92474] = {t = "Tomber avec panache"},
    [92479] = {ot = "Lisez la lettre écrite à la hâte et parlez à Tordrin Tigelame à l’abbaye de Comté-du-Nord.", st = "On m’a demandé de vous remettre cela dès que vous seriez de retour des camps des Kobolds, $n. Il s’agit d’une lettre portant le sceau de Tordrin Tigelame, notre maître des chasseurs local. Prenez un moment pour la lire avant de faire quoi que ce soit d’autre, ici, dans l’abbaye.", t = "Une lettre écrite à la hâte"},
    [92481] = {ot = "Examinez le cristal de rappel luminescent, puis parlez à Dorii Murméclat dans le bosquet de Thendal.", st = "Pendant que vous vous occupiez de notre problème de vuldrènes, notre maîtresse des mages locale, Dorii Murméclat, a laissé ce cristal de rappel, qui contient une sorte de message pour vous. Après l’avoir consulté, vous pourrez la trouver dans le bâtiment juste derrière moi.", t = "Élève des arcanes"},
    [92482] = {ot = "Lisez la note gribouillée, puis parlez à Tai’ree Doublevue dans le bosquet de Thendal.", st = "Pendant que vous vous occupiez de notre problème de vuldrènes, notre maîtresse des chasseurs locale, Tai’ree Doublevue, a laissé ce message pour vous. Vous pouvez la trouver juste là-bas, près du centre du village. Lisez ce mot avant de lui parler.", t = "La voie de la chasse"},
    [92483] = {ot = "Lisez la note simple, puis parlez à Akeri Lamebrune dans la tour de guet, dans le bosquet de Thendal.", st = "Pendant que vous vous occupiez de notre problème de vuldrènes, notre maître des voleurs local, Akeri Lamebrune, a demandé à vous parler. Il a laissé ce message, que vous devriez lire avant de le retrouver dans la tour de guet du village.\n\nIl est un peu louche, mais vous aussi, au bout du compte. Vous devriez vous entendre.", t = "Un foyer dans les ombres"},
    [92484] = {ot = "Examinez le cristal de rappel bourdonnant, puis parlez au sculpte-vent Boro dans le bosquet de Thendal.", st = "Pendant que vous vous occupiez de notre problème de vuldrènes, notre maître des chamans local, le sculpte-vent Boro, a laissé ce cristal de rappel pour vous. Vous devriez l’examiner avant de le retrouver juste là-bas, près du centre du village.", t = "S’ouvrir aux éléments"},
    [92485] = {ot = "Lisez le parchemin plié, puis parlez à Xyton Vent-argent dans le bosquet de Thendal.", st = "Pendant que vous vous occupiez de notre problème de vuldrènes, notre maître des druides local, Xyton Vent-argent, a laissé ce message pour vous. Lisez-le au plus vite, puis vous le trouverez au rez-de-chaussée du grand arbre juste derrière moi.\n\nÉcoutez bien ce qu’il a à vous dire, il a beaucoup à vous apprendre.", t = "Élève de la nature"},
    [92489] = {ot = "Tuez l’élémentaire de mana pour le grand sorcier Andromath à Hurlevent.", st = "Le Kirin Tor est un allié de longue date de l’Alliance. Avec la destruction de sa ville aux mains de l’archidémon Archimonde, la cité des mages, jadis majestueuse, est désormais recluse et méfiante envers les étrangers.\n\nCes dernières années, ils ont entamé des efforts de reconstruction pour ramener Dalaran à sa gloire d’antan. Toutefois, des rapports indiquent qu’ils ont du mal à contenir une vague d’énergie arcanique incontrôlable.\n\nNous devons les aider à dissiper ces attaques, sous peine de perdre l’un de nos plus puissants alliés.", t = "Puissance accablante"},
    [92514] = {t = "Bienvenue à Shen’dar !"},
    [92515] = {t = "Le problème avec les fièregriffes"},
    [92516] = {t = "Harceleurs hippogriffes"},
    [92517] = {t = "L’élément du crime"},
    [92528] = {t = "Parmi les fidèles"},
    [92529] = {ot = "Présentez-vous au missionnaire Jasaan près de l’entrée de Falaath.\n\nSi vous perdez votre marque d’Akir, retournez voir Sania Flot-d’Argent à Shen’dar pour la récupérer.", st = "Mon cœur se réjouit d’apprendre que vous souhaitez servir Al’Akir. Les épreuves que notre peuple traverse actuellement sont nées de notre propre fatuité. Nous sommes devenus trop fiers, au point de tenir pour acquis les bienfaits des vents. La période de stagnation qui a suivi a poussé les esprits du vent à nous délaisser.\n\nCe n’est qu’en faisant preuve de contrition que nous pourrons à nouveau sentir la caresse salutaire de la brise. Si vous cherchez une communauté de Shen’dorei partageant ces idéaux, rendez-vous à Falaath et adressez-vous au missionnaire Jasaan. Laissez-moi vous apposer notre marque, afin que les fidèles sachent que vous êtes une recrue.", t = "Falaath"},
    [92532] = {ot = "Lisez la note chiffonnée qu’on vous a donnée, puis cherchez la maître-lame Ren dans la tour de guet de Thendal.", st = "Pendant votre absence, notre maîtresse des guerriers, la maître-lame Ren, a demandé à ce que vous alliez lui parler à votre retour. Elle vous a également laissé ce message.\n\nLisez-le, puis rendez-vous à la tour de guet du village et parlez à la maître-lame Ren.", t = "La voie du guerrier"},
    [92544] = {t = "Voyous al’aketh"},
    [92550] = {t = "Malheur dans les hautes-terres"},
    [92551] = {t = "Fournitures volées"},
    [92553] = {t = "Remplir les garde-manger"},
    [92579] = {t = "Vers Valanaar"},
    [92595] = {t = "Les Sculpte-vents"},
    [92596] = {ot = "Asseyez-vous et discutez avec Rathiril Lance-Solaire.", st = "L’aura d’énergie arcanique qui vous enveloppe est puissante, pour quelqu’un qui n’a pas suivi le cursus des mages. Vous ferez très certainement $gun excellent aventurier:une excellente aventurière;. Et même si vous ne canalisez jamais le moindre sort, votre lien avec la magie antique ne pourra vous être que bénéfique.\n\nVenez, asseyons-nous et parlons un peu de mon ordre, de la nature des arcanes sur Zéphras et de la situation désespérée de notre peuple.", t = "L’Ordre suprême"},
    [92597] = {ot = "Utilisez votre compétence raciale Lecture de ligne tellurique à la ligne tellurique dans le bosquet de Thendal.", st = "Ici, dans le plan élémentaire, nous puisons une grande partie de notre force arcanique dans les lignes telluriques qui s’étendent encore dans le sol sous nos pieds. Il y a peu, ces lignes telluriques ont commencé à transpercer la surface, nous offrant ainsi un accès plus direct et plus puissant à cette énergie arcanique latente.\n\nRendez-vous aux pierres dressées au nord-est. Il y a une ligne tellurique là-bas. Utilisez votre héritage pour puiser dans son énergie.", t = "Lecture des lignes telluriques"},
    [92598] = {ot = "Utilisez votre compétence raciale Vue céleste à la convergence élémentaire dans le bosquet de Thendal.", st = "En tant que sculpte-vent, vous êtes capable d’utiliser la vue céleste sacrée qui nous a été offerte par les esprits élémentaires. Rendez-vous aux pierres dressées, au nord-est du village. Trouvez la convergence élémentaire et utilisez votre don.\n\nVous constaterez que vous pouvez utiliser la vue céleste partout, mais son pouvoir est bien plus puissant si vous le faites en présence d’une convergence élémentaire. Parfois, les esprits attirés par de tels lieux de pouvoir vous offriront également leur sagesse.", t = "Le don de vue céleste"},
    [92640] = {ot = "Parlez à Valennia Poing-Tempête à Valanaar et suivez ses instructions.", st = "Nous ne pouvons pas affronter la secte en plein air, alors nous devons utiliser cette occasion pour attaquer le sanctuaire directement. Nous pouvons nous débarrasser de Lorthuna avant qu’elle ne puisse accomplir son rôle dans ce plan.\n\nCela tombe bien, Valennia prépare depuis quelque temps une tactique pour un potentiel assaut contre le sanctuaire. Le seul problème, c’est que nous aurons besoin d’aide.\n\nParlez-lui pour plus de détails.", t = "Une situation désespérée"},
    [92642] = {t = "Perturbation logistique"},
    [92643] = {ot = "Trouvez le transfuge de la secte à la maison dans les hautes-terres, au nord-ouest de Valanaar.", st = "Il y a un transfuge parmi les Al’Aketh. Il prétend connaître les véritables intentions de la secte concernant l’île et il souhaite nous rejoindre, mais seulement si nous promettons de le protéger.\n\nCe renégat se cache dans une demeure isolée au nord-ouest de Valanaar, dans les hautes-terres. J’ai besoin de quelqu’un capable de s’y rendre discrètement, trouver ce traître et l’escorter jusqu’à nous. C’est peut-être un piège, mais si cette information est aussi importante que le prétend ce personnage, cela vaut le coup.", t = "Le transfuge"},
    [92644] = {ot = "Apportez le cristal luminescent à Talaanis Chantelombre, à Valaanar.", st = "<Vous fouillez sous le cadavre encore chaud du transfuge de la secte et attrapez un petit cristal bleu et luminescent. Il a l’air abîmé, mais il est sans doute important. Peut-être que ça intéressera le grand ancien Chantelombre.>", t = "Des nouvelles regrettables"},
    [92645] = {t = "Briser la Briseuse"},
    [92646] = {ot = "Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna.", st = "Lorthuna s’est enfuie vers les flèches en utilisant une sorte de portail. Ayessa et Elaadrin l’ont suivie. C’était il y a quelques instants à peine.\n\nJe crains d’avoir essuyé trop de coups et je vais devoir rester ici. Traversez le portail, retrouvez Ayessa et aidez-les à arrêter Lorthuna.\n\nSauf si les renforts qu’Elaadrin et Ayessa ont dit avoir appelés arrivent bientôt, vous devrez vous débrouiller par vous-mêmes. Bonne chance, $c.", t = "La confrontation avec Lorthuna"},
    [92679] = {t = "La dîme du sang"},
    [92682] = {t = "Rendez-vous utile"},
    [92683] = {t = "Poussière de voltemouche"},
    [92684] = {t = "Trotteurs gloutons"},
    [92685] = {t = "Les collines ont des yeux"},
    [92693] = {ot = "Parlez à Aamelia Champ-des-Vents quand serez $gprêt:prête; à affronter le chef des bandits.", st = "Vous avez travaillé dur pour nous donner une chance de survie. Même si nous mourrons aujourd’hui, nous saurons au moins que nous avons fait de notre mieux.\n\nC’est votre dernière chance, $gétranger:étrangère;. Si vous voulez retourner à Valanaar et rester en vie, je ne vous en voudrai pas.\n\nEn revanche, si vous avez un faible pour les causes perdues, dites-moi quand vous serez $gprêt:prête; à partir. Nous marcherons la tête haute et advienne que pourra.", t = "Tenir bon sans mollir"},
    [92698] = {t = "Quelle est ma tâche ?"},
    [92699] = {ot = "Allez voir Elaadrin Trombecalme à Valanaar.", st = "Maintenant que vous êtes à Valanaar, vous devriez parler aux autres membres de l’Ordre suprême. L’actuel magistère suprême, Elaadrin Trombecalme, et ses fidèles se sont installés dans le pavillon situé dans la partie la plus au sud-est de Valanaar.\n\nMais je vous enjoins à la prudence, car l’Ordre suprême et les Sculpte-vents ne sont pas en très bons termes, ici. À votre place, je garderais mes distances avec ces derniers. De bonnes, longues distances. Nous avons bien assez de chats à fouetter avec la secte, je n’accepterai pas de violences interfactions dans les rues de Valanaar.", t = "Le magistère suprême"},
    [92700] = {ot = "Allez voir Ayessa Chantelaube à Valanaar.", st = "Maintenant que vous êtes à Valanaar, vous devriez parler aux autres membres des Sculpte-vents. L’actuelle grande oracle des cieux et ses fidèles se sont installés dans le pavillon près du centre de Valanaar.\n\nMais je vous enjoins à la prudence, car les Sculpte-vents et l’Ordre suprême ne sont pas en très bons termes, ici. À votre place, je garderais mes distances avec ce dernier. De bonnes, longues distances. Nous avons bien assez de chats à fouetter avec la secte, je n’accepterai pas de violences interfactions dans les rues de Valanaar.", t = "La grande oracle des cieux"},
    [92701] = {t = "Vers Valanaar"},
    [92703] = {t = "Apporter la nouvelle"},
    [92706] = {t = "ON RECHERCHE : Bruuz"},
    [92708] = {ot = "Écoutez ce qu’Ayessa Chantelaube a à dire.", st = "Les Sculpte-vents sont à pied d’œuvre pour essayer de régler la crise actuelle sur l’île de Zéphras. Nous avons fait plusieurs découvertes surprenantes en cherchant les esprits du vent disparus et nous sommes en train d’élaborer un plan d’action qui pourrait nous permettre d’obtenir les moyens de sauver l’île.\n\nCependant, pour que cela fonctionne, nous aurons besoin de jeunes $gaventuriers courageux:aventurières courageuses; comme vous. Si vous avez un instant, venez discuter.", t = "Une grande aventure"},
    [92709] = {ot = "Écoutez ce qu’Elaadrin Trombecalme a à dire.", st = "Votre héritage bien-né brille dans vos yeux aussi clairement que le ciel au-dessus de nos têtes. Vous êtes $gl’un:l’une; des nôtres, et ce sont des jeunes comme vous qui nous aideront à sauver notre foyer. Mais avant tout, laissez-moi vous en dire plus sur notre mission et nos projets sur Zéphras… et au-delà.", t = "Une grande aventure"},
    [92727] = {ot = "Découvrez ce qui est arrivé à Fillion Flammebrise.", st = "La recherche de la connaissance est l’objectif premier de l’Ordre suprême, mais notre mission est devenue plus dangereuse que jamais sur Zéphras.\n\nL’un de nos érudits, Fillion Flammebrise, se rendait dans les hautes-terres de Shen’dar afin de rassembler des données sur la magie née du vent, qui tend à s’agglomérer dans certaines zones de la région. Hélas, il n’est pas rentré et nous craignons qu’il ne lui soit arrivé quelque chose en chemin.\n\nSi vous le pouvez, retrouvez-le pour nous, je vous prie. Nous avons perdu sa trace sur la route ouest de Valanaar, celle qui mène aux hautes-terres de Shen’dar.", t = "L’érudit disparu"},
    [92741] = {t = "Visiteuses indésirables"},
    [92742] = {ot = "Utilisez le kit d’échantillonnage d’eau de puits pour collecter des échantillons dans les puits de la ferme des Jansen et de la ferme des Molsen.", st = "Nous devons déterminer la source et la nature du poison qui corrompt ces terres. Commençons par les eaux sous les fermes de la zone.\n\nRendez-vous à la ferme des Jansen, au nord, puis à celle des Molsen, au nord-ouest d’ici, et prélevez des échantillons dans leurs puits.", t = "Tester les puits"},
    [92744] = {t = "Des branchies de Murloc"},
    [92745] = {t = "Quelles sales mines !"},
    [92747] = {t = "Espionnage de Ruisselune"},
    [92748] = {ot = "Rendez-vous au quartier des Nains à Hurlevent et cherchez un ingénieur pour vous aider.", st = "Les fournitures que vous avez trouvées indiquent l’existence d’une vaste installation industrielle, quelque part dans les Mortemines. C’est sans aucun doute la source des toxines qui ravagent les terres agricoles de la marche de l’Ouest. Nous devons y mettre un terme, et vite.\n\nQuoi que ce soit qui se trouve là-dedans sera difficile à détruire. Rendez-vous dans le quartier des Nains de Hurlevent et trouvez un spécialiste en ingénierie qui puisse nous fournir des explosifs.", t = "Consultation explosive"},
    [92749] = {t = "Un plan explosif"},
    [92750] = {t = "Détonation à distance"},
    [92751] = {t = "Détonation à distance"},
    [92752] = {t = "Consultation explosive"},
    [92753] = {ot = "Trouvez la forge cachée dans les Mortemines et placez les explosifs de destruction ultime à proximité. Rejoignez ensuite Alba Lunepâle à la sortie des Mortemines.", st = "La source du poison est probablement une grande forge métallurgique. Trouvez un moyen de pénétrer dans les Mortemines, localisez la forge, puis placez les explosifs.\nJe vous attendrai dans les collines derrière Ruisselune. À votre retour, nous pourrons faire exploser les charges. Avec un peu de chance, la destruction de la forge permettra à ces terres de commencer à guérir.", t = "Destruction dans les Mortemines"},
    [92819] = {ot = "Utilisez le détonateur.", st = "Nous y sommes presque. Utilisez le détonateur et mettez un terme à tout cela.", t = "Destruction dans les Mortemines"},
    [92834] = {t = "Rendre au centuple"},
    [92840] = {t = "Au gré du vent"},
    [92849] = {ot = "Continuez à chercher Fillion Flammebrise.", st = "<À en juger ce que vous venez de trouver, il est fort probable que Fillion se soit retrouvé dans une situation malencontreuse. Il se trouve peut-être encore dans les parages et a besoin d’aide. Vous remarquez une grotte au nord de votre position. Vous devriez poursuivre vos recherches là-bas.>", t = "L’érudit disparu"},
    [92850] = {t = "L’érudit disparu"},
    [92860] = {ot = "Allez voir Valennia Poing-Tempête et faites-lui savoir que l’Ordre suprême soutiendra son camp dans sa lutte contre les Al’Aketh.", st = "L’Ordre suprême a fait de son mieux pour éviter un conflit direct avec la secte, mais ce n’est de toute évidence plus une option. Son hostilité n’est plus à prouver et la rumeur parle de mouvements de plus grande ampleur un peu partout sur l’île. Elle prépare manifestement quelque chose, et cela ne peut pas être bon pour le peuple de Zéphras.\n\nAllez voir Valennia Poing-Tempête et assurez-lui que l’Ordre suprême apportera tout son soutien aux efforts de Valanaar contre les Al’Aketh, si le besoin s’en faisait sentir.", t = "Au service de Zéphras"},
    [92871] = {ot = "Allez voir Valennia Poing-Tempête et faites-lui savoir que les Sculpte-vents soutiendront son camp dans sa lutte contre les Al’Aketh.", st = "Valennia Poing-Tempête et ses garde-protègent depuis toujours Zéphras et nous avons fait notre possible pour les aider du mieux que nous le pouvons. La rumeur parle de mouvements d’une secte de plus grande ampleur, un peu partout sur l’île. Ils préparent manifestement quelque chose.\n\nAllez voir Valennia et répétez-lui que les Sculpte-vents apporteront tout leur soutien aux efforts de Valanaar contre les Al’Aketh, si le besoin s’en faisait sentir.", t = "Au service de Zéphras"},
    [92880] = {ot = "Apportez le rapport de Yorana à Valennia Poing-Tempête à Valanaar.", st = "Je pense qu’il nous faudra un peu de temps pour éliminer le reste des assaillants, mais nos chances sont bien meilleures désormais. Retournez à Valanaar et faites-leur savoir que la situation est sous contrôle ici.\n\nJe ne saurais trop vous remercier de votre aide. La situation serait bien pire sans vous. J’ai demandé des renforts, mais il me semble que j’ai reçu $gun héros:une héroïne; en devenir à la place.\n\nQue les quatre vents vous bénissent, $c.", t = "Retour à Valanaar"},
    [92881] = {ot = "Parlez à Talaanis Chantelombre à Valanaar.", st = "Les attaques contre les tours de guet orientale et occidentale ne sont pas une coïncidence. D’après ce que vous nous avez dit sur les évènements à la tour de l’ouest avec le prêtre céleste, il est probable que la secte essaie de s’en prendre aux pylônes d’ancrage.\n\nAllez parler au grand ancien Chantelombre. Il vous fera part d’une piste qui pourrait s’avérer prometteuse.", t = "La requête du grand ancien"},
    [92909] = {t = "La moisson des moissonneurs"},
    [92910] = {ot = "Apportez l’assemblage autocognitif de précision à Ozwin Pignondefer, à la ferme des Saldean.", st = "Les pièces que vous avez réussi à récupérer sur les moissonneurs semblent quasiment intactes. Elles intéresseront peut-être une personne passionnée par les golems des moissons.", t = "La moisson des moissonneurs"},
    [92911] = {t = "La récolte des moissonneurs"},
    [92947] = {t = "Passage à l’action"},
    [93036] = {t = "L’infiltration de la secte"},
    [93065] = {ot = "Parlez à Valennia Poing-Tempête dans les plaines Aérelles.", st = "Les garde-paix se mobilisent et nous nous préparons toutes et tous à partir. Faites vos préparatifs et rejoignez-nous sur la route orientale qui quitte la ville vers le nord. Nous ferons un dernier point avec tout le monde avant de partir.", t = "Préparation à la bataille"},
    [93089] = {t = "La suite des évènements"},
    [93090] = {t = "La suite des évènements"},
    [93159] = {t = "L’étrange ermite"},
    [93160] = {t = "Les richesses de la forêt"},
    [93165] = {t = "La miséricorde tombe dans l’oreille d’un sourd"},
    [93172] = {t = "Libérez les creux"},
    [93317] = {t = "La saison des crabes"},
    [93318] = {t = "AVIS DE RECHERCHE : Vulgara l’Insatiable"},
    [93319] = {t = "Les pierres de vent chapardées"},
    [93320] = {t = "Défense des tours"},
    [93461] = {t = "Bienvenue à Shen’dar !"},
    [93552] = {t = "Collecte de pierres de vent"},
    [93680] = {t = "Clé de la ville"},
    [93735] = {ot = "Trouvez Riaani Ventenuit dans la partie ouest de Valanaar.", st = "Historiquement, ce sont les Sculpte-vents qui s’occupaient des instruments et des appareils magiques qui nous ont été confiés par les esprits du vent, notamment de la multitude d’assemblages magiques que l’on trouve tout autour de l’île. Depuis que les esprits nous ont quittés, seuls quelques-uns de ces dispositifs fonctionnent toujours.\n\nL’un des rares assemblages encore fonctionnels de Valanaar a été endommagé. L’un de nos artisans a été dépêché sur place afin d’apporter son aide, mais il pourrait avoir besoin d’un coup de main. Rendez-vous dans la partie ouest de la ville et proposez-lui toute l’assistance possible.", t = "L’assemblage brisé"},
    [93736] = {t = "Esprits indésirables"},
    [93737] = {t = "L’assemblage brisé"},
    [93738] = {t = "L’assemblage brisé"},
    [93740] = {t = "Sang pour sang"},
    [93746] = {ot = "Confrontez Belathaan Voeu-Radieux sur la route qui mène au sanctuaire d’Akir.", st = "L’Ordre suprême a été prévenu des conséquences d’une ingérence dans les affaires des Sculpte-vents. Je crois que nous allons devoir faire un exemple de Belathaan et le renvoyer à l’Ordre avec quelques ecchymoses et un respect renouvelé pour les limites que nous avons définies.\n\nOn l’a vu quitter la ville pour prendre la direction du nord, vers le sanctuaire d’Akir. Je ne sais pas pourquoi il s’y rendait, mais l’option la plus sûre consiste à l’arrêter pendant qu’il est seul sur la route. Trouvez-le et semez la crainte dans son cœur.", t = "Une réponse ferme"},
    [93791] = {t = "Parler à Belann"},
    [93797] = {ot = "Apportez un rameau imprégné de vent à Belann Vif-Bois, à Valanaar.", st = "Une vieille tradition veut que les jeunes mages créent leur propre focalisateur de sort, une fois qu’ils ont atteint un certain degré de maîtrise de la magie. Pour cela, les initiés ramassent généralement une branche tombée d’un de nos arbres les plus anciens, car ces derniers portent encore des traces de vent élémentaire.\n\nJ’ai pu remarquer que les meilleurs se situent généralement près du sanctuaire du vent, au sud de Falaath. Allez-y et rapportez-moi un rameau de belle taille. Nous parlerons de nos traditions tout en fabriquant votre focalisateur de sort.", t = "La brise dans les branches"},
    [93835] = {ot = "Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna.", st = "Lorthuna s’est enfuie vers les flèches en utilisant une sorte de portail. Ayessa et Elaadrin l’ont suivie. C’était il y a quelques instants à peine.\n\nJe crains d’avoir essuyé trop de coups et je vais devoir rester ici. Traversez le portail, retrouvez Elaadrin et aidez-les à arrêter Lorthuna.\n\nSauf si les renforts qu’Elaadrin et Ayessa ont dit avoir appelés arrivent bientôt, vous devrez vous débrouiller par vous-mêmes. Bonne chance, $c.", t = "La confrontation avec Lorthuna"},
    [93836] = {ot = "Parlez à Talaanis Chantelombre à Valanaar.", st = "Muln m’a raconté beaucoup de choses sur les seigneurs élémentaires et je crains que nous ayons de bonnes raisons de redouter Al’Akir. Maintenant que les protections qui dissimulaient Zéphras aux yeux de ce dernier ont disparu, nous sommes totalement sans défense. S’il décide de nous attaquer, nous n’avons aucune chance de lui résister ici, dans son propre domaine.\n\nLe grand ancien Chantelombre doit être informé du danger qui nous menace et, surtout, de nos intentions concernant notre mission sur Azeroth. Nous trouverons le moyen de sauver notre foyer. J’en fais le serment.", t = "Le destin de Zéphras"},
    [93926] = {t = "Le guet occidental"},
    [93927] = {ot = "Récupérez la note trouvée à proximité de la dépouille du garde-paix et lisez-la pour décider d’un plan d’action.", st = "<En inspectant la dépouille du garde-paix, vous remarquez une note ensanglantée tombée de sa main. Vous devriez la ramasser et la lire, elle contient peut-être un indice qui vous sera utile.>", t = "Une dernière demande"},
    [93948] = {t = "Livraison de chevalière"},
    [93949] = {t = "Les insectes ont des oreilles"},
    [93951] = {t = "Sa plus belle plume"},
    [93958] = {ot = "Parlez à Valennia Poing-Tempête dans le sanctum intérieur du sanctuaire d’Akir.", st = "Les troupes de Valennia viennent d’accéder au sanctum intérieur. La bataille était intense au début, mais à présent… c’est étrangement calme. Allez-y et faites de votre mieux pour rejoindre Valennia et ses troupes… s’il en reste.\n\nJe reste ici pour vous couvrir.", t = "Le sanctum intérieur"},
    [94003] = {ot = "Reprenez le Rempart des Briseciel à Zaal Pare-tempête au sanctuaire d’Akir.", st = "Je suis tout ce qu’il reste de la lignée des Briseciel ici sur l’île de Zéphras. Les autres ont été assassinés par les Al’Aketh.\n\nSeul mon chagrin prend le pas sur ma honte. Le bouclier ancestral de ma famille, le Rempart de Briseciel, se trouve désormais aux mains d’un sectateur nommé Zaal Pare-tempête. La tradition familiale veut que le digne porteur de ce bouclier ne souffre jamais aucun mal.\n\nZaal n’en est pas digne, de ça je suis certain. Trouvez cet homme au sanctuaire d’Akir et reprenez-lui mon bouclier. Ensuite, je vous enseignerai l’art de la défense des Briseciel.", t = "Le Rempart de Briseciel"},
    [94006] = {ot = "Parlez avec Urs’endris près de la cascade au nord-est de Valanaar.", st = "Salutations, $n. Vous avez suffisamment progressé dans vos études druidiques pour que je considère qu’il est temps pour vous de rencontrer l’un des grands esprits qui résident ici sur Zéphras. Urs’endris est un esprit noble et sage qui apprend aux druides à adopter la forme de l’ursera depuis des générations. Son domaine a malheureusement commencé à se flétrir et chute dans les cieux comme tant d’autres régions de Zéphras.\n\nSi vous souhaitez le trouver, rendez-vous au nord-est près de la cascade située dans l’ombre du sanctuaire d’Akir. Il devrait se charger de poursuivre votre instruction.", t = "Le grand esprit ursera"},
    [94013] = {ot = "Utilisez le bâtonnet de domptage pour dompter une alpha vuldrène des plaines Aérelles. Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar.", st = "Vous voilà de retour $gcouvert:couverte; de gloire après avoir apprivoisé deux bêtes. Il est temps maintenant d’affronter votre dernière épreuve. Les vents de Zéphras murmurent que de plus grands défis vous attendent.\n\nPrenez ce bâtonnet de domptage et rendez-vous dans les plaines Aérelles. Là-bas, apprivoisez une alpha vuldrène et prouvez votre maîtrise.\n\nUne fois cette leçon terminée, vous serez $gprêt:prête; à découvrir les aspects les plus profonds de la chasse.", t = "Dompter la bête"},
    [94050] = {ot = "Parlez à Quel’dora Vent-Vif à Valanaar.", st = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez aussi acquérir celles qui sont nécessaires à son apprivoisement. Personne n’est mieux placé pour cela que ma sœur Quel’dora. Elle vous apprendra à dresser votre nouveau compagnon animal.\n\nQue les vents vous portent, jeune $c.", t = "Entraîner la bête"},
    [94369] = {ot = "Parlez à Talaanis Chantelombre à Valanaar.", st = "Ansirem m’a raconté beaucoup de choses sur les seigneurs élémentaires et je crains que nous ayons de bonnes raisons de redouter Al’Akir maintenant que les protections qui dissimulaient Zéphras ont disparu. Si le seigneur des Vents décide de nous attaquer, nous n’avons aucune chance de lui résister ici, dans son domaine.\n\nLe grand ancien Chantelombre doit être informé du danger qui nous menace et, surtout, de nos intentions concernant notre mission sur Azeroth. Nous trouverons le moyen de sauver notre foyer. J’en fais le serment.", t = "Le destin de Zéphras"},
    [94373] = {t = "L’appel de la terre"},
    [94374] = {ot = "Trouvez la pierre d’esprit et buvez le sapta de terre.", st = "Oui, le sapta est un breuvage forgé par la magie, qui lie notre esprit aux éléments. Seule une poignée de chamans en connaît la recette, et croyez-moi, il n’est pas pour les âmes sensibles. Buvez-le et vous verrez ce que les autres ne peuvent pas voir. Mais attention… ça ne se boit que dans un lieu sacré.\n\nFilez au nord, jusqu’au rocher des esprits. Il se trouve au bout d’un sentier caché, en haut de la montagne. Buvez le sapta là-bas… et voyez ce que la terre a à vous montrer.", t = "L’appel de la terre"},
    [94375] = {ot = "Apportez le quartz brut à Teo Martel-tempête, à Courbenclume.", st = "Prenez ce quartz brut et apportez-le à Teo Martel-tempête. Il attestera de notre rencontre. Il créera un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu’il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre à bien d’autres.\n\nSoyez $gpatient:patiente;, $n. Restez $gfort:forte;. Et recherchez la sagesse. C’est ce que la terre attend de vous. À la fin, vous ne ferez plus qu’un avec elle. Respectez-la comme elle vous respecte.", t = "L’appel de la terre"},
    [94411] = {t = "Des mages perturbateurs"},
    [94413] = {t = "Un affront magique"},
    [94414] = {ot = "Parlez à Halaan Œil-de-Faucon et empruntez son don pour observer le pylône d’ancrage au loin.", st = "Salutations, jeune $n. Je viens souvent ici pour admirer l’antique pylône d’ancrage. Ces derniers sont des cadeaux des esprits du vent qui maintiennent et alimentent notre île. Toutefois, leur magie est récemment devenue instable et fluctuante.\n\nJe ne détecte aucun signe de détresse en eux. Leur splendeur n’a pas changé.\n\nSi vous le voulez, je peux vous prêter mon don afin que vous puissiez regarder vous-même.", t = "Les ancres de Zéphras"},
    [94427] = {ot = "Parlez à Tanis Aulnebois, à Fossoyeuse.", st = "L’un des principes clés d’un paladin est sa quête de divinité. Je ne parle pas d’un désir de devenir un dieu, mais bien d’une quête pour servir le bien, dans son ensemble. Nous avons tous atterri ici à cause d’une tragédie que nous avons subie, quelle que soit sa forme, et il serait aisé de perdre cette grâce qui faisait de nous des paladins, dans notre ancienne vie.\n\nRendez-vous à Fossoyeuse et cherchez Tanis Aulnebois, dans le quartier des Marchands. Notre intervention pourrait lui être d’un grand secours.", t = "Une leçon de divinité"},
    [94434] = {t = "Une leçon de divinité"},
    [94435] = {ot = "Retournez voir Danitha Morr, à la forteresse de Bandarion.", st = "J’ignore pourquoi vous vous donnez tant de mal pour moi, mais je vous en remercie. Et si quelqu’un vous a demandé de passer me voir, je l’en remercie aussi. Vous pourrez toujours compter sur Tanis Aulnebois, $c.", t = "Une leçon de divinité"},
    [94436] = {ot = "Parlez au nécrogarde Billmuth, à la forteresse de Bandarion .\n\nSi vous égarez votre Symbole de vie, retournez voir Danitha Morr pour en obtenir un autre.", st = "Il est temps pour vous de nous montrer votre maîtrise de l’un des plus grands dons de la Lumière.\n\nL’objet que je viens de vous donner est un Symbole de vie. Mais allez-y doucement, car manipuler un talisman de la Lumière comme celui-ci peut être désagréable. Mais si les forces qui nous ont créés abhorrent la Lumière, elle n’en reste pas moins notre guide et notre alliée. La douleur nous le rappelle.\n\nAllez voir le nécrogarde Billmuth, en bas. Il vient d’arriver et a requis notre assistance. Montrez, à lui comme aux Réprouvés, ce que les vrais paladins savent faire.", t = "Une leçon de divinité"},
    [94438] = {ot = "Prenez le Symbole de vie et utilisez-le pour ressusciter le nécrogarde Falgan dans la vallée de Tissevenin.\n\nSi vous égarez votre Symbole de vie, retournez voir Danitha Morr pour en obtenir un autre.", st = "Falgan et moi étions en mission de reconnaissance, pour recenser les activités de la Croisade écarlate dans la vallée de Tissevenin. On a pu s’approcher suffisamment de l’un de leurs camps pour les entendre mentionner de nouveaux ordres, exigeant une attaque contre Brill. Mais avant qu’on ait pu décider quoi faire, j’ai marché sur une brindille et alerté nos ennemis.\n\nFalgan m’a crié de fuir, alors j’ai fui. Quand j’ai réalisé qu’il n’était plus derrière moi, j’ai déjà à mi-chemin de Brill. Ce courageux imbécile a dû rester en arrière pour les retenir.\n\nJe vous en prie, trouvez mon ami et aidez-le, si vous le pouvez.", t = "Une leçon de divinité"},
    [94440] = {ot = "Dérobez les plans d’attaque de la Croisade écarlate aux croisés écarlates de la vallée de Tissevenin, puis retrouvez le nécrogarde Billmuth à la forteresse de Bandarion.", st = "La Croisade écarlate transporte souvent des sacoches contenant leurs ordres de déploiement. Nous savons qu’une attaque arrive, mais en mettant la main sur leurs ordres, nous pourrons avertir le reste de la Nécrogarde et préparer une embuscade.\n\nVous êtes $gun paladin impressionnant:une paladine impressionnante;. Tuez ces vermines écarlates, récupérez une copie de leurs ordres et apportez-la au nécrogarde Billmuth. Il s’occupera du reste.", t = "Une leçon de divinité"},
    [94441] = {ot = "Parlez à Danitha Morr au donjon de la forteresse de Bandarion.", st = "Remerciez Danitha Morr de ma part, et dites-lui que le reste de la Nécrogarde entendra parler de ce que les paladins de la forteresse de Bandarion ont fait pour nous.\n\nVotre avenir est prometteur, $gpaladin:paladine;. C’est un honneur de compter des personnes comme vous dans les rangs des Réprouvés. Que la Dame noire vous protège, $n.", t = "Une leçon de divinité"},
    [94449] = {ot = "Trouvez Bruegs Flammené en Dun Morogh.", st = "Vot’ dernière épreuve r’monte à longtemps, $n. Z’avez fait preuve de patience, pour sûr, mais il est désormais temps pour vous d’en apprendre un peu plus sur l’chaos… et la destruction. L’appel du feu est fort et si vous êtes $gprêt:prête; à en payer l’prix, il vous parl’ra. \n\nCherchez Bruegs Flammené, loin à l’est, dans les montagnes. Il habite dans une caverne au-d’ssus de l’avant-poste de la Porte sud. Il saura si vous êtes vraiment $gprêt:prête;.", t = "L’appel du feu"},
    [94465] = {ot = "Apportez la torche de la flamme dormante à Braldir Houppecendre au Loch Modan.", st = "Ouais, z’avez la force de porter l’totem du feu, $ggamin:gamine;, mais c’est pas avec la force seule que vous s’rez $gprêt:prête;.\n\nAu-d’là d’la vallée des Rois, dans les combes du Loch Modan, vous trouv’rez un sentier caché vers l’un d’nos pics sacrés. Braldir Houppecendre y garde l’Autel d’la flamme dormante. \n\nApportez-lui cet’ torche. Elle montrera votre résolution. Rapportez-la allumée au brasero de l’Autel et je f’rai en sorte que vous obteniez le totem comme il se doit.", t = "L’appel du feu"},
    [94466] = {t = "L’appel du feu"},
    [94467] = {ot = "Éliminez la manifestation de feu mineure, et placez sa braise rougeoyante dans le brasero, en haut de l’Autel de la flamme éternelle.", st = "Le sapta d’feu est prêt, $n. Maintenant, vous d’vez faire façe à la flamme. Utilisez-la sur l’autel, puis escaladez la montagne jusqu’au sommet. Vous y trouv’rez l’esprit. Il vous frappera pas avant que vous n’lui portiez l’premier coup, mais il saura qu’vous l’voyez.$B$BFrappez vite, $ggamin:gamine;. Plus vous attendrez, plus il brûlera fort. Quand il tomb’ra, prenez ses braises rougeoyantes et placez-les dans l’brasero. Allumez la torche et vous aurez mérité la faveur de la flamme.", t = "L’appel du feu"},
    [94468] = {ot = "Apportez la torche de la flamme éternelle à Bruegs Flammené en Dun Morogh.", st = "La torche fermement en main, vous vous détournez du brasero et embrassez le Loch Modan du regard. Vous sentez la fièvre battre dans votre esprit tandis que le vent avive les flammes qui dansent furieusement.$B$BVous prenez le chemin du retour en Dun Morogh pour trouver Bruegs Flammené.", t = "L’appel du feu"},
    [94484] = {t = "Un silence angoissant"},
    [94485] = {t = "Les larmes de la Dame"},
    [94486] = {t = "Des plumes pour le bandage"},
    [94487] = {t = "Indignes même dans la mort"},
    [94488] = {ot = "Tuez le commandant Haalien et apportez sa tête à Elegael Piquepatte dans la forêt de Trombenoire.", st = "Je ne comprends toujours pas ce que les sectateurs manigançaient ici, mais je perçois une odeur familière par-dessus celle du massacre.\n\nL’un des druides de notre cercle, Haalien, a disparu il y a plusieurs mois. Apparemment, il a décidé de rallier les sectateurs.\n\nMontrez-lui ce qui arrive à ceux qui versent le sang de leur propre clan. Rapportez-moi donc sa tête.", t = "Ces liens qui nous entravent"},
    [94489] = {t = "La douleur de la trahison"},
    [94490] = {ot = "Apportez la missive déchirée à Elegael Piquepatte dans la forêt de Trombenoire.", st = "<Coincée sous l’un des brassards de Haalien se trouve une note légèrement déchirée et tachée de sang pendant votre combat. Elle semble contenir des informations utiles sur les intentions des sectateurs envers la tanière des druides. Cela devrait intéresser Elegael.>", t = "Missive déchirée"},
    [94491] = {ot = "Apportez la missive à Lotheluum, à Valanaar, et informez-le de la situation.", st = "Il semble que la secte dispose d’un informateur, quelque part à Valanaar. Je ne suis pas en état de faire le voyage, mais Lotheluum doit apprendre ce qui est arrivé ici.\n\nNous devons aussi lui faire part du sort de ceux qui nous ont quittés. Grâce à votre intervention, nous devrions pouvoir reprendre les choses en main ici… même si le mal est fait.\n\nJe vous en prie, dépêchez-vous, $n. J’espère avoir la chance de vous recroiser un jour. En attendant… j’ai des sectateurs à tuer.", t = "Le sort des druides"},
    [94494] = {ot = "Trouvez Norric Lochthane au Loch Modan.", st = "Cela fait longtemps qu’vous n’avez pas été $gmis:mise; à l’épreuve, $n. Vous avez fait preuve de patience jusque-là dans vos études, mais l’temps est à présent venu pour vous d’apprendre la pureté de l’eau.\n\nCherchez Norric Lochthane au Loch Modan. Vous l’trouverez sur la berge nord-ouest du lac, au sud du barrage de Formepierre, dans une hutte enfouie. Bonne chance à vous, $n.", t = "L’appel de l’eau"},
    [94495] = {t = "L’appel de l’eau"},
    [94497] = {t = "L’appel de l’eau"},
    [94499] = {ot = "Remplissez l’outre rouge vide aux chutes de Guet-de-Pierre près des Murlocs marcheurs de l’ombre et retournez voir Hervdana Saegrund dans les Paluns.", st = "Ouais, les Carmines s’abreuvent abondamment du lac Placide, mais des créatures s’y infiltrent avant que les eaux ne tombent des chutes de Guet-de-Pierre. Les Murlocs en contrebas sont de grosses brutes corrompues. Pas du tout comme ceux que vous trouvez ici ou au Loch. Heureusement pour les villageois, ils restent au pied des cascades.\n\nRapportez-moi un échantillon. Je compte bien découvrir si c’est la magie, le venin ou quelque chose de pire qui souille les eaux près de ce vieux fort.", t = "L’appel de l’eau"},
    [94500] = {ot = "Remplissez l’outre bleue vide dans les eaux d’Astranaar en Orneval et rapportez-la à Hervdana Saegrund dans les Paluns.", st = "Prenez cette outre et aventurez-vous profondément sous les frondaisons émeraude d’Orneval. Astranaar est nichée près des eaux vierges de toute corruption. Le lit du lac est jonché d’ruines, comme autant d’vestiges d’une époque révolue. Rapportez-moi un échantillon d’eau du lac. Pure, ancienne et potentiellement enchantée.\n\nC’est l’dernier liquide dont j’ai besoin avant d’vous renvoyer vers Norric.\n\nEmbarquez à bord du bateau qui va de Menethil à Auberdine, après une escale à Austrivage.\n\nEt souvenez-vous… La forêt à des yeux, qui ne cillent jamais.", t = "L’appel de l’eau"},
    [94568] = {ot = "Parlez à Talaanis Chantelombre et assistez à la conversation.", st = "Le transfuge était de toute évidence terrifié par les plans de la secte. Assez pour fuir et demander notre aide. C’est vraiment regrettable qu’il soit mort et ait emporté ses secrets dans la tombe.\n\nNous devons en discuter en détail pour déterminer les prochaines étapes.", t = "Le véritable objectif de la secte"},
    [94638] = {ot = "Trouvez Ur’endra dans les hautes-terres de Shen’dar et tuez-la.", st = "Vous venez à moi dans l’espoir d’apprendre à emprunter une forme de force. J’ai une tâche pour vous, bien qu’elle me pèse énormément.\n\nMa compagne Ur’endra a succombé à la folie et a commencé à attaquer ses semblables. Sans la magie des vents, de nombreuses créatures ont commencé à perdre pied… c’est ce qui arrive à Ur’endra. Elle s’est réfugiée dans une grotte, à l’ouest d’ici, sous les falaises qui longent la frontière entre les hautes-terres de Shen’dar et les plaines Aérelles.\n\nMettez un terme à ses souffrances et je vous octroierai ma bénédiction.", t = "Force et clémence"},
    [94774] = {ot = "Parlez à la grande prêtresse Laurena à Hurlevent.", st = "Vous avez attiré l’attention de nos supérieurs, $n. Ils ont demandé à ce que vous vous rendiez à la cathédrale de la Lumière de Hurlevent dès que possible. Apparemment, ils estiment que vous avez fait vos preuves et souhaitent poursuivre votre entraînement. Lorsque vous serez là-bas, trouvez la grande prêtresse Laurena. Elle saura vous guider. Bonne chance, et que la Lumière soit avec vous.", t = "Grâce divine"},
    [94792] = {t = "Dompter la bête"},
    [94793] = {ot = "Parlez à Isaac Chan à Comté-de-l’Or.", st = "Vous avez maintenant les compétences pour dompter un familier, mais vous devez aussi acquérir celles qui sont nécessaires à son apprivoisement. Personne n’est mieux placé pour cela qu’Isaac Chan, un bûcheron de longue date. Il vous apprendra à dresser votre nouveau compagnon animal.\n\nQue les vents vous portent, jeune $c.", t = "Entraîner la bête"},
    [94818] = {t = "Plan d’urgence"},
    [94824] = {ot = "Parlez à la grande prêtresse Mims à Forgefer.", st = "Il est temps pour vous de retourner à Forgefer, $n. La grande prêtresse Mims vous ordonne de venir lui parler au Hall des mystères. Il doit s’agir de quelque chose de vraiment positif ou de véritablement négatif pour que la grande prêtresse veuille vous voir personnellement. Mais j’imagine que vous n’avez fait que le bien autour de vous et qu’elle vous en récompensera.$B$BNe perdez pas de temps, partez au plus tôt.", t = "Éclair déconcertant"},
    [94863] = {ot = "Utilisez le bâtonnet de domptage pour dompter un loup forestier gris. Entraînez-vous à ses côtés, puis rapportez le bâtonnet de domptage à Joséphine Carson.", st = "Vous savez déjà apprivoiser un sanglier. Passons maintenant à la leçon suivante. La forêt abrite des compagnons bien plus féroces. À force de prudence, vous pourrez gagner leur confiance.\n\nPrenez ce bâtonnet de domptage et partez à la recherche d’un loup forestier gris. N’oubliez pas que l’équilibre de la nature doit être respecté. Prouvez une fois de plus vos talents en matière de chasse.", t = "Dompter la bête"},
    [94864] = {ot = "Utilisez le bâtonnet de domptage pour dompter un jeune ours des forêts. Entraînez-vous à ses côtés, puis rapportez le bâtonnet de domptage à Joséphine Carson.", st = "Vous avez fait vos preuves en apprivoisant un sanglier et un loup. À présent, votre dernier défi vous attend. L’équilibre d’Elwynn repose à la fois sur le respect et le savoir-faire. Prenez ce bâtonnet de domptage et partez à la recherche d’un jeune ours des forêts. Démontrez que vous méritez la confiance du plus redoutable des compagnons.\n\nSi vous achevez cette leçon, votre affinité avec les bêtes sera renforcée.", t = "Dompter la bête"},
    [94896] = {t = "Un coup de main pour les réfugiés"},
    [94897] = {ot = "Trouvez Resaan dans les ruines de Ban’aethal.", st = "Si vous vous rendez à Ban’aethal, j’ai… une requête très égoïste. Mon amour, Resaan… je crains qu’il ne soit plus de ce monde. Il a voulu retourner au village dans l’espoir de récupérer des fournitures, quand bien même je l’ai supplié de rester. C’était il y a plus d’une semaine et je crains le pire.\n\nJe vous en prie, si vous le trouvez, ramenez-le auprès de moi. Et s’il a péri… s’il vous plaît, rapportez-moi ses affaires.", t = "Le sort de l’être aimé"},
    [94911] = {ot = "Parlez à Turak Totem-Runique aux Pitons du Tonnerre.", st = "Salutations, jeune $r. Je vois que vous montrez de grandes dispositions pour les arts druidiques. Je vous invite à parler au dénommé Turak Totem-Runique aux Pitons-du-Tonnerre. Il vous enseignera le secret pour vous rendre au bastion du Cercle cénarien sur Kalimdor, Reflet-de-Lune.\n\nLes druides du Cercle vous accueilleront chaleureusement et vous transmettront leur savoir.\n\nMaintenant, comme votre peuple le dirait, allez avec la bénédiction du vent, mon enfant. Je vous souhaite bonne chance dans vos aventures.", t = "Enfant de la nature"},
    [94912] = {t = "Enfant de la nature"},
    [94913] = {t = "Reflet-de-Lune"},
    [94946] = {t = "La cité magique de Dalaran"},
    [94947] = {t = "Bienvenue sur Azeroth"},
    [94978] = {ot = "Utilisez le bâtonnet de domptage pour dompter un clampant chantevent près d’un point d’eau.\nEntraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar.", st = "Pour débuter, tout chasseur doit apprendre à comprendre le lien qui unit la bête et son maître. C’est là votre premier défi. Avec le temps, vous apprivoiserez des créatures venues des quatre coins du monde, mais pour aujourd’hui, commencez par nos rivières et nos lacs sur Zéphras.\n\nPrenez ce bâtonnet de domptage et partez à la recherche d’un clampant chantevent.\n\nMontrez-lui que vous êtes capable de gagner sa confiance, et engagez-vous sur la voie vers la véritable maîtrise des bêtes.", t = "Dompter la bête"},
    [94979] = {ot = "Utilisez le bâtonnet de domptage pour dompter un trotteur des trombes hargneux des plaines Aérelles.\nEntraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar.", st = "Vous avez fait vos preuves en apprivoisant le clampant des rivières. À présent, il est temps de mettre vos talents à l’épreuve en terrain ouvert. Les plaines de Zéphras sont le théâtre des cris du trotteur des trombes, un fier chasseur ailé qui court aussi vite que le vent.\n\nPrenez ce bâtonnet de domptage et partez à sa recherche. Rendez-vous dans les plaines et gagnez sa confiance.\n\nMontrez que vous êtes $gprêt:prête; pour les épreuves à venir.", t = "Dompter la bête"},
    [95034] = {t = "La dette"},
    [95065] = {t = "L’heure de la pêche"},
    [95161] = {t = "N’oublie pas que je t’aime"},
    [95189] = {ot = "Rendez l’écu de Lordaeron à dame Dena Kennedy, à Hurlevent.", st = "<Un écu patiné frappé de l’emblème de Lordaeron. Vu le peu de reliques qui subsistent depuis la chute du royaume, quelqu’un à Hurlevent serait fort désireux de mettre la main dessus.>", t = "Écu de Lordaeron"},
    [95195] = {t = "Insigne ensanglanté"},
    [95204] = {ot = "Rapportez l’écu de Lordaeron à Oran Serpenroule, à Fossoyeuse.", st = "<Un écu patiné frappé de l’emblème de Lordaeron. Vu le peu de reliques qui subsistent depuis la chute du royaume, quelqu’un à Fossoyeuse serait fort désireux de mettre la main dessus.>", t = "Écu de Lordaeron"},
    [95212] = {t = "Il ne faut jamais s’asseoir sur la qualité"},
    [95213] = {t = "Poudre explosive volée"},
    [95214] = {t = "Poudre explosive volée"},
    [95216] = {t = "La peste nouvelle"},
    [95217] = {t = "Le forgeron de la carrière"},
    [95250] = {t = "Abominables créatures"},
    [95314] = {t = "Cet élixir vert d’Ombreval"},
    [95328] = {ot = "Rapportez le résidu d’horreur murmurante au père Lankester dans le Quartier de la Guerre de Fossoyeuse.", st = "Contrairement à vos habitudes, vous ramassez et récupérez les restes frétillants de la bête. Quelqu’un pourrait en avoir besoin à Fossoyeuse.", t = "Résidu d’horreur murmurante"},
    [95349] = {ot = "Embarquez à bord d’un perceciel au départ de l’île de Zéphras pour vous rendre en Mulgore, puis parlez à Alaana Marchetempête à votre arrivée.", st = "J’ai dû reporter mon voyage vers Azeroth à cause des derniers évènements liés à la secte. Je dois rester ici, à Valanaar, encore un moment. Vous, ainsi qu’une poignée d’autres Sculpte-vents, allez nous servir d’avant-garde. Alaana Marchetempête attendra les nôtres en Mulgore pour les accueillir à leur arrivée. Je vous conseille d’explorer Azeroth pendant que nous réglons tout ça. Nous vous contacterons bientôt.\n\nQuand vous serez $gprêt:prête;, rendez-vous sur le quai devant ce bâtiment et montez à bord du perceciel qui s’y trouve.\n\nBanu-Alah, $n.", t = "Le Cercle terrestre"},
    [95350] = {t = "Bienvenue sur Azeroth"},
    [95494] = {t = "Fierté meurtrie et peaux de lion"},
    [95495] = {ot = "Apportez le tas de peaux à l’ermite vivant sur la crête qui surplombe les collines Arides dans les Tarides.", st = "Ces peaux sont pour un tanneur avec lequel je commerce souvent. C’est une sorte d’ermite qui vit seul en haut de la crête derrière moi. Je ne peux vraiment gravir une colline pentue à l’heure actuelle, alors je vous serais redevable si vous pouviez livrer ces peaux pour moi.\n\nOh, et concernant… l’apparence de ce tanneur. Ne vous inquiétez pas. Malgré son aspect, il n’est pas une menace. Je vous jure que c’est vrai.", t = "L’ermite tanneur"},
    [95507] = {t = "Le gibier de Vrang"},
    [95508] = {t = "Des invités indésirables"},
    [95621] = {ot = "Rendez-vous jusqu’à l’épave de la caravane et apprenez-en davantage sur les raisons de la venue des Kultirassiens.", st = "Ce matin, j’ai repéré un groupe d’Humains à la recherche de quelque chose dans la vallée en contrebas. J’ai réussi à utiliser la lunette de mon fusil pour y regarder de plus près et il m’est apparu clairement qu’il s’agissait de soldats portant les couleurs de Kul Tiras. \n\nSi vous souhaitez que je vous confie du travail, rendez-vous à l’endroit où ces soldats ont établir leur camp, près de l’épave de la caravane, au sud. Tuez tous les soldats que vous y trouverez et essayez de découvrir les raisons de leur venue.", t = "Des problèmes dans la vallée"},
    [95646] = {ot = "Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns.", st = "Ces terres saumâtres recèlent une réserve plus vaste d’eaux douces venues du sud. J’en éprouve de la peine, et pourtant, jusque dans mes racines, je perçois une corruption qui suinte à travers ce ravin de la montagne.\n\nLes créatures, comme celles de nos basses-terres, sont bien plus atteintes par cette souillure. Privées depuis l’aube de la vie du sel endurcissant de la mer, elles n’ont guère de force pour affronter un tel mal.\n\nRendez-vous dans les hautes-terres et rapportez-moi le cœur-racine de l’horreur des hautes-terres.", t = "Horreurs dans les hautes-terres"},
    [95647] = {t = "Perdu dans les fourrés"},
    [95663] = {ot = "Rendez-vous dans les Paluns et retrouvez l’agente nécrotraqueuse dans les collines qui dominent le campement gueule-de-dragon.", st = "Les Gueules-de-Dragon forment un clan redoutable.\n\nOn les sait capables d’une magie d’asservissement assez puissante pour plier les Dragons à leur volonté, et la rumeur veut qu’ils préparent une démonstration de ce pouvoir dans les Paluns. Que cette rumeur soit la vérité ou pure fanfaronnade, les nécrotraqueurs ne peuvent s’y fier. Les symboles incomplets ne m’ont pas fourni davantage d’informations.\n\nUne agente nécrotraqueuse a besoin d’un coup de main dans les collines qui dominent le campement gueule-de-dragon. Rejoignez-la là-bas. Elle vous exposera la suite.", t = "Rumeurs sur les Gueules-de-Dragon"},
    [95664] = {ot = "Apportez la relique des Titans à la cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un qui saura vous en apprendre davantage à son sujet.", st = "Cet étrange éclat composite diffracte la lumière tel un prisme vivant. Sa nature demeure incertaine, mais son pouvoir semble ancien. S’il existe encore des érudits capables de percer les secrets d’un artéfact d’une époque aussi lointaine, vous les trouverez sans doute à la cime des Anciens, aux Pitons-du-Tonnerre.", t = "Le savoir des anciens"},
    [95682] = {t = "Gueule-de-bois"},
    [95697] = {t = "Goûts changeants"},
    [95772] = {t = "À la recherche de Lame-chantante"},
    [95774] = {t = "Son nom est Olgra"},
    [95795] = {ot = "Retournez voir Dorin Lame-chantante", st = "<Vous recouvrez le corps du Nain de son manteau.>\n\nRendez-vous à Comté-du-Lac et informez Dorin Lame-chantante en personne de ce qu’il est advenu de son frère dans les excavations.", t = "Chute dans les marais"},
    [95803] = {ot = "Apportez la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse.", st = "Maintenant que nous avons la tête du commandant terni, j’aimerais que vous l’apportiez à Fossoyeuse. Sylvanas Coursevent se méfie de nous comme de la peste, si je puis me permettre l’expression, et c’est tout juste si elle ne nous dénigre pas ouvertement.\n\nApportez la tête de Rudolph Gelhardt à la Dame noire. Montrez-lui que nous faisons notre propre ménage et que nous sommes engagés à assurer la prospérité des Réprouvés.", t = "Un gage de bonne volonté"},
    [95805] = {t = "Grâce d’An’she et Mu’sha"},
    [95809] = {t = "Cœur tressé"},
    [95810] = {t = "La relique égarée"},
    [95883] = {ot = "Récupérez une âme torturée sur les morts-vivants des environs, au Péril de Beren, dans la forêt des Pins-Argentés.", st = "<Les préparatifs d’un rituel organisé à la va-vite ont été entassés sur l’autel sans égard. D’après la note, il ne manque rien, à l’exception d’une offrande de sang et d’une âme torturée.\n\nLes morts-vivants autour de vous ont l’air relativement torturés. Ils auront peut-être ce qu’il vous faut.>", t = "L’âme torturée"},
    [95884] = {ot = "Trouvez la pierre à offrandes au Péril de Beren, dans la forêt des Pins-Argentés.", st = "<Le message est pratiquement illisible. Vous ne déchiffrez que quelques bribes, des notes de préparation pour une offrande.\n\nLa note mentionne une pierre à offrandes, ainsi qu’un rituel.\n\nVous la trouverez peut-être dans les environs.>", t = "La pierre à offrandes"},
    [95885] = {ot = "Utilisez l’âme torturée pour faire une offrande de sang sur la pierre à offrandes au Péril de Beren.", st = "<Il ne reste plus que l’offrande de sang.\n\nLe bout de note mentionne un sacrifice volontaire.\n\nVous êtes $gsaisi:saisie; d’un effroi intense.>", t = "L’offrande de sang"},
    [95981] = {t = "Routes sous surveillance"},
    [95998] = {t = "Les grands espaces sauvages"},
    [95999] = {t = "AVIS DE RECHERCHE : incinérateur Gar’im"},
    [96031] = {t = "Introduction au camping : le travail du cuir"},
    [96044] = {t = "Introduction au camping : la forge"},
    [96045] = {t = "Introduction au camping : l’alchimie"},
    [96046] = {t = "Introduction au camping : le minage"},
    [96047] = {t = "Introduction au camping : les premiers soins"},
    [96050] = {t = "Introduction au camping : la pêche"},
    [96055] = {t = "Introduction au camping : l’herboristerie"},
    [96056] = {t = "Introduction au camping : le dépeçage"},
    [96057] = {t = "Introduction au camping : la couture"},
    [96058] = {t = "Introduction au camping : l’ingénierie"},
    [96059] = {t = "Introduction au camping : l’enchantement"},
    [96101] = {t = "Les grands espaces sauvages"},
    [96102] = {t = "Introduction au camping : la couture"},
    [96130] = {t = "Chakuyak"},
    [96137] = {t = "Dague d’Ira"},
    [96139] = {t = "La famille Valor"},
    [96204] = {ot = "Accompagnez Lumina Chantelevent et aidez-la à s’échapper du donjon de Fenris.", st = "Maintenant que je suis libre, je vais faire en sorte que ces viles créatures regrettent de s’en être prises à une Sculpte-vent.\n\nSortons d’ici, $c.", t = "La colère de la Sculpte-vent"},
    [96390] = {t = "Étouffer le mal dans l’œuf"},
    [96391] = {ot = "Remettez la carte sombrefer au terre-voyant Farsen, à Dun Morogh.", st = "La carte que vous tenez semble représenter un réseau complexe de galeries et de tunnels, qui paraissent tous converger vers un point situé sous Forgefer même.\n\nImpossible de dire ce qu’indiquent les runes, car elles sont tracées dans l’écriture runique, laide et anguleuse, des Nains sombrefer, mais la finalité de ces tunnels se devine aisément. Tandis que vous étudiez la carte, une bourrasque vous enveloppe et vous croyez y percevoir, ténue, la voix d’un Nain. Le terre-voyant Farsen doit voir ceci.", t = "La carte souterraine"},
    [96392] = {ot = "Parlez au terre-voyant Farsen et demandez-lui de vous prêter sa double vue pour observer la menace des Sombrefer.", st = "Bien le bonjour, l’$gami:amie;. Je me nomme Farsen, le Terre-voyant, et je suis venu du Nid-de-l’Aigle visiter Dun Morogh. En chemin, je n’ai pas pu m’empêcher de remarquer que nous avons, eh bien… un petit souci avec les Nains sombrefer.\n\nSi vous avez un moment, je peux vous montrer ce que je veux dire. J’ai un brin de magie qui devrait faire l’affaire.", t = "Le guet de Farsen"},
    [96393] = {t = "Incursion dans le Vieux Forgefer"},
    [96394] = {t = "Les morts sans repos"},
    [96395] = {ot = "Apaisez l’esprit de Faldrim Courbenclume, puis retournez voir la domestique fantomatique dans la salle des Thanes.", st = "Le… thane… mon puissant… thane… il… a besoin de… repos.\n\nJe vous en prie… aidez-le… aidez-le à… trouver le repos…\n\nRongé… par… une ancienne… rancune… Pas de… repos…", t = "Une rancune ancestrale"},
    [96403] = {t = "Précieux héritages"},
    [96408] = {ot = "Inspectez le campement qui domine la carrière de Gol’Bolar.", st = "La nuit dernière, l’un de nos montagnards a repéré un feu de camp à flanc de colline, à l’est. Il semble se trouver assez haut et dominer la carrière de Gol’Bolar.\n\nCe n’est sans doute rien, mais j’aimerais que vous alliez jeter un œil à ce campement. S’il s’agit d’alliés, aucun problème. Et dans le cas contraire… eh bien, vous savez ce qu’il vous reste à faire.", t = "Une visite à Dun Morogh"},
    [96604] = {t = "Les grands espaces sauvages"},
    [96605] = {t = "Les grands espaces sauvages"},
    [96606] = {t = "Les grands espaces sauvages"},
    [96607] = {t = "Les grands espaces sauvages"},
    [96608] = {t = "Les grands espaces sauvages"},
    [96626] = {t = "Introduction au camping : la cuisine"},
    [96627] = {ot = "Parlez à Sam Salsepareille près de Comté-de-l’Or.", st = "$n, vous avez prouvé jusqu’à présent que vous étiez capable de protéger les autres, et c’est pour cela que je vous confie aujourd’hui une mission inhabituelle.\n\nJ’ai entendu parler d’un nouvel aventurier, non loin de Comté-de-l’Or. Allez voir ce qu’il fait.", t = "L’aventurier"},
    [96628] = {t = "L’aventurier"},
    [96629] = {t = "Introduction au camping : la cuisine"},
    [96630] = {ot = "Apportez le journal à Lyreena Lamebrune, près de Dolanaar.", st = "<Le journal semble des plus ordinaires. Il détaille la vie et les aventures de quelqu’un dont vous n’avez jamais entendu parler.\n\nDe nombreuses entrées mentionnent le camping. Cette activité a l’air pour le moins… amusante.>", t = "L’aventurière"},
    [96634] = {t = "Introduction au camping : la cuisine"},
    [96638] = {ot = "Parlez à Raan Aile-sauvage près de Shen’dar.", st = "De plus en plus d’adeptes de l’aventure, comme vous, quittent la sécurité du bosquet de Thendal en quête de gloire et de fortune. L’un de ces aventuriers a d’ailleurs monté son campement à l’extérieur de Shen’dar, le long de la route qui part du bosquet en direction du sud-ouest.\n\nAllez donc le voir, il pourra peut-être vous enseigner deux ou trois choses qui vous seront utiles au cours de vos pérégrinations.", t = "L’aventurier"},
    [96646] = {t = "Introduction au camping : la cuisine"},
    [96652] = {ot = "Apportez le journal à Brakk près de Tranchecolline.", st = "<Le journal semble des plus ordinaires. Il détaille la vie et les aventures de quelqu’un dont vous n’avez jamais entendu parler.\n\nDe nombreuses entrées mentionnent le camping. Cette activité a l’air pour le moins… amusante.>", t = "L’aventurier"},
    [96655] = {t = "Introduction au camping : la cuisine"},
    [96656] = {ot = "Parlez à Eleanor Shackleton, près de Brill.", st = "$n, vous avez prouvé votre loyauté lors de vos combats contre la Croisade écarlate., et c’est pour cela que je vous confie aujourd’hui une mission inhabituelle.\n\nJ’ai entendu parler d’une nouvelle aventurière, non loin de Brill. Allez voir ce qu’elle fait.", t = "L’aventurière"},
    [96658] = {t = "Introduction au camping : la cuisine"},
    [96659] = {t = "L’aventurière"},
    [96661] = {t = "Introduction au camping : la cuisine"},
    [96779] = {t = "Sabotage du Syndicat"},
    [96821] = {t = "Toutes pattes dehors"},
    [96822] = {ot = "Récupérez la hache d’armes d’écumeur, l’arc d’écumeur et le bouclier d’écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline.", st = "Lors du pillage du donjon de Tiragarde, nous avons perdu nombre de vaillantes âmes guerrières de la Horde. Puisque les Humains ont fortifié les ruines, nous ne pouvons pas récupérer les dépouilles de nos troupes pour leur rendre un hommage à la hauteur de leur sacrifice.\n\nRendez-vous dans les ruines autour du donjon et récupérez les armes des nôtres tombés au combat. Nous les exposerons dans un lieu symbolique.", t = "Pour l’honneur"},
    [96825] = {t = "Ces fruits pourraient se défendre"},
    [96873] = {t = "Une douleur dans la nuque"},
    [96874] = {t = "Spinal Hache"},
    [96875] = {t = "Les bêtes des falaises du Tonnerre"},
    [96876] = {t = "Le sac perdu d’Ukor"},
    [96877] = {ot = "Rapportez le sabot d’Halikor à Orgrimmar.", st = "Cet énorme sabot sert de preuve de votre victoire sur le puissant lézard.", t = "Le sabot d’Halikor"},
    [96895] = {ot = "Trouvez le membre de l’Aube d’argent près de l’entrée de Fossoyeuse.", st = "Je ne sais pas si vous êtes au courant, mais deux émissaires de l’Aube d’argent viennent de passer par ici. Je n’ai rien contre l’Aube d’argent, mais je n’apprécie pas non plus qu’ils viennent fouiner en Tirisfal sans surveillance. Ces émissaires étaient tous deux des Réprouvés, mais ça ne me rassure pas pour autant.\n\nL’un d’entre eux vient tout juste de passer et se rendait vers le sud-est. Un groupe de sectateurs du Fléau rôde aux abords de la ville dans cette direction. Si ces deux-là en ont entendu parler, cela a sans aucun doute attiré leur attention.", t = "L’émissaire de l’Aube d’argent"},
    [96896] = {t = "Une juste cause"},
    [96897] = {t = "Le Culte des damnés"},
    [96898] = {t = "Les vestiges de la guerre"},
    [96899] = {ot = "Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal.", st = "Vous avez rendu un fier service à la cause de l’Aube d’argent, aujourd’hui, et je vous en remercie. J’ignore si la forteresse de Bandarion vous est familière, mais mon commandant et moi-même nous y rendions pour rencontrer les paladins et paladines qui y résident… du moins, jusqu’à ce qu’on nous signale la présence du Culte des damnés.\n\nSi vous souhaitez en apprendre davantage sur l’Aube d’argent et notre mission, allez trouver mon commandant à la forteresse de Bandarion, au nord-ouest d’ici. Je vais rester et finir de nettoyer ce gâchis.", t = "La forteresse de Bandarion"},
    [96984] = {t = "Cœur de la perturbation"},
    [96986] = {ot = "Triomphez d’Atrexis le Chevalier de la tombe dans la cité de Dalaran pour Melisara à Moulin-de-Tarren.", st = "Un traitre aux nôtres se terre dans les entrailles de la cité des mages au nord. Un nécromancien d’un talent perturbant. Il lève une armée de morts-vivants juste sous le nez du Kirin Tor.\n\nJe ne me soucie pas du destin de la cité des mages, $n, mais ce Chevalier de la tombe est un affront à tout ce pour quoi les Réprouvés se battent. Mettez un terme à son existence. Montrez-lui que personne ne se situe hors de portée de la Dame noire.", t = "Le Chevalier de la tombe"},
    [96987] = {t = "Éducation opportuniste"},
    [96988] = {t = "Source de pouvoir"},
    [97003] = {t = "Chol’aruk le Vorace"},
    [97220] = {t = "La faveur de Philmor"},
    [97222] = {t = "Livraison au corps de garde"},
    [97223] = {ot = "Apportez les œufs de la matriarche griffesang à Xar’Ti, au village de Sen’jin.", st = "Tous les raptors que vous voyez là sont ceux que j’ai dressés moi-même. Ils viennent des quatre coins de Kalimdor, mais la crème de la crème provient de la lignée des raptors griffesang, sur les îles au large de nos côtes.\n\nL’un des raptors de ce groupe, la matriarche griffesang, est particulièrement féroce et a tué de nombreux habitants de notre village. Elle est devenue bien trop dangereuse pour rester à nos frontières. Si vous parvenez à la terrasser, revenez avec ses œufs afin que nous puissions élever sa progéniture en alliés plutôt qu’ennemis.", t = "La matriarche griffesang"},
    [97225] = {t = "Idoles de Loa oubliées"},
    [97234] = {t = "Salle de lecture"},
    [97236] = {ot = "Apportez le crochet de Githyiss à quelqu’un d’Aldrassil qui s’intéresse tout particulièrement à l’étude des araignées.", st = "Un spécimen en si bon état d’une bête de cette taille représente une sacrée trouvaille. Son crochet intéressera sans doute quelqu’un d’Aldrassil qui se passionne pour l’étude des araignées.", t = "Crochet de Githyiss"},
    [97237] = {t = "Récupérés à la main"},
    [97242] = {ot = "Prélevez des spécimens d’herbe polisson et de roseau qui poussent près des eaux de la vallée de l’Honneur et retournez voir Kor’geld à la boutique Alchimie et potions de Yelmak.", st = "Yelmak ne veut pas que son apprenti casse du verre. Enfin, pas plus que ce qu’il a déjà cassé.\n\nIl m’a dit que son jeune élève est trop fier pour demander de l’aide, même quand il en a vraiment besoin, et il veut lui faire goûter une formule locale en particulier.\n\nCollectez un mélange de roseaux et d’herbes polisson parmi la végétation qui pousse près de l’eau dans la vallée de l’Honneur. J’irais bien les chercher moi-même, mais si je quitte la boutique, Whuut s’apercevra sans doute que nous essayons de gérer ses humeurs.", t = "Le mélange de Yelmak"},
    [97243] = {t = "L’appel du feu"},
    [97244] = {ot = "Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur.", st = "Il existe un prêtre céleste al’aketh du nom de Faladiel. Autrefois, il répondait à l’appel des flammes et comptait parmi les plus fidèles Sculpte-vents. Comme tant d’autres Al’Aketh, il a troqué sa loyauté contre le pouvoir, et ses mains sont désormais tachées du sang de ses anciens frères et sœurs.\n\nVous trouverez le prêtre céleste Faladiel à la ferme située au nord-est de Valanaar, juste au sud du sanctuaire d’Akir. Tuez ce traître et rapportez-moi son cœur. C’est une tâche macabre, mais elle est nécessaire au rituel que nous nous apprêtons à accomplir.", t = "L’appel du feu"},
    [97245] = {t = "L’appel du feu"},
    [97246] = {t = "En souffrance de pitance"},
    [97249] = {ot = "Apportez son repas à Migi derrière le fort Grommash.", st = "Maintenant que je sais que les parents de Migi s’inquiètent de savoir s’il se remplit bien l’estomac, ça me donne une idée.\n\nIls m’ont fait promettre de ne pas lui donner la même chose tous les jours, pour qu’il apprenne à aimer des plats différents. Mais quand le fumoir est plein et qu’on fait des sandwichs de panse de cochon laquée, il n’oublie jamais de passer le midi. On s’est mis à garder les chutes de croûte bien croustillante comme garniture, et ça on peut lui en saupoudrer tous les jours.\n\nApportez-lui ce paquet. Peut-être que ça le fera passer plus souvent et ramener ses petits camarades.", t = "Son plat préféré"},
    [97250] = {t = "Accusé à tort, corrigé à raison"},
    [97253] = {t = "Foire à la ferraille"},
    [97257] = {t = "L’appel du feu"},
    [97275] = {ot = "Apportez la potion de Yelmak à Whuut.", st = "Whuut est un petit prodige, c’est vrai. Mais il n’a pas encore l’expérience, la sagesse ou les heures burette en main pour savoir vraiment respecter les réactions alchimiques.\n\nIl est en train d’épuiser tous nos stocks des réactifs les plus rares ou exotiques sans prendre le temps d’affiner ses compétences de base.\n\nApportez-lui cette potion que j’ai préparée avec une simple distillation médicinale rapide. Quand il verra que la vraie maîtrise commence avec les remèdes locaux et un dosage soigneux, il remettra son approche en question.", t = "Droit au Whuut"},
    [97277] = {t = "Grund et Gozwin"},
    [97279] = {t = "Armes égarées"},
    [97281] = {t = "Une tempête en approche"},
    [97282] = {t = "Un potentiel houleux"},
    [97287] = {t = "Négociations avisées"},
    [97288] = {ot = "Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse.", st = "<Lorsque la créature s’effondre, sa tête se détache et roule au sol. Elle semble avoir été rattachée à plusieurs reprises, la jointure devenant plus fragile à chaque fois.\n\nQuelqu’un à Fossoyeuse doit en savoir davantage sur cette abomination singulière.>", t = "Tourment interminable"},
    [97289] = {t = "Tourment interminable"},
    [97290] = {ot = "Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse.", st = "Espèce… d’abomination…\n\nPourquoi devrais-je… vous aider…\n\nPartez…", t = "Tourment interminable"},
    [97291] = {t = "Tourment interminable"},
    [97292] = {ot = "Injectez le sérum sifflant dans le dispositif au-dessus du corps d’Othmar, pour le maître apothicaire Faranell.", st = "J’ai concocté un charmant sérum que notre nouvel invité trouvera à coup sûr fort… stimulant.\n\nPrenez ceci. Introduisez-le dans le mécanisme qui goutte au-dessus de lui. Voyons si nous ne parvenons à lui faire saisir tout l’intérêt qu’il a à nous servir loyalement.\n\nEt tâchez de ne pas le renverser. Je n’ai pas les moyens de me payer $gun nouvel assistant:une nouvelle assistante;.", t = "Tourment interminable"},
    [97326] = {t = "Ameublement rocheux"},
    [97485] = {ot = "Achetez un paquet d’herbes à Nida l’herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d’enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l’amadou de cérémonie à Naal le fournisseur de matériel de cuisine.\n\nCombinez ces composants, puis répandez l’encens depuis la cime des Chasseurs.", st = "Qu’An’she vous bénisse, $gl’ami:l’amie;.\n\nLe peuple tauren a pour tradition de confier de l’encens aux vents, et j’espère que vous accepterez de rendre hommage à cette coutume.\n\nPour préparer l’encens, vous devrez acheter des herbes à Nida, du bois de cèdre à Nata, des fibres tendineuses à Mahu, sur la Côte centrale, ainsi que du silex et de l’amadou de cérémonie à Naal, sur la Côte supérieure. Une fois ces composants réunis, combinez-les, puis répandez l’encens depuis la falaise orientée au sud de la cime des Chasseurs.\n\nVous trouverez un tapis et de l’encens sur le lieu de la cérémonie.", t = "Traditions des pitons"},
    [97538] = {t = "Pigments pour peintures"},
    [97558] = {t = "Des peaux pour les Réprouvés"},
