    [97977] = {t = "L’appel de la nature"},
    [97979] = {ot = "Lancez Lumière d’Elune et Camouflage dans l’ombre.", st = "Vous êtes d’origine kaldorei, les enfants des étoiles, et avez ainsi hérité d’un patrimoine sans commune mesure en ce monde. La grâce d’Élune peut révéler nos forces et guider nos coups avec justesse, ou nous envelopper de son voile, tout comme la lune peut éclipser le soleil.\n\nNotre longue veille après la défense du mont Hyjal a pris fin, et nous avons forgé une Alliance avec d’autres peuples… vous les rencontrerez bien assez tôt. Pour l’heure, vous demeurez à l’abri sous les frondaisons de Teldrassil.\n\nFaites honneur aux dons de mère Lune et baignez dans ses bénédictions.", t = "La déesse pourvoyeuse"},
    [98013] = {t = "Forces croissantes"},
    [98021] = {t = "En route pour la colline des Sentinelles"},
    [98024] = {t = "Un voyage à la Croisée"},
    [98025] = {t = "ON RECHERCHE : Jai’vhanel"},
    [98027] = {t = "Le collier de lune resplendissante"},
    [98042] = {ot = "Obtenez un œil sans pareil auprès d’un disciple ou d’un nervi du Crépuscule, au Glaive du Maître à Sombrivage, puis trouvez quelqu’un à Auberdine qui accepte de le prendre.", st = "<Alors que vous arrachez l’unique page du tome du Crépuscule, une voix menaçante envahit votre esprit, sans y avoir été conviée.>\n\nIls ont échoué.\n\nOn vous oubliera.\n\nIls perdront l’œil qu’ils ont acquis.", t = "Rira bien qui rira le dernier"},
    [98046] = {t = "La couronne de la Terre"},
    [98065] = {t = "La couronne de la Terre"},
    [98067] = {t = "Regard des Sentinelles"},
    [98069] = {t = "Les fournitures de Librevent volées"},
    [98070] = {t = "Interruption des hurlements"},
    [98093] = {t = "Un champ à nettoyer"},
    [98094] = {ot = "La grande exécutrice Darthalia vous charge de remettre des ordres mis à jour au nécrotraqueur Masoj, au sud de Moulin-de-Tarren, à l’extérieur de Dun Garok.", st = "Maintenant que nous savons que vous êtes digne de confiance pour transmettre des informations cruciales à nos éclaireurs de première ligne, j’ai une tâche supplémentaire pour vous.\n\nApportez ceci au nécrotraqueur Masoj, presque plein sud d’ici. Une fois que vous le lui aurez remis, il aura d’autres instructions à vous confier. Il est posté sur les hauteurs, au nord du vignoble en ruine qu’ils appellent la ferme des Nethander.\n\nNotre plan pour prendre le contrôle de ces terres progresse comme prévu.", t = "Soutien aux éclaireurs"},
    [98095] = {t = "Positions stratégiques"},
    [98189] = {t = "Rapporter la statuette"},
    [98190] = {t = "Proche de la famille"},
    [98191] = {ot = "Apportez la statuette de Menethil au seigneur Grayson Brisombre, à la cathédrale de la Lumière.", st = "Le roi Terenas était un homme bon. Un homme dévoué. Aimé de son peuple. C’est grâce à lui que cette Alliance a pu voir le jour.\n\nComble de l’ironie, il était incroyablement modeste… Il détestait ce genre d’hommage, et il en existe donc très peu. Ceux qui ont survécu à la chute de Lordaeron sont encore moins nombreux.\n\nLa Lumière semble s’être concentrée au sein de cette statuette. Elle sera parfaitement à sa place dans la cathédrale de la Lumière, au centre de la ville, sur la place de la Cathédrale. Apportez-la au seigneur Grayson Brisombre pour qu’il la mette en lieu sûr.", t = "Proche de la famille"},
    [98197] = {t = "Butin de guerre"},
    [98219] = {ot = "Allez parler au lieutenant Farren Orinelle à Austrivage, dans les contreforts de Hautebrande.", st = "Encore merci d’avoir amené la statuette à bon port, $n.\n\nJe crains de devoir à nouveau faire appel à vos services. Un membre de la garde de la ville a été réaffecté à Austrivage, dans les contreforts de Hautebrande.\n\nSon père était un ami proche. Si je dois bien reconnaître qu’il méritait une bonne leçon… je tiens malgré tout à le voir réussir. L’aide de quelqu’un comme vous lui serait vraiment bénéfique.\n\nSi vous repassez au port de Menethil, un bateau pourra vous conduire à destination.", t = "Le lieutenant déshonoré"},
    [98245] = {t = "Travail d’aiguille tranchegueule"},
    [98246] = {t = "Période de disette"},
    [98251] = {t = "Point de non-retour"},
    [98252] = {t = "La voie du Vide"},
    [98282] = {t = "Dangers alchimiques"},
    [98284] = {t = "Introduction au camping : l’enchantement"},
    [98285] = {t = "Introduction au camping : l’ingénierie"},
    [98286] = {t = "Introduction au camping : l’enchantement"},
    [98299] = {t = "Endiguer la propagation"},
    [98319] = {t = "Sécuriser la montagne"},
    [98321] = {t = "Cargaison de Flammesilex"},
    [98322] = {t = "Sécuriser la montagne"},
    [98323] = {t = "Sécuriser la montagne"},
    [98326] = {t = "Hurlegivre"},
    [98340] = {ot = "Parlez à Dendrite Brasétoile au village de Havrenuit, à Reflet-de-Lune.", st = "Vous me semblez $gprêt:prête; à entreprendre la prochaine étape de votre voyage, jeune $gdruide:druidesse;. Dendrite Brasétoile vous invite à lui rendre visite à Reflet-de-Lune une fois encore.\n\nVous avez déjà appris à manier la magie qui vous transportera à Reflet-de-Lune, vous pouvez donc vous y rendre immédiatement si vous le désirez. Je vous conseille de ne pas trop tarder si vous souhaitez poursuivre votre apprentissage druidique.", t = "L’esprit du Grand félin"},
    [98341] = {ot = "Partez à la recherche de l’avatar de Saeyleenan dans la partie sud de Reflet-de-Lune et découvrez ce qu’il peut vous apprendre sur la nature du félin du vent.", st = "Un esprit venu de votre terre natale a récemment fait son apparition ici et m’a demandé de vous conduire jusqu’à lui. Cet esprit félin du vent est venu vous instruire et vous guider afin que vous puissiez adopter sa forme sur Zéphras.\n\nTous les druides et druidesses finissent par suivre cet enseignement, même si l’esprit de votre terre natale a une apparence quelque peu différente de celle que nous connaissons traditionnellement. Si vous souhaitez revêtir la forme féline de cet esprit, vous devrez vous soumettre à notre épreuve.\n\nVous la trouverez dans la partie sud de Reflet-de-Lune, au sud des ponts jumeaux.", t = "L’esprit du Grand félin du vent"},
    [98342] = {ot = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’esprit du Grand félin.", st = "Pour pouvoir faire appel à mon esprit, vous ne pourrez vous contenter de quelques belles paroles. Afin de comprendre et de respecter ma forme, vous devrez montrer que vous savez faire preuve de ruse, de discrétion et, si vous êtes $gacculé:acculée;, de férocité.\n\nDans le refuge des saisons, juste à l’est d’ici, se trouvent trois reliques qui me sont chères et que vous devrez récupérer. De puissants esprits enragés les protègent et vous attaqueront à vue. Une statue située à l’entrée vous accordera temporairement le pouvoir de la discrétion afin de vous permettre de les contourner.\n\nRapportez-moi ces reliques. Nous verrons alors si vous êtes en mesure d’apprendre à adopter ma forme.", t = "L’esprit du Grand félin"},
    [98362] = {ot = "Retournez aux Pitons-du-Tonnerre et parlez à Turak Totem-runique, sur la cime des Anciens.", st = "Nos chemins doivent à nouveau se séparer, $gmon jeune ami:ma jeune amie;, car la pratique des connaissances acquises vous incite à retourner auprès de celui qui vous a $genvoyé:envoyée; à ma rencontre. Turak Totem-Runique, votre instructeur, a trouvé en vous $gun:une; disciple digne de ce nom. À mes yeux, ça ne fait aucun doute. Écoutez ses leçons avec attention et vous serez bientôt capable de faire appel à l’esprit du Grand félin pour adopter sa forme.\n\nRebroussez chemin. Le moment venu, nos routes se croiseront une fois de plus.", t = "Vers les Pitons-du-Tonnerre"},
    [98386] = {t = "La scierie d’Alther"},
    [98387] = {t = "Barricade rochenoire"},
    [98389] = {t = "Une lumière dans les ténèbres"},
    [98391] = {ot = "Parlez à Sœur Aquinne à Darnassus.", st = "Qu’Élune vous bénisse, $c. La Sororité d’Élune est l’un des piliers de la société kaldorei depuis des millénaires.\n\nD’avant la Grande Fracture à la guerre des Anciens, puis tout au long de la longue veille, nous avons guidé notre peuple et pansé ses blessures à travers les ténèbres. Telle est notre mission, telle est la volonté de notre incomparable mère Lune.\n\nAujourd’hui, nous avons besoin de votre aide pour une affaire de la plus haute importance. Sœur Aquinne attend votre arrivée à Darnassus.", t = "La Sororité d’Élune"},
    [98392] = {t = "Les ténèbres dans la clairière"},
    [98393] = {ot = "Parlez à Dendrite Brasétoile au village de Havrenuit, à Reflet-de-Lune.", st = "Vous me semblez $gprêt:prête; à entreprendre la prochaine étape de votre voyage, jeune $gdruide:druidesse;. Dendrite Brasétoile vous invite à lui rendre visite à Reflet-de-Lune une fois encore.\n\nVous avez déjà appris à manier la magie qui vous transportera à Reflet-de-Lune, vous pouvez donc vous y rendre immédiatement si vous le désirez. Je vous conseille de ne pas trop tarder si vous souhaitez poursuivre votre apprentissage druidique.", t = "L’esprit du Grand félin"},
    [98394] = {ot = "Partez à la recherche de l’esprit du Grand félin dans la partie sud de Reflet-de-Lune, et découvrez ce qu’il peut vous apprendre sur la nature du félin.", st = "Dans la partie sud de Reflet-de-Lune, sur une colline surplombant le pont, réside un être sage et rusé que nous appelons l’esprit du Grand félin.\n\nÀ l’instar de l’esprit du Grand ours, cet esprit fait office de tuteur et de mentor pour les druides et druidesses qui désirent adopter la forme de félin. Tôt ou tard, ils finissent tous et toutes par se mettre en quête de ses conseils et, si vous aspirez à adopter la forme d’un félin, vous en ferez de même.\n\nAllez à la rencontre de l’esprit du Grand félin pour apprendre ce qu’il jugera utile de vous enseigner.", t = "L’esprit du Grand félin"},
    [98396] = {ot = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’esprit du Grand félin.", st = "Pour pouvoir faire appel à mon esprit, vous ne pourrez vous contenter de quelques belles paroles. Afin de comprendre et de respecter ma forme, vous devrez montrer que vous savez faire preuve de ruse, de discrétion et, si vous êtes $gacculé:acculée;, de férocité.\n\nDans le refuge des saisons, juste à l’est d’ici, se trouvent trois reliques qui me sont chères et que vous devrez récupérer. De puissants esprits enragés les protègent et vous attaqueront à vue. Une statue située à l’entrée vous accordera temporairement le pouvoir de la discrétion afin de vous permettre de les contourner.\n\nRapportez-moi ces reliques. Nous verrons alors si vous êtes en mesure d’apprendre à adopter ma forme.", t = "L’esprit du Grand félin"},
    [98397] = {ot = "Retournez à Darnassus et parlez à Mathrengyl Pasdelours, dans l’enclave Cénarienne.", st = "Nos chemins doivent à nouveau se séparer, $gmon jeune ami:ma jeune amie;, car la pratique des connaissances acquises vous incite à retourner auprès de celui qui vous a $genvoyé:envoyée; à ma rencontre. Mathrengyl Pasdelours, votre instructeur, a trouvé en vous $gun:une; disciple digne de ce nom. À mes yeux, ça ne fait aucun doute. Écoutez ses leçons avec attention et vous serez bientôt capable de faire appel à l’esprit du Grand félin pour adopter sa forme.\n\nRebroussez chemin. Le moment venu, nos routes se croiseront une fois de plus.", t = "En route vers Darnassus"},
    [98398] = {ot = "Trouvez l’écorce de l’arbre de l’Oracle dans les environs afin de recevoir son message.", st = "Je suis impressionnée par ce que vous venez d’accomplir en un temps aussi court, $n. J’aimerais vous demander de rester ici et de m’épauler… Mais je sais dans mon cœur que de plus grandes quêtes vous attendent.$b$bJ’ai remarqué que l’arbre-oracle a laissé tomber un morceau de son écorce. Il ne fait pas de doute qu’il a une tâche qu’il aimerait vous voir accomplir. Vous devriez aller lui parler.", t = "L’arbre de l’Oracle"},
    [98403] = {t = "Haine folle"},
    [98404] = {ot = "Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’avatar de Saeyleenan.", st = "Pour pouvoir faire appel à mon esprit, vous devrez vous soumettre à une épreuve. Afin de comprendre et de respecter ma forme, vous devrez montrer que vous savez faire preuve de ruse, de discrétion et, si vous êtes $gacculé:acculée;, de férocité.\n\nDans le refuge des saisons, juste à l’est d’ici, se trouvent trois reliques que vous devrez récupérer. De puissants esprits enragés les protègent et vous attaqueront à vue. Une statue située à l’entrée vous accordera temporairement le pouvoir de la discrétion afin de vous permettre de les contourner.\n\nRapportez-moi ces reliques afin de réussir l’épreuve druidique de ces terres.", t = "L’esprit du Grand félin du vent"},
    [98405] = {ot = "Partez à la recherche de l’esprit du Grand félin dans la partie sud de Reflet-de-Lune, et découvrez ce qu’il peut vous apprendre sur la nature du félin.", st = "Dans la partie sud de Reflet-de-Lune, sur une colline surplombant le pont, réside un être sage et rusé que nous appelons l’esprit du Grand félin.\n\nÀ l’instar de l’esprit du Grand ours, cet esprit fait office de tuteur et de mentor pour les druides et druidesses qui désirent adopter la forme de félin. Tôt ou tard, ils finissent tous et toutes par se mettre en quête de ses conseils et, si vous aspirez à adopter la forme d’un félin, vous en ferez de même.\n\nAllez à la rencontre de l’esprit du Grand félin pour apprendre ce qu’il jugera utile de vous enseigner.", t = "L’esprit du Grand félin"},
    [98407] = {t = "Démonstration de force"},
    [98417] = {ot = "Maseara Lune-d’Automne vous demande de fouiller la région située à l’ouest du Chant des forêts, parmi les démons de Satyrnaar. À votre retour, faites-lui part de tout indice concernant son époux, Kurothel.", st = "Alors que nous traversions l’une de nos heures les plus vulnérables, le malheur s’est abattu sur nos villages. Les Satyres ont profané nos temples, souillé nos bosquets sacrés de leur présence impie et massacré les innocents sans la moindre pitié.\n\nKurothel a succombé à la colère. Les druides ont porté le combat jusqu’aux Satyres, et il les a suivis.\n\nLe lien qui nous unit demeure. Je sens la présence de mon époux, à l’ouest, dans ces bois. Je vous en prie, revenez m’apporter des nouvelles de son sort.", t = "La piste de la vengeance"},
    [98418] = {t = "Fureur partagée"},
    [98423] = {ot = "Remettez le traité de l’entente à Magni Barbe-de-Bronze, à Forgefer.", st = "<À l’intérieur de la chambre forte, vous découvrez une tablette détaillant les termes d’un traité de paix entre les clans nains Barbe-de-Bronze et Marteau-Hardi. Elle semble remonter à la période qui suivit de peu la guerre des Trois marteaux et représente très probablement une pièce marquante de l’histoire des Nains. Le roi de Forgefer porterait sans nul doute de l’intérêt à cet artéfact.>", t = "Le traité d’entente"},
    [98424] = {ot = "Récupérez les pages du superviseur Vibrouage se trouvant encore à l’intérieur de la mine de la KapitalRisk, et apportez-les à Morin Traqueur-de-Nuage, près de Sabot-de-Sang.", st = "Une liasse de documents très abîmés est pliée dans la poche de poitrine de Vibrouage.\n\nIls semblent contenir des informations importantes qui pourraient être utilisées contre la KapitalRisk et ses opérations dans la région. Il serait sage de voir si vous pouvez trouver d’autres documents avant de retourner auprès de Morin Traqueur-de-Nuage.", t = "Les notes de Vibrouage"},
    [98427] = {ot = "Apportez la clé de déboiseur à Morin Traqueur-de-Nuage, à l’extérieur de Sabot-de-Sang.", st = "Le déchiqueteur dont parle l’une des pages… Je l’ai déjà aperçu lors de mes périples. Il est capable de raser une forêt en une fraction du temps qu’il faudrait pour le faire à la hache.\n\nDes clairières entières… foyers millénaires des enfants de la Terre-Mère… détruites en l’espace de quelques jours.\n\nNous ne laisserons pas notre demeure connaître le même sort, si près des terres où nos jeunes font leurs premiers pas.\n\n$n, je dois vous demander de former un groupe, de retourner dans la mine au nord-est et de faire le nécessaire pour qu’il n’abatte plus aucun arbre.", t = "Fin des opérations"},
    [98430] = {t = "Les longues-marches"},
    [98435] = {ot = "Apportez le rapport de Corne-Tonnerre à l’archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre.", st = "Nos anciens des Pitons-du-Tonnerre doivent être informés de notre progression, merci pour votre aide.\n\nS’il vous plaît, apportez ceci à l’archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre. Vous le trouverez sur la cime des Anciens, du côté est de la ville. Vous devrez prendre l’ascenseur pour entrer dans la ville, puis traverser les ponts pour l’atteindre.", t = "Rapport de Corne-Tonnerre"},
    [98461] = {t = "Amour non partagé"},
    [98512] = {t = "Les assassins al’aketh"},
    [98545] = {ot = "Portez la lettre scellée à Glix Xizzix à Fossoyeuse.", st = "Puisque vous êtes là, j’aimerais vous demander de porter cette lettre à un vieil ami à moi à Fossoyeuse. Je m’en chargerais bien, mais la Dame noire et moi avons un petit passif ensemble et il vaudrait mieux que la livraison soit assurée par quelqu’un de neutre.\n\nC’est un Gobelin du nom de Glix Xizzix que vous cherchez, dans le quartier des Marchands de Fossoyeuse. Je suis sûr qu’il sera ravi de vous dédommager pour votre peine.\n\n<En vous tendant la lettre, Leonid laisse échapper un petit ricanement.>", t = "La lettre de Leonid"},
    [98574] = {ot = "Lisez la note sanctifiée, et parlez à Branstock Khalder, à Courbenclume.", st = "Pendant que vous m’aidiez, on m’a donné cette note pour vous. Prenez le temps de la lire. Je pense qu’elle provient du maître des prêtres, Branstock. Jetez-y un coup d’œil et, quand vous en aurez le temps, allez le retrouver à l’intérieur de Courbenclume.", t = "Note sanctifiée"},
    [98575] = {ot = "Lisez la tablette corrompue, et parlez à Nartok, à l’intérieur de l’Antre, dans la vallée des Épreuves.", st = "Ah, une tablette est arrivée pour vous pendant que vous n’étiez pas là, $n.$B$BJ’évite autant que possible de traiter avec des démonistes, mais je pense que vous devriez la lire, quand vous en aurez le temps. Si je ne me trompe pas, elle provient du maître qui vous a été récemment assigné, Nartok. Il souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Tablette corrompue"},
    [98576] = {ot = "Lisez le parchemin glyphé, et parlez à Mai’ah, près de l’entrée de l’Antre de la vallée des Épreuves.", st = "Ah, pendant votre absence, on m’a apporté un parchemin pour vous, $n.$B$BLisez-le quand vous aurez le temps. Si je ne me trompe pas, il provient de la maîtresse des mages Mai’ah. Elle souhaiterait s’entretenir avec vous, quand vous jugerez le moment venu.", t = "Parchemin glyphé"},
    [98581] = {ot = "Lisez la rune archaïque, puis parlez à Teo Martel-tempête, à Courbenclume.", st = "Pendant que vous m’aidiez, on m’a donné cette rune pour vous. Prenez le temps de la lire. D’après le style marteau-Hardi de cette calligraphie, je pense qu’elle provient du maître des chamans, Teo Martel-tempête. Jetez-y un coup d’œil et allez le retrouver, à l’intérieur de Courbenclume, quand vous en aurez le temps.", t = "La rune archaïque"},
    [98601] = {ot = "Lisez le parchemin consacré et parlez à Aramis Mainmartel, dans l’église du Glas.", st = "Pendant que vous étiez $gparti:partie; vous occuper de ces décérébrés du Fléau, ce parchemin est arrivé à votre intention. Il empeste la Lumière, alors j’imagine qu’il doit avoir une certaine importance pour $gun paladin tel:une paladine telle; que vous.\n\nLisez-le avant de repartir. Mais, par pitié… éloignez-vous un peu. Les paladins me mettent vraiment mal à l’aise.", t = "Un chemin tortueux"},
    [98731] = {ot = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", st = "Maintenant que vous avez ma bénédiction, retournez voir Dendrite pour qu’il vous donne plus d’instructions. J’espère que nous nous reverrons un jour.\n\nPuissent les ombres vous dissimuler et vos ennemis tomber sous vos griffes, jeune $gdruide:druidesse;.", t = "Bénédiction de l’esprit du Grand félin"},
    [98738] = {ot = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.", st = "Maintenant que vous avez ma bénédiction, retournez voir Dendrite pour qu’il vous donne plus d’instructions.\n\nMalheureusement, je n’ai plus grand-chose à vous enseigner pour le moment. J’espère que vous reviendrez me voir à Zéphras un jour. Vous avez du potentiel, jeune shen’dorei.\n\nPuissent les ombres vous dissimuler, vos ennemis tomber sous vos griffes et les vents guider vos pas.", t = "Bénédiction de l’esprit du Grand félin du vent"},
    [98739] = {ot = "Parlez à Dendrite.", st = "Maintenant que vous avez ma bénédiction, retournez voir Dendrite pour qu’il vous donne plus d’instructions. J’espère que nous nous reverrons un jour.\n\nPuissent les ombres vous dissimuler et vos ennemis tomber sous vos griffes, jeune $gdruide:druidesse;.", t = "Bénédiction de l’esprit du Grand félin"},
    [98815] = {t = "Cuir des hautes-terres"},
    [98823] = {ot = "Apportez la relique des Titans à Muln Rageterre, sur le plateau de Guette-ciel au nord-ouest de Mulgore.", st = "Voilà un objet réellement fascinant.\n\nIl semble s’agir de bien plus qu’une simple sculpture.\n\nNos anciens souhaiteront peut-être jeter un œil à cet artéfact, mais personne ne connaît mieux nos ruines enfuies et nos terres oubliées que le Cercle terrestre. Allez voir Muln Rageterre. Une approche directe serait appropriée pour un objet d’une telle importance.\n\nVous le trouverez ainsi que d’autres membres du conseil des anciens du Cercle terrestre sur le plateau de Guette-ciel, en Mulgore.", t = "Écho terrestre"},
    [98824] = {t = "Prisme préhistorique"},
    [99046] = {t = "La messagère égarée"},
    [99047] = {ot = "Allez chercher l’aide de Byancie à Dolanaar pour la sentinelle Eralya Feuillombre.", st = "Mes sœurs et moi avons été… envoyées… à l’arbre-oracle…\n\nL’arbre… le message. Je… des harpies… partout…\n\n<Eralya crache du sang, le visage tordu par la douleur.>\n\nJe ne tiendrai pas longtemps… personne ne viendra. Pitié… Byancie… à Dolanaar…", t = "Toujours en vie"},
    [99048] = {ot = "Trouvez Heglan Ombredœil au nord du donjon de Tiragarde.", st = "Le donjon de Tiragarde était surveillé de loin par une membre de la Main-Brisée, un groupe de combattants plutôt… discrets. Ses rapports ont cessé de nous parvenir du jour au lendemain.\n\nJe doute fort que les Humains l’aient attrapée, mais j’ai peur que quelque chose de bien pire lui soit arrivé. Voyez si vous parvenez à la trouver. Espérons que ses messages aient simplement pris un peu de retard.", t = "Une main en moins"},
    [99049] = {ot = "Trouvez des traces de ce qui a attaqué Heglan Ombredœil.", st = "La zone alentour est détruite et vous repérez les traces évidentes d’une embuscade. Quoi qu’Heglan ait affronté, son adversaire ne s’en est pas tiré indemne. Il doit y avoir des indices dans les environs qui vous en apprendront plus.\n\nOrgnil voudra sans doute examiner les preuves laissées par les agresseurs.", t = "Une menace venue d’en bas"},
    [99050] = {t = "La bonté du Grand arbre"},
    [99051] = {t = "Une menace venue d’en bas"},
    [99052] = {ot = "Tuez le Géant des mers au large de la côte nord de Durotar, puis rapportez une preuve de votre victoire.", st = "On m’a rapporté qu’un Géant des mers aurait suivi les Nagas. J’ignore si c’était volontaire de leur part, mais dans tous les cas, il est dangereux.\n\nIl est encore jeune, mais il est déjà capable d’étriper un Orc un peu distrait en un instant. Il doit disparaître. Néanmoins, je vous déconseille de l’affronter $gseul:seule;.", t = "Une menace venue d’en bas"},
    [99053] = {t = "Évasion de Ban’ethil"},
    [99073] = {ot = "Apportez le baume luxuriant à la sentinelle Eralya Feuillombre sur la route vers l’arbre-oracle.", st = "Le baume est prêt. Portez-le à Eralya sans tarder.\n\nJ’ignore s’il suffira à la guérir. La pourriture se propage rapidement et empire à mesure qu’elle gagne du terrain.\n\nNous pouvons au moins soulager sa douleur, et c’est là une raison suffisante pour vous hâter.", t = "Soulager le mal"},
    [99079] = {ot = "Trouvez la longue-marche Malah Longuebrise à l’est de Sabot-de-Sang, près de la frontière de Mulgore.", st = "Les longues-marches sont les éclaireurs les plus fiables de notre peuple. Ils sont entièrement dévoués au grand chef et à personne d’autre, mais le jeune Baine fait parfois appel à leur aide.\n\nC’est le cas aujourd’hui. Il y a trois jours, la longue-marche Malah a été envoyée près de nos frontières, à l’est, et elle n’est pas revenue depuis. Dans ces circonstances, il est de notre devoir de nous assurer qu’elle est saine et sauve.\n\nJe dois protéger le village. Prouvez-moi votre valeur et retrouvez Malah. Vous la reconnaîtrez à son bandeau et son bâton à plumes, emblèmes des longues-marches.", t = "Longue-marche Malah"},
    [99080] = {t = "Qu’ils disparaissent"},
    [99081] = {ot = "Apportez le rapport de la longue-marche Malah au brave Course-Sauvage à Sabot-de-Sang.", st = "Vous apercevez un camp de Centaures fraîchement installé dont l’emplacement correspond à la direction des flèches qui ont transpercé le dos de Malah. Le camp est animé, ce qui suggère qu’un petit groupe de pilleurs est entré en Mulgore.\n\nLa longue-marche tient un rapport dans sa main. Le brave Course-Sauvage sera intéressé de connaître le sort de Malah et l’identité de ses bourreaux.", t = "De sombres nouvelles"},
    [99082] = {ot = "Sollicitez une audience auprès de Cairne Sabot-de-Sang aux Pitons-du-Tonnerre.", st = "Vous défendez les vôtres avec beaucoup de bravoure. Allez au nord-ouest, aux Pitons-du-Tonnerre, notre grande cité dont l’ombre nous protège du soleil pendant la saison chaude, et sollicitez une audience auprès de mon père.\n\nC’est lui qui a mené l’assaut aux côtés du jeune chef de guerre Thrall pour reprendre possession de ces plaines et chasser les Centaures pour de bon. En tant que grand chef, il vous récompensera généreusement d’avoir fait honneur à son propre courage.\n\nVous devez prendre un ascenseur pour rejoindre le grand chef sur la cime centrale.", t = "Le grand chef"},
    [99101] = {t = "Un adversaire ancien"},
    [99108] = {t = "Combat d’entraînement"},
    [99123] = {ot = "Aidez Pal’juh à sortir de la combe des Kolkar, puis informez-en maître Vornal, au village de Sen’jin.", st = "J’ai décidé de partir en reconnaissance de mon côté dans la combe. Malheureusement, je suis tombée à court de magie au mauvais moment, et je suis coincée ici depuis.\n\nSi vous pouviez m’aider à sortir, je vous en serais reconnaissante.", t = "Perdue dans les ombres"},
    [99127] = {ot = "Jetez un œil aux pièges à poissons dans le lac de Cristal.", st = "La pêche n’est pas fructueuse, aujourd’hui. Quelque chose cloche avec les poissons. On pourrait croire qu’ils sont juste timides, mais je n’ai pas vu un seul vairon dans l’eau.\n\nLee a posé quelques pièges pendant la nuit. Allez voir s’ils sont remplis. Si vous trouvez quoi que ce soit d’étrange, n’hésitez pas à me le montrer.", t = "Filet sans arêtes"},
    [99128] = {t = "Menace visqueuse"},
    [99129] = {t = "Solution anti-Murloc"},
    [99130] = {t = "Une proposition alléchante"},
    [99131] = {ot = "Retournez voir Jason Mathers.", st = "Dites à Mathers qu’il pourra venir chercher l’appât plus tard dans la journée. Je lui expliquerai comment l’utiliser correctement.\n\nJ’espère qu’il pourra bientôt vendre ses poissons à nouveau, et que le monde sera débarrassé de quelques Murlocs au passage.", t = "Appâter pour mieux tuer"},
    [99134] = {t = "Discipline"},
    [99141] = {ot = "Obtenez les rapports des nécrogardes Dillinger et Kristof et de Gordo pour l’exécuteur Zygand.", st = "Sachez, $c, que la Dame noire exige que sa volonté soit accomplie dans les plus parfaites circonstances. En tant qu’exécuteur, il est de mon devoir de m’en assurer.\n\nPlusieurs rapports de mes nécrogardes sont en retard, et inutile de vous dire que ma patience a ses limites. Récupérez leurs rapports et apportez-les-moi, au nom de la Dame noire.\n\nVous trouverez le nécrogarde Dillinger à l’ouest, près du cimetière. Le nécrogarde Kristof est stationné au relais à l’est. Allez aussi jeter un œil à l’abomination Gordo. Il se promène à l’ouest, près de l’étang Immobile.", t = "Patience"},
    [99142] = {t = "Herbes sépulcrales"},
    [99143] = {t = "Appâts de pacotille"},
    [99144] = {t = "Demande d’asile"},
    [99152] = {t = "L’ombre sous le val"},
    [99153] = {t = "Celui qui s’échappa"},
    [99156] = {t = "Patrouille d’arrière-garde"},
    [99158] = {t = "Aube sur les montagnes"},
    [99159] = {t = "Un peu de chaleur"},
    [99160] = {t = "La colère du givre"},
    [99161] = {t = "La colère du givre"},
    [99162] = {t = "Un froid dangereux"},
    [99260] = {ot = "Parlez à Elaadrin Trombecalme, à Valanaar.", st = "On m’a ordonner de collecter des données importantes sur le flux d’énergie élémentaire des pierres dressées surplombantes. Nous avons besoin de ces informations pour concevoir un moyen sûr de voyager entre Mur-Céleste et Azeroth. Sans données précises pour réaliser nos calculs, toutes nos tentatives pour orienter les vaisseaux perceciel à travers le plan élémentaire seront vouées à l’échec.\n\nMais au point où nous en sommes, je crains que ces données ne soient perdues et je ne suis pas en état de tout recommencer. J’ai expliqué au magistère suprême que vous m’aviez secouru, et il tient à vous parler à nouveau.", t = "La mission de Fillion"},
    [99411] = {t = "Kyle a disparu !"},
  },
})
end)
